// app.js
let activeRibbonTabId = 'ventes';
let isRibbonExpanded = false;

function setRibbonExpanded(expanded) {
    const ribbon = document.querySelector('.ribbon');
    if (!ribbon) return;
    isRibbonExpanded = Boolean(expanded);
    ribbon.classList.toggle('ribbon-collapsed', !isRibbonExpanded);
}

function activateRibbonTab(tabId) {
    activeRibbonTabId = tabId || activeRibbonTabId || 'ventes';

    document.querySelectorAll('.ribbon-tab').forEach(tab => {
        tab.classList.remove('active');
        if (tab.getAttribute('onclick') && tab.getAttribute('onclick').includes(`'${activeRibbonTabId}'`)) {
            tab.classList.add('active');
        }
    });

    document.querySelectorAll('.ribbon-panel').forEach(panel => {
        panel.classList.remove('active');
    });

    const activePanel = document.getElementById(`panel-${activeRibbonTabId}`);
    if (activePanel) activePanel.classList.add('active');
}

window.switchRibbonTab = function (tabId) {
    const nextTabId = tabId || activeRibbonTabId || 'ventes';
    const isSameTab = activeRibbonTabId === nextTabId;

    activateRibbonTab(nextTabId);

    if (isSameTab) {
        setRibbonExpanded(!isRibbonExpanded);
        return;
    }

    setRibbonExpanded(true);
};

function collapseRibbon() {
    setRibbonExpanded(false);
}

function initRibbonAutoHide() {
    activateRibbonTab(activeRibbonTabId);
    setRibbonExpanded(false);

    if (window.__ribbonAutoHideBound) return;

    document.addEventListener('click', event => {
        const ribbon = document.querySelector('.ribbon');
        if (!ribbon) return;
        if (ribbon.contains(event.target)) return;
        collapseRibbon();
    });

    window.__ribbonAutoHideBound = true;
}

