async function initClientSettlementModule() {
    const customerSelect = document.getElementById('client-settlement-customer');
    const pendingCustomerId = pendingClientSettlementCustomerId;
    if (customerSelect) {
        const customers = saleState.customers.length > 0 ? saleState.customers : await fetchCollection('customers?select=id,nom,telephone,solde,en_cours,reste_a_payer,mutuelles(nom)&order=nom');
        saleState.customers = customers;
        customerSelect.innerHTML = [
            '<option value="">Choisir un client</option>',
            ...customers.map(customer => `<option value="${customer.id}">${escapeHtml(customer.nom)}</option>`)
        ].join('');
        if (pendingCustomerId) {
            customerSelect.value = pendingCustomerId;
            pendingClientSettlementCustomerId = '';
        }
    }

    await loadClientSettlementSnapshot();
    if (pendingCustomerId) {
        const amountInput = document.getElementById('client-settlement-amount');
        const balance = await getClientOutstandingBalance(pendingCustomerId);
        if (amountInput && balance > 0) {
            amountInput.value = formatMoney(balance);
            amountInput.focus();
            amountInput.select?.();
        }
    }
}

async function loadClientSettlementSnapshot() {
    const tbody = document.getElementById('client-settlement-body');
    if (!tbody) return;

    const customerId = document.getElementById('client-settlement-customer')?.value || '';
    const customer = customerId ? getSaleCustomerById(customerId) : null;
    const movementRows = await getClientMovementRows();
    const rows = customerId
        ? movementRows.filter(item => String(item.client_id || '') === String(customerId))
        : movementRows;

    tbody.innerHTML = rows.length
        ? rows.map((item) => {
            const isPayment = item.source === 'PAYMENT';
            const isDebit = !isPayment && Number(item.debit || 0) > Number(item.credit || 0);
            const rowBg = isPayment ? '#dcfce7' : isDebit ? '#fee2e2' : '#dbeafe';
            const statut = isPayment ? (item.statut || 'Reglement') : (isDebit ? 'A regler' : 'Solde');
            return `
            <tr style="background:${rowBg};">
                <td style="border:none; padding:8px 10px;">${item.date_vente ? new Date(item.date_vente).toLocaleString('fr-FR') : '-'}</td>
                <td style="border:none; padding:8px 10px;">${escapeHtml(item.numero_vente || '-')}</td>
                <td style="border:none; padding:8px 10px;">${escapeHtml(item.customerName || item.customers?.nom || '-')}</td>
                <td style="border:none; padding:8px 10px;">${escapeHtml(getModeDisplayLabel(item))}</td>
                <td style="border:none; padding:8px 10px;">${escapeHtml(item.paymentReference || '-')}</td>
                <td style="border:none; padding:8px 10px;">${escapeHtml(item.paymentNote || '-')}</td>
                <td style="border:none; padding:8px 10px; text-align:right; font-weight:700;">${formatMoney(Number(item.credit || 0) > 0 ? item.credit : item.debit)} DT</td>
                <td style="border:none; padding:8px 10px; font-weight:700; color:${isPayment ? '#16a34a' : isDebit ? '#dc2626' : '#1d4ed8'};">${escapeHtml(statut)}</td>
            </tr>`;
        }).join('')
        : '<tr><td colspan="8" style="text-align:center; padding:40px;">Aucun mouvement client.</td></tr>';

    const balanceNode = document.getElementById('client-settlement-balance');
    const customerNode = document.getElementById('client-settlement-customer-name');
    const lastDateNode = document.getElementById('client-settlement-last-date');
    const balance = customerId ? await getClientOutstandingBalance(customerId) : 0;
    const lastPayment = rows[0] || null;

    if (balanceNode) balanceNode.innerText = `${formatMoney(balance)} DT`;
    if (customerNode) customerNode.innerText = customer?.nom || '-';
    if (lastDateNode) lastDateNode.innerText = lastPayment?.date_vente ? new Date(lastPayment.date_vente).toLocaleString('fr-FR') : '-';
}

async function getClientOutstandingBalance(customerId) {
    if (!customerId) return 0;
    const rows = await getClientMovementRows();
    return rows
        .filter(item => String(item.client_id || '') === String(customerId))
        .reduce((sum, item) => sum + Number(item.debit || 0) - Number(item.credit || 0), 0);
}

function buildClientSettlementNumber() {
    const now = new Date();
    return `RCL-${now.getFullYear()}${String(now.getMonth() + 1).padStart(2, '0')}${String(now.getDate()).padStart(2, '0')}-${String(now.getHours()).padStart(2, '0')}${String(now.getMinutes()).padStart(2, '0')}${String(now.getSeconds()).padStart(2, '0')}`;
}

async function getCustomerPaymentsRows() {
    const rows = await fetchCollection('customer_payments?select=id,payment_number,client_id,amount,payment_date,payment_mode,reference,note,statut,created_at,customers(nom)&order=payment_date.desc,created_at.desc', []);
    return Array.isArray(rows) ? rows.map(item => ({
        ...item,
        id: `payment-${item.id}`,
        source: 'PAYMENT',
        client_id: item.customer_id || item.client_id,
        numero_vente: item.payment_number || item.id || '-',
        date_vente: item.payment_date || item.created_at,
        mode: 'REGLEMENT',
        customerType: 'REGISTERED',
        customerTypeLabel: 'Client enregistre',
        customerName: item.customers?.nom || item.customer_name || 'Client',
        totalTtc: 0,
        partMutuelle: 0,
        clientAmount: 0,
        debit: 0,
        credit: Number(item.amount || 0),
        paymentReference: item.reference || '',
        paymentNote: item.note || ''
    })) : [];
}

function updateCachedCustomersLocally(customerUpdates = []) {
    if (!Array.isArray(customerUpdates) || customerUpdates.length === 0) return;

    const updatesMap = new Map(
        customerUpdates
            .filter(item => item && item.id)
            .map(item => [String(item.id), item])
    );

    const applyUpdates = (rows = []) => rows.map(customer => {
        const update = updatesMap.get(String(customer?.id || ''));
        return update ? { ...customer, ...update } : customer;
    });

    saleState.customers = applyUpdates(saleState.customers || []);
    allCustomers = applyUpdates(allCustomers || []);
}

async function saveClientSettlement() {
    const customerId = document.getElementById('client-settlement-customer')?.value || '';
    const paymentDate = document.getElementById('client-settlement-date')?.value || '';
    const amount = Number(document.getElementById('client-settlement-amount')?.value || 0);
    const paymentMode = document.getElementById('client-settlement-mode')?.value || 'ESPECE';
    const reference = document.getElementById('client-settlement-reference')?.value.trim() || '';
    const note = document.getElementById('client-settlement-note')?.value.trim() || '';

    if (!customerId) {
        alert('Choisissez un client.');
        return;
    }

    if (!(amount > 0)) {
        alert('Le montant du reglement doit etre superieur a zero.');
        return;
    }

    const balance = await getClientOutstandingBalance(customerId);
    if (balance <= 0) {
        alert('Ce client ne presente aucun solde a regler.');
        return;
    }

    if (amount - balance > 0.0009) {
        if (!confirm(`Le montant saisi depasse le solde du client (${formatMoney(balance)} DT).\n\nContinuer quand meme ?`)) {
            return;
        }
    }

    const payload = {
        payment_number: buildClientSettlementNumber(),
        client_id: customerId,
        payment_date: paymentDate ? new Date(paymentDate).toISOString() : new Date().toISOString(),
        amount,
        payment_mode: paymentMode,
        reference: reference || null,
        note: note || null,
        statut: 'VALIDE'
    };

    try {
        const response = await fetch(`${supabaseUrl}customer_payments`, {
            method: 'POST',
            headers: { ...supabaseHeaders, Prefer: 'return=representation' },
            body: JSON.stringify(payload)
        });

        if (!response.ok) {
            const errorText = await response.text();
            if (response.status === 400 && /customer_payments|schema cache|payment_number|payment_mode/i.test(errorText)) {
                throw new Error(`Table manquante dans Supabase.\n\nExecute d'abord ce SQL dans Supabase:\n${getCustomerPaymentsMigrationSql()}`);
            }
            throw new Error(errorText);
        }

        document.getElementById('client-settlement-amount').value = '';
        document.getElementById('client-settlement-reference').value = '';
        document.getElementById('client-settlement-note').value = '';
        await loadClientSettlementSnapshot();
        if (activeTabId === 'mouv_clients') {
            await loadClientMovements();
        }
        alert('Reglement client enregistre avec succes.');
    } catch (error) {
        console.error('Erreur reglement client:', error);
        alert(`Impossible d'enregistrer le reglement.\n\nDetail: ${getSupabaseErrorMessage(error)}`);
    }
}

