let pendingClientSettlementCustomerId = '';
let pendingReturnToSaleAfterCustomerSave = false;
let pendingSaleCustomerSelection = null;

function debounce(fn, delay) {
    let timer = null;
    return function(...args) {
        if (timer) clearTimeout(timer);
        timer = setTimeout(() => {
            timer = null;
            fn.apply(this, args);
        }, delay);
    };
}

const debouncedLoadFridgeSales = debounce(loadFridgeSales, 300);
const debouncedLoadActionHistoryRows = debounce(loadActionHistoryRows, 300);
const debouncedLoadSalesDeletionRows = debounce(loadSalesDeletionRows, 300);
const debouncedLoadPurchasesDeletionRows = debounce(loadPurchasesDeletionRows, 300);

