let salesJournalHiddenIdsCache = null;
let salesJournalDaySelectionCache = new Set();
let salesJournalDayCurrentDateKey = '';
let salesJournalHiddenSelectionCache = new Set();

function pickCompanySettingValue(record, keys = [], fallback = '') {
    for (const key of keys) {
        const value = record?.[key];
        if (value !== undefined && value !== null && String(value).trim() !== '') {
            return String(value).trim();
        }
    }
    return fallback;
}

function normalizeCompanySettingsRecord(record = {}) {
    return {
        companyName: pickCompanySettingValue(record, ['companyName', 'nomSociete', 'nom_societe', 'societe', 'raisonSociale'], COMPANY_SETTINGS_DEFAULTS.companyName),
        subtitle: pickCompanySettingValue(record, ['subtitle', 'sousTitre', 'sous_titre'], COMPANY_SETTINGS_DEFAULTS.subtitle),
        address: pickCompanySettingValue(record, ['address', 'adresse']),
        city: pickCompanySettingValue(record, ['city', 'ville']),
        phone: pickCompanySettingValue(record, ['phone', 'telephone', 'telephoneFixe', 'telephone_fixe']),
        mobile: pickCompanySettingValue(record, ['mobile', 'gsm', 'portable']),
        email: pickCompanySettingValue(record, ['email', 'mail']),
        fiscalId: pickCompanySettingValue(record, ['fiscalId', 'fiscal_id', 'matriculeFiscal', 'matricule_fiscal', 'codeTva', 'code_tva']),
        website: pickCompanySettingValue(record, ['website', 'siteWeb', 'site_web']),
        rib: pickCompanySettingValue(record, ['rib', 'RIB']),
        pharmacistCode: pickCompanySettingValue(record, ['pharmacistCode', 'codePharmacien', 'code_pharmacien']),
        deliveryFeeStandard: Number(record?.deliveryFeeStandard ?? record?.delivery_fee_standard ?? 0) || 0,
        deliveryFeeExpress: Number(record?.deliveryFeeExpress ?? record?.delivery_fee_express ?? 0) || 0,
        deliveryFeePickup: Number(record?.deliveryFeePickup ?? record?.delivery_fee_pickup ?? 0) || 0
    };
}

function getSalesJournalHiddenIds() {
    if (salesJournalHiddenIdsCache instanceof Set) {
        return new Set(salesJournalHiddenIdsCache);
    }
    try {
        const raw = localStorage.getItem(SALES_JOURNAL_HIDDEN_STORAGE_KEY);
        const parsed = raw ? JSON.parse(raw) : [];
        salesJournalHiddenIdsCache = new Set(
            (Array.isArray(parsed) ? parsed : [])
                .map(item => String(item || '').trim())
                .filter(Boolean)
        );
    } catch (error) {
        salesJournalHiddenIdsCache = new Set();
    }
    return new Set(salesJournalHiddenIdsCache);
}

function saveSalesJournalHiddenIds(ids) {
    salesJournalHiddenIdsCache = new Set(
        Array.from(ids || [])
            .map(item => String(item || '').trim())
            .filter(Boolean)
    );
    localStorage.setItem(SALES_JOURNAL_HIDDEN_STORAGE_KEY, JSON.stringify(Array.from(salesJournalHiddenIdsCache)));
}

function isSalesJournalRowHidden(item) {
    const id = String(item?.id || '').trim();
    if (!id) return false;
    return getSalesJournalHiddenIds().has(id);
}

function getLegacyCompanySettingsFromStorage() {
    const merged = {};
    const candidateKeys = [
        'companySettings',
        'company_settings',
        'societe',
        'parametre_societe',
        'parametreSociete',
        'settings',
        'config'
    ];

    candidateKeys.forEach(key => {
        try {
            const raw = localStorage.getItem(key);
            if (!raw) return;
            const parsed = JSON.parse(raw);
            if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) {
                Object.assign(merged, normalizeCompanySettingsRecord(parsed));
            }
        } catch (error) {
            // ignore legacy entries that are not JSON
        }
    });

    const flatKeys = {
        companyName: ['companyName', 'nomSociete', 'nom_societe', 'societe'],
        subtitle: ['subtitle', 'sousTitre', 'sous_titre'],
        address: ['address', 'adresse'],
        city: ['city', 'ville'],
        phone: ['phone', 'telephone', 'telephoneFixe', 'telephone_fixe'],
        mobile: ['mobile', 'gsm', 'portable'],
        email: ['email', 'mail'],
        fiscalId: ['fiscalId', 'fiscal_id', 'matriculeFiscal', 'matricule_fiscal', 'codeTva', 'code_tva'],
        website: ['website', 'siteWeb', 'site_web'],
        rib: ['rib', 'RIB'],
        pharmacistCode: ['pharmacistCode', 'codePharmacien', 'code_pharmacien']
    };

    Object.entries(flatKeys).forEach(([targetKey, keys]) => {
        const value = pickCompanySettingValue(
            Object.fromEntries(keys.map(key => [key, localStorage.getItem(key)])),
            keys
        );
        if (value) {
            merged[targetKey] = value;
        }
    });

    return {
        ...COMPANY_SETTINGS_DEFAULTS,
        ...merged
    };
}

const RAYONNAGE_STORAGE_PREFIX = 'para_mv_rayonnage_intelligent';

let rayonnageState = {
    assignments: [],
    products: [],
    selectedProductId: '',
    filter: ''
};

function getRayonnageTenantKey() {
    const settings = getCompanySettings();
    const tenantSource = [
        window.location.hostname || 'local',
        settings.fiscalId || settings.companyName || 'default'
    ].join('|');
    return normalizeSearchText(tenantSource).replace(/[^a-z0-9]+/g, '_') || 'default';
}

function getRayonnageStorageKey() {
    return `${RAYONNAGE_STORAGE_PREFIX}_${getRayonnageTenantKey()}`;
}

function loadRayonnageAssignments() {
    try {
        const parsed = JSON.parse(localStorage.getItem(getRayonnageStorageKey()) || '[]');
        rayonnageState.assignments = Array.isArray(parsed) ? parsed : [];
    } catch (error) {
        console.warn('Rayonnage local indisponible.', error);
        rayonnageState.assignments = [];
    }
    return rayonnageState.assignments;
}

function saveRayonnageAssignments() {
    localStorage.setItem(getRayonnageStorageKey(), JSON.stringify(rayonnageState.assignments));
}

function getRayonnageAssignment(productId) {
    return rayonnageState.assignments.find(item => String(item.product_id) === String(productId)) || null;
}

function formatRayonnageLocation(assignment = null) {
    if (!assignment) return '-';
    return [assignment.zone, assignment.rayon, assignment.niveau, assignment.position]
        .map(value => String(value || '').trim())
        .filter(Boolean)
        .join(' / ') || '-';
}

function getRayonnageFilteredProducts() {
    const query = normalizeSearchText(rayonnageState.filter || '');
    return (rayonnageState.products || []).filter(product => {
        if (!query) return true;
        const assignment = getRayonnageAssignment(product.id);
        return [
            product.code_article,
            product.designation,
            product.forme,
            formatRayonnageLocation(assignment),
            assignment?.priorite,
            assignment?.note
        ].some(value => normalizeSearchText(value).includes(query));
    });
}

function buildRayonnageRecommendations(products = []) {
    const assignedIds = new Set(rayonnageState.assignments.map(item => String(item.product_id)));
    const unassignedStock = products.filter(product => Number(product.stock_actuel || 0) > 0 && !assignedIds.has(String(product.id))).length;
    const ruptureAssigned = products.filter(product => Number(product.stock_actuel || 0) <= 0 && assignedIds.has(String(product.id))).length;
    const capacityAlerts = products.filter(product => {
        const assignment = getRayonnageAssignment(product.id);
        const capacity = Number(assignment?.capacite || 0);
        return capacity > 0 && Number(product.stock_actuel || 0) > capacity;
    }).length;
    const datedProducts = products.filter(product => product.peremption).length;

    return [
        { label: 'Articles en stock sans emplacement', value: unassignedStock, tone: unassignedStock ? 'warn' : 'ok' },
        { label: 'Emplacements avec stock nul/negatif', value: ruptureAssigned, tone: ruptureAssigned ? 'danger' : 'ok' },
        { label: 'Depassements capacite rayon', value: capacityAlerts, tone: capacityAlerts ? 'danger' : 'ok' },
        { label: 'Articles avec date peremption', value: datedProducts, tone: 'info' }
    ];
}

