async function initRayonnageModule() {
    loadRayonnageAssignments();
    await ensureManagedProductsCacheLoaded();
    rayonnageState.products = Array.isArray(allManagedProducts) ? allManagedProducts : [];
    renderRayonnageRecommendations();
    renderRayonnageTable();
}

function filterRayonnageProducts() {
    rayonnageState.filter = document.getElementById('rayonnage-product-search')?.value || '';
    renderRayonnageTable();
}

function selectRayonnageProduct(productId) {
    const product = rayonnageState.products.find(item => String(item.id) === String(productId));
    if (!product) return;
    rayonnageState.selectedProductId = product.id;
    const assignment = getRayonnageAssignment(product.id) || {};
    document.getElementById('rayonnage-zone').value = assignment.zone || '';
    document.getElementById('rayonnage-rayon').value = assignment.rayon || '';
    document.getElementById('rayonnage-niveau').value = assignment.niveau || '';
    document.getElementById('rayonnage-position').value = assignment.position || '';
    document.getElementById('rayonnage-capacite').value = assignment.capacite || '';
    document.getElementById('rayonnage-priorite').value = assignment.priorite || 'NORMAL';
    document.getElementById('rayonnage-note').value = assignment.note || '';
    const selectedNode = document.getElementById('rayonnage-selected-product');
    if (selectedNode) selectedNode.innerText = `${product.code_article || '-'} - ${product.designation || ''}`;
    renderRayonnageTable();
}

function clearRayonnageForm() {
    rayonnageState.selectedProductId = '';
    ['rayonnage-zone', 'rayonnage-rayon', 'rayonnage-niveau', 'rayonnage-position', 'rayonnage-capacite', 'rayonnage-note'].forEach(id => {
        const input = document.getElementById(id);
        if (input) input.value = '';
    });
    const priority = document.getElementById('rayonnage-priorite');
    if (priority) priority.value = 'NORMAL';
    const selectedNode = document.getElementById('rayonnage-selected-product');
    if (selectedNode) selectedNode.innerText = 'Selectionnez une ligne article.';
    renderRayonnageTable();
}

function saveRayonnageAssignment() {
    if (!rayonnageState.selectedProductId) {
        alert('Selectionnez un article dans la liste.');
        return;
    }
    const nextRecord = {
        product_id: rayonnageState.selectedProductId,
        tenant_id: getRayonnageTenantKey(),
        zone: document.getElementById('rayonnage-zone')?.value.trim() || '',
        rayon: document.getElementById('rayonnage-rayon')?.value.trim() || '',
        niveau: document.getElementById('rayonnage-niveau')?.value.trim() || '',
        position: document.getElementById('rayonnage-position')?.value.trim() || '',
        capacite: Number(document.getElementById('rayonnage-capacite')?.value || 0),
        priorite: document.getElementById('rayonnage-priorite')?.value || 'NORMAL',
        note: document.getElementById('rayonnage-note')?.value.trim() || '',
        updated_at: new Date().toISOString()
    };
    rayonnageState.assignments = [
        ...rayonnageState.assignments.filter(item => String(item.product_id) !== String(nextRecord.product_id)),
        nextRecord
    ];
    saveRayonnageAssignments();
    renderRayonnageRecommendations();
    renderRayonnageTable();
}

function deleteRayonnageAssignment() {
    if (!rayonnageState.selectedProductId) return;
    rayonnageState.assignments = rayonnageState.assignments.filter(item => String(item.product_id) !== String(rayonnageState.selectedProductId));
    saveRayonnageAssignments();
    clearRayonnageForm();
    renderRayonnageRecommendations();
}

function renderRayonnageRecommendations() {
    const container = document.getElementById('rayonnage-recommendations');
    if (!container) return;
    container.innerHTML = buildRayonnageRecommendations(rayonnageState.products).map(item => `
        <div class="rayonnage-kpi rayonnage-kpi-${item.tone}">
            <span>${escapeHtml(item.label)}</span>
            <strong>${item.value}</strong>
        </div>
    `).join('');
}

function renderRayonnageTable() {
    const tbody = document.getElementById('rayonnage-table-body');
    if (!tbody) return;
    const rows = getRayonnageFilteredProducts();
    if (!rows.length) {
        tbody.innerHTML = '<tr><td colspan="7" style="text-align:center; padding:34px;">Aucun article trouve.</td></tr>';
        return;
    }
    tbody.innerHTML = rows.slice(0, 250).map(product => {
        const assignment = getRayonnageAssignment(product.id);
        const isSelected = String(product.id) === String(rayonnageState.selectedProductId);
        const capacity = Number(assignment?.capacite || 0);
        const stock = Number(product.stock_actuel || 0);
        const capacityAlert = capacity > 0 && stock > capacity;
        return `
            <tr class="${isSelected ? 'rayonnage-row-selected' : ''}" onclick="selectRayonnageProduct('${escapeHtml(String(product.id || ''))}')" style="cursor:pointer;">
                <td>${escapeHtml(product.code_article || '-')}</td>
                <td>${escapeHtml(product.designation || '-')}<br><small>${escapeHtml(product.forme || '')}</small></td>
                <td style="text-align:right; font-weight:800; color:${stock <= 0 ? '#b91c1c' : '#166534'};">${formatMoney(stock)}</td>
                <td>${escapeHtml(formatRayonnageLocation(assignment))}</td>
                <td style="text-align:right; color:${capacityAlert ? '#b91c1c' : '#0f172a'}; font-weight:800;">${capacity ? formatMoney(capacity) : '-'}</td>
                <td><span class="rayonnage-priority">${escapeHtml(assignment?.priorite || 'NON RANGE')}</span></td>
                <td>${escapeHtml(assignment?.note || '-')}</td>
            </tr>
        `;
    }).join('');
}

function exportRayonnageCsv() {
    const rows = rayonnageState.products.map(product => {
        const assignment = getRayonnageAssignment(product.id) || {};
        return [
            product.code_article || '',
            product.designation || '',
            product.stock_actuel || 0,
            assignment.zone || '',
            assignment.rayon || '',
            assignment.niveau || '',
            assignment.position || '',
            assignment.capacite || '',
            assignment.priorite || '',
            assignment.note || '',
            getRayonnageTenantKey()
        ];
    });
    const header = ['Code', 'Designation', 'Stock', 'Zone', 'Rayon', 'Niveau', 'Position', 'Capacite', 'Priorite', 'Note', 'Tenant'];
    const csv = [header, ...rows].map(row => row.map(value => `"${String(value).replace(/"/g, '""')}"`).join(';')).join('\n');
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `rayonnage-${getRayonnageTenantKey()}-${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
    URL.revokeObjectURL(link.href);
}

function initApp() {
    loadCompanySettingsFromSupabase();
    openTab('dashboard');
}

function getCompanySettings() {
    try {
        const raw = localStorage.getItem(COMPANY_SETTINGS_STORAGE_KEY);
        const parsed = raw ? JSON.parse(raw) : {};
        const normalizedLegacy = getLegacyCompanySettingsFromStorage();
        const normalizedStored = normalizeCompanySettingsRecord(parsed && typeof parsed === 'object' ? parsed : {});
        const form = document.getElementById('company-settings-form');
        if (!form) {
            return {
                ...COMPANY_SETTINGS_DEFAULTS,
                ...normalizedLegacy,
                ...normalizedStored
                ,
                ...companySettingsCache
            };
        }

        const formData = new FormData(form);
        const normalizedForm = normalizeCompanySettingsRecord({
            companyName: formData.get('companyName'),
            subtitle: formData.get('subtitle'),
            address: formData.get('address'),
            city: formData.get('city'),
            phone: formData.get('phone'),
            mobile: formData.get('mobile'),
            email: formData.get('email'),
            fiscalId: formData.get('fiscalId'),
            website: formData.get('website'),
            rib: formData.get('rib'),
            pharmacistCode: formData.get('pharmacistCode')
        });

        return {
            ...COMPANY_SETTINGS_DEFAULTS,
            ...normalizedLegacy,
            ...normalizedStored,
            ...companySettingsCache,
            ...normalizedForm
        };
    } catch (error) {
        console.warn('Parametres societe introuvables, valeurs par defaut utilisees.', error);
        return { ...COMPANY_SETTINGS_DEFAULTS, ...companySettingsCache };
    }
}

async function loadCompanySettingsFromSupabase() {
    try {
        const rows = await fetchCollection('company_settings?select=id,company_name,subtitle,address,city,phone,mobile,email,fiscal_id,website,rib,pharmacist_code,delivery_fee_standard,delivery_fee_express,delivery_fee_pickup&id=eq.1', null);
        const record = Array.isArray(rows) ? rows[0] : rows;
        if (!record || typeof record !== 'object') return null;

        companySettingsCache = {
            ...COMPANY_SETTINGS_DEFAULTS,
            ...normalizeCompanySettingsRecord(record)
        };
        localStorage.setItem(COMPANY_SETTINGS_STORAGE_KEY, JSON.stringify(companySettingsCache));
        companySettingsSupabaseLoaded = true;

        if (typeof activeTabId !== 'undefined' && activeTabId === 'company_settings') {
            renderContent();
        }
        updateBackofficeLoginBranding();
        return companySettingsCache;
    } catch (error) {
        console.warn('Chargement Parametre societe depuis Supabase impossible.', error);
        return null;
    }
}

async function saveCompanySettingsToSupabase(settings) {
    const payload = {
        id: 1,
        company_name: settings.companyName,
        subtitle: settings.subtitle,
        address: settings.address,
        city: settings.city,
        phone: settings.phone,
        mobile: settings.mobile,
        email: settings.email,
        fiscal_id: settings.fiscalId,
        website: settings.website,
        rib: settings.rib,
        pharmacist_code: settings.pharmacistCode,
        delivery_fee_standard: Number(settings.deliveryFeeStandard || 0),
        delivery_fee_express: Number(settings.deliveryFeeExpress || 0),
        delivery_fee_pickup: Number(settings.deliveryFeePickup || 0)
    };

    const response = await fetch(`${supabaseUrl}company_settings`, {
        method: 'POST',
        headers: {
            ...supabaseHeaders,
            Prefer: 'resolution=merge-duplicates,return=representation'
        },
        body: JSON.stringify(payload)
    });

    if (!response.ok) {
        const errorText = await response.text();
        throw new Error(errorText || `HTTP ${response.status}`);
    }

    return response.json();
}

async function saveCompanySettingsFromForm() {
    const form = document.getElementById('company-settings-form');
    if (!form) {
        return;
    }

    const formData = new FormData(form);
    const nextSettings = {
        companyName: String(formData.get('companyName') || '').trim() || COMPANY_SETTINGS_DEFAULTS.companyName,
        subtitle: String(formData.get('subtitle') || '').trim() || COMPANY_SETTINGS_DEFAULTS.subtitle,
        address: String(formData.get('address') || '').trim(),
        city: String(formData.get('city') || '').trim(),
        phone: String(formData.get('phone') || '').trim(),
        mobile: String(formData.get('mobile') || '').trim(),
        email: String(formData.get('email') || '').trim(),
        fiscalId: String(formData.get('fiscalId') || '').trim(),
        website: String(formData.get('website') || '').trim(),
        rib: String(formData.get('rib') || '').trim(),
        pharmacistCode: String(formData.get('pharmacistCode') || '').trim(),
        deliveryFeeStandard: Number(formData.get('deliveryFeeStandard') || 0) || 0,
        deliveryFeeExpress: Number(formData.get('deliveryFeeExpress') || 0) || 0,
        deliveryFeePickup: Number(formData.get('deliveryFeePickup') || 0) || 0
    };

    localStorage.setItem(COMPANY_SETTINGS_STORAGE_KEY, JSON.stringify(nextSettings));
    companySettingsCache = {
        ...COMPANY_SETTINGS_DEFAULTS,
        ...nextSettings
    };
    try {
        await saveCompanySettingsToSupabase(nextSettings);
        companySettingsSupabaseLoaded = true;
    } catch (error) {
        console.warn('Sauvegarde Parametre societe dans Supabase impossible.', error);
    }
    if (typeof activeTabId !== 'undefined' && activeTabId === 'company_settings') {
        renderContent();
    }
    updateBackofficeLoginBranding();
    alert(companySettingsSupabaseLoaded
        ? 'Parametres societe enregistres.'
        : 'Parametres societe enregistres localement. La synchronisation Supabase a echoue.');
}

function resetCompanySettingsForm() {
    const form = document.getElementById('company-settings-form');
    if (!form) {
        return;
    }

    const defaults = { ...COMPANY_SETTINGS_DEFAULTS };
    Object.entries(defaults).forEach(([key, value]) => {
        const field = form.elements.namedItem(key);
        if (field) {
            field.value = value;
        }
    });
}

function getAdminLogoPrintUrl() {
    try {
        return new URL('logo.png', window.location.href).href;
    } catch (error) {
        console.warn('URL logo impression indisponible.', error);
        return '';
    }
}

function buildCompanyPrintMetaLines(settings) {
    const lines = [];
    const addressLine = [settings.address, settings.city].filter(Boolean).join(' - ');
    const contactLine = [settings.phone, settings.mobile].filter(Boolean).join(' / ');
    const detailLine = [settings.email, settings.website].filter(Boolean).join(' | ');

    if (addressLine) lines.push(addressLine);
    if (contactLine) lines.push(contactLine);
    if (detailLine) lines.push(detailLine);

    return lines;
}

function getCompanyFiscalId(settings = {}) {
    return String(
        settings.fiscalId
        || settings.matriculeFiscal
        || settings.matricule_fiscal
        || settings.codeTva
        || settings.code_tva
        || ''
    ).trim();
}

function buildPrintAmountWordsSentence(documentLabel, amount) {
    const normalizedLabel = String(documentLabel || '').trim().toLowerCase();
    const amountInWords = amountToFrenchCurrencyWords(amount || 0);
    if (normalizedLabel === 'ordonnance') {
        return `Arrete la presente ordonnance a la somme de : ${amountInWords}.`;
    }
    if (normalizedLabel === 'devis') {
        return `Arrete le present devis a la somme de : ${amountInWords}.`;
    }
    return `Arrete la presente facture a la somme de : ${amountInWords}.`;
}

function getAuthorizationModuleIds() {
    const groupedModules = Object.values(AUTHORIZATION_MODULE_GROUPS).flat();
    const moduleIds = Object.keys(modulesData)
        .filter(moduleId => !['dashboard', 'authorization_management', ...ADMIN_ONLY_MODULES].includes(moduleId));
    return Array.from(new Set([...groupedModules, ...moduleIds]));
}

function getDefaultBackofficeAdmin() {
    return {
        id: 'local-admin',
        username: 'admin',
        fullName: 'Administrateur',
        password: DEFAULT_ADMIN_PASSWORD,
        isAdmin: true,
        allowedModules: getAuthorizationModuleIds(),
        maxSaleDiscountPct: 100,
        isActive: true,
        createdAt: new Date().toISOString()
    };
}

function normalizeBackofficeUserRecord(record = {}) {
    const normalized = {
        id: String(record.id || `user-${Date.now()}`),
        username: String(record.username || record.login || '').trim(),
        fullName: String(record.full_name || record.fullName || '').trim(),
        password: String(record.password_text || record.password || '').trim(),
        isAdmin: Boolean(record.is_admin ?? record.isAdmin ?? false),
        allowedModules: Array.isArray(record.allowed_modules)
            ? record.allowed_modules
            : Array.isArray(record.allowedModules)
                ? record.allowedModules
                : [],
        maxSaleDiscountPct: Number(record.max_discount_pct ?? record.maxSaleDiscountPct ?? ((record.is_admin ?? record.isAdmin) ? 100 : 15)),
        isActive: Boolean(record.is_active ?? record.isActive ?? true),
        createdAt: record.created_at || record.createdAt || ''
    };
    if (!Number.isFinite(normalized.maxSaleDiscountPct) || normalized.maxSaleDiscountPct < 0) {
        normalized.maxSaleDiscountPct = normalized.isAdmin ? 100 : 15;
    }
    if (normalized.isAdmin && !normalized.password) {
        normalized.password = DEFAULT_ADMIN_PASSWORD;
    }
    if (normalized.isAdmin) {
        normalized.maxSaleDiscountPct = 100;
    }
    return normalized;
}

function getStoredBackofficeUsers() {
    try {
        const raw = localStorage.getItem(BACKOFFICE_USERS_STORAGE_KEY);
        const parsed = raw ? JSON.parse(raw) : [];
        const list = Array.isArray(parsed) ? parsed.map(normalizeBackofficeUserRecord) : [];
        return list.length > 0 ? list : [getDefaultBackofficeAdmin()];
    } catch (error) {
        console.warn('Lecture utilisateurs backoffice impossible.', error);
        return [getDefaultBackofficeAdmin()];
    }
}

function saveStoredBackofficeUsers(users) {
    localStorage.setItem(BACKOFFICE_USERS_STORAGE_KEY, JSON.stringify(Array.isArray(users) ? users : []));
}

async function loadBackofficeUsersFromSupabase() {
    const rows = await fetchCollection('backoffice_users?select=id,username,full_name,is_admin,allowedModules&order=full_name.asc,username.asc', null);
    if (!Array.isArray(rows) || rows.length === 0) {
        return null;
    }
    return rows.map(normalizeBackofficeUserRecord);
}

async function saveBackofficeUserToSupabase(user) {
    const payload = {
        id: user.id.startsWith('user-') ? undefined : user.id,
        username: user.username,
        full_name: user.fullName,
        password_text: user.password,
        is_admin: user.isAdmin,
        allowed_modules: user.allowedModules,
        max_discount_pct: Number(user.maxSaleDiscountPct ?? (user.isAdmin ? 100 : 15)),
        is_active: user.isActive
    };

    let url = `${supabaseUrl}backoffice_users`;
    let method = 'POST';
    if (user.id && !String(user.id).startsWith('user-') && user.id !== 'local-admin') {
        url += `?id=eq.${user.id}`;
        method = 'PATCH';
    }

    const response = await fetch(url, {
        method,
        headers: { ...supabaseHeaders, Prefer: 'return=representation' },
        body: JSON.stringify(payload)
    });

    if (!response.ok) {
        const errorText = await response.text();
        throw new Error(errorText || `HTTP ${response.status}`);
    }

    const returned = await response.json();
    const saved = Array.isArray(returned) ? returned[0] : returned;
    return normalizeBackofficeUserRecord(saved || user);
}

async function deleteBackofficeUserFromSupabase(userId) {
    if (!userId || userId === 'local-admin' || String(userId).startsWith('user-')) return;
    const response = await fetch(`${supabaseUrl}backoffice_users?id=eq.${userId}`, {
        method: 'DELETE',
        headers: supabaseHeaders
    });
    if (!response.ok) {
        const errorText = await response.text();
        throw new Error(errorText || `HTTP ${response.status}`);
    }
}

function getCurrentBackofficeUser() {
    const sessionId = authorizationState.currentUserId || localStorage.getItem(BACKOFFICE_SESSION_STORAGE_KEY) || '';
    return authorizationState.users.find(user => user.id === sessionId) || null;
}

function hasAuthenticatedBackofficeSession() {
    return Boolean(getCurrentBackofficeUser());
}

function setCurrentBackofficeUser(userId) {
    authorizationState.currentUserId = userId || 'local-admin';
    localStorage.setItem(BACKOFFICE_SESSION_STORAGE_KEY, authorizationState.currentUserId);
    refreshAuthorizationUi();
}

function canAccessModule(moduleId) {
    if (!moduleId) return true;
    if (!hasAuthenticatedBackofficeSession()) {
        return moduleId === 'dashboard';
    }
    if (ALWAYS_ALLOWED_MODULES.includes(moduleId)) return true;
    const currentUser = getCurrentBackofficeUser();
    if (!currentUser) return false;
    if (ADMIN_ONLY_MODULES.includes(moduleId)) return Boolean(currentUser.isAdmin);
    if (currentUser.isAdmin) return true;
    return Array.isArray(currentUser.allowedModules) && currentUser.allowedModules.includes(moduleId);
}

function getAuthorizationModuleLabel(moduleId) {
    return AUTHORIZATION_PERMISSION_LABELS[moduleId] || modulesData[moduleId]?.title || moduleId;
}

function canManageArticleAction(actionId) {
    return canAccessModule(actionId);
}

function openPreferredStartupModule(force = false) {
    const preferredModule = canAccessModule('vente') ? 'vente' : 'dashboard';
    if (!force && activeTabId && activeTabId !== 'dashboard' && activeTabId !== 'vente') {
        return;
    }
    openTab(preferredModule);
}

function extractModuleIdFromOnclick(raw = '') {
    const match = String(raw || '').match(/openTab\('([^']+)'\)/);
    return match ? match[1] : '';
}

function refreshAuthorizationUi() {
    ensureBackofficeSessionTools();
    const currentUser = getCurrentBackofficeUser();
    const isAdminUser = Boolean(currentUser?.isAdmin);

    // Gérer la classe admin-user sur le body pour les éléments admin-only
    if (isAdminUser) {
        document.body.classList.add('admin-user');
    } else {
        document.body.classList.remove('admin-user');
    }

    const configTab = document.querySelector('.ribbon-tab[data-theme="config"]');
    const configPanel = document.getElementById('panel-config');

    if (configTab) {
        configTab.style.display = isAdminUser ? '' : 'none';
    }
    if (configPanel) {
        configPanel.style.display = isAdminUser ? '' : 'none';
    }
    if (!isAdminUser && configTab?.classList.contains('active')) {
        switchRibbonTab('ventes');
    }

    document.querySelectorAll('.ribbon-button-large, .ribbon-button-small').forEach(button => {
        const moduleId = extractModuleIdFromOnclick(button.getAttribute('onclick'));
        if (!moduleId) return;
        button.style.display = canAccessModule(moduleId) ? '' : 'none';
    });

    openTabs = openTabs.filter(moduleId => canAccessModule(moduleId));
    if (activeTabId && !canAccessModule(activeTabId)) {
        activeTabId = 'dashboard';
        if (!openTabs.includes('dashboard')) openTabs.push('dashboard');
    }
    renderTabs();
    renderContent();
    updateSidebarSelection();
    updateBackofficeSessionUi();
}

async function loadBackofficeUsers() {
    let users = null;
    try {
        users = await loadBackofficeUsersFromSupabase();
    } catch (error) {
        console.warn('Chargement utilisateurs backoffice depuis Supabase impossible.', error);
    }

    authorizationState.users = Array.isArray(users) && users.length > 0
        ? users
        : getStoredBackofficeUsers();

    if (!authorizationState.users.some(user => user.isAdmin)) {
        authorizationState.users.unshift(getDefaultBackofficeAdmin());
    }

    saveStoredBackofficeUsers(authorizationState.users);
    authorizationState.currentUserId = localStorage.getItem(BACKOFFICE_SESSION_STORAGE_KEY) || '';
    ensureBackofficeLoginModal();
    refreshAuthorizationUi();
    if (!hasAuthenticatedBackofficeSession()) {
        showBackofficeLoginModal();
        return;
    }
    openPreferredStartupModule(true);
}

