function buildBackofficeModulesChecklist(selectedModules = []) {
    const target = document.getElementById('backoffice-user-modules-grid');
    if (!target) return;
    target.innerHTML = Object.entries(AUTHORIZATION_MODULE_GROUPS).map(([groupLabel, moduleIds]) => `
        <div style="border:1px solid #dbe4f0; border-radius:10px; background:#f8fbff; padding:10px;">
            <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:8px;">
                <strong style="color:#0f172a;">${escapeHtml(groupLabel)}</strong>
                <button type="button" class="small-action-btn" onclick="toggleAuthorizationGroup('${escapeHtml(groupLabel)}', true)">Tout</button>
            </div>
            <div style="display:grid; grid-template-columns:1fr; gap:6px;">
                ${moduleIds.map(moduleId => `
                    <label class="article-filter-check" style="padding:6px 8px; border:1px solid #dbe4f0; border-radius:8px; background:white;">
                        <input type="checkbox" data-group="${escapeHtml(groupLabel)}" value="${moduleId}" ${selectedModules.includes(moduleId) ? 'checked' : ''}>
                        ${escapeHtml(getAuthorizationModuleLabel(moduleId))}
                    </label>
                `).join('')}
            </div>
        </div>
    `).join('');
    toggleBackofficeModulesAccess();
}

function toggleBackofficeModulesAccess() {
    const isAdmin = document.getElementById('backoffice-user-is-admin')?.checked;
    const maxDiscountInput = document.getElementById('backoffice-user-max-discount');
    document.querySelectorAll('#backoffice-user-modules-grid input[type="checkbox"]').forEach(input => {
        input.disabled = Boolean(isAdmin);
    });
    if (maxDiscountInput) {
        maxDiscountInput.disabled = Boolean(isAdmin);
        if (isAdmin) {
            maxDiscountInput.value = '100';
        } else if (!String(maxDiscountInput.value || '').trim()) {
            maxDiscountInput.value = '15';
        }
    }
}

function toggleAuthorizationGroup(groupLabel, checked) {
    document.querySelectorAll(`#backoffice-user-modules-grid input[data-group="${groupLabel}"]`).forEach(input => {
        if (!input.disabled) input.checked = checked;
    });
}

function initAuthorizationManagementModule() {
    renderBackofficeSessionCard();
    renderBackofficeUsersTable();
}

function showBackofficeUserModal(userId = '') {
    const modal = document.getElementById('backoffice-user-modal');
    if (!modal) return;
    const user = authorizationState.users.find(item => item.id === userId);
    document.getElementById('backoffice-user-modal-title').innerText = user ? 'Modifier utilisateur' : 'Nouvel utilisateur';
    document.getElementById('backoffice-user-id').value = user?.id || '';
    document.getElementById('backoffice-user-fullname').value = user?.fullName || '';
    document.getElementById('backoffice-user-login').value = user?.username || '';
    document.getElementById('backoffice-user-password').value = user?.password || '';
    document.getElementById('backoffice-user-is-admin').checked = Boolean(user?.isAdmin);
    document.getElementById('backoffice-user-max-discount').value = String(user?.isAdmin ? 100 : Number(user?.maxSaleDiscountPct ?? 15));
    buildBackofficeModulesChecklist(Array.isArray(user?.allowedModules) ? user.allowedModules : []);
    modal.style.display = 'block';
}

function hideBackofficeUserModal() {
    const modal = document.getElementById('backoffice-user-modal');
    if (modal) modal.style.display = 'none';
}

function editBackofficeUser(userId) {
    showBackofficeUserModal(userId);
}

function activateBackofficeUser(userId) {
    setCurrentBackofficeUser(userId);
    renderBackofficeSessionCard();
    renderBackofficeUsersTable();
}

async function saveBackofficeUser() {
    const userId = document.getElementById('backoffice-user-id')?.value || '';
    const fullName = document.getElementById('backoffice-user-fullname')?.value.trim() || '';
    const username = document.getElementById('backoffice-user-login')?.value.trim() || '';
    const password = document.getElementById('backoffice-user-password')?.value.trim() || '';
    const isAdmin = Boolean(document.getElementById('backoffice-user-is-admin')?.checked);
    const maxSaleDiscountPct = Math.max(0, Math.min(100, Number(document.getElementById('backoffice-user-max-discount')?.value || (isAdmin ? 100 : 15))));
    const allowedModules = Array.from(document.querySelectorAll('#backoffice-user-modules-grid input[type="checkbox"]:checked')).map(input => input.value);

    if (!username) {
        alert('Le login est obligatoire.');
        return;
    }
    if (!password) {
        alert(isAdmin ? 'Le mot de passe administrateur est obligatoire.' : 'Le mot de passe est obligatoire.');
        return;
    }

    const user = normalizeBackofficeUserRecord({
        id: userId || `user-${Date.now()}`,
        username,
        full_name: fullName || username,
        password_text: password,
        is_admin: isAdmin,
        allowed_modules: isAdmin ? getAuthorizationModuleIds() : allowedModules,
        max_discount_pct: isAdmin ? 100 : maxSaleDiscountPct,
        is_active: true
    });

    let savedUser = user;
    try {
        savedUser = await saveBackofficeUserToSupabase(user);
    } catch (error) {
        console.warn('Sauvegarde utilisateur backoffice dans Supabase impossible.', error);
    }

    const nextUsers = authorizationState.users.filter(item => item.id !== userId && item.username !== user.username);
    nextUsers.push(savedUser);
    authorizationState.users = nextUsers.sort((a, b) => String(a.fullName || a.username).localeCompare(String(b.fullName || b.username), 'fr', { sensitivity: 'base' }));
    saveStoredBackofficeUsers(authorizationState.users);
    hideBackofficeUserModal();
    renderBackofficeSessionCard();
    renderBackofficeUsersTable();
    refreshAuthorizationUi();
}

async function deleteBackofficeUser(userId) {
    if (!userId || userId === 'local-admin') {
        alert('Le compte administrateur par defaut ne peut pas etre supprime.');
        return;
    }
    if (!confirm('Supprimer cet utilisateur ?')) return;
    try {
        await deleteBackofficeUserFromSupabase(userId);
    } catch (error) {
        console.warn('Suppression utilisateur backoffice dans Supabase impossible.', error);
    }
    authorizationState.users = authorizationState.users.filter(user => user.id !== userId);
    if (authorizationState.currentUserId === userId) {
        setCurrentBackofficeUser('local-admin');
    }
    saveStoredBackofficeUsers(authorizationState.users);
    renderBackofficeSessionCard();
    renderBackofficeUsersTable();
    refreshAuthorizationUi();
}

