const supabaseUrl = BACKEND_URL
    ? BACKEND_URL.replace(/\/+$/, '') + '/rest/v1/'
    : 'https://sckhssxmgtyqrwwsoqtk.supabase.co/rest/v1/';
const supabaseKey = 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6InNja2hzc3htZ3R5cXJ3d3NvcXRrIiwicm9sZSI6ImFub24iLCJpYXQiOjE3ODM0MDg2MDUsImV4cCI6MjA5ODk4NDYwNX0.N7M-c7HVpcJ85iFFY5xCVAOnZB6TTzRv9A2l-4Kb4kY';

// Note: On utilise fetch pour Supabase car on n'a pas chargé la lib cliente complète
const supabaseHeaders = {
    'apikey': BACKEND_URL ? '' : supabaseKey,
    'Authorization': BACKEND_URL ? '' : `Bearer ${supabaseKey}`,
    'Content-Type': 'application/json',
    'Prefer': 'return=representation'
};

async function callSupabaseRpc(functionName, payload = {}) {
    const response = await fetch(`${supabaseUrl}rpc/${functionName}`, {
        method: 'POST',
        headers: supabaseHeaders,
        body: JSON.stringify(payload || {})
    });

    if (!response.ok) {
        throw new Error(`RPC ${functionName} HTTP ${response.status}`);
    }

    return response.json();
}

function getRpcScalarValue(result, preferredKeys = []) {
    if (typeof result === 'string' || typeof result === 'number') return result;
    if (result === null || typeof result === 'undefined') return '';
    if (Array.isArray(result)) {
        if (!result.length) return '';
        return getRpcScalarValue(result[0], preferredKeys);
    }
    for (const key of preferredKeys) {
        if (Object.prototype.hasOwnProperty.call(result, key)) {
            return result[key];
        }
    }
    const firstKey = Object.keys(result)[0];
    return firstKey ? result[firstKey] : '';
}

function generateLegacyPrefixedNumber(prefix = 'REF') {
    const normalizedPrefix = String(prefix || 'REF').trim().toUpperCase() || 'REF';
    const now = new Date();
    const stamp = [
        now.getFullYear(),
        String(now.getMonth() + 1).padStart(2, '0'),
        String(now.getDate()).padStart(2, '0'),
        String(now.getHours()).padStart(2, '0'),
        String(now.getMinutes()).padStart(2, '0'),
        String(now.getSeconds()).padStart(2, '0')
    ].join('');
    return `${normalizedPrefix}-${stamp}`;
}

async function requestSequentialNumber(prefix, fallbackFactory = null) {
    try {
        const result = await callSupabaseRpc('generate_prefixed_number', { prefix });
        const value = String(getRpcScalarValue(result, ['generate_prefixed_number']) || '').trim();
        if (value) return value;
    } catch (error) {
        console.warn(`Numerotation sequentielle indisponible pour ${prefix}, fallback local.`, error);
    }
    return fallbackFactory ? fallbackFactory() : generateLegacyPrefixedNumber(prefix);
}

async function peekSequentialNumber(prefix, fallbackFactory = null) {
    try {
        const result = await callSupabaseRpc('peek_prefixed_number', { prefix });
        const value = String(getRpcScalarValue(result, ['peek_prefixed_number']) || '').trim();
        if (value) return value;
    } catch (error) {
        console.warn(`Apercu numerotation sequentielle indisponible pour ${prefix}, fallback local.`, error);
    }
    return fallbackFactory ? fallbackFactory() : generateLegacyPrefixedNumber(prefix);
}

function getSaleDocumentColumnName(documentKind = '') {
    if (documentKind === 'invoice') return 'numero_facture';
    if (documentKind === 'delivery_note') return 'numero_bl';
    if (documentKind === 'quote') return 'numero_devis';
    return 'numero_vente';
}

function getSaleDocumentPrefix(documentKind = '') {
    if (documentKind === 'invoice') return 'FAC';
    if (documentKind === 'delivery_note') return 'BL';
    if (documentKind === 'quote') return 'DEV';
    return 'VTE';
}

function getSaleDocumentNumberFromSale(sale = null, documentKind = '') {
    if (!sale || typeof sale !== 'object') return '';
    const columnName = getSaleDocumentColumnName(documentKind);
    return String(sale?.[columnName] || '').trim();
}

function getSaleDocumentDisplayNumber(sale = null, documentKind = '') {
    return getSaleDocumentNumberFromSale(sale, documentKind) || String(sale?.numero_vente || '').trim();
}

async function ensureSaleDocumentNumber(sale = null, documentKind = '') {
    const fallbackValue = getSaleDocumentDisplayNumber(sale, documentKind) || generateLegacyPrefixedNumber(getSaleDocumentPrefix(documentKind));
    if (!sale?.id) return fallbackValue;

    const existingValue = getSaleDocumentNumberFromSale(sale, documentKind);
    if (existingValue) return existingValue;

    try {
        const result = await callSupabaseRpc('assign_sale_document_number', {
            p_sale_id: sale.id,
            p_doc_type: getSaleDocumentPrefix(documentKind)
        });
        const assignedValue = String(getRpcScalarValue(result, ['assign_sale_document_number']) || '').trim();
        if (assignedValue) {
            sale[getSaleDocumentColumnName(documentKind)] = assignedValue;
            return assignedValue;
        }
    } catch (error) {
        console.warn(`Affectation numero document ${documentKind} indisponible, fallback local.`, error);
    }

    return fallbackValue;
}

