// Recherche de produit (Simulation scan code-barres)
async function searchProduct(code) {
    try {
        const response = await fetch(`${supabaseUrl}products?code_article=eq.${code}&select=id,code_article,code_barre,designation,forme,stock_actuel,prix_vente_ttc,tva,prix_achat_ht,prix_vente_web_ttc,prix_vente_passager_ttc,marge,remise_web_pct,peremption,image_url,code_pct`, {
            headers: supabaseHeaders
        });
        const data = await response.json();
        return data.length > 0 ? data[0] : null;
    } catch (error) {
        console.error("Erreur recherche produit:", error);
        return null;
    }
}

// Ajout d'une ligne à la vente
async function addSaleItem(code) {
    const product = await searchProduct(code);
    if (!product) {
        alert("Produit non trouvé !");
        return;
    }

    const tbody = document.getElementById('pos-items-body');
    if (!tbody) return;

    // Supprimer la ligne vide si elle existe
    if (tbody.innerHTML.includes('&nbsp;')) {
        tbody.innerHTML = '';
    }

    const row = document.createElement('tr');
    const totalLine = product.prix_vente_ttc;
    row.innerHTML = `
        <td>${product.code_article}</td>
        <td>${product.designation}</td>
        <td>${product.forme || '-'}</td>
        <td><input type="number" value="1" class="field-input small" onchange="calculateSaleTotals()"></td>
        <td>${product.stock_actuel}</td>
        <td>${product.peremption || '-'}</td>
        <td>${product.prix_vente_ttc.toFixed(3)}</td>
        <td class="line-total">${totalLine.toFixed(3)}</td>
        <td>${product.tva}%</td>
        <td>0.000</td>
        <td>-</td>
    `;
    tbody.appendChild(row);
    calculateSaleTotals();
}

// Calcul des totaux de la vente
function calculateSaleTotals() {
    let totalTTC = 0;
    const lines = document.querySelectorAll('#pos-items-body tr');

    lines.forEach(line => {
        const qteInput = line.querySelector('input[type="number"]');
        if (qteInput) {
            const qte = parseFloat(qteInput.value);
            const price = parseFloat(line.cells[6].innerText);
            const lineTotal = qte * price;
            line.querySelector('.line-total').innerText = lineTotal.toFixed(3);
            totalTTC += lineTotal;
        }
    });

    const netEl = document.getElementById('pos-total-net');
    const bigTotalEl = document.getElementById('pos-big-total');
    if (netEl) netEl.value = totalTTC.toFixed(3);
    if (bigTotalEl) bigTotalEl.innerText = totalTTC.toFixed(3);
}

// Enregistrement de la vente dans Supabase
async function saveSale() {
    const lines = document.querySelectorAll('#pos-items-body tr');
    if (lines.length === 0 || lines[0].innerHTML.includes('&nbsp;')) {
        alert("La vente est vide !");
        return;
    }

    const totalTTC = parseFloat(document.getElementById('pos-total-net').value);

    // 1. Créer la vente
    const saleData = {
        total_ttc: totalTTC,
        statut: 'Validé'
    };

    try {
        const response = await fetch(`${supabaseUrl}sales`, {
            method: 'POST',
            headers: supabaseHeaders,
            body: JSON.stringify(saleData)
        });

        if (response.ok) {
            alert("Vente enregistrée avec succès !");
            openTab('vente'); // Reset via template refresh
        }
    } catch (error) {
        alert("Erreur lors de l'enregistrement !");
    }
}

async function loadReport(type) {
    let endpoint = 'sales';
    let fields = 'id,numero_vente,date_vente,mode,total_ttc,total_ht,client_id';
    if (type === 'Inventaire' || type === 'Fichier Articles' || type === 'Articles Web') { endpoint = 'products'; fields = 'id,code_article,code_barre,designation,forme,stock_actuel,prix_vente_ttc,tva,prix_achat_ht'; }
    if (type === 'Commandes E-commerce') { endpoint = 'web_orders'; fields = 'id,order_number,customer_name,status,total_ttc,created_at'; }

    try {
        const response = await fetch(`${supabaseUrl}${endpoint}?select=${fields}`, {
            headers: supabaseHeaders
        });
        const data = await response.json();
        renderReportTable(data, type);
    } catch (error) {
        console.error('Erreur rapport:', error);
    }
}

function renderReportTable(data, type) {
    const tbody = document.getElementById('report-table-body');
    if (!tbody) return;

    if (data.length === 0) {
        tbody.innerHTML = '<tr><td colspan="6" style="text-align:center; padding: 40px;">Aucune donnée trouvée.</td></tr>';
        return;
    }

    let totalGeral = 0;
    const isWeb = type === 'Commandes E-commerce';

    tbody.innerHTML = data.map(item => {
        const total = item.total_ttc || item.prix_vente_ttc || 0;
        totalGeral += total;

        if (isWeb) {
            let statusClass = 'gray';
            if (item.status === 'Nouvelle') statusClass = 'blue';
            if (item.status === 'En préparation') statusClass = 'yellow';
            if (item.status === 'Expédiée') statusClass = 'green';

            return `
                <tr>
                    <td style="font-weight: 600;">${item.order_number}</td>
                    <td>${new Date(item.created_at).toLocaleString('fr-FR')}</td>
                    <td>${item.customer_name}</td>
                    <td style="text-align: right; font-weight: 600;">${total.toFixed(3)}</td>
                    <td><span class="badge ${statusClass}">${item.status}</span></td>
                    <td>
                        <button class="small-action-btn">Détails</button>
                        ${item.status === 'Nouvelle' ? '<button class="small-action-btn green">Valider</button>' : ''}
                    </td>
                </tr>
            `;
        }

        return `
            <tr>
                <td>${new Date(item.date_vente || item.created_at).toLocaleString('fr-FR')}</td>
                <td>${item.numero_vente || item.code_article || '-'}</td>
                <td>${item.customers?.nom || item.designation || 'CLIENT PASSAGER'}</td>
                <td>${item.mutuelle_id ? 'MUTUELLE' : 'COMPTANT'}</td>
                <td style="text-align: right; font-weight: 600;">${total.toFixed(3)}</td>
                <td><span class="badge ${item.statut === 'Validé' ? 'green' : 'gray'}">${item.statut || (item.stock_actuel !== undefined ? item.stock_actuel + ' en stock' : 'Actif')}</span></td>
            </tr>
        `;
    }).join('');

    const totalEl = document.getElementById('report-total-ttc');
    const countEl = document.getElementById('report-total-count');
    if (totalEl) totalEl.innerText = totalGeral.toFixed(3) + ' DT';
    if (countEl) countEl.innerText = data.length;
}

function isKeyboardDateInput(element) {
    return element instanceof HTMLInputElement && ['date', 'datetime-local'].includes(element.type);
}

function getDateInputLabelText(input) {
    const escapedId = input.id && window.CSS?.escape ? window.CSS.escape(input.id) : '';
    const explicitLabel = escapedId ? document.querySelector(`label[for="${escapedId}"]`) : null;
    const nearbyLabel = input.closest('.recap-caisse-inline-field, .filter-field, .filter-item, .mouv-field, .date-field, div')?.querySelector('label');
    return String((explicitLabel || nearbyLabel)?.textContent || '').trim().toLowerCase();
}

function isDatePeriodEndInput(input) {
    const id = input.id || '';
    if (/(?:-to|_to|To|-au|_au)$/u.test(id)) return true;
    const labelText = getDateInputLabelText(input).replace(/\s+/g, ' ');
    return /^(au|à|a)\s*:?$/u.test(labelText);
}

function resolveDatePeriodPeer(input, direction) {
    if (!isKeyboardDateInput(input)) return null;

    const id = input.id || '';
    const replacements = direction === 'next'
        ? [['-from', '-to'], ['_from', '_to'], ['From', 'To'], ['-du', '-au'], ['_du', '_au']]
        : [['-to', '-from'], ['_to', '_from'], ['To', 'From'], ['-au', '-du'], ['_au', '_du']];

    for (const [source, target] of replacements) {
        if (id.endsWith(source)) {
            const peer = document.getElementById(`${id.slice(0, -source.length)}${target}`);
            if (isKeyboardDateInput(peer)) return peer;
        }
    }

    const scope = input.closest('.tax-report-filter-card, .modal-content, .table-filters, .filter-panel, .content-area') || document;
    const periodInputs = Array.from(scope.querySelectorAll('input[type="date"], input[type="datetime-local"]'))
        .filter(isKeyboardDateInput);
    const index = periodInputs.indexOf(input);
    if (index === -1) return null;

    const labelText = getDateInputLabelText(input).replace(/\s+/g, ' ');
    if (direction === 'next' && /^(du|de)\s*:?$/u.test(labelText)) {
        return periodInputs.slice(index + 1).find(dateInput => /^(au|à|a)\s*:?$/u.test(getDateInputLabelText(dateInput).replace(/\s+/g, ' '))) || periodInputs[index + 1] || null;
    }
    if (direction === 'previous' && /^(au|à|a)\s*:?$/u.test(labelText)) {
        return periodInputs.slice(0, index).reverse().find(dateInput => /^(du|de)\s*:?$/u.test(getDateInputLabelText(dateInput).replace(/\s+/g, ' '))) || periodInputs[index - 1] || null;
    }

    return direction === 'next' ? periodInputs[index + 1] || null : periodInputs[index - 1] || null;
}

function focusDatePeriodPeer(input, direction) {
    const peer = resolveDatePeriodPeer(input, direction);
    if (!peer || peer.disabled || peer.readOnly) return false;

    peer.focus();
    window.requestAnimationFrame(() => peer.select?.());
    return true;
}

function focusNextKeyboardField(input) {
    const fields = Array.from(document.querySelectorAll(
        'input:not([type="hidden"]), select, textarea, button'
    )).filter(element =>
        !element.disabled
        && element.offsetParent !== null
        && element.tabIndex !== -1
    );
    const index = fields.indexOf(input);
    const nextField = index >= 0 ? fields[index + 1] : null;
    if (!nextField) return false;

    nextField.focus();
    return true;
}

function handleDatePeriodKeyboard(event) {
    if (!['Enter', 'NumpadEnter'].includes(event.key) || event.ctrlKey || event.altKey || event.metaKey) return;
    if (!isKeyboardDateInput(event.target)) return;

    const input = event.target;
    const isEndDate = isDatePeriodEndInput(input);
    event.preventDefault();

    input.dispatchEvent(new Event('change', { bubbles: true }));

    if (!isEndDate && focusDatePeriodPeer(input, 'next')) return;
    focusNextKeyboardField(input);
}

document.addEventListener('DOMContentLoaded', () => {
    bootstrapApplication();
});

document.addEventListener('keydown', handleDatePeriodKeyboard, true);
document.addEventListener('keydown', handleGlobalTabCloseShortcut);

window.openTab = function (moduleId) {
    if (!modulesData[moduleId]) return;
    if (!canAccessModule(moduleId)) {
        alert('Acces refuse a ce module pour l utilisateur actif.');
        return;
    }
    if (moduleId === 'utilitaire' && !utilityModuleUnlocked) {
        const providedPassword = window.prompt('Mot de passe requis pour acceder au module Utilitaire :', '') || '';
        if (String(providedPassword).trim() !== UTILITY_MODULE_PASSWORD) {
            alert('Mot de passe incorrect.');
            return;
        }
        utilityModuleUnlocked = true;
    }

    if (!openTabs.includes(moduleId)) {
        openTabs.push(moduleId);
    }

    activeTabId = moduleId;
    renderTabs();
    renderContent();
    updateSidebarSelection();
};

window.closeTab = function (moduleId, event) {
    if (event) event.stopPropagation();
    openTabs = openTabs.filter(id => id !== moduleId);

    if (activeTabId === moduleId) {
        activeTabId = openTabs.length > 0 ? openTabs[openTabs.length - 1] : null;
    }

    renderTabs();
    renderContent();
    updateSidebarSelection();
};

window.closeActiveTab = function (event) {
    if (event) event.stopPropagation();
    if (!activeTabId) return;
    closeTab(activeTabId, event);
};

function handleGlobalTabCloseShortcut(event) {
    if (event.defaultPrevented) return;
    if (event.key !== 'F12') return;
    if (!activeTabId) return;
    if (activeTabId === 'vente' && (
        isSalePaymentModalOpen()
        || isSalePrintChoiceModalOpen()
        || isSaleFridgeModalOpen()
        || isSaleFrigoListModalOpen()
        || isSaleCustomerSettlementModalOpen()
    )) return;
    event.preventDefault();
    closeActiveTab(event);
}

window.closeAllTabs = function (event) {
    if (event) event.stopPropagation();
    const protectedActiveTab = ['vente', 'achat'].includes(activeTabId) ? activeTabId : null;
    openTabs = protectedActiveTab ? [protectedActiveTab] : [];
    activeTabId = protectedActiveTab;
    renderTabs();
    renderContent();
    updateSidebarSelection();
};

function renderTabs() {
    const tabsBar = document.getElementById('tabs-bar');
    if (!tabsBar) return;
    tabsBar.innerHTML = '';

    openTabs.forEach(id => {
        const tab = document.createElement('div');
        tab.className = 'tab' + (id === activeTabId ? ' active' : '');
        tab.dataset.theme = getOpenTabTheme(id);
        tab.onclick = () => {
            activeTabId = id;
            renderTabs();
            renderContent();
            updateSidebarSelection();
        };

        tab.innerHTML = modulesData[id].title + ' <span class="close-tab" onclick="closeTab(\'' + id + '\', event)">×</span>';
        tabsBar.appendChild(tab);
    });

    const closeAllButton = document.createElement('button');
    closeAllButton.type = 'button';
    closeAllButton.className = 'close-all-tabs-btn';
    closeAllButton.textContent = 'FERMER TOUS LES ONGLETS';
    closeAllButton.disabled = openTabs.length === 0;
    closeAllButton.onclick = event => closeAllTabs(event);

    const closeActiveButton = document.createElement('button');
    closeActiveButton.type = 'button';
    closeActiveButton.className = 'close-active-tab-btn';
    closeActiveButton.textContent = 'FERMER F12';
    closeActiveButton.disabled = !activeTabId;
    closeActiveButton.onclick = event => closeActiveTab(event);
    tabsBar.appendChild(closeActiveButton);
}

function getOpenTabTheme(moduleId) {
    if (moduleId === 'dashboard') return 'accueil';
    if (['vente', 'suppression_vente', 'vente_articles', 'vente_frigo', 'etat_ventes', 'journal_ventes', 'mouv_clients', 'gestion_clients', 'recap_caisse', 'reglement_client'].includes(moduleId)) return 'ventes';
    if (['achat', 'suppression_achat', 'hist_achats', 'hist_gratuite_achat', 'gestion_fournisseurs', 'mouv_fourn'].includes(moduleId)) return 'achats';
    if (['article', 'inventaire', 'rayonnage_intelligent', 'stock_peremption', 'entree_stock', 'sortie_stock', 'hit_parade', 'stock_pret', 'stock_emprunt', 'stock_entree', 'stock_sortie', 'hist_pret_emprunt'].includes(moduleId)) return 'stocks';
    if (['releve_mutuelle', 'etat_mutuelles'].includes(moduleId)) return 'mutuelles';
    if (['import_public_catalog', 'web_orders', 'web_delivery_fees', 'web_categories'].includes(moduleId)) return 'ecommerce';
    if (['company_settings', 'action_history', 'authorization_management', 'import_articles', 'parametres', 'system_reset', 'sequence_reset', 'utilitaire'].includes(moduleId)) return 'config';
    return 'default';
}

function renderContent() {
    const contentArea = document.getElementById('tab-content');
    if (!contentArea) return;

    if (!activeTabId) {
        contentArea.innerHTML = `
            <div class="welcome-screen">
                <h2>Système de Gestion Centralisé</h2>
                <p>Sélectionnez un module dans la barre d'outils ou l'arborescence pour commencer.</p>
            </div>
        `;
        return;
    }

    contentArea.innerHTML = modulesData[activeTabId].content;

    if (activeTabId === 'recap_caisse') {
        setTimeout(() => loadCaisseRecap(), 50);
    }
}

function bootstrapApplication() {
    const appMode = document.body?.dataset?.app || 'admin';
    if (appMode === 'public-store') {
        initPublicStorefrontApp();
        return;
    }

    initApp();
}

function initPublicStorefrontApp() {
    const root = document.getElementById('public-store-root');
    if (!root) return;
    root.innerHTML = webStorefrontTemplate();
}

function updateSidebarSelection() {
    document.querySelectorAll('.tree-leaf').forEach(leaf => leaf.classList.remove('active'));
    if (activeTabId) {
        const leaves = Array.from(document.querySelectorAll('.tree-leaf'));
        const activeLeaf = leaves.find(l => l.getAttribute('onclick') && l.getAttribute('onclick').includes(activeTabId));
        if (activeLeaf) activeLeaf.classList.add('active');
    }
}

function updateClock() {
    const clockEl = document.getElementById('clock');
    if (clockEl) {
        const now = new Date();
        clockEl.textContent = now.toLocaleTimeString();
    }
}

