async function initWebOrdersAdmin() {
    window.SUPABASE_CACHE?.invalidate?.('web_orders');
    webStoreState.adminTab = 'orders';
    if (webOrderAlertState.openPendingOnNextModuleLoad) {
        applyWebOrderNotificationModuleFilters();
        webOrderAlertState.openPendingOnNextModuleLoad = false;
    }

    try {
        await loadWebStoreOrders();
        if (hasPendingWebOrdersForAdmin()) {
            applyWebOrderNotificationModuleFilters();
        }
    } catch (error) {
        console.error('Erreur chargement commandes web:', error);
        renderWebStoreOrdersLoadError(error);
    }
}

function refreshWebStoreOrders() {
    window.SUPABASE_CACHE?.invalidate?.('web_orders');
    loadWebStoreOrders();
}

function switchWebOrdersAdminTab(tab = 'orders') {
    webStoreState.adminTab = tab === 'stats' ? 'stats' : 'orders';
    const ordersTab = document.getElementById('web-orders-admin-orders-tab');
    const statsTab = document.getElementById('web-orders-admin-stats-tab');
    const ordersButton = document.getElementById('web-orders-admin-tab-orders');
    const statsButton = document.getElementById('web-orders-admin-tab-stats');
    if (ordersTab) ordersTab.style.display = webStoreState.adminTab === 'orders' ? '' : 'none';
    if (statsTab) statsTab.style.display = webStoreState.adminTab === 'stats' ? '' : 'none';
    if (ordersButton) ordersButton.classList.toggle('active', webStoreState.adminTab === 'orders');
    if (statsButton) statsButton.classList.toggle('active', webStoreState.adminTab === 'stats');
    if (webStoreState.adminTab === 'stats') loadWebSalesHistory();
}

let _webSalesHistoryAllRows = [];

async function loadWebSalesHistory() {
    const tbody = document.getElementById('web-sales-history-body');
    if (!tbody) return;
    tbody.innerHTML = '<tr><td colspan="7" style="text-align:center;padding:40px;color:#64748b;">Chargement...</td></tr>';

    const from = document.getElementById('web-hist-from')?.value || '';
    const to = document.getElementById('web-hist-to')?.value || '';

    try {
        let url = 'web_orders?select=id,order_number,customer_name,customer_phone,customer_email,customer_address,notes,delivery_mode,payment_mode,delivery_fee_ttc,total_ttc,status,stock_decremented,created_at&order=created_at.desc';
        if (from) url += `&created_at=gte.${from}T00:00:00`;
        if (to)   url += `&created_at=lte.${to}T23:59:59`;
        const rows = await fetchCollection(url, []);
        _webSalesHistoryAllRows = Array.isArray(rows) ? rows : [];
        filterWebSalesHistoryTable();
    } catch(e) {
        tbody.innerHTML = `<tr><td colspan="9" style="text-align:center;padding:40px;color:#dc2626;">${escapeHtml(String(e.message || e))}</td></tr>`;
    }
}

function filterWebSalesHistoryTable() {
    const tbody = document.getElementById('web-sales-history-body');
    if (!tbody) return;
    const search = (document.getElementById('web-hist-search')?.value || '').toLowerCase().trim();
    const status = (document.getElementById('web-hist-status')?.value || '').toLowerCase().trim();

    const filtered = _webSalesHistoryAllRows.filter(o => {
        if (status && String(o.status || '').toLowerCase() !== status) return false;
        if (search) {
            const hay = [o.customer_name, o.customer_phone, o.order_number].map(v => String(v||'').toLowerCase()).join(' ');
            if (!hay.includes(search)) return false;
        }
        return true;
    });

    const totalTtc = filtered.reduce((s, o) => s + Number(o.total_ttc || 0), 0);
    const totalTva = filtered.reduce((s, o) => s + Number(o.total_tva || (Number(o.total_ttc||0) - Number(o.total_ht||0))), 0);
    const avg = filtered.length ? totalTtc / filtered.length : 0;

    const badge = document.getElementById('web-hist-count-badge');
    const kpiCount = document.getElementById('web-hist-kpi-count');
    const kpiTtc = document.getElementById('web-hist-kpi-ttc');
    const kpiTva = document.getElementById('web-hist-kpi-tva');
    const kpiAvg = document.getElementById('web-hist-kpi-avg');
    if (badge) badge.textContent = `${filtered.length} vente${filtered.length > 1 ? 's' : ''}`;
    if (kpiCount) kpiCount.textContent = filtered.length;
    if (kpiTtc)  kpiTtc.textContent = formatMoney(totalTtc) + ' DT';
    if (kpiTva)  kpiTva.textContent = formatMoney(totalTva) + ' DT';
    if (kpiAvg)  kpiAvg.textContent = formatMoney(avg) + ' DT';

    const statusColors = {
        nouvelle:    { bg: '#dbeafe', color: '#1d4ed8' },
        preparation: { bg: '#fef9c3', color: '#92400e' },
        expediee:    { bg: '#dcfce7', color: '#166534' },
        annulee:     { bg: '#fee2e2', color: '#991b1b' },
    };
    const rowColors = ['#f8fafc', '#ffffff'];

    if (!filtered.length) {
        tbody.innerHTML = '<tr><td colspan="7" style="text-align:center;padding:40px;color:#64748b;">Aucune vente trouvee.</td></tr>';
        return;
    }

    tbody.innerHTML = filtered.map((o, idx) => {
        const totalTtcRow = Number(o.total_ttc || 0);
        const st = String(o.status || 'nouvelle').toLowerCase();
        const sc = statusColors[st] || { bg: '#f1f5f9', color: '#475569' };
        const bg = rowColors[idx % 2];
        const date = o.created_at ? new Date(o.created_at).toLocaleString('fr-FR') : '-';
        return `<tr style="background:${bg}; transition:background 0.15s;" onmouseover="this.style.background='#e0f2fe'" onmouseout="this.style.background='${bg}'">
            <td style="border:none;padding:10px 14px;font-size:13px;color:#475569;">${date}</td>
            <td style="border:none;padding:10px 14px;font-size:13px;font-weight:700;color:#0f172a;">${escapeHtml(o.order_number||'-')}</td>
            <td style="border:none;padding:10px 14px;font-size:13px;font-weight:600;color:#1e3a5f;">${escapeHtml(o.customer_name||'-')}</td>
            <td style="border:none;padding:10px 14px;font-size:13px;color:#64748b;">${escapeHtml(o.customer_phone||'-')}</td>
            <td style="border:none;padding:10px 14px;font-size:14px;font-weight:900;text-align:right;color:#16a34a;">${formatMoney(totalTtcRow)} DT</td>
            <td style="border:none;padding:10px 14px;text-align:center;">
                <span style="background:${sc.bg};color:${sc.color};padding:3px 10px;border-radius:20px;font-size:11px;font-weight:800;white-space:nowrap;">${escapeHtml(st.charAt(0).toUpperCase()+st.slice(1))}</span>
            </td>
            <td style="border:none;padding:8px 10px;text-align:center;white-space:nowrap;">
                <button type="button" onclick="openWebStoreOrderDetail('${o.id}')" style="background:#3b82f6;color:#fff;border:none;border-radius:7px;padding:5px 10px;font-size:11px;font-weight:700;cursor:pointer;margin-right:4px;">📋 Détails</button>
                <button type="button" onclick="printWebStoreOrder('${o.id}')" style="background:#0f172a;color:#fff;border:none;border-radius:7px;padding:5px 10px;font-size:11px;font-weight:700;cursor:pointer;">🖨️ Facture</button>
            </td>
        </tr>`;
    }).join('');
}

