function getConfiguredDeliveryFeeByMode(mode = '') {
    const settings = getCompanySettings();
    const normalizedMode = normalizeWebOrderText(mode);
    if (normalizedMode.includes('express')) return Number(settings.deliveryFeeExpress || 0);
    if (normalizedMode.includes('retrait')) return Number(settings.deliveryFeePickup || 0);
    return Number(settings.deliveryFeeStandard || 0);
}

async function saveWebDeliveryFeeDefaults() {
    const nextSettings = {
        ...getCompanySettings(),
        deliveryFeeStandard: Number(document.getElementById('delivery-fee-standard')?.value || 0) || 0,
        deliveryFeeExpress: Number(document.getElementById('delivery-fee-express')?.value || 0) || 0,
        deliveryFeePickup: Number(document.getElementById('delivery-fee-pickup')?.value || 0) || 0
    };

    localStorage.setItem(COMPANY_SETTINGS_STORAGE_KEY, JSON.stringify(nextSettings));
    companySettingsCache = {
        ...COMPANY_SETTINGS_DEFAULTS,
        ...nextSettings
    };

    try {
        await saveCompanySettingsToSupabase(nextSettings);
        companySettingsSupabaseLoaded = true;
    } catch (error) {
        console.warn('Sauvegarde montants livraison impossible.', error);
        alert(`Montants enregistres localement, mais la synchronisation Supabase a echoue.\n\nDetail: ${getSupabaseErrorMessage(error)}`);
        return;
    }

    if (activeTabId === 'web_delivery_fees') {
        renderContent();
    }
    alert('Montants des frais de livraison enregistres.');
}

async function initWebDeliveryFeesModule() {
    await loadWebDeliveryFeesModule();
}

async function loadWebDeliveryFeesModule() {
    await loadWebStoreOrders();
    const history = await fetchCollection('web_order_delivery_history?select=order_id&order=created_at.desc', []);
    const historyCountByOrder = new Map();
    (Array.isArray(history) ? history : []).forEach(item => {
        const key = String(item.order_id || '');
        if (!key) return;
        historyCountByOrder.set(key, (historyCountByOrder.get(key) || 0) + 1);
    });

    webStoreState.deliveryFeeRows = (Array.isArray(webStoreState.recentOrders) ? webStoreState.recentOrders : []).map(order => ({
        ...order,
        deliveryHistoryCount: historyCountByOrder.get(String(order.id || '')) || 0
    }));
    renderWebDeliveryFeesTable();
}

function renderWebDeliveryFeesTable() {
    const tbody = document.getElementById('web-delivery-fees-body');
    if (!tbody) return;

    const searchValue = normalizeWebOrderText(document.getElementById('web-delivery-fee-search')?.value || '');
    const rows = (Array.isArray(webStoreState.deliveryFeeRows) ? webStoreState.deliveryFeeRows : []).filter(item => {
        if (!searchValue) return true;
        return [
            item.order_number,
            item.customer_name,
            item.customer_phone,
            item.delivery_mode
        ].some(value => normalizeWebOrderText(value).includes(searchValue));
    });

    const countNode = document.getElementById('web-delivery-fees-count');
    const sumNode = document.getElementById('web-delivery-fees-sum');
    const historyCountNode = document.getElementById('web-delivery-fees-history-count');
    if (countNode) countNode.innerText = String(rows.length);
    if (sumNode) sumNode.innerText = `${formatMoney(rows.reduce((sum, item) => sum + getWebOrderDeliveryFee(item), 0))} DT`;
    if (historyCountNode) historyCountNode.innerText = String(rows.reduce((sum, item) => sum + Number(item.deliveryHistoryCount || 0), 0));

    if (rows.length === 0) {
        tbody.innerHTML = '<tr><td colspan="10" style="text-align:center; padding:32px;">Aucune commande trouvee.</td></tr>';
        return;
    }

    tbody.innerHTML = rows.map(item => `
        <tr>
            <td style="font-weight:700;">${escapeHtml(item.order_number || '-')}</td>
            <td>${item.created_at ? new Date(item.created_at).toLocaleString('fr-FR') : '-'}</td>
            <td>${escapeHtml(item.customer_name || '-')}</td>
            <td>${escapeHtml(item.customer_phone || '-')}</td>
            <td>${escapeHtml(item.delivery_mode || 'Livraison standard')}</td>
            <td style="text-align:right;">${formatMoney(getWebOrderSubtotal(item))} DT</td>
            <td style="text-align:right; font-weight:800; color:#0f766e;">${formatMoney(getWebOrderDeliveryFee(item))} DT</td>
            <td style="text-align:right; font-weight:700;">${formatMoney(item.total_ttc || 0)} DT</td>
            <td style="text-align:center;">${Number(item.deliveryHistoryCount || 0)}</td>
            <td>
                <button type="button" class="small-action-btn" onclick="openWebStoreOrderDetail('${item.id}')">Modifier frais</button>
            </td>
        </tr>
    `).join('');
}

