async function initWebStorefront() {
    if (!Array.isArray(allManagedWebCategories) || allManagedWebCategories.length === 0) {
        allManagedWebCategories = await fetchCollection('web_categories?select=id,parent_id,name,slug,sort_order,is_active&is_active=eq.true&order=sort_order.asc,name.asc', []);
    }
    webStoreState.products = await fetchWebStoreProducts();
    webStoreState.categories = getWebStoreCategories(webStoreState.products);
    await loadWebStoreOrders();
    refreshWebStoreProducts();
    renderWebStoreCart();
}

function getWebStoreCategories(products) {
    const usedSlugs = Array.from(new Set((products || []).map(item => String(item.web_category_slug || '').trim()).filter(Boolean)));
    const categories = usedSlugs.map(slug => ({
        id: slug,
        label: getManagedWebCategoryLeafLabel(slug)
    })).sort((a, b) => a.label.localeCompare(b.label, 'fr', { sensitivity: 'base' }));

    return [{ id: 'all', label: 'Tous' }, ...categories];
}

async function refreshWebStorefront() {
    await initWebStorefront();
}

function handleWebStoreSearch(event) {
    webStoreState.query = event.target.value || '';
    webStoreState.filteredSearchProducts = getFilteredWebStoreSearchProducts(webStoreState.query);
    webStoreState.highlightedSearchIndex = webStoreState.filteredSearchProducts.length > 0 ? 0 : -1;
    renderWebStoreSearchSuggestions();
    refreshWebStoreProducts();
}

function getFilteredWebStoreSearchProducts(searchTerm) {
    const normalized = normalizeSearchText(searchTerm);
    if (!normalized) return (webStoreState.products || []).slice(0, 8);

    return (webStoreState.products || [])
        .filter(product => [
            product.code_article,
            product.code_barre,
            product.designation,
            product.forme,
            getManagedWebCategoryLabel(product.web_category_slug)
        ].some(value => normalizeSearchText(value).includes(normalized)))
        .slice(0, 10);
}

function renderWebStoreSearchSuggestions() {
    const container = document.getElementById('web-store-search-suggestions');
    if (!container) return;

    if (!webStoreState.filteredSearchProducts.length) {
        container.innerHTML = '<div class="sale-autocomplete-item empty">Aucun produit trouve</div>';
        container.style.display = webStoreState.query ? 'block' : 'none';
        return;
    }

    container.innerHTML = webStoreState.filteredSearchProducts.map((product, index) => `
        <button
            type="button"
            class="sale-autocomplete-item ${index === webStoreState.highlightedSearchIndex ? 'active' : ''}"
            onmousedown="chooseWebStoreSearchSuggestion(${index})"
        >
            <span class="code">${escapeHtml(product.code_article || '-')}</span>
            <span class="label">${escapeHtml(product.designation || '-')}</span>
        </button>
    `).join('');
    container.style.display = 'block';
}

function closeWebStoreSearchSuggestions() {
    const container = document.getElementById('web-store-search-suggestions');
    if (container) {
        container.style.display = 'none';
    }
}

function chooseWebStoreSearchSuggestion(index) {
    const product = webStoreState.filteredSearchProducts[index];
    if (!product) return;

    const searchInput = document.getElementById('web-store-search');
    webStoreState.query = product.designation || '';
    if (searchInput) searchInput.value = webStoreState.query;
    closeWebStoreSearchSuggestions();
    refreshWebStoreProducts();
    openWebStoreProductDetail(product.id);
}

function handleWebStoreSearchKeydown(event) {
    if (event.key === 'ArrowDown') {
        event.preventDefault();
        webStoreState.filteredSearchProducts = webStoreState.filteredSearchProducts.length
            ? webStoreState.filteredSearchProducts
            : getFilteredWebStoreSearchProducts(event.target.value);
        if (!webStoreState.filteredSearchProducts.length) return;
        webStoreState.highlightedSearchIndex = Math.min(
            webStoreState.highlightedSearchIndex + 1,
            webStoreState.filteredSearchProducts.length - 1
        );
        renderWebStoreSearchSuggestions();
        return;
    }

    if (event.key === 'ArrowUp') {
        event.preventDefault();
        if (!webStoreState.filteredSearchProducts.length) return;
        webStoreState.highlightedSearchIndex = Math.max(webStoreState.highlightedSearchIndex - 1, 0);
        renderWebStoreSearchSuggestions();
        return;
    }

    if (event.key === 'Enter') {
        event.preventDefault();
        if (webStoreState.highlightedSearchIndex >= 0 && webStoreState.filteredSearchProducts[webStoreState.highlightedSearchIndex]) {
            chooseWebStoreSearchSuggestion(webStoreState.highlightedSearchIndex);
            return;
        }
        refreshWebStoreProducts();
        closeWebStoreSearchSuggestions();
        return;
    }

    if (event.key === 'Escape') {
        closeWebStoreSearchSuggestions();
    }
}

function handleWebStoreSortChange(event) {
    webStoreState.sort = event.target.value || 'featured';
    refreshWebStoreProducts();
}

function setWebStoreCategory(categoryId) {
    webStoreState.activeCategory = categoryId || 'all';
    refreshWebStoreProducts();
}

function scrollWebStoreToProducts() {
    document.getElementById('web-store-products-anchor')?.scrollIntoView({ behavior: 'smooth', block: 'start' });
}

function refreshWebStoreProducts() {
    const query = normalizeSearchText(webStoreState.query);
    let rows = webStoreState.products.filter(product => {
        const matchesCategory = webStoreState.activeCategory === 'all'
            || String(product.web_category_slug || '').trim() === webStoreState.activeCategory;
        if (!matchesCategory) return false;
        if (!query) return true;
        return [
            product.code_article,
            product.code_barre,
            product.designation,
            product.forme,
            getManagedWebCategoryLabel(product.web_category_slug)
        ].some(value => normalizeSearchText(value).includes(query));
    });

    if (webStoreState.sort === 'price_asc') {
        rows = rows.sort((a, b) => getProductWebPriceTtc(a) - getProductWebPriceTtc(b));
    } else if (webStoreState.sort === 'price_desc') {
        rows = rows.sort((a, b) => getProductWebPriceTtc(b) - getProductWebPriceTtc(a));
    } else if (webStoreState.sort === 'designation') {
        rows = rows.sort((a, b) => String(a.designation || '').localeCompare(String(b.designation || ''), 'fr'));
    }

    webStoreState.filteredProducts = rows;
    renderWebStoreCategories();
    renderWebStoreProducts();
}

function renderWebStoreCategories() {
    const container = document.getElementById('web-store-categories');
    if (!container) return;

    container.innerHTML = webStoreState.categories.map(category => `
        <button
            type="button"
            class="web-store-category-chip ${webStoreState.activeCategory === category.id ? 'active' : ''}"
            data-category="${escapeHtml(category.id)}"
        >${escapeHtml(category.label)}</button>
    `).join('');

    container.querySelectorAll('.web-store-category-chip').forEach(button => {
        button.addEventListener('click', () => {
            setWebStoreCategory(button.dataset.category || 'all');
        });
    });
}

function renderWebStoreProducts() {
    const grid = document.getElementById('web-store-products-grid');
    const counter = document.getElementById('web-store-product-count');
    if (!grid) return;
    if (counter) counter.innerText = `${webStoreState.filteredProducts.length} produits`;

    if (webStoreState.filteredProducts.length === 0) {
        grid.innerHTML = '<div class="web-store-empty">Aucun produit ne correspond a votre recherche.</div>';
        return;
    }

    grid.innerHTML = webStoreState.filteredProducts.map(product => {
        const stock = Number(product.stock_actuel || 0);
        const inStock = stock > 0;
        return `
            <article class="web-store-product-card">
                <div class="web-store-product-badge-row">
                    <span class="web-store-product-badge">${escapeHtml(product.forme || 'Parapharmacie')}</span>
                    <span class="web-store-product-stock ${inStock ? 'ok' : 'empty'}">${inStock ? `Stock ${stock}` : 'Sur commande'}</span>
                </div>
                <button type="button" class="web-store-product-media" onclick="openWebStoreProductDetail('${product.id}')">${getWebStoreProductMedia(product)}</button>
                <div class="web-store-product-code">${escapeHtml(product.code_article || '')}</div>
                <h4>${escapeHtml(product.designation || 'Produit')}</h4>
                <p>${escapeHtml(product.forme || 'Soin et bien-etre')} • ${product.peremption ? `Peremption ${new Date(product.peremption).toLocaleDateString('fr-FR')}` : 'Disponible en ligne'}</p>
                <div class="web-store-product-footer">
                    <div class="web-store-product-price">${formatMoney(getProductWebPriceTtc(product))} DT</div>
                    <button type="button" class="web-store-card-btn" onclick="addWebStoreProduct('${product.id}')">Ajouter</button>
                </div>
            </article>
        `;
    }).join('');
}

function addWebStoreProduct(productId) {
    const product = webStoreState.products.find(item => item.id === productId);
    if (!product) return;

    const existingLine = webStoreState.cart.find(item => item.product_id === productId);
    if (existingLine) {
        existingLine.quantity += 1;
    } else {
        webStoreState.cart.push({
            product_id: product.id,
            designation: product.designation,
            code_article: product.code_article,
            unit_price: getProductWebPriceTtc(product),
            quantity: 1
        });
    }

    renderWebStoreCart();
}

function updateWebStoreCartQuantity(productId, nextQuantity) {
    const line = webStoreState.cart.find(item => item.product_id === productId);
    if (!line) return;
    line.quantity = Math.max(1, Number(nextQuantity || 1));
    renderWebStoreCart();
}

function removeWebStoreProduct(productId) {
    webStoreState.cart = webStoreState.cart.filter(item => item.product_id !== productId);
    renderWebStoreCart();
}

function getWebStoreCartSummary() {
    return webStoreState.cart.reduce((acc, item) => {
        acc.count += Number(item.quantity || 0);
        acc.total += Number(item.unit_price || 0) * Number(item.quantity || 0);
        return acc;
    }, { count: 0, total: 0 });
}

function renderWebStoreCart() {
    const itemsContainer = document.getElementById('web-store-cart-items');
    const cartCount = document.getElementById('web-store-cart-count');
    const totalItems = document.getElementById('web-store-cart-total-items');
    const subtotal = document.getElementById('web-store-cart-subtotal');
    const total = document.getElementById('web-store-cart-total');

    const summary = getWebStoreCartSummary();
    if (cartCount) cartCount.innerText = `${summary.count} article${summary.count > 1 ? 's' : ''}`;
    if (totalItems) totalItems.innerText = `${summary.count} produit${summary.count > 1 ? 's' : ''}`;
    if (subtotal) subtotal.innerText = `${formatMoney(summary.total)} DT`;
    if (total) total.innerText = `${formatMoney(summary.total)} DT`;

    if (!itemsContainer) return;
    if (webStoreState.cart.length === 0) {
        itemsContainer.innerHTML = '<div class="web-store-empty small">Aucun article dans le panier.</div>';
        renderWebStoreCheckoutLines();
        return;
    }

    itemsContainer.innerHTML = webStoreState.cart.map(item => `
        <div class="web-store-cart-line">
            <div>
                <strong>${escapeHtml(item.designation || 'Produit')}</strong>
                <span>${escapeHtml(item.code_article || '')}</span>
            </div>
            <div class="web-store-cart-line-controls">
                <input type="number" min="1" value="${item.quantity}" class="field-input" onchange="updateWebStoreCartQuantity('${item.product_id}', this.value)">
                <strong>${formatMoney(Number(item.unit_price || 0) * Number(item.quantity || 0))} DT</strong>
                <button type="button" class="small-action-btn" onclick="removeWebStoreProduct('${item.product_id}')">X</button>
            </div>
        </div>
    `).join('');

    renderWebStoreCheckoutLines();
}

function renderWebStoreCheckoutLines() {
    const linesContainer = document.getElementById('web-store-checkout-lines');
    const total = document.getElementById('web-store-checkout-total');
    if (!linesContainer || !total) return;

    const summary = getWebStoreCartSummary();
    total.innerText = `${formatMoney(summary.total)} DT`;

    if (webStoreState.cart.length === 0) {
        linesContainer.innerHTML = '<div class="web-store-empty small">Aucun article dans le panier.</div>';
        return;
    }

    linesContainer.innerHTML = webStoreState.cart.map(item => `
        <div class="web-store-checkout-line">
            <span>${escapeHtml(item.designation || 'Produit')} x${item.quantity}</span>
            <strong>${formatMoney(Number(item.unit_price || 0) * Number(item.quantity || 0))} DT</strong>
        </div>
    `).join('');
}

function toggleWebStoreCheckout() {
    if (webStoreState.cart.length === 0) {
        alert('Le panier est vide.');
        return;
    }
    const modal = document.getElementById('web-store-checkout-modal');
    if (!modal) return;
    renderWebStoreCheckoutLines();
    modal.style.display = modal.style.display === 'block' ? 'none' : 'block';
}

function closeWebStoreCheckout() {
    const modal = document.getElementById('web-store-checkout-modal');
    if (modal) modal.style.display = 'none';
}

function generateWebOrderNumber() {
    return generateLegacyPrefixedNumber('WEB');
}

async function submitWebStoreOrder() {
    if (webStoreState.isSubmitting) return;
    if (webStoreState.cart.length === 0) {
        alert('Le panier est vide.');
        return;
    }

    const customerName = document.getElementById('web-store-customer-name')?.value.trim() || '';
    const customerPhone = document.getElementById('web-store-customer-phone')?.value.trim() || '';
    const customerAddress = document.getElementById('web-store-customer-address')?.value.trim() || '';
    const note = document.getElementById('web-store-customer-note')?.value.trim() || '';
    const total = getWebStoreCartSummary().total;

    if (!customerName || !customerPhone) {
        alert('Nom complet et telephone sont obligatoires.');
        return;
    }

    webStoreState.isSubmitting = true;
    const submitButton = document.getElementById('web-store-submit-order-btn');
    if (submitButton) {
        submitButton.disabled = true;
        submitButton.innerText = 'Envoi en cours...';
    }

    const orderNumber = await requestSequentialNumber('WEB', () => generateWebOrderNumber());
    let savedOrder = null;

    try {
        let response = await fetch(`${supabaseUrl}web_orders`, {
            method: 'POST',
            headers: { ...supabaseHeaders, Prefer: 'return=representation' },
            body: JSON.stringify({
                order_number: orderNumber,
                customer_name: customerName,
                customer_phone: customerPhone,
                customer_address: customerAddress,
                notes: note,
                delivery_fee_ttc: 0,
                total_ttc: total,
                status: 'Nouvelle'
            })
        });

        if (!response.ok) {
            response = await fetch(`${supabaseUrl}web_orders`, {
                method: 'POST',
                headers: { ...supabaseHeaders, Prefer: 'return=representation' },
                body: JSON.stringify({
                    order_number: orderNumber,
                    customer_name: `${customerName} - ${customerPhone}`,
                    delivery_fee_ttc: 0,
                    total_ttc: total,
                    status: 'Nouvelle'
                })
            });
        }

        if (!response.ok) {
            const errorText = await response.text();
            throw new Error(errorText || `HTTP ${response.status}`);
        }

        [savedOrder] = await response.json();

        const itemsPayload = webStoreState.cart.map(item => ({
            order_id: savedOrder.id,
            product_id: item.product_id,
            quantity: item.quantity,
            unit_price: item.unit_price
        }));

        const itemsResponse = await fetch(`${supabaseUrl}web_order_items`, {
            method: 'POST',
            headers: supabaseHeaders,
            body: JSON.stringify(itemsPayload)
        });

        if (!itemsResponse.ok) {
            const errorText = await itemsResponse.text();
            throw new Error(errorText || `HTTP ${itemsResponse.status}`);
        }

        alert(`Commande envoyee avec succes. Numero ${orderNumber}.`);
        webStoreState.cart = [];
        ['web-store-customer-name', 'web-store-customer-phone', 'web-store-customer-address', 'web-store-customer-note'].forEach(id => {
            const field = document.getElementById(id);
            if (field) field.value = '';
        });
        closeWebStoreCheckout();
        renderWebStoreCart();
        await loadWebStoreOrders();
    } catch (error) {
        console.error('Erreur commande web:', error);
        alert(`Impossible d'envoyer la commande.\n\nDetail: ${getSupabaseErrorMessage(error)}`);
    } finally {
        webStoreState.isSubmitting = false;
        if (submitButton) {
            submitButton.disabled = false;
            submitButton.innerText = 'Envoyer la commande';
        }
    }
}

function getWebOrderDeliveryFee(order) {
    return Number(order?.delivery_fee_ttc || 0);
}

function getWebOrderSubtotal(order) {
    const total = Number(order?.total_ttc || 0);
    const fee = getWebOrderDeliveryFee(order);
    return Math.max(0, total - fee);
}

async function loadWebStoreOrders() {
    webStoreState.recentOrders = await fetchCollection('web_orders?select=id,order_number,customer_name,customer_phone,customer_email,customer_address,notes,delivery_mode,payment_mode,delivery_fee_ttc,total_ttc,status,stock_decremented,created_at&order=created_at.desc');
    const tbody = document.getElementById('web-store-orders-body');
    if (!tbody) return;

    if (!Array.isArray(webStoreState.recentOrders) || webStoreState.recentOrders.length === 0) {
        tbody.innerHTML = '<tr><td colspan="6" style="text-align:center; padding:32px;">Aucune commande web pour le moment.</td></tr>';
        return;
    }

    tbody.innerHTML = webStoreState.recentOrders.slice(0, 10).map(item => `
        <tr>
            <td>${escapeHtml(item.order_number || '-')}</td>
            <td>${item.created_at ? new Date(item.created_at).toLocaleString('fr-FR') : '-'}</td>
            <td>${escapeHtml(item.customer_name || '-')}</td>
            <td>${escapeHtml(item.customer_phone || '-')}</td>
            <td style="text-align:right; font-weight:700;">${formatMoney(item.total_ttc || 0)} DT</td>
            <td><span class="web-store-status-badge">${escapeHtml(item.status || 'Nouvelle')}</span></td>
        </tr>
    `).join('');
}

function getWebStoreProductMedia(product) {
    const imageUrl = String(product?.image_url || '').trim();
    if (imageUrl) {
        return `<img src="${escapeHtml(imageUrl)}" alt="${escapeHtml(product.designation || 'Produit')}" class="web-store-product-image" loading="lazy" decoding="async" referrerpolicy="no-referrer" onerror="this.onerror=null; this.style.display='none'; if (this.parentElement) { this.parentElement.innerHTML = '<span>${escapeHtml((product?.designation || '?').charAt(0).toUpperCase())}</span>'; }">`;
    }
    return `<span>${escapeHtml((product?.designation || '?').charAt(0).toUpperCase())}</span>`;
}

function normalizeWebOrderText(value) {
    return String(value || '')
        .normalize('NFD')
        .replace(/[\u0300-\u036f]/g, '')
        .toLowerCase()
        .trim();
}

function getWebOrderStatusKey(status) {
    const value = normalizeWebOrderText(status);
    if (value.includes('annule')) return 'annulee';
    if (value.includes('expedie')) return 'expediee';
    if (value.includes('preparation')) return 'preparation';
    return 'nouvelle';
}

function loadStoredWebOrderAlertIds() {
    try {
        const raw = localStorage.getItem(WEB_ORDER_ALERT_STORAGE_KEY);
        const parsed = raw ? JSON.parse(raw) : [];
        if (!Array.isArray(parsed)) return new Set();
        return new Set(parsed.map(value => String(value)));
    } catch (error) {
        console.warn('Lecture alertes web impossible.', error);
        return new Set();
    }
}

function saveStoredWebOrderAlertIds(ids) {
    try {
        const values = Array.from(ids).slice(-300);
        localStorage.setItem(WEB_ORDER_ALERT_STORAGE_KEY, JSON.stringify(values));
    } catch (error) {
        console.warn('Sauvegarde alertes web impossible.', error);
    }
}

function ensureWebOrderNotificationCenter() {
    const sessionTools = document.getElementById('backoffice-session-tools');
    const logoutButton = document.getElementById('backoffice-logout-button');
    const existing = document.getElementById('web-order-notification-center');
    if (existing) {
        if (sessionTools && existing.parentElement !== sessionTools) {
            if (logoutButton && logoutButton.parentElement === sessionTools) {
                sessionTools.insertBefore(existing, logoutButton);
            } else {
                sessionTools.appendChild(existing);
            }
        }
        if (!webOrderAlertState.layoutBound) {
            window.addEventListener('resize', positionWebOrderNotificationCenter);
            window.addEventListener('scroll', positionWebOrderNotificationCenter, true);
            webOrderAlertState.layoutBound = true;
        }
        positionWebOrderNotificationCenter();
        return;
    }

    const container = document.createElement('div');
    container.id = 'web-order-notification-center';
    container.className = 'web-order-notification-center';
    container.innerHTML = `
        <button type="button" id="web-order-notification-trigger" class="web-order-notification-trigger" onclick="toggleWebOrderNotificationPanel()" style="display:none;">
            <span class="web-order-notification-trigger-label">WEB</span>
            <span id="web-order-notification-count" class="web-order-notification-count">0</span>
        </button>
        <div id="web-order-notification-card" class="web-order-notification-card" style="display:none;">
            <div class="web-order-notification-head">
                <div>
                    <div class="web-order-notification-kicker">Alerte web</div>
                    <div class="web-order-notification-title">Nouvelles ventes web</div>
                </div>
                <button type="button" class="web-order-notification-close" onclick="dismissWebOrderNotificationPanel()">Fermer</button>
            </div>
            <div class="web-order-notification-body">
                <div id="web-order-notification-summary" class="web-order-notification-summary">Aucune commande web en attente.</div>
                <div id="web-order-notification-list" class="web-order-notification-list"></div>
            </div>
            <div class="web-order-notification-actions">
                <button type="button" class="achat-btn blue-dark" onclick="openWebOrderNotificationsModule()">Ouvrir boutique en ligne</button>
            </div>
        </div>
    `;
    if (sessionTools) {
        if (logoutButton && logoutButton.parentElement === sessionTools) {
            sessionTools.insertBefore(container, logoutButton);
        } else {
            sessionTools.appendChild(container);
        }
    } else {
        document.body.appendChild(container);
    }
    if (!webOrderAlertState.layoutBound) {
        window.addEventListener('resize', positionWebOrderNotificationCenter);
        window.addEventListener('scroll', positionWebOrderNotificationCenter, true);
        webOrderAlertState.layoutBound = true;
    }
    positionWebOrderNotificationCenter();
}

function positionWebOrderNotificationCenter() {
    const center = document.getElementById('web-order-notification-center');
    if (!center) return;

    center.style.position = 'relative';
    center.style.top = 'auto';
    center.style.left = 'auto';
    center.style.right = 'auto';
    center.style.transform = 'none';
}

function dismissWebOrderNotificationPanel() {
    webOrderAlertState.panelOpen = false;
    renderWebOrderNotificationState();
}

function toggleWebOrderNotificationPanel() {
    webOrderAlertState.panelOpen = !webOrderAlertState.panelOpen;
    renderWebOrderNotificationState();
}

function openWebOrderNotificationsModule() {
    webOrderAlertState.panelOpen = true;
    webOrderAlertState.freshOrderIds.clear();
    webOrderAlertState.openPendingOnNextModuleLoad = true;
    renderWebOrderNotificationState();
    openTab('web_orders');
    setTimeout(applyWebOrderNotificationModuleFilters, 0);
}

function applyWebOrderNotificationModuleFilters() {
    const pending = getPendingWebOrdersForAdmin();
    const filter = document.getElementById('web-store-order-filter');
    const from = document.getElementById('web-store-order-from');
    const to = document.getElementById('web-store-order-to');

    if (filter) filter.value = 'nouvelle';

    const pendingDates = pending
        .map(order => String(order?.created_at || '').split('T')[0])
        .filter(Boolean)
        .sort();

    if (pendingDates.length > 0) {
        if (from) from.value = pendingDates[0];
        if (to) to.value = pendingDates[pendingDates.length - 1] || new Date().toISOString().split('T')[0];
    }

    if (document.getElementById('web-store-orders-body')) {
        filterWebStoreOrders();
    }
}

function getPendingWebOrdersForAdmin() {
    const alertPending = Array.isArray(webOrderAlertState.pendingOrders) ? webOrderAlertState.pendingOrders : [];
    if (alertPending.length > 0) return alertPending;
    return (Array.isArray(webStoreState.recentOrders) ? webStoreState.recentOrders : [])
        .filter(order => getWebOrderStatusKey(order.status) === 'nouvelle');
}

function hasPendingWebOrdersForAdmin() {
    return getPendingWebOrdersForAdmin().length > 0;
}

function updateWebOrderRibbonBadge(count = 0) {
    const buttons = Array.from(document.querySelectorAll('[onclick*="openTab(\'web_orders\')"]'));
    buttons.forEach(button => {
        let badge = button.querySelector('.web-order-ribbon-badge');
        if (count > 0) {
            button.classList.add('web-order-ribbon-alert');
            if (!badge) {
                badge = document.createElement('span');
                badge.className = 'web-order-ribbon-badge';
                button.appendChild(badge);
            }
            badge.innerText = String(count);
        } else {
            button.classList.remove('web-order-ribbon-alert');
            if (badge) {
                badge.remove();
            }
        }
    });
}

function renderWebOrderNotificationState() {
    const center = document.getElementById('web-order-notification-center');
    const trigger = document.getElementById('web-order-notification-trigger');
    const count = document.getElementById('web-order-notification-count');
    const card = document.getElementById('web-order-notification-card');
    const summary = document.getElementById('web-order-notification-summary');
    const list = document.getElementById('web-order-notification-list');
    if (!center || !trigger || !count || !card || !summary || !list) return;

    const pending = Array.isArray(webOrderAlertState.pendingOrders) ? webOrderAlertState.pendingOrders : [];
    updateWebOrderRibbonBadge(pending.length);

    if (pending.length === 0) {
        center.style.display = 'none';
        trigger.style.display = 'none';
        card.style.display = 'none';
        return;
    }

    center.style.display = 'inline-flex';
    positionWebOrderNotificationCenter();
    trigger.style.display = 'inline-flex';
    count.innerText = String(pending.length);

    if (!webOrderAlertState.panelOpen) {
        card.style.display = 'none';
        return;
    }

    const freshCount = webOrderAlertState.freshOrderIds.size;
    summary.innerText = freshCount > 0
        ? `${pending.length} commande(s) web en attente, dont ${freshCount} nouvelle(s).`
        : `${pending.length} commande(s) web en attente de traitement.`;

    list.innerHTML = pending.slice(0, 4).map(order => {
        const isFresh = webOrderAlertState.freshOrderIds.has(String(order.id));
        return `
            <button type="button" class="web-order-notification-item ${isFresh ? 'fresh' : ''}" onclick="openWebOrderNotificationsModule()">
                <div class="web-order-notification-item-top">
                    <strong>${escapeHtml(order.order_number || 'Commande web')}</strong>
                    <span>${formatMoney(Number(order.total_ttc || 0))} DT</span>
                </div>
                <div class="web-order-notification-item-bottom">
                    <span>${escapeHtml(order.customer_name || 'Client web')}</span>
                    <span>${order.created_at ? new Date(order.created_at).toLocaleTimeString('fr-FR', { hour: '2-digit', minute: '2-digit' }) : '-'}</span>
                </div>
            </button>
        `;
    }).join('');

    card.style.display = 'block';
    positionWebOrderNotificationCenter();
}

let _webOrderFullRefreshCounter = 0;

async function refreshWebOrderAlerts() {
    try {
        _webOrderFullRefreshCounter++;
        const isFullRefresh = !webOrderAlertState.initialized || _webOrderFullRefreshCounter % 20 === 0;

        let orders;
        if (isFullRefresh) {
            orders = await fetchCollection('web_orders?select=id,order_number,customer_name,total_ttc,status,created_at&status=not.ilike.*annule*,status=not.ilike.*expedie*,status=not.ilike.*preparation*&order=created_at.desc&limit=100', [], 100);
        } else {
            const since = new Date(Date.now() - 86400000).toISOString();
            orders = await fetchCollection(`web_orders?select=id,order_number,customer_name,total_ttc,status,created_at&status=not.ilike.*annule*,status=not.ilike.*expedie*,status=not.ilike.*preparation*&created_at=gt.${since}&order=created_at.desc&limit=100`, [], 100);
        }
        const pendingOrders = (Array.isArray(orders) ? orders : [])
            .filter(order => getWebOrderStatusKey(order.status) === 'nouvelle');

        if (!webOrderAlertState.initialized) {
            webOrderAlertState.seenIds = loadStoredWebOrderAlertIds();
            if (webOrderAlertState.seenIds.size === 0) {
                pendingOrders.forEach(order => webOrderAlertState.seenIds.add(String(order.id)));
                saveStoredWebOrderAlertIds(webOrderAlertState.seenIds);
            }
            webOrderAlertState.initialized = true;
        }

        const nextPendingIds = new Set(pendingOrders.map(order => String(order.id)));
        const freshIds = pendingOrders
            .map(order => String(order.id))
            .filter(id => !webOrderAlertState.seenIds.has(id));

        if (freshIds.length > 0) {
            freshIds.forEach(id => {
                webOrderAlertState.seenIds.add(id);
                webOrderAlertState.freshOrderIds.add(id);
            });
            saveStoredWebOrderAlertIds(webOrderAlertState.seenIds);
        }

        webOrderAlertState.freshOrderIds.forEach(id => {
            if (!nextPendingIds.has(id)) {
                webOrderAlertState.freshOrderIds.delete(id);
            }
        });

        if (isFullRefresh || pendingOrders.length > 0) {
            webOrderAlertState.pendingOrders = pendingOrders;
        } else {
            const checkUrl = 'web_orders?select=id&status=not.ilike.*annule*,status=not.ilike.*expedie*,status=not.ilike.*preparation*&limit=1';
            const checkResponse = await fetch(`${supabaseUrl}${checkUrl}`, {
                headers: supabaseHeaders
            });
            if (checkResponse.ok) {
                const rows = await checkResponse.json();
                if (Array.isArray(rows) && rows.length > 0) {
                    webOrderAlertState.pendingOrders = [null];
                }
            }
        }
        renderWebOrderNotificationState();
    } catch (error) {
        console.warn('Surveillance ventes web indisponible.', error);
    }
}

function startWebOrderAlertPolling() {
    if (webOrderAlertState.pollHandle) return;
    _webOrderFullRefreshCounter = 0;
    refreshWebOrderAlerts();
    webOrderAlertState.pollHandle = setInterval(refreshWebOrderAlerts, 300000);
}

function isWebOrderValidated(order) {
    return Boolean(order?.order_number) && getWebOrderStatusKey(order?.status) === 'expediee';
}

function getWebStoreProductSummary(product) {
    if (String(product?.description_web || '').trim()) {
        return String(product.description_web).trim();
    }

    const bits = [product?.forme || 'Soin et bien-etre'];
    if (product?.peremption) bits.push(`Peremption ${new Date(product.peremption).toLocaleDateString('fr-FR')}`);
    else bits.push('Disponible en ligne');
    return bits.join(' • ');
}

function renderWebStoreProducts() {
    const grid = document.getElementById('web-store-products-grid');
    const counter = document.getElementById('web-store-product-count');
    if (!grid) return;
    if (counter) counter.innerText = `${webStoreState.filteredProducts.length} produits`;

    if (webStoreState.filteredProducts.length === 0) {
        grid.innerHTML = '<div class="web-store-empty">Aucun produit ne correspond a votre recherche.</div>';
        return;
    }

    grid.innerHTML = webStoreState.filteredProducts.map(product => {
        const stock = Number(product.stock_actuel || 0);
        const inStock = stock > 0;
        return `
            <article class="web-store-product-card">
                <div class="web-store-product-badge-row">
                    <span class="web-store-product-badge">${escapeHtml(product.forme || 'Parapharmacie')}</span>
                    <span class="web-store-product-stock ${inStock ? 'ok' : 'empty'}">${inStock ? `Stock ${stock}` : 'Sur commande'}</span>
                </div>
                <button type="button" class="web-store-product-media" onclick="openWebStoreProductDetail('${product.id}')">${getWebStoreProductMedia(product)}</button>
                <div class="web-store-product-code">${escapeHtml(product.code_article || '')}</div>
                <h4>${escapeHtml(product.designation || 'Produit')}</h4>
                <p>${escapeHtml(getWebStoreProductSummary(product))}</p>
                <div class="web-store-product-footer">
                    <div class="web-store-product-price">${formatMoney(getProductWebPriceTtc(product))} DT</div>
                    <div class="web-store-product-actions">
                        <button type="button" class="web-store-secondary-btn web-store-mini-btn" onclick="openWebStoreProductDetail('${product.id}')">Fiche</button>
                        <button type="button" class="web-store-card-btn" onclick="addWebStoreProduct('${product.id}')">Ajouter</button>
                    </div>
                </div>
            </article>
        `;
    }).join('');
}

function renderWebStoreMetrics() {
    const container = document.getElementById('web-store-metrics');
    if (!container) return;

    const productsCount = webStoreState.products.length;
    const inStockCount = webStoreState.products.filter(item => Number(item.stock_actuel || 0) > 0).length;
    const orderCount = webStoreState.recentOrders.length;
    const pendingCount = webStoreState.recentOrders.filter(item => item.status === 'Nouvelle').length;

    container.innerHTML = `
        <div class="web-store-metric-card"><strong>${productsCount}</strong><span>Produits boutique</span></div>
        <div class="web-store-metric-card"><strong>${inStockCount}</strong><span>Produits en stock</span></div>
        <div class="web-store-metric-card"><strong>${orderCount}</strong><span>Commandes recues</span></div>
        <div class="web-store-metric-card accent"><strong>${pendingCount}</strong><span>Nouvelles a traiter</span></div>
    `;
}

function openWebStoreProductDetail(productId) {
    webStoreState.selectedProductId = productId;
    const product = webStoreState.products.find(item => item.id === productId);
    const body = document.getElementById('web-store-product-modal-body');
    const modal = document.getElementById('web-store-product-modal');
    if (!product || !body || !modal) return;

    const stock = Number(product.stock_actuel || 0);
    const description = String(product.description_web || '').trim() || `${product.designation || 'Produit'} est disponible dans la boutique en ligne avec un parcours de commande rapide.`;

    body.innerHTML = `
        <div class="web-store-detail-shell">
            <div class="web-store-detail-media">${getWebStoreProductMedia(product)}</div>
            <div class="web-store-detail-content">
                <div class="web-store-checkout-header">
                    <div>
                        <div class="web-store-section-kicker">Fiche produit</div>
                        <h3 style="margin:0;">${escapeHtml(product.designation || 'Produit')}</h3>
                    </div>
                    <button type="button" class="small-action-btn" onclick="closeWebStoreProductDetail()">Fermer</button>
                </div>
                <div class="web-store-detail-hero">
                    <div class="web-store-detail-heading">
                        <div class="web-store-detail-meta">
                            <span class="web-store-product-badge">${escapeHtml(product.forme || 'Parapharmacie')}</span>
                            <span class="web-store-status-badge">Code ${escapeHtml(product.code_article || '-')}</span>
                        </div>
                        <div class="web-store-detail-price">${formatMoney(getProductWebPriceTtc(product))} DT</div>
                    </div>
                    <aside class="web-store-detail-availability-card">
                        <span class="web-store-detail-availability-label">Disponibilite</span>
                        <span class="web-store-product-stock ${stock > 0 ? 'ok' : 'empty'}">${stock > 0 ? `En stock (${stock})` : 'Hors stock'}</span>
                    </aside>
                </div>
                <p class="web-store-detail-description">${escapeHtml(description)}</p>
                <div class="web-store-detail-grid">
                    <div><span>TVA</span><strong>${formatMoney(product.tva || 0)} %</strong></div>
                    <div><span>Peremption</span><strong>${product.peremption ? new Date(product.peremption).toLocaleDateString('fr-FR') : '-'}</strong></div>
                    <div><span>Code barre</span><strong>${escapeHtml(product.code_barre || '-')}</strong></div>
                </div>
                <div class="web-store-hero-actions">
                    <button type="button" class="web-store-primary-btn" onclick="addWebStoreProduct('${product.id}'); closeWebStoreProductDetail();">Ajouter au panier</button>
                    <button type="button" class="web-store-secondary-btn" onclick="closeWebStoreProductDetail()">Continuer</button>
                </div>
            </div>
        </div>
    `;

    modal.style.display = 'block';
}

function closeWebStoreProductDetail() {
    const modal = document.getElementById('web-store-product-modal');
    if (modal) modal.style.display = 'none';
}

function getWebStoreOrderStatusClass(status) {
    if (status === 'Nouvelle') return 'blue';
    if (status === 'En préparation') return 'yellow';
    if (status === 'Expédiée') return 'green';
    return 'gray';
}

async function loadWebStoreOrders() {
    try {
        const [ordersResult, orderItemsResult, productsResult] = await Promise.all([
            fetchCollection('web_orders?select=id,order_number,customer_name,customer_phone,customer_email,customer_address,notes,delivery_mode,payment_mode,delivery_fee_ttc,total_ttc,status,stock_decremented,created_at&order=created_at.desc', []),
            fetchCollection('web_order_items?select=order_id,product_id,quantity,unit_price&order=order_id', []),
            fetchCollection('products?select=id,code_article,designation,forme,stock_actuel', [])
        ]);

        const orders = Array.isArray(ordersResult) ? ordersResult : [];
        const orderItems = Array.isArray(orderItemsResult) ? orderItemsResult : [];
        const products = Array.isArray(productsResult) ? productsResult : [];
        const productMap = new Map(products.map(item => [item.id, item]));

        webStoreState.recentOrders = orders.map(order => {
            const items = orderItems
                .filter(item => item.order_id === order.id)
                .map(item => ({
                    ...item,
                    product: productMap.get(item.product_id) || null
                }));
            return { ...order, items };
        });

        renderWebStoreMetrics();
        filterWebStoreOrders();
    } catch (error) {
        console.error('Erreur chargement commandes web:', error);
        renderWebStoreOrdersLoadError(error);
    }
}

function renderWebStoreOrdersLoadError(error) {
    const tbody = document.getElementById('web-store-orders-body');
    const countNode = document.getElementById('web-orders-admin-count');
    if (countNode) countNode.innerText = '0 commande';
    if (!tbody) return;

    tbody.innerHTML = `
        <tr>
            <td colspan="9" style="text-align:center; padding:32px; color:#b91c1c; font-weight:700;">
                Impossible de charger les commandes web.${error?.message ? ` ${escapeHtml(error.message)}` : ''}
            </td>
        </tr>
    `;
}

function filterWebStoreOrders() {
    const tbody = document.getElementById('web-store-orders-body');
    if (!tbody) return;

    const filterValue = document.getElementById('web-store-order-filter')?.value || 'all';
    const rows = filterValue === 'all'
        ? webStoreState.recentOrders
        : webStoreState.recentOrders.filter(item => item.status === filterValue);

    if (rows.length === 0) {
        tbody.innerHTML = '<tr><td colspan="9" style="text-align:center; padding:32px;">Aucune commande pour ce filtre.</td></tr>';
        return;
    }

    tbody.innerHTML = rows.map(item => `
        <tr>
            <td style="font-weight:700;">${escapeHtml(item.order_number || '-')}</td>
            <td>${item.created_at ? new Date(item.created_at).toLocaleString('fr-FR') : '-'}</td>
            <td>${escapeHtml(item.customer_name || '-')}</td>
            <td>${escapeHtml(item.customer_phone || '-')}</td>
            <td style="text-align:center;">${item.items.length}</td>
            <td style="text-align:right; font-weight:700;">${formatMoney(item.total_ttc || 0)} DT</td>
            <td><span class="badge ${getWebStoreOrderStatusClass(item.status || 'Nouvelle')}">${escapeHtml(item.status || 'Nouvelle')}</span></td>
            <td>${buildWebStorePreparationLabel(item)}</td>
            <td>
                <button type="button" class="small-action-btn" onclick="openWebStoreOrderDetail('${item.id}')">Details</button>
                <button type="button" class="small-action-btn" onclick="printWebStoreOrder('${item.id}', false)">Impr.</button>
                <button type="button" class="small-action-btn" onclick="printWebStoreOrder('${item.id}', true)">Prep.</button>
            </td>
        </tr>
    `).join('');
}

function buildWebStorePreparationLabel(order) {
    if (!Array.isArray(order.items) || order.items.length === 0) return 'Aucun article';
    const totalQty = order.items.reduce((sum, item) => sum + Number(item.quantity || 0), 0);
    const reservedBadge = order.stock_decremented
        ? ' <span class="badge green">Stock réservé</span>'
        : '';
    return `${totalQty} unite(s)${reservedBadge}`;
}

