function closeWebStoreOrderDetail() {
    const modal = document.getElementById('web-store-order-modal');
    if (modal) modal.style.display = 'none';
}

function switchWebStoreOrderTab(tab) {
    const main = document.getElementById('web-store-order-main');
    const history = document.getElementById('web-store-order-history');
    document.querySelectorAll('.web-store-order-tab').forEach(button => {
        button.classList.toggle('active', button.dataset.orderTab === tab);
    });

    if (main) main.style.display = tab === 'commande' ? 'grid' : 'none';
    if (history) history.style.display = tab === 'historique' ? 'block' : 'none';
}

function updateWebStoreOrderStatusButtonState(isSaving = false) {
    const select = document.getElementById('web-store-order-status-select');
    const button = document.getElementById('web-store-order-save-btn');
    if (!select || !button) return;

    const currentStatus = select.dataset.currentStatus || 'Nouvelle';
    const hasChanged = select.value !== currentStatus;

    button.disabled = isSaving || !hasChanged;
    button.innerText = isSaving ? 'Enregistrement...' : 'Enregistrer le statut';
}

function updateWebStoreDeliveryFeeButtonState(isSaving = false) {
    const input = document.getElementById('web-store-order-delivery-fee-input');
    const button = document.getElementById('web-store-order-delivery-save-btn');
    const subtotalNode = document.getElementById('web-store-order-subtotal-value');
    const totalNode = document.getElementById('web-store-order-total-value');
    if (!input || !button) return;

    const currentFee = Number(input.dataset.currentFee || 0);
    const nextFee = Math.max(0, Number(input.value || 0));
    const order = webStoreState.recentOrders.find(item => item.id === webStoreState.selectedOrderId);
    const subtotal = order ? getWebOrderSubtotal(order) : 0;

    if (subtotalNode) {
        subtotalNode.innerText = `${formatMoney(subtotal)} DT`;
    }
    if (totalNode) {
        totalNode.innerText = `${formatMoney(subtotal + nextFee)} DT`;
    }

    button.disabled = isSaving || Math.abs(nextFee - currentFee) < 0.0005;
    button.innerText = isSaving ? 'Enregistrement...' : 'Enregistrer frais livraison';
}

async function saveWebStoreOrderDeliveryFee(orderId) {
    const input = document.getElementById('web-store-order-delivery-fee-input');
    if (!input) return;

    const nextFee = Math.max(0, Number(input.value || 0));
    const orderIndex = webStoreState.recentOrders.findIndex(item => item.id === orderId);
    const order = orderIndex >= 0 ? webStoreState.recentOrders[orderIndex] : null;
    if (!order) {
        alert('Commande introuvable.');
        return;
    }

    const oldFee = getWebOrderDeliveryFee(order);
    if (Math.abs(nextFee - oldFee) < 0.0005) {
        updateWebStoreDeliveryFeeButtonState(false);
        return;
    }

    const subtotal = getWebOrderSubtotal(order);
    const nextTotal = subtotal + nextFee;

    try {
        updateWebStoreDeliveryFeeButtonState(true);

        await recordWebOrderDeliveryFeeHistory(order, oldFee, nextFee, Number(order.total_ttc || 0), nextTotal);

        const response = await fetch(`${supabaseUrl}web_orders?id=eq.${orderId}`, {
            method: 'PATCH',
            headers: supabaseHeaders,
            body: JSON.stringify({
                delivery_fee_ttc: nextFee,
                total_ttc: nextTotal
            })
        });

        if (!response.ok) {
            const errorText = await response.text();
            throw new Error(errorText || `HTTP ${response.status}`);
        }

        webStoreState.recentOrders[orderIndex] = {
            ...order,
            delivery_fee_ttc: nextFee,
            total_ttc: nextTotal
        };
        input.dataset.currentFee = String(nextFee);
        filterWebStoreOrders();
        renderWebStoreMetrics();
        syncWebOrderAlertsFromRecentOrders();
        if (activeTabId === 'web_delivery_fees') {
            await loadWebDeliveryFeesModule();
        }
        await loadWebStoreOrderHistory(orderId);
        updateWebStoreDeliveryFeeButtonState(false);
        alert('Frais de livraison mis a jour avec succes.');
    } catch (error) {
        console.error('Erreur mise a jour frais livraison:', error);
        const detail = getSupabaseErrorMessage(error);
        const migrationHint = /delivery_fee_ttc|web_order_delivery_history/i.test(detail)
            ? `\n\nExecute d'abord ce SQL dans Supabase:\n${getWebDeliveryFeesMigrationSql()}`
            : '';
        updateWebStoreDeliveryFeeButtonState(false);
        alert(`Impossible de mettre a jour les frais de livraison.\n\nDetail: ${detail}${migrationHint}`);
    }
}

async function saveWebStoreOrderStatus(orderId) {
    const status = document.getElementById('web-store-order-status-select')?.value || 'Nouvelle';
    try {
        updateWebStoreOrderStatusButtonState(true);
        const orderIndex = webStoreState.recentOrders.findIndex(item => item.id === orderId);
        const order = orderIndex >= 0 ? webStoreState.recentOrders[orderIndex] : null;
        if (!order) throw new Error('Commande introuvable.');

        const shouldAdjustStock =
            (status === 'En préparation' || status === 'Expédiée') && !order.stock_decremented;
        const shouldRestoreStock = status === 'Annulée' && !!order.stock_decremented;

        if (shouldAdjustStock) {
            await adjustStockForWebOrder(order, -1);
        }

        if (shouldRestoreStock) {
            await adjustStockForWebOrder(order, 1);
        }

        const nextStockDecremented = shouldAdjustStock
            ? true
            : shouldRestoreStock
                ? false
                : order.stock_decremented || false;
        const historyNote = shouldAdjustStock
            ? 'Stock reserve automatiquement'
            : shouldRestoreStock
                ? 'Stock reintegre automatiquement'
                : 'Changement de statut';
        const requests = [];
        if (status !== (order.status || 'Nouvelle')) {
            requests.push(recordWebOrderStatusHistory(order.id, order.status || null, status, historyNote));
        }
        requests.push(fetch(`${supabaseUrl}web_orders?id=eq.${orderId}`, {
            method: 'PATCH',
            headers: supabaseHeaders,
            body: JSON.stringify({
                status,
                stock_decremented: nextStockDecremented
            })
        }));

        const responses = await Promise.all(requests);
        const response = responses[responses.length - 1];

        if (!response.ok) {
            const errorText = await response.text();
            throw new Error(errorText || `HTTP ${response.status}`);
        }

        webStoreState.recentOrders[orderIndex] = {
            ...order,
            status,
            stock_decremented: nextStockDecremented
        };
        filterWebStoreOrders();
        renderWebStoreMetrics();
        syncWebOrderAlertsFromRecentOrders();
        refreshProductsCacheInBackground('statut commande web');
        if (activeTabId === 'web_delivery_fees') {
            await loadWebDeliveryFeesModule();
        }
        openWebStoreOrderDetail(orderId);
    } catch (error) {
        console.error('Erreur changement statut commande web:', error);
        updateWebStoreOrderStatusButtonState(false);
        alert(`Impossible de changer le statut.\n\nDetail: ${getSupabaseErrorMessage(error)}`);
    }
}

async function recordWebOrderStatusHistory(orderId, oldStatus, newStatus, note = '') {
    const response = await fetch(`${supabaseUrl}web_order_status_history`, {
        method: 'POST',
        headers: supabaseHeaders,
        body: JSON.stringify({
            order_id: orderId,
            old_status: oldStatus,
            new_status: newStatus,
            note
        })
    });

    if (!response.ok) {
        const errorText = await response.text();
        throw new Error(errorText || `HTTP ${response.status}`);
    }
}

async function recordWebOrderDeliveryFeeHistory(order, oldFee, newFee, oldTotal, newTotal, note = '') {
    const response = await fetch(`${supabaseUrl}web_order_delivery_history`, {
        method: 'POST',
        headers: supabaseHeaders,
        body: JSON.stringify({
            order_id: order.id,
            old_fee_ttc: oldFee,
            new_fee_ttc: newFee,
            old_total_ttc: oldTotal,
            new_total_ttc: newTotal,
            note: note || `Ajustement frais livraison commande ${order.order_number || ''}`.trim()
        })
    });

    if (!response.ok) {
        const errorText = await response.text();
        throw new Error(errorText || `HTTP ${response.status}`);
    }
}

