async function loadCustomers() {
    egressTracker.pushFlow('load-customers');
    try {
        allCustomers = await fetchCollection('customers?select=id,nom,telephone,email,adresse,solde,en_cours,reste_a_payer,solde_initial,date_initial,mutuelle_id,numero_matricule_mutuelle,nom_malade,mutuelles(nom)&order=nom', []);
        saleState.customers = allCustomers;
        renderCustomersTable(allCustomers);
    } catch (error) {
        console.error('Erreur clients:', error);
    } finally { egressTracker.popFlow(); }
}

function renderCustomersTable(data) {
    const tbody = document.getElementById('customers-table-body');
    if (!tbody) return;

    tbody.innerHTML = data.map(c => `
        <tr class="${customerHasBalance(c) ? 'customer-row-with-balance' : 'customer-row-without-balance'}">
            <td style="font-weight:600;">${c.nom}</td>
            <td>${c.telephone || '-'}</td>
            <td>${c.adresse || '-'}</td>
            <td>${new Date(c.created_at).toLocaleDateString()}</td>
            <td style="text-align:center;">
                <button class="small-action-btn" onclick="editCustomer('${c.id}')">✏️</button>
                <button class="small-action-btn" onclick="deleteCustomer('${c.id}')" style="color:red;">🗑️</button>
            </td>
        </tr>
    `).join('');
}

function getCustomerCodeValue(customer) {
    return String(customer?.code_client || customer?.code || customer?.customer_code || customer?.id || '').trim();
}

function getCustomerMutuelleName(customer) {
    return String(customer?.mutuelles?.nom || customer?.mutuelle_nom || customer?.mutuelle || '').trim();
}

function customerHasBalance(customer) {
    return Math.abs(Number(customer?.solde || 0)) > 0.0005;
}

function customerIsCnam(customer) {
    const mutuelleName = normalizeSearchText(getCustomerMutuelleName(customer));
    return mutuelleName.includes('cnam') || normalizeSearchText(customer?.numero_matricule_mutuelle || '').includes('cnam');
}

function customerMatchesFilters(customer, filters) {
    const code = normalizeSearchText(getCustomerCodeValue(customer));
    const name = normalizeSearchText(customer?.nom || '');
    const phone = normalizeSearchText(customer?.telephone || '');
    const address = normalizeSearchText(customer?.adresse || '');
    const mutuelleName = normalizeSearchText(getCustomerMutuelleName(customer));
    const matricule = normalizeSearchText(customer?.numero_matricule_mutuelle || '');
    const solde = Number(customer?.solde || 0);
    const hasMutuelle = Boolean(customer?.mutuelle_id || getCustomerMutuelleName(customer));
    const isCnam = customerIsCnam(customer);

    if (filters.code) {
        if (filters.codeExact ? code !== filters.code : !code.includes(filters.code)) return false;
    }

    if (filters.search) {
        const haystack = `${name} ${phone} ${matricule}`;
        if (!haystack.includes(filters.search)) return false;
    }

    if (filters.mutuelle && !mutuelleName.includes(filters.mutuelle)) return false;
    if (filters.address && !address.includes(filters.address)) return false;

    if (Number.isFinite(filters.soldeMin) && solde < filters.soldeMin) return false;
    if (Number.isFinite(filters.soldeMax) && solde > filters.soldeMax) return false;

    if (filters.balanceStatus === 'with_balance' && !customerHasBalance(customer)) return false;
    if (filters.balanceStatus === 'without_balance' && customerHasBalance(customer)) return false;
    if (filters.balanceStatus === 'creditor' && solde >= 0) return false;
    if (filters.balanceStatus === 'debtor' && solde <= 0) return false;

    return true;
}

function filterCustomers() {
    const filters = {
        code: normalizeSearchText(document.getElementById('customer-filter-code')?.value || ''),
        codeExact: Boolean(document.getElementById('customer-filter-code-exact')?.checked),
        search: normalizeSearchText(document.getElementById('customer-search')?.value || ''),
        balanceStatus: document.getElementById('customer-filter-balance-status')?.value || '',
        soldeMin: Number(document.getElementById('customer-filter-solde-min')?.value),
        soldeMax: Number(document.getElementById('customer-filter-solde-max')?.value),
        mutuelle: normalizeSearchText(document.getElementById('customer-filter-mutuelle')?.value || ''),
        address: normalizeSearchText(document.getElementById('customer-filter-address')?.value || '')
    };
    const filtered = allCustomers.filter(customer => customerMatchesFilters(customer, filters));
    renderCustomersTable(filtered);
}

function resetCustomerFilters() {
    [
        'customer-filter-code',
        'customer-search',
        'customer-filter-mutuelle'
    ].forEach(id => {
        const node = document.getElementById(id);
        if (node) node.value = '';
    });

    const status = document.getElementById('customer-filter-balance-status');
    if (status) status.value = '';

    renderCustomersTable(allCustomers);
}

function showCustomerModal() {
    document.getElementById('modal-title').innerText = 'Ajouter un Client';
    document.getElementById('cust-id').value = '';
    document.getElementById('cust-name').value = '';
    document.getElementById('cust-phone').value = '';
    document.getElementById('cust-address').value = '';
    document.getElementById('customer-modal').style.display = 'block';
}

function hideCustomerModal() {
    document.getElementById('customer-modal').style.display = 'none';
}

function editCustomer(id) {
    const c = allCustomers.find(item => item.id === id);
    if (!c) return;

    document.getElementById('modal-title').innerText = 'Modifier le Client';
    document.getElementById('cust-id').value = c.id;
    document.getElementById('cust-name').value = c.nom;
    document.getElementById('cust-phone').value = c.telephone || '';
    document.getElementById('cust-address').value = c.adresse || '';
    document.getElementById('customer-modal').style.display = 'block';
}

async function saveCustomer() {
    const id = document.getElementById('cust-id').value;
    const customer = {
        nom: document.getElementById('cust-name').value,
        telephone: document.getElementById('cust-phone').value,
        adresse: document.getElementById('cust-address').value
    };

    if (!customer.nom) {
        alert('Le nom est obligatoire');
        return;
    }

    if (!id) {
        const dupCheck = await findDuplicateByName('customers', customer.nom);
        if (dupCheck) {
            if (!confirm(`Un client "${dupCheck.nom}" existe deja. Creer quand meme ?`)) return;
        }
    }

    try {
        let url = `${supabaseUrl}customers`;
        let method = 'POST';

        if (id) {
            url += `?id=eq.${id}`;
            method = 'PATCH';
        }

        const response = await fetch(url, {
            method: method,
            headers: supabaseHeaders,
            body: JSON.stringify(customer)
        });

        if (response.ok) {
            invalidateReferenceCache('customers');
            hideCustomerModal();
            loadCustomers();
        }
    } catch (error) {
        console.error('Erreur sauvegarde:', error);
    }
}

