function filterRowsByDateRange(rows, rawDate, from, to) {
    const day = String(rawDate || '').split('T')[0];
    if (from && day && day < from) return false;
    if (to && day && day > to) return false;
    return true;
}

async function loadSalesDeletionRows() {
    const tbody = document.getElementById('sales-delete-body');
    if (!tbody) return;

    try {
        const rows = await fetchCollection(`sales?select=id,numero_vente,date_vente,type_vente,total_ttc,statut,client_id,mutuelle_id,customers(nom),mutuelles(nom)&date_vente=gte.${getDefaultDateFilter(1)}&order=date_vente.desc`, []);
        const from = document.getElementById('sale-delete-from')?.value || '';
        const to = document.getElementById('sale-delete-to')?.value || '';
        const search = normalizeSearchText(document.getElementById('sale-delete-search')?.value || '');
        const filtered = rows.filter(item => {
            if (!filterRowsByDateRange(rows, item.date_vente, from, to)) return false;
            if (!search) return true;
            const haystack = [
                item.numero_vente,
                item.type_vente,
                item.statut,
                item.customers?.nom,
                item.mutuelles?.nom
            ].map(normalizeSearchText).join(' ');
            return haystack.includes(search);
        });

        tbody.innerHTML = filtered.length
            ? filtered.map(item => `
                <tr>
                    <td>${escapeHtml(item.numero_vente || '-')}</td>
                    <td>${item.date_vente ? new Date(item.date_vente).toLocaleString('fr-FR') : '-'}</td>
                    <td>${escapeHtml(item.type_vente || '-')}</td>
                    <td>${escapeHtml(item.customers?.nom || 'Client passager')}</td>
                    <td style="text-align:right; font-weight:700;">${formatMoney(item.total_ttc || 0)} DT</td>
                    <td>${escapeHtml(item.statut || '-')}</td>
                    <td><button class="small-action-btn red" type="button" onclick="deleteSaleRecord('${item.id}', '${escapeHtml(item.numero_vente || '')}')">Supprimer</button></td>
                </tr>
            `).join('')
            : '<tr><td colspan="7" style="text-align:center; padding:28px;">Aucune vente a supprimer.</td></tr>';
    } catch (error) {
        console.error('Erreur chargement suppression ventes:', error);
        tbody.innerHTML = `<tr><td colspan="7" style="text-align:center; padding:28px; color:#b91c1c;">${escapeHtml(getSupabaseErrorMessage(error))}</td></tr>`;
    }
}

