async function deleteSaleRecord(saleId, saleNumber = '') {
    if (!saleId) return;
    const confirmed = confirm(`Supprimer definitivement la vente ${saleNumber || ''} ?\n\nLe stock des articles sera recredite.`);
    if (!confirmed) return;

    try {
        const saleItems = await fetchCollection(`sale_items?select=product_id,quantite,products(id,stock_actuel)&sale_id=eq.${saleId}`, []);
        const stockUpdates = new Map();
        saleItems.forEach(item => {
            const productId = String(item.product_id || '');
            if (!productId) return;
            const currentStock = Number(item.products?.stock_actuel || stockUpdates.get(productId)?.stock_actuel || 0);
            const nextStock = currentStock + Number(item.quantite || 0);
            stockUpdates.set(productId, { id: productId, stock_actuel: nextStock });
        });

        await Promise.all(Array.from(stockUpdates.values()).map(item => fetch(`${supabaseUrl}products?id=eq.${item.id}`, {
            method: 'PATCH',
            headers: supabaseHeaders,
            body: JSON.stringify({ stock_actuel: item.stock_actuel })
        })));

        if (stockUpdates.size > 0) {
            updateCachedProductsLocally(Array.from(stockUpdates.values()));
        }

        const deleteItemsResponse = await fetch(`${supabaseUrl}sale_items?sale_id=eq.${saleId}`, {
            method: 'DELETE',
            headers: supabaseHeaders
        });
        if (!deleteItemsResponse.ok) {
            throw new Error(await deleteItemsResponse.text() || `HTTP ${deleteItemsResponse.status}`);
        }

        const deleteSaleResponse = await fetch(`${supabaseUrl}sales?id=eq.${saleId}`, {
            method: 'DELETE',
            headers: supabaseHeaders
        });
        if (!deleteSaleResponse.ok) {
            throw new Error(await deleteSaleResponse.text() || `HTTP ${deleteSaleResponse.status}`);
        }

        alert(`Vente ${saleNumber || ''} supprimee avec succes.`);
        refreshProductsCacheInBackground('vente-suppression');
        await loadSalesDeletionRows();
    } catch (error) {
        console.error('Erreur suppression vente:', error);
        alert(`Impossible de supprimer la vente.\n\nDetail: ${getSupabaseErrorMessage(error)}`);
    }
}

async function deletePurchaseRecord(purchaseId, purchaseNumber = '') {
    if (!purchaseId) return;
    const confirmed = confirm(`Supprimer definitivement l'achat ${purchaseNumber || ''} ?\n\nLe stock ajoute par cet achat sera retire.`);
    if (!confirmed) return;

    try {
        const purchaseItems = await fetchCollection(`purchase_items?select=product_id,quantite,quantite_gratuite,products(id,stock_actuel)&purchase_id=eq.${purchaseId}`, []);
        const stockUpdates = new Map();
        purchaseItems.forEach(item => {
            const productId = String(item.product_id || '');
            if (!productId) return;
            const currentStock = Number(item.products?.stock_actuel || stockUpdates.get(productId)?.stock_actuel || 0);
            const quantityToRemove = Number(item.quantite || 0) + Number(item.quantite_gratuite || 0);
            const nextStock = Math.max(currentStock - quantityToRemove, 0);
            stockUpdates.set(productId, { id: productId, stock_actuel: nextStock });
        });

        await Promise.all(Array.from(stockUpdates.values()).map(item => fetch(`${supabaseUrl}products?id=eq.${item.id}`, {
            method: 'PATCH',
            headers: supabaseHeaders,
            body: JSON.stringify({ stock_actuel: item.stock_actuel })
        })));

        if (stockUpdates.size > 0) {
            updateCachedProductsLocally(Array.from(stockUpdates.values()));
        }

        const deleteItemsResponse = await fetch(`${supabaseUrl}purchase_items?purchase_id=eq.${purchaseId}`, {
            method: 'DELETE',
            headers: supabaseHeaders
        });
        if (!deleteItemsResponse.ok) {
            throw new Error(await deleteItemsResponse.text() || `HTTP ${deleteItemsResponse.status}`);
        }

        const deletePurchaseResponse = await fetch(`${supabaseUrl}purchases?id=eq.${purchaseId}`, {
            method: 'DELETE',
            headers: supabaseHeaders
        });
        if (!deletePurchaseResponse.ok) {
            throw new Error(await deletePurchaseResponse.text() || `HTTP ${deletePurchaseResponse.status}`);
        }

        alert(`Achat ${purchaseNumber || ''} supprime avec succes.`);
        refreshProductsCacheInBackground('achat-suppression');
        await loadPurchasesDeletionRows();
    } catch (error) {
        console.error('Erreur suppression achat:', error);
        alert(`Impossible de supprimer l'achat.\n\nDetail: ${getSupabaseErrorMessage(error)}`);
    }
}

async function deleteCustomer(id) {
    if (!confirm('Voulez-vous vraiment supprimer ce client ?')) return;

    try {
        const response = await fetch(`${supabaseUrl}customers?id=eq.${id}`, {
            method: 'DELETE',
            headers: supabaseHeaders
        });

        if (response.ok) {
            invalidateReferenceCache('customers');
            loadCustomers();
        }
    } catch (error) {
        console.error('Erreur suppression:', error);
    }
}

