function ensureGlobalProductModalHost() {
    if (document.getElementById('product-modal')) return;
    const host = document.createElement('div');
    host.id = 'global-product-modal-host';
    host.innerHTML = getProductModalMarkup();
    document.body.appendChild(host);
}

async function loadManagedProducts() {
    const requestId = ++managedProductsLastRequestId;
    try {
        const firstBundle = await getManagedProductsBundlePage(0, MANAGED_PRODUCTS_PAGE_SIZE);
        if (requestId !== managedProductsLastRequestId) return;

        allManagedWebCategories = await resolveManagedWebCategoriesFromBundle(firstBundle);
        allManagedProducts = Array.isArray(firstBundle.products) ? firstBundle.products : [];
        managedProductDetailsCache = {};
        populateManagedWebCategorySelect();
        populateManagedProductFilters();
        refreshManagedProductsViews();

        const totalProducts = Number(firstBundle.products_total || allManagedProducts.length || 0);
        if (totalProducts > allManagedProducts.length) {
            void hydrateManagedProductsInBackground(requestId, totalProducts);
        }
    } catch (error) {
        console.error('Erreur articles:', error);
    }
}

let managedProductsCacheTime = 0;
const MANAGED_PRODUCTS_CACHE_TTL = 6 * 60 * 60 * 1000;

async function ensureManagedProductsCacheLoaded() {
    if (Array.isArray(allManagedProducts) && allManagedProducts.length > 0 && Date.now() - managedProductsCacheTime < MANAGED_PRODUCTS_CACHE_TTL) {
        return;
    }

    const requestId = ++managedProductsLastRequestId;
    const firstBundle = await getManagedProductsBundlePage(0, MANAGED_PRODUCTS_PAGE_SIZE);
    if (requestId !== managedProductsLastRequestId) return;

    allManagedWebCategories = await resolveManagedWebCategoriesFromBundle(firstBundle);
    allManagedProducts = Array.isArray(firstBundle.products) ? firstBundle.products : [];
    managedProductDetailsCache = {};
    managedProductsCacheTime = Date.now();

    const totalProducts = Number(firstBundle.products_total || allManagedProducts.length || 0);
    if (totalProducts > allManagedProducts.length) {
        void hydrateManagedProductsInBackground(requestId, totalProducts);
    }
}

async function resolveManagedWebCategoriesFromBundle(bundle) {
    const bundleCategories = Array.isArray(bundle?.web_categories) ? bundle.web_categories : [];
    if (bundleCategories.length > 0) {
        return bundleCategories;
    }

    try {
        const fetchedCategories = await fetchCollection('web_categories?select=id,parent_id,name,slug,sort_order,is_active&is_active=eq.true&order=sort_order.asc,name.asc', []);
        return Array.isArray(fetchedCategories) && fetchedCategories.length > 0
            ? fetchedCategories
            : getFallbackManagedWebCategories();
    } catch (error) {
        console.warn('Chargement web_categories en fallback impossible.', error);
        return getFallbackManagedWebCategories();
    }
}

function flattenManagedWebCategoryTree(nodes, parentId = null, rows = [], state = { nextId: 1 }) {
    (nodes || []).forEach(node => {
        const rowId = `fallback-${state.nextId++}`;
        rows.push({
            id: rowId,
            parent_id: parentId,
            name: node.name,
            slug: node.slug,
            sort_order: Number(node.sort_order || rows.length + 1),
            is_active: true
        });
        if (Array.isArray(node.children) && node.children.length > 0) {
            flattenManagedWebCategoryTree(node.children, rowId, rows, state);
        }
    });
    return rows;
}

function getFallbackManagedWebCategories() {
    return flattenManagedWebCategoryTree(DEFAULT_MANAGED_WEB_CATEGORY_TREE);
}

function refreshManagedProductsViews() {
    filterManagedProducts();
    filterInventoryProducts();
}

function formatPercentDisplay(value) {
    const numeric = Number(value || 0);
    if (!Number.isFinite(numeric)) return '0';
    return Number.isInteger(numeric) ? String(numeric) : String(Number(numeric.toFixed(3)));
}

function getNegativeStockCellStyle(value, baseStyle = '') {
    const numeric = Number(value || 0);
    const negativeStyle = numeric < 0
        ? 'color:#b91c1c; background:#fff1f2; border-radius:8px;'
        : '';
    return `${baseStyle}${negativeStyle}`;
}

function getNegativeStockTextStyle(value, negativeColor = '#b91c1c', normalColor = '#475569') {
    return Number(value || 0) < 0 ? negativeColor : normalColor;
}

function renderManagedProductsTable(data) {
    const tbody = document.getElementById('products-table-body');
    if (!tbody) return;
    const canEditProducts = canManageArticleAction('articles_edit');
    const canDeleteProducts = canManageArticleAction('articles_delete');

    if (!Array.isArray(data) || data.length === 0) {
        tbody.innerHTML = '<tr><td colspan="14" style="text-align:center; padding:40px;">Aucun article charge. Verifiez la table products et les droits Supabase.</td></tr>';
        updateManagedProductsPagination(0);
        return;
    }

    const totalPages = Math.max(1, Math.ceil(data.length / MANAGED_PRODUCTS_TABLE_PAGE_SIZE));
    if (managedProductsCurrentPage > totalPages) {
        managedProductsCurrentPage = totalPages;
    }
    if (managedProductsCurrentPage < 1) {
        managedProductsCurrentPage = 1;
    }

    const startIndex = (managedProductsCurrentPage - 1) * MANAGED_PRODUCTS_TABLE_PAGE_SIZE;
    const pageRows = data.slice(startIndex, startIndex + MANAGED_PRODUCTS_TABLE_PAGE_SIZE);

    tbody.innerHTML = pageRows.map(product => `
        <tr class="${getManagedProductRowClass(product)}">
            <td style="font-weight:700;">${escapeHtml(product.code_article)}</td>
            <td>${escapeHtml(product.designation || '-')}</td>
            <td title="${escapeHtml(getManagedWebCategoryLabel(product.web_category_slug))}"><div class="article-web-category-cell">${escapeHtml(getManagedWebCategoryLeafLabel(product.web_category_slug))}</div></td>
            <td style="${getNegativeStockCellStyle(product.stock_actuel, 'text-align:right; font-weight:700; padding-right:10px;')}">${Number(product.stock_actuel || 0)}</td>
            <td>${product.peremption ? new Date(product.peremption).toLocaleDateString('fr-FR') : '-'}</td>
            <td style="text-align:right;">${formatMoney(product.prix_vente_ht)}</td>
            <td style="text-align:right;">${formatPercentDisplay(product.tva)}</td>
            <td style="text-align:right; font-weight:700;">${formatMoney(product.prix_vente_ttc)}</td>
            <td style="text-align:right; font-weight:800; color:#7c3aed; background:#f5f3ff;">${formatMoney(getProductWebPriceTtc(product))}</td>
            <td style="text-align:right; font-weight:700;">${formatMoney(getProductPassagerPriceTtc(product))}</td>
            <td style="text-align:right;">${formatMoney(product.marge)}</td>
            <td style="text-align:right;">${formatMoney(product.prix_achat_ht)}</td>
            <td style="text-align:right;">${formatMoney(product.prix_achat_ttc)}</td>
            <td style="text-align:center;" class="article-action-cell">
                <button class="small-action-btn" onclick="viewProduct('${product.id}')" style="color:#0369a1; border-color:#0369a1;">Voir</button>
                <button class="small-action-btn" onclick="toggleProductWebMask('${product.id}')" style="color:${product.is_web_hidden ? '#b91c1c' : '#0f766e'}">${product.is_web_hidden ? 'Masque' : 'Masquer'}</button>
                ${canEditProducts ? `<button class="small-action-btn" onclick="editProduct('${product.id}')">Modifier</button>` : ''}
                ${canDeleteProducts ? `<button class="small-action-btn" onclick="deleteProduct('${product.id}')" style="color:red;">Suppr.</button>` : ''}
            </td>
        </tr>
    `).join('');

    updateManagedProductsPagination(data.length);
}

async function filterManagedProducts(options = {}) {
    const tbody = document.getElementById('products-table-body');
    if (!tbody) return;
    const { skipRemoteSearch = false } = options;
    const requestId = ++managedProductSearchRequestId;

    const code = normalizeSearchText(document.getElementById('product-filter-code')?.value || '');
    const designation = normalizeSearchText(document.getElementById('product-filter-designation')?.value || '');
    const tva = document.getElementById('product-filter-tva')?.value || '';
    const peremption = document.getElementById('product-filter-peremption')?.value || '';
    const hideZero = document.getElementById('product-filter-hide-zero')?.checked;
    const alertOnly = document.getElementById('product-filter-alert')?.checked;
    const stockMode = document.querySelector('input[name="product-stock-filter"]:checked')?.value || 'all';
    const hasSearchQuery = Boolean(code || designation);
    const codeTerms = code ? code.split(/\s+/).filter(Boolean) : [];
    const designationTerms = designation ? designation.split(/\s+/).filter(Boolean) : [];

    const today = new Date();
    const soonDate = new Date();
    soonDate.setDate(soonDate.getDate() + 90);

    const filtered = allManagedProducts.filter(product => {
        const stock = Number(product.stock_actuel || 0);
        const tvaValue = String(Number(product.tva ?? 0));
        const peremptionDate = product.peremption ? new Date(product.peremption) : null;
        const normalizedCode = normalizeSearchText(product.code_article || '');
        const normalizedBarcode = normalizeSearchText(product.code_barre || '');
        const normalizedBarcodeCompact = normalizeBarcodeText(product.code_barre || '');
        const compactCodeTerms = codeTerms.map(term => normalizeBarcodeText(term));
        const normalizedDesignation = normalizeSearchText(product.designation || '');
        const normalizedCategory = normalizeSearchText(getManagedWebCategoryLabel(product.web_category_slug) || '');
        const combinedSearch = `${normalizedCode} ${normalizedBarcode} ${normalizedDesignation} ${normalizedCategory}`.trim();

        if (codeTerms.length && !codeTerms.every((term, index) => {
            const compactTerm = compactCodeTerms[index];
            return normalizedCode.includes(term)
                || normalizedBarcode.includes(term)
                || (compactTerm && normalizedBarcodeCompact.includes(compactTerm))
                || combinedSearch.includes(term);
        })) {
            return false;
        }
        if (designationTerms.length && !designationTerms.every(term => normalizedDesignation.includes(term) || combinedSearch.includes(term))) return false;
        if (tva && tvaValue !== tva) return false;
        if (hideZero && stock === 0 && !hasSearchQuery) return false;
        if (alertOnly && !product.date_alerte) return false;
        if (stockMode === 'gt0' && stock <= 0 && !hasSearchQuery) return false;
        if (stockMode === 'eq0' && stock !== 0) return false;
        if (stockMode === 'lt0' && stock >= 0) return false;

        if (peremption === 'expired' && (!peremptionDate || peremptionDate >= today)) return false;
        if (peremption === 'soon' && (!peremptionDate || peremptionDate < today || peremptionDate > soonDate)) return false;
        if (peremption === 'dated' && !peremptionDate) return false;
        if (peremption === 'empty' && peremptionDate) return false;

        return true;
    }).sort((a, b) => {
        const byDesignation = String(a.designation || '').localeCompare(String(b.designation || ''), 'fr', { sensitivity: 'base' });
        if (byDesignation !== 0) return byDesignation;
        return String(a.code_article || '').localeCompare(String(b.code_article || ''), 'fr', { sensitivity: 'base' });
    });

    if (!filtered.length && hasSearchQuery && !skipRemoteSearch) {
        const remoteRows = await searchEntryProductsFromDatabase([code, designation].filter(Boolean).join(' '));
        if (requestId !== managedProductSearchRequestId) return;
        if (remoteRows.length) {
            allManagedProducts = mergeEntryProductsCache(allManagedProducts, remoteRows);
            return filterManagedProducts({ skipRemoteSearch: true });
        }
    }

    filteredManagedProducts = filtered;
    managedProductsCurrentPage = 1;
    const totalEl = document.getElementById('products-total-count');
    if (totalEl) totalEl.innerText = String(filtered.length);
    renderManagedProductsTable(filtered);
}

function updateManagedProductsPagination(totalItems) {
    const total = Math.max(Number(totalItems) || 0, 0);
    const totalPages = Math.max(1, Math.ceil(total / MANAGED_PRODUCTS_TABLE_PAGE_SIZE));
    const currentPage = Math.min(Math.max(managedProductsCurrentPage, 1), totalPages);
    managedProductsCurrentPage = currentPage;

    const start = total === 0 ? 0 : ((currentPage - 1) * MANAGED_PRODUCTS_TABLE_PAGE_SIZE) + 1;
    const end = total === 0 ? 0 : Math.min(currentPage * MANAGED_PRODUCTS_TABLE_PAGE_SIZE, total);

    const pageInfo = document.getElementById('products-page-info');
    const pageRange = document.getElementById('products-page-range');
    if (pageInfo) pageInfo.innerText = `Page ${currentPage} / ${totalPages}`;
    if (pageRange) pageRange.innerText = `${start}-${end} sur ${total}`;

    const buttons = document.querySelectorAll('.article-pagination-btn');
    if (buttons[0]) buttons[0].disabled = currentPage <= 1;
    if (buttons[1]) buttons[1].disabled = currentPage >= totalPages || total === 0;
}

function changeManagedProductsPage(direction) {
    const totalItems = Array.isArray(filteredManagedProducts) ? filteredManagedProducts.length : 0;
    const totalPages = Math.max(1, Math.ceil(totalItems / MANAGED_PRODUCTS_TABLE_PAGE_SIZE));
    const nextPage = managedProductsCurrentPage + Number(direction || 0);

    if (nextPage < 1 || nextPage > totalPages) return;

    managedProductsCurrentPage = nextPage;
    renderManagedProductsTable(filteredManagedProducts);
}

