function getInventoryDocuments() {
    try {
        const raw = localStorage.getItem(INVENTORY_STORAGE_KEY);
        return raw ? JSON.parse(raw) : [];
    } catch { return []; }
}

function saveInventoryDocuments(docs) {
    try {
        localStorage.setItem(INVENTORY_STORAGE_KEY, JSON.stringify(docs));
    } catch {}
}

function loadInventoryDocumentsFromStorage() {
    return getInventoryDocuments();
}

function loadInventoryDocumentList() {
    inventoryDocuments = loadInventoryDocumentsFromStorage();
    const tbody = document.getElementById('inv-list-body');
    if (!tbody) return;
    const fromVal = document.getElementById('inv-list-from')?.value || '';
    const toVal = document.getElementById('inv-list-to')?.value || '';
    const filtered = inventoryDocuments.filter(d => {
        if (fromVal && d.date < fromVal) return false;
        if (toVal && d.date > toVal) return false;
        return true;
    }).sort((a, b) => b.date.localeCompare(a.date) || b.id.localeCompare(a.id));
    const countEl = document.getElementById('inv-list-count');
    if (countEl) countEl.innerText = `${filtered.length} document(s)`;
    if (filtered.length === 0) {
        tbody.innerHTML = '<tr><td colspan="11" style="text-align:center;padding:40px;color:#64748b;">Aucun inventaire trouve.</td></tr>';
        return;
    }
    tbody.innerHTML = filtered.map(d => {
        const totalArticles = Object.keys(d.items || {}).length;
        const corrections = Object.values(d.items || {}).filter(i => i.old_stock !== i.new_stock).length;
        const dateStr = d.date ? d.date.split('-').reverse().join('/') : '-';
        let totalPaHt = 0, totalPaTtc = 0, totalPvHt = 0, totalPvTtc = 0;
        Object.values(d.items || {}).forEach(i => {
            const delta = i.new_stock - i.old_stock;
            totalPaHt += delta * (i.prix_achat_ht || 0);
            totalPaTtc += delta * (i.prix_achat_ttc || 0);
            totalPvHt += delta * (i.prix_vente_ht || 0);
            totalPvTtc += delta * (i.prix_vente_ttc || 0);
        });
        return `
            <tr style="border-bottom:1px solid #e2e8f0;">
                <td style="padding:8px; font-weight:700;">${escapeHtml(d.docNumber || d.id)}</td>
                <td style="padding:8px;">${dateStr}</td>
                <td style="padding:8px; color:#475569;">${escapeHtml(d.operator || '-')}</td>
                <td style="padding:8px; text-align:right; font-weight:600;">${totalArticles}</td>
                <td style="padding:8px; text-align:right; font-weight:600; color:${corrections > 0 ? '#0891b2' : '#94a3b8'};">${corrections}</td>
                <td style="padding:8px; text-align:right; font-size:12px; color:#d97706;">${formatMoney(totalPaHt)}</td>
                <td style="padding:8px; text-align:right; font-size:12px; color:#b45309;">${formatMoney(totalPaTtc)}</td>
                <td style="padding:8px; text-align:right; font-size:12px; color:#2563eb;">${formatMoney(totalPvHt)}</td>
                <td style="padding:8px; text-align:right; font-size:12px; font-weight:700; color:#1d4ed8;">${formatMoney(totalPvTtc)}</td>
                <td style="padding:8px; text-align:center;"><span style="padding:2px 10px; border-radius:4px; font-size:11px; font-weight:700; background:#dcfce7; color:#166534;">Confirmé</span></td>
                <td style="padding:8px; text-align:center;">
                    <button class="small-action-btn" onclick="viewInventoryDocument('${d.id}')" style="margin-right:4px;">Voir</button>
                    <button class="small-action-btn" onclick="printInventoryDocument('${d.id}')">Impr.</button>
                </td>
            </tr>
        `;
    }).join('');
}

function buildInventoryDocNumber() {
    const docs = loadInventoryDocumentsFromStorage();
    const maxNum = docs.reduce((max, d) => {
        const m = (d.docNumber || '').match(/INV-(\d+)/);
        return m ? Math.max(max, parseInt(m[1], 10)) : max;
    }, 0);
    return 'INV-' + String(maxNum + 1).padStart(4, '0');
}

function showNewInventoryPassword() {
    const pwd = prompt('Mot de passe operateur:');
    if (!pwd) return;
    const currentUser = getCurrentBackofficeUser();
    const opName = currentUser ? (currentUser.fullName || currentUser.username) : 'Operateur';
    initNewInventory(opName);
}

function initNewInventory(operator) {
    inventoryViewMode = 'new';
    inventoryNewItems = [];
    inventoryNewValues = {};
    inventoryCurrentDocId = 'inv_' + Date.now() + '_' + Math.random().toString(36).slice(2, 6);
    const docNumber = buildInventoryDocNumber();
    document.getElementById('inv-new-number').textContent = docNumber;
    document.getElementById('inv-new-count').textContent = '0';
    document.getElementById('inventory-list-view').style.display = 'none';
    document.getElementById('inventory-new-view').style.display = 'flex';
    document.getElementById('inv-new-body').innerHTML = '<tr><td colspan="6" style="text-align:center;padding:40px;color:#64748b;">Cliquez sur "Filtres" pour selectionner les articles a corriger.</td></tr>';
    document.getElementById('inv-new-pagination').style.display = 'none';
    inventoryCurrentPage = 1;
    showInventoryFilterModal();
}

function cancelNewInventory() {
    inventoryViewMode = 'list';
    inventoryNewItems = [];
    inventoryNewValues = {};
    inventoryCurrentDocId = null;
    document.getElementById('inventory-list-view').style.display = 'flex';
    document.getElementById('inventory-new-view').style.display = 'none';
    loadInventoryDocumentList();
}

function showInventoryFilterModal() {
    const modal = document.getElementById('inventory-filter-modal');
    if (!modal) return;
    modal.style.display = 'flex';
    document.getElementById('inv-modal-code').value = '';
    document.getElementById('inv-modal-designation').value = '';
    document.getElementById('inv-modal-stock').value = 'all';
    document.getElementById('inv-modal-peremption').value = '';
    document.getElementById('inv-modal-alert').checked = false;
    document.getElementById('inv-modal-hide-zero').checked = false;
    document.getElementById('inv-modal-not-moved').value = '';
    populateInventoryFormes();
    populateInventoryCategories();
    setTimeout(() => document.getElementById('inv-modal-code')?.focus(), 100);
}

function populateInventoryFormes() {
    const sel = document.getElementById('inv-modal-forme');
    if (!sel) return;
    const formes = new Set();
    if (Array.isArray(allManagedProducts)) {
        allManagedProducts.forEach(p => { if (p.forme) formes.add(p.forme); });
    }
    const current = sel.value;
    sel.innerHTML = '<option value="">Toutes</option>' + Array.from(formes).sort().map(f => `<option value="${escapeHtml(f)}">${escapeHtml(f)}</option>`).join('');
    sel.value = current || '';
}

let _cachedCategories = [];
async function populateInventoryCategories() {
    const sel = document.getElementById('inv-modal-categorie');
    if (!sel) return;
    if (_cachedCategories.length === 0) {
        try {
            const { data } = await supabase.from('web_categories').select('id,name').order('name');
            if (data) _cachedCategories = data;
        } catch {}
    }
    const current = sel.value;
    sel.innerHTML = '<option value="">Toutes</option>' + _cachedCategories.map(c => `<option value="${c.id}">${escapeHtml(c.name)}</option>`).join('');
    sel.value = current || '';
}

function hideInventoryFilterModal() {
    const modal = document.getElementById('inventory-filter-modal');
    if (modal) modal.style.display = 'none';
}

function applyInventoryFiltersFromModal() {
    const code = (document.getElementById('inv-modal-code')?.value || '').toLowerCase().trim();
    const designation = (document.getElementById('inv-modal-designation')?.value || '').toLowerCase().trim();
    const stockMode = document.getElementById('inv-modal-stock')?.value || 'all';
    const peremption = document.getElementById('inv-modal-peremption')?.value || '';
    const hideZero = document.getElementById('inv-modal-hide-zero')?.checked;
    const alertOnly = document.getElementById('inv-modal-alert')?.checked;
    const forme = document.getElementById('inv-modal-forme')?.value || '';
    const categorie = document.getElementById('inv-modal-categorie')?.value || '';
    const notMovedSince = document.getElementById('inv-modal-not-moved')?.value || '';
    const today = new Date();
    const soonDate = new Date();
    soonDate.setDate(soonDate.getDate() + 90);

    inventoryNewItems = Array.isArray(allManagedProducts) ? allManagedProducts.filter(product => {
        const stock = Number(product.stock_actuel || 0);
        const peremptionDate = product.peremption ? new Date(product.peremption) : null;
        if (code && !String(product.code_article || '').toLowerCase().includes(code) && !String(product.code_barre || '').toLowerCase().includes(code)) return false;
        if (designation && !String(product.designation || '').toLowerCase().includes(designation)) return false;
        if (hideZero && stock === 0) return false;
        if (alertOnly && !product.date_alerte) return false;
        if (stockMode === 'gt0' && stock <= 0) return false;
        if (stockMode === 'eq0' && stock !== 0) return false;
        if (stockMode === 'lt0' && stock >= 0) return false;
        if (peremption === 'expired' && (!peremptionDate || peremptionDate >= today)) return false;
        if (peremption === 'soon' && (!peremptionDate || peremptionDate < today || peremptionDate > soonDate)) return false;
        if (peremption === 'dated' && !peremptionDate) return false;
        if (peremption === 'empty' && peremptionDate) return false;
        if (forme && product.forme !== forme) return false;
        if (categorie && String(product.web_category_slug || '') !== categorie && String(product.categorie || '') !== categorie) return false;
        return true;
    }) : [];

    const countEl = document.getElementById('inv-new-count');
    if (notMovedSince && Array.isArray(inventoryNewItems) && inventoryNewItems.length > 0) {
        applyNotMovedSinceFilter(notMovedSince, countEl);
        return;
    }

    inventoryCurrentPage = 1;
    if (countEl) countEl.innerText = String(inventoryNewItems.length);
    hideInventoryFilterModal();
    if (inventoryNewItems.length === 0) {
        document.getElementById('inv-new-body').innerHTML = '<tr><td colspan="6" style="text-align:center;padding:40px;color:#64748b;">Aucun article ne correspond aux filtres.</td></tr>';
        document.getElementById('inv-new-pagination').style.display = 'none';
        return;
    }
    renderInventoryNewTable();
}

async function applyNotMovedSinceFilter(notMovedSince, countEl) {
    try {
        const sinceDate = new Date(notMovedSince);
        const prodIds = inventoryNewItems.map(p => p.id).filter(Boolean);
        if (prodIds.length === 0) { finalizeNotMovedFilter(null, countEl); return; }
        const batchSize = 50;
        const movedIds = new Set();
        const tables = ['stock_operations', 'sale_items', 'purchase_items'];
        for (let i = 0; i < prodIds.length; i += batchSize) {
            const batch = prodIds.slice(i, i + batchSize);
            const promises = tables.map(tbl =>
                supabase.from(tbl)
                    .select('product_id')
                    .in('product_id', batch)
                    .gte('created_at', notMovedSince)
                    .limit(1)
                    .then(({ data }) => { if (data) data.forEach(r => movedIds.add(r.product_id)); })
                    .catch(() => {})
            );
            await Promise.allSettled(promises);
        }
        inventoryNewItems = inventoryNewItems.filter(p => !movedIds.has(p.id));
        finalizeNotMovedFilter(countEl);
    } catch {
        finalizeNotMovedFilter(countEl);
    }
}

function finalizeNotMovedFilter(countEl) {
    inventoryCurrentPage = 1;
    if (countEl) countEl.innerText = String(inventoryNewItems.length);
    hideInventoryFilterModal();
    if (inventoryNewItems.length === 0) {
        document.getElementById('inv-new-body').innerHTML = '<tr><td colspan="6" style="text-align:center;padding:40px;color:#64748b;">Aucun article ne correspond aux filtres.</td></tr>';
        document.getElementById('inv-new-pagination').style.display = 'none';
        return;
    }
    renderInventoryNewTable();
}

function renderInventoryNewTable() {
    const tbody = document.getElementById('inv-new-body');
    if (!tbody) return;
    const totalItems = inventoryNewItems.length;
    const totalPages = Math.max(1, Math.ceil(totalItems / INVENTORY_TABLE_PAGE_SIZE));
    if (inventoryCurrentPage > totalPages) inventoryCurrentPage = totalPages;
    if (inventoryCurrentPage < 1) inventoryCurrentPage = 1;
    const startIndex = (inventoryCurrentPage - 1) * INVENTORY_TABLE_PAGE_SIZE;
    const pageRows = inventoryNewItems.slice(startIndex, startIndex + INVENTORY_TABLE_PAGE_SIZE);

    tbody.innerHTML = pageRows.map(product => {
        const currentStock = Number(product.stock_actuel || 0);
        const pendingVal = inventoryNewValues[product.id];
        const nextValueStr = pendingVal !== undefined ? String(pendingVal) : String(currentStock);
        const nextValue = Number(nextValueStr);
        const hasNextValue = !isNaN(nextValue);
        const delta = hasNextValue ? (nextValue - currentStock) : null;
        return `
            <tr data-inv-row="${product.id}" data-current-stock="${currentStock}">
                <td style="padding:8px; font-weight:700;">${escapeHtml(product.code_article || '-')}</td>
                <td style="padding:8px;">${escapeHtml(product.designation || '-')}</td>
                <td style="padding:8px; text-align:right; font-weight:700; ${currentStock < 0 ? 'color:#dc2626;' : ''}">${formatMoney(currentStock)}</td>
                <td style="padding:8px;">${product.peremption ? new Date(product.peremption).toLocaleDateString('fr-FR') : '-'}</td>
                <td style="padding:8px; text-align:center;">
                    <input type="number" class="field-input" style="width:100px; text-align:center; font-weight:700;" value="${nextValueStr}" step="any" onchange="updateInventoryNewValue('${product.id}', this.value)" onclick="this.select()">
                </td>
                <td style="padding:8px; text-align:right; font-weight:700; color:${delta === null ? '#94a3b8' : delta > 0 ? '#16a34a' : delta < 0 ? '#dc2626' : '#94a3b8'};">${delta === null ? '-' : (delta > 0 ? '+' : '') + formatMoney(delta)}</td>
            </tr>
        `;
    }).join('');

    const pagination = document.getElementById('inv-new-pagination');
    if (totalPages > 1) {
        pagination.style.display = 'flex';
        document.getElementById('inv-new-page-info').innerText = `Page ${inventoryCurrentPage} / ${totalPages}`;
        const start = ((inventoryCurrentPage - 1) * INVENTORY_TABLE_PAGE_SIZE) + 1;
        const end = Math.min(inventoryCurrentPage * INVENTORY_TABLE_PAGE_SIZE, totalItems);
        document.getElementById('inv-new-page-range').innerText = `${start}-${end} sur ${totalItems}`;
    } else {
        pagination.style.display = 'none';
    }
}

function changeInventoryNewPage(direction) {
    const totalPages = Math.max(1, Math.ceil(inventoryNewItems.length / INVENTORY_TABLE_PAGE_SIZE));
    const next = inventoryCurrentPage + Number(direction || 0);
    if (next < 1 || next > totalPages) return;
    inventoryCurrentPage = next;
    renderInventoryNewTable();
}

function updateInventoryNewValue(productId, value) {
    const v = String(value ?? '').trim();
    inventoryNewValues[productId] = v === '' ? undefined : Number(v);
    const row = document.querySelector(`[data-inv-row="${productId}"]`);
    if (!row) return;
    const currentStock = Number(row.getAttribute('data-current-stock') || 0);
    const nextVal = inventoryNewValues[productId];
    const delta = nextVal !== undefined ? nextVal - currentStock : null;
    const deltaCell = row.querySelector('td:last-child');
    if (deltaCell) {
        deltaCell.innerText = delta === null ? '-' : (delta > 0 ? '+' : '') + formatMoney(delta);
        deltaCell.style.color = delta === null ? '#94a3b8' : delta > 0 ? '#16a34a' : delta < 0 ? '#dc2626' : '#94a3b8';
    }
}

async function confirmInventoryDocument() {
    const items = Object.keys(inventoryNewValues)
        .filter(pid => inventoryNewValues[pid] !== undefined)
        .map(pid => {
            const product = Array.isArray(allManagedProducts) ? allManagedProducts.find(p => p.id === pid) : null;
            return { productId: pid, product, newStock: inventoryNewValues[pid] };
        })
        .filter(i => i.product && i.newStock !== Number(i.product.stock_actuel || 0));

    if (items.length === 0) {
        alert('Aucune correction a enregistrer.');
        return;
    }

    if (!confirm(`Confirmer l'inventaire avec ${items.length} correction(s) ?`)) return;

    const docNumber = document.getElementById('inv-new-number')?.textContent || buildInventoryDocNumber();
    const dateVal = document.getElementById('inv-new-date')?.value || new Date().toISOString().split('T')[0];
    const currentUser = getCurrentBackofficeUser();
    const operator = currentUser ? (currentUser.fullName || currentUser.username) : 'Operateur';
    let successCount = 0;
    let failCount = 0;

    for (const item of items) {
        try {
            const response = await fetch(`${supabaseUrl}products?id=eq.${encodeURIComponent(item.productId)}`, {
                method: 'PATCH',
                headers: supabaseHeaders,
                body: JSON.stringify({ stock_actuel: item.newStock })
            });
            if (response.ok) {
                allManagedProducts = allManagedProducts.map(p => p.id === item.productId ? { ...p, stock_actuel: item.newStock } : p);
                successCount++;
            } else {
                failCount++;
            }
        } catch {
            failCount++;
        }
    }

    const docItems = {};
    items.forEach(item => {
        docItems[item.productId] = {
            code: item.product.code_article || '',
            designation: item.product.designation || '',
            old_stock: Number(item.product.stock_actuel || 0),
            new_stock: item.newStock,
            prix_achat_ht: Number(item.product.prix_achat_ht || 0),
            prix_achat_ttc: Number(item.product.prix_achat_ttc || 0),
            prix_vente_ht: Number(item.product.prix_vente_ht || 0),
            prix_vente_ttc: Number(item.product.prix_vente_ttc || 0)
        };
    });
    const docData = {
        id: inventoryCurrentDocId,
        docNumber,
        date: dateVal,
        operator,
        items: docItems,
        createdAt: new Date().toISOString()
    };
    const docs = loadInventoryDocumentsFromStorage();
    docs.unshift(docData);
    saveInventoryDocuments(docs);

    const msg = successCount > 0 ? `${successCount} correction(s) enregistree(s).` : '';
    const errMsg = failCount > 0 ? ` ${failCount} echec(s).` : '';
    alert(`Inventaire ${docNumber} confirme. ${msg}${errMsg}`);
    cancelNewInventory();
}

function viewInventoryDocument(docId) {
    const docs = loadInventoryDocumentsFromStorage();
    const doc = docs.find(d => d.id === docId);
    if (!doc) { alert('Document introuvable.'); return; }
    const items = Object.values(doc.items || {});
    const tbody = document.getElementById('inv-new-body');
    if (!tbody) return;
    inventoryViewMode = 'view';
    inventoryCurrentDocId = docId;
    document.getElementById('inventory-list-view').style.display = 'none';
    document.getElementById('inventory-new-view').style.display = 'flex';
    document.getElementById('inv-new-number').textContent = doc.docNumber;
    document.getElementById('inv-new-date').value = doc.date;
    document.getElementById('inv-new-count').textContent = items.length;
    document.getElementById('inv-new-pagination').style.display = 'none';
    const btns = document.querySelector('#inventory-new-view .stock-op-header-compact')?.querySelector('.achat-btn.green');
    if (btns) btns.style.display = 'none';
    if (items.length === 0) {
        tbody.innerHTML = '<tr><td colspan="6" style="text-align:center;padding:40px;color:#64748b;">Aucun article dans ce document.</td></tr>';
        return;
    }
    tbody.innerHTML = items.map(item => {
        const delta = item.new_stock - item.old_stock;
        return `
            <tr>
                <td style="padding:8px; font-weight:700;">${escapeHtml(item.code || '-')}</td>
                <td style="padding:8px;">${escapeHtml(item.designation || '-')}</td>
                <td style="padding:8px; text-align:right; font-weight:700;">${formatMoney(item.old_stock)}</td>
                <td style="padding:8px;">-</td>
                <td style="padding:8px; text-align:center; font-weight:700;">${formatMoney(item.new_stock)}</td>
                <td style="padding:8px; text-align:right; font-weight:700; color:${delta === 0 ? '#94a3b8' : delta > 0 ? '#16a34a' : '#dc2626'};">${delta === 0 ? '-' : (delta > 0 ? '+' : '') + formatMoney(delta)}</td>
            </tr>
        `;
    }).join('');
}

function printInventoryDocument(docId) {
    if (!docId) { alert('Aucun document a imprimer.'); return; }
    const docs = loadInventoryDocumentsFromStorage();
    const doc = docs.find(d => d.id === docId);
    if (!doc) { alert('Document introuvable.'); return; }
    const items = Object.values(doc.items || {});
    const dateStr = doc.date ? doc.date.split('-').reverse().join('/') : '-';
    let grandTotalPaHt = 0, grandTotalPaTtc = 0, grandTotalPvHt = 0, grandTotalPvTtc = 0;
    const rows = items.map((item, i) => {
        const delta = item.new_stock - item.old_stock;
        const valPaHt = delta * (item.prix_achat_ht || 0);
        const valPaTtc = delta * (item.prix_achat_ttc || 0);
        const valPvHt = delta * (item.prix_vente_ht || 0);
        const valPvTtc = delta * (item.prix_vente_ttc || 0);
        grandTotalPaHt += valPaHt;
        grandTotalPaTtc += valPaTtc;
        grandTotalPvHt += valPvHt;
        grandTotalPvTtc += valPvTtc;
        return `
            <tr>
                <td style="border:1px solid #333; padding:6px; text-align:center;">${i + 1}</td>
                <td style="border:1px solid #333; padding:6px;">${escapeHtml(item.code || '')}</td>
                <td style="border:1px solid #333; padding:6px;">${escapeHtml(item.designation || '')}</td>
                <td style="border:1px solid #333; padding:6px; text-align:right; color:#d97706;">${formatMoney(valPaHt)}</td>
                <td style="border:1px solid #333; padding:6px; text-align:right; color:#b45309;">${formatMoney(valPaTtc)}</td>
                <td style="border:1px solid #333; padding:6px; text-align:right; color:#2563eb;">${formatMoney(valPvHt)}</td>
                <td style="border:1px solid #333; padding:6px; text-align:right; color:#1d4ed8;">${formatMoney(valPvTtc)}</td>
                <td style="border:1px solid #333; padding:6px; text-align:right;">${formatMoney(item.old_stock)}</td>
                <td style="border:1px solid #333; padding:6px; text-align:right;">${formatMoney(item.new_stock)}</td>
                <td style="border:1px solid #333; padding:6px; text-align:right;">${delta === 0 ? '-' : (delta > 0 ? '+' : '') + formatMoney(delta)}</td>
            </tr>
        `;
    }).join('');
    const win = window.open('', '_blank');
    win.document.write(`<!DOCTYPE html><html><head><meta charset="utf-8"><title>Inventaire ${doc.docNumber}</title><style>
        body { font-family: Arial, sans-serif; padding: 20px; }
        h2 { text-align:center; margin-bottom:5px; }
        .meta { text-align:center; font-size:13px; color:#555; margin-bottom:20px; }
        table { width:100%; border-collapse:collapse; }
        th { background:#1e293b; color:white; padding:8px; border:1px solid #333; font-size:12px; }
        td { font-size:12px; }
        .footer { margin-top:30px; display:flex; justify-content:space-between; }
        .footer div { text-align:center; }
        .footer .line { border-top:1px solid #333; width:150px; margin-top:30px; padding-top:5px; font-size:11px; }
    </style></head><body>
        <h2>INVENTAIRE</h2>
        <div class="meta">N ${doc.docNumber} | Date: ${dateStr} | Operateur: ${escapeHtml(doc.operator || '')}</div>
        <table>
            <thead><tr><th>#</th><th>Code</th><th>Designation</th><th style="color:#d97706;">Val. PA HT</th><th style="color:#b45309;">Val. PA TTC</th><th style="color:#2563eb;">Val. PV HT</th><th style="color:#1d4ed8;">Val. PV TTC</th><th>Stock actuel</th><th>Nouveau stock</th><th>Ecart</th></tr></thead>
            <tbody>${rows}</tbody>
            <tfoot><tr style="font-weight:700; background:#f1f5f9;">
                <td colspan="3" style="border:1px solid #333; padding:6px; text-align:right;">TOTAUX</td>
                <td style="border:1px solid #333; padding:6px; text-align:right; color:#d97706;">${formatMoney(grandTotalPaHt)}</td>
                <td style="border:1px solid #333; padding:6px; text-align:right; color:#b45309;">${formatMoney(grandTotalPaTtc)}</td>
                <td style="border:1px solid #333; padding:6px; text-align:right; color:#2563eb;">${formatMoney(grandTotalPvHt)}</td>
                <td style="border:1px solid #333; padding:6px; text-align:right; color:#1d4ed8;">${formatMoney(grandTotalPvTtc)}</td>
                <td style="border:1px solid #333; padding:6px;"></td>
                <td style="border:1px solid #333; padding:6px;"></td>
                <td style="border:1px solid #333; padding:6px;"></td>
            </tr></tfoot>
        </table>
        <div class="footer">
            <div><div class="line">Signature operateur</div></div>
            <div><div class="line">Validation</div></div>
        </div>
        <script>window.print();window.close();</script>
    </body></html>`);
    win.document.close();
}

function loadInventoryProducts() {
    if (inventoryViewMode === 'new') {
        showInventoryFilterModal();
    } else {
        initInventoryModule();
    }
}

function getInventoryPendingValue(product) {
    if (Object.prototype.hasOwnProperty.call(inventoryNewValues, product.id)) {
        return String(inventoryNewValues[product.id] ?? '');
    }
    return '';
}

function setInventoryPendingValue(productId, value) {
    inventoryNewValues[productId] = String(value ?? '').trim();
}

function filterInventoryProducts() {
    applyInventoryFiltersFromModal();
}

function renderInventoryTable(data) {
    const tbody = document.getElementById('inv-new-body');
    if (!tbody) return;
    if (!Array.isArray(data) || data.length === 0) {
        tbody.innerHTML = '<tr><td colspan="6" style="text-align:center;padding:40px;">Aucun article a corriger.</td></tr>';
        return;
    }
    inventoryNewItems = data;
    renderInventoryNewTable();
}

function resetInventoryFilters() {
    document.getElementById('inv-modal-code').value = '';
    document.getElementById('inv-modal-designation').value = '';
    document.getElementById('inv-modal-stock').value = 'all';
    document.getElementById('inv-modal-peremption').value = '';
    document.getElementById('inv-modal-alert').checked = false;
    document.getElementById('inv-modal-hide-zero').checked = false;
    applyInventoryFiltersFromModal();
}

function changeInventoryPage(direction) {
    changeInventoryNewPage(direction);
}

function applyInventoryCorrection(productId) {
    const val = inventoryNewValues[productId];
    if (val === undefined) { alert('Saisissez le nouveau stock.'); return; }
    if (!confirm(`Corriger le stock de cet article ?`)) return;
    const product = Array.isArray(allManagedProducts) ? allManagedProducts.find(p => p.id === productId) : null;
    if (!product) { alert('Article introuvable.'); return; }
    fetch(`${supabaseUrl}products?id=eq.${encodeURIComponent(productId)}`, {
        method: 'PATCH',
        headers: supabaseHeaders,
        body: JSON.stringify({ stock_actuel: val })
    }).then(r => {
        if (!r.ok) throw new Error('Erreur');
        allManagedProducts = allManagedProducts.map(p => p.id === productId ? { ...p, stock_actuel: val } : p);
        alert('Stock corrige.');
    }).catch(e => alert('Erreur: ' + e.message));
}

async function initStockExpiryModule() {
    await ensureManagedProductsCacheLoaded();
    stockExpiryState.products = Array.isArray(allManagedProducts) ? allManagedProducts.slice() : [];
    filterStockExpiryProducts();
}

async function loadStockExpiryProducts() {
    await ensureManagedProductsCacheLoaded();
    stockExpiryState.products = Array.isArray(allManagedProducts) ? allManagedProducts.slice() : [];
    filterStockExpiryProducts();
}

function getStockExpiryStatusBadge(info) {
    if (!info?.hasDate) {
        return '<span class="expiry-status-badge expiry-status-empty">Sans date</span>';
    }
    if (info.status === 'expired') {
        return '<span class="expiry-status-badge expiry-status-expired">Expiree</span>';
    }
    if (info.status === 'soon') {
        return '<span class="expiry-status-badge expiry-status-soon">Alerte 4 mois</span>';
    }
    return '<span class="expiry-status-badge expiry-status-ok">OK</span>';
}

function filterStockExpiryProducts() {
    const tbody = document.getElementById('stock-expiry-table-body');
    if (!tbody) return;

    const code = (document.getElementById('stock-expiry-filter-code')?.value || '').toLowerCase().trim();
    const designation = (document.getElementById('stock-expiry-filter-designation')?.value || '').toLowerCase().trim();
    const status = document.getElementById('stock-expiry-filter-status')?.value || 'alert';
    const stockMode = document.getElementById('stock-expiry-filter-stock')?.value || 'all';
    const fromDate = parseDateOnlyValue(document.getElementById('stock-expiry-filter-from')?.value || '');
    const toDate = parseDateOnlyValue(document.getElementById('stock-expiry-filter-to')?.value || '');
    const hideZero = document.getElementById('stock-expiry-filter-hide-zero')?.checked;
    const alertOnly = document.getElementById('stock-expiry-filter-only-alert-date')?.checked;

    const rows = (stockExpiryState.products || []).map(product => ({
        ...product,
        expiryInfo: getPeremptionAlertInfo(product.peremption, 4)
    })).filter(product => {
        const stock = Number(product.stock_actuel || 0);
        const currentStatus = product.expiryInfo?.hasDate ? product.expiryInfo.status : 'empty';
        const expiryDate = product.expiryInfo?.date || null;

        if (code && !String(product.code_article || '').toLowerCase().includes(code) && !String(product.code_barre || '').toLowerCase().includes(code)) {
            return false;
        }
        if (designation && !String(product.designation || '').toLowerCase().includes(designation)) return false;
        if (fromDate && (!expiryDate || expiryDate < fromDate)) return false;
        if (toDate && (!expiryDate || expiryDate > toDate)) return false;
        if (hideZero && stock === 0) return false;
        if (alertOnly && !product.date_alerte) return false;
        if (stockMode === 'gt0' && stock <= 0) return false;
        if (stockMode === 'eq0' && stock !== 0) return false;
        if (stockMode === 'lt0' && stock >= 0) return false;
        if (status === 'alert' && !['expired', 'soon'].includes(currentStatus)) return false;
        if (status === 'expired' && currentStatus !== 'expired') return false;
        if (status === 'soon' && currentStatus !== 'soon') return false;
        if (status === 'ok' && currentStatus !== 'ok') return false;
        if (status === 'empty' && currentStatus !== 'empty') return false;
        return true;
    }).sort((a, b) => {
        const aDate = a.expiryInfo?.date?.getTime?.() ?? Number.MAX_SAFE_INTEGER;
        const bDate = b.expiryInfo?.date?.getTime?.() ?? Number.MAX_SAFE_INTEGER;
        if (aDate !== bDate) return aDate - bDate;
        return String(a.designation || '').localeCompare(String(b.designation || ''), 'fr', { sensitivity: 'base' });
    });

    stockExpiryState.filteredProducts = rows;
    stockExpiryState.currentPage = 1;

    const totalEl = document.getElementById('stock-expiry-total-count');
    if (totalEl) totalEl.innerText = String(rows.length);

    const expiredCount = rows.filter(item => item.expiryInfo?.status === 'expired').length;
    const soonCount = rows.filter(item => item.expiryInfo?.status === 'soon').length;
    const summary = document.getElementById('stock-expiry-summary');
    if (summary) {
        summary.innerText = `${rows.length} article(s) | Expire(s): ${expiredCount} | Alerte moins de 4 mois: ${soonCount}`;
    }

    renderStockExpiryTable(rows);
}

function renderStockExpiryTable(data) {
    const tbody = document.getElementById('stock-expiry-table-body');
    if (!tbody) return;

    if (!Array.isArray(data) || data.length === 0) {
        tbody.innerHTML = '<tr><td colspan="7" style="text-align:center; padding:40px;">Aucune alerte peremption.</td></tr>';
        updateStockExpiryPagination(0);
        return;
    }

    const totalPages = Math.max(1, Math.ceil(data.length / INVENTORY_TABLE_PAGE_SIZE));
    if (stockExpiryState.currentPage > totalPages) stockExpiryState.currentPage = totalPages;
    if (stockExpiryState.currentPage < 1) stockExpiryState.currentPage = 1;

    const startIndex = (stockExpiryState.currentPage - 1) * INVENTORY_TABLE_PAGE_SIZE;
    const pageRows = data.slice(startIndex, startIndex + INVENTORY_TABLE_PAGE_SIZE);

    tbody.innerHTML = pageRows.map(product => {
        const stock = Number(product.stock_actuel || 0);
        const info = product.expiryInfo || getPeremptionAlertInfo(product.peremption, 4);
        const daysText = !info.hasDate ? '-' : info.status === 'expired' ? `${Math.abs(Number(info.daysLeft || 0))} j depasse` : `${Number(info.daysLeft || 0)} j`;

        return `
            <tr class="${info.status === 'expired' ? 'expiry-table-row-expired' : info.status === 'soon' ? 'expiry-table-row-soon' : ''}">
                <td style="font-weight:700;">${escapeHtml(product.code_article || '-')}</td>
                <td>${escapeHtml(product.designation || '-')}</td>
                <td style="${getNegativeStockCellStyle(stock, 'text-align:right; font-weight:700; padding-right:10px;')}">${formatMoney(stock)}</td>
                <td>${product.peremption ? new Date(product.peremption).toLocaleDateString('fr-FR') : '-'}</td>
                <td style="text-align:right; font-weight:700;">${daysText}</td>
                <td>${getStockExpiryStatusBadge(info)}</td>
                <td>${product.date_alerte ? new Date(product.date_alerte).toLocaleDateString('fr-FR') : '-'}</td>
            </tr>
        `;
    }).join('');

    updateStockExpiryPagination(data.length);
}

function updateStockExpiryPagination(totalItems) {
    const total = Math.max(Number(totalItems) || 0, 0);
    const totalPages = Math.max(1, Math.ceil(total / INVENTORY_TABLE_PAGE_SIZE));
    const currentPage = Math.min(Math.max(stockExpiryState.currentPage, 1), totalPages);
    stockExpiryState.currentPage = currentPage;

    const start = total === 0 ? 0 : ((currentPage - 1) * INVENTORY_TABLE_PAGE_SIZE) + 1;
    const end = total === 0 ? 0 : Math.min(currentPage * INVENTORY_TABLE_PAGE_SIZE, total);

    const pageInfo = document.getElementById('stock-expiry-page-info');
    const pageRange = document.getElementById('stock-expiry-page-range');
    if (pageInfo) pageInfo.innerText = `Page ${currentPage} / ${totalPages}`;
    if (pageRange) pageRange.innerText = `${start}-${end} sur ${total}`;

    const buttons = document.querySelectorAll('#tab-content .inventory-view .article-pagination-btn');
    if (buttons[0]) buttons[0].disabled = currentPage <= 1;
    if (buttons[1]) buttons[1].disabled = currentPage >= totalPages || total === 0;
}

function changeStockExpiryPage(direction) {
    const totalItems = Array.isArray(stockExpiryState.filteredProducts) ? stockExpiryState.filteredProducts.length : 0;
    const totalPages = Math.max(1, Math.ceil(totalItems / INVENTORY_TABLE_PAGE_SIZE));
    const nextPage = stockExpiryState.currentPage + Number(direction || 0);
    if (nextPage < 1 || nextPage > totalPages) return;
    stockExpiryState.currentPage = nextPage;
    renderStockExpiryTable(stockExpiryState.filteredProducts);
}

function resetStockExpiryFilters() {
    const ids = [
        'stock-expiry-filter-code',
        'stock-expiry-filter-designation',
        'stock-expiry-filter-status',
        'stock-expiry-filter-stock',
        'stock-expiry-filter-from',
        'stock-expiry-filter-to'
    ];

    ids.forEach(id => {
        const field = document.getElementById(id);
        if (!field) return;
        if (field.tagName === 'SELECT') {
            field.value = id === 'stock-expiry-filter-status' ? 'alert' : 'all';
        } else {
            field.value = '';
        }
    });

    const hideZero = document.getElementById('stock-expiry-filter-hide-zero');
    const alertOnly = document.getElementById('stock-expiry-filter-only-alert-date');
    if (hideZero) hideZero.checked = false;
    if (alertOnly) alertOnly.checked = false;

    stockExpiryState.currentPage = 1;
    filterStockExpiryProducts();
}

function getStockOperationConfig(moduleId) {
    return STOCK_OPERATION_TYPES[moduleId] || null;
}

function normalizeStockOperationRecord(item) {
    if (!item) return null;
    const moduleId = item.moduleId || item.module_id || '';
    const config = getStockOperationConfig(moduleId);
    return {
        id: item.id || buildStockOperationId(config?.key || 'MOV'),
        numero: item.numero || item.operation_number || '',
        moduleId,
        type: item.type || item.movement_type || config?.key || '',
        product_id: item.product_id || '',
        code_article: item.code_article || item.product_code || '',
        designation: item.designation || item.product_designation || '',
        partner: item.partner || item.partner_name || '',
        note: item.note || '',
        quantity: Number(item.quantity || 0),
        stock_effect: Number(item.stock_effect || 0),
        date: item.date || item.operation_date || item.created_at || ''
    };
}

function getStockOperationRecords() {
    try {
        if (Array.isArray(stockOperationRecordsCache) && stockOperationRecordsCache.length > 0) {
            return stockOperationRecordsCache;
        }
        const raw = localStorage.getItem(STOCK_OPERATION_STORAGE_KEY);
        const parsed = raw ? JSON.parse(raw) : [];
        const normalized = Array.isArray(parsed) ? parsed.map(normalizeStockOperationRecord).filter(Boolean) : [];
        stockOperationRecordsCache = normalized;
        return normalized;
    } catch (error) {
        console.warn('Lecture mouvements stock impossible.', error);
        return [];
    }
}

function saveStockOperationRecords(records) {
    const normalized = Array.isArray(records) ? records.map(normalizeStockOperationRecord).filter(Boolean) : [];
    stockOperationRecordsCache = normalized;
    articleMovementState.stockOperations = normalized;
    localStorage.setItem(STOCK_OPERATION_STORAGE_KEY, JSON.stringify(normalized));
}

async function loadStockOperationRecordsFromSupabase() {
    egressTracker.pushFlow('load-stock-ops');
    try {
    const rows = await fetchCollection('stock_operations?select=id,operation_number,module_id,movement_type,product_id,product_code,product_designation,partner_name,quantity,stock_effect,operation_date,note,created_at,created_by&order=operation_date.desc,created_at.desc', []);
    const normalized = Array.isArray(rows) ? rows.map(normalizeStockOperationRecord).filter(Boolean) : [];
    if (normalized.length === 0) {
        const localRows = getStockOperationRecords();
        if (Array.isArray(localRows) && localRows.length > 0) {
            articleMovementState.stockOperations = localRows;
            return localRows;
        }
    }
    saveStockOperationRecords(normalized);
    return normalized;
    } finally { egressTracker.popFlow(); }
}

async function ensureStockOperationRecordsLoaded(forceRefresh = false) {
    if (!forceRefresh && Array.isArray(stockOperationRecordsCache) && stockOperationRecordsCache.length > 0) {
        articleMovementState.stockOperations = stockOperationRecordsCache;
        return stockOperationRecordsCache;
    }

    try {
        const rows = await loadStockOperationRecordsFromSupabase();
        articleMovementState.stockOperations = rows;
        return rows;
    } catch (error) {
        console.warn('Lecture Supabase mouvements stock indisponible, repli local.', error);
        const localRows = getStockOperationRecords();
        articleMovementState.stockOperations = localRows;
        return localRows;
    }
}

function buildStockOperationId(prefix = 'MOV') {
    return generateLegacyPrefixedNumber(prefix);
}

function getStockOperationNumberPrefix(configKey = '') {
    if (configKey === 'ENTREE') return 'ENT';
    if (configKey === 'SORTIE') return 'SOR';
    if (configKey === 'PRET') return 'PRT';
    if (configKey === 'EMPRUNT') return 'EMP';
    return 'MOV';
}

function syncProductStockCache(productId, nextStock) {
    const apply = (list) => Array.isArray(list)
        ? list.map(item => String(item.id) === String(productId) ? { ...item, stock_actuel: nextStock } : item)
        : list;

    allManagedProducts = apply(allManagedProducts);
    filteredManagedProducts = apply(filteredManagedProducts);
    filteredInventoryProducts = apply(filteredInventoryProducts);
    saleState.products = apply(saleState.products);
    articleMovementState.products = apply(articleMovementState.products);
    webStoreState.products = apply(webStoreState.products);
    if (managedProductDetailsCache[productId]) {
        managedProductDetailsCache[productId] = { ...managedProductDetailsCache[productId], stock_actuel: nextStock };
    }
}

async function applyStockOperationProductDelta(productId, deltaQty) {
    const product = (allManagedProducts || []).find(item => String(item.id) === String(productId))
        || (saleState.products || []).find(item => String(item.id) === String(productId));
    if (!product) throw new Error('Article introuvable.');

    const currentStock = Number(product.stock_actuel || 0);
    const nextStock = currentStock + Number(deltaQty || 0);
    if (nextStock < 0) {
        throw new Error(`Stock insuffisant. Disponible: ${formatMoney(currentStock)}.`);
    }

    const response = await fetch(`${supabaseUrl}products?id=eq.${encodeURIComponent(productId)}`, {
        method: 'PATCH',
        headers: supabaseHeaders,
        body: JSON.stringify({ stock_actuel: nextStock })
    });

    if (!response.ok) {
        const errorText = await response.text();
        throw new Error(errorText || `HTTP ${response.status}`);
    }

    syncProductStockCache(productId, nextStock);
    return { product, nextStock };
}

// --- STOCK OPERATIONS STATE & AUTOSUGGESTIONS ---
const stockOperationDraftState = {};

function getStockOpState(moduleId) {
    if (!stockOperationDraftState[moduleId]) {
        stockOperationDraftState[moduleId] = {
            items: [],
            numero: '',
            date: new Date().toISOString().split('T')[0],
            partner: '',
            note: '',
            historyIndex: -1,
            historyDocuments: [],
            selectedLineIndex: -1,
            filteredProducts: [],
            highlightedSuggestionIndex: -1,
            filteredPartners: [],
            highlightedPartnerIndex: -1,
            historyDateFrom: '',
            historyDateTo: ''
        };
    }
    return stockOperationDraftState[moduleId];
}

function getStockOpPartnersList() {
    const list = new Set();
    if (Array.isArray(allSuppliers)) {
        allSuppliers.forEach(s => { if (s.nom) list.add(s.nom.trim()); });
    }
    if (Array.isArray(stockOperationRecordsCache)) {
        stockOperationRecordsCache.forEach(r => { if (r.partner) list.add(r.partner.trim()); });
    }
    return Array.from(list).sort();
}

function calculateStockOpTotals(moduleId) {
    const state = getStockOpState(moduleId);
    let totalHt = 0;
    let totalTtc = 0;
    state.items.forEach(item => {
        const qty = Number(item.quantity || 0);
        const puHt = Number(item.prix_achat_ht || 0);
        const puTtc = Number(item.prix_achat_ttc || 0);
        totalHt += qty * puHt;
        totalTtc += qty * puTtc;
    });
    return {
        ht: totalHt,
        ttc: totalTtc,
        tva: totalTtc - totalHt
    };
}

function ensureStockOpKeyboardShortcuts(moduleId) {
    const key = `__stockOpShortcutsBound_${moduleId}`;
    if (window[key]) return;
    window[key] = true;
    document.addEventListener('keydown', async (event) => {
        if (activeTabId !== moduleId) return;
        const state = getStockOpState(moduleId);
        const isHistory = state.historyIndex >= 0;

        if (event.key === 'F5') {
            event.preventDefault();
            createNewStockOpDocument(moduleId);
        } else if (event.key === 'F3') {
            event.preventDefault();
            if (!isHistory) {
                confirmStockOpDocument(moduleId);
            }
        } else if (event.key === 'F4') {
            event.preventDefault();
            if (!isHistory) {
                focusStockOpSearch(moduleId);
            }
        } else if (event.key === 'F7') {
            event.preventDefault();
            if (!isHistory) {
                deleteStockOpLine(moduleId, state.selectedLineIndex);
            }
        } else if (event.key === 'F10') {
            event.preventDefault();
            resetStockOpForm(moduleId);
        } else if (event.key === 'F11') {
            event.preventDefault();
            printStockOpDocument(moduleId);
        } else if (event.key === 'F12') {
            event.preventDefault();
            closeTab(moduleId, event);
        }
    });
}

function focusStockOpSearch(moduleId) {
    const searchField = document.getElementById(`${moduleId}-product-search`);
    if (searchField) {
        searchField.focus();
        searchField.select();
    }
}

function resetStockOpForm(moduleId) {
    createNewStockOpDocument(moduleId);
}

function createNewStockOpDocument(moduleId) {
    const state = getStockOpState(moduleId);
    state.items = [];
    state.numero = '';
    state.date = new Date().toISOString().split('T')[0];
    state.partner = '';
    state.note = '';
    state.historyIndex = -1;
    state.selectedLineIndex = -1;
    state.filteredProducts = [];
    state.highlightedSuggestionIndex = -1;
    state.filteredPartners = [];
    state.highlightedPartnerIndex = -1;
    const config = getStockOperationConfig(moduleId);
    const prefix = getStockOperationNumberPrefix(config?.key);
    peekSequentialNumber(prefix, () => buildStockOperationId(prefix)).then(num => {
        state.numero = num;
        renderStockOperationModule(moduleId);
    });
}

function getFilteredStockOperationProducts(query) {
    const q = (query || '').toLowerCase().trim();
    if (!q) return [];
    const products = Array.isArray(allManagedProducts) ? allManagedProducts : [];
    return products.filter(p =>
        (p.designation || '').toLowerCase().includes(q) ||
        (p.code_article || '').toLowerCase().includes(q) ||
        (p.code_barre || '').toLowerCase().includes(q)
    ).slice(0, 50);
}


function stockOperationTemplate(moduleId) {
    const config = getStockOperationConfig(moduleId);
    if (!config) return '<div class="welcome-screen"><p>Module introuvable.</p></div>';
    setTimeout(() => initStockOperationModule(moduleId), 100);

    return `
        <div class="achat-theme stock-operation-container" id="${moduleId}-view-container" style="height:100%; display:flex; flex-direction:column; overflow:hidden;">
            <div style="text-align:center; padding:50px; color:#64748b; font-weight:700;">Chargement du module...</div>
        </div>
    `;
}

async function initStockOperationModule(moduleId) {
    await ensureManagedProductsCacheLoaded();
    await ensureStockOperationRecordsLoaded();
    ensureStockOpKeyboardShortcuts(moduleId);
    
    const state = getStockOpState(moduleId);
    const config = getStockOperationConfig(moduleId);
    const prefix = getStockOperationNumberPrefix(config?.key);
    
    if (!state.numero) {
        state.numero = await peekSequentialNumber(prefix, () => buildStockOperationId(prefix));
    }
    
    loadStockOpHistoryDocs(moduleId);
    renderStockOperationModule(moduleId);
}

