async function findDuplicateByName(table, name) {
    if (!table || !name) return null;
    try {
        const encoded = encodeURIComponent(name.trim());
        const res = await fetch(`${supabaseUrl}${table}?select=id,nom&nom=ilike.${encoded}&limit=2`, { headers: supabaseHeaders });
        if (!res.ok) return null;
        const rows = await res.json();
        if (!Array.isArray(rows)) return null;
        return rows.find(r => r.nom?.toUpperCase() === name.trim().toUpperCase()) || null;
    } catch (e) {
        return null;
    }
}

function formatMoney(value) {
    return Number(value || 0).toFixed(3);
}

function showSuccessToast(message, duration = 3200) {
    const text = String(message || '').trim();
    if (!text) return;

    let container = document.getElementById('app-success-toast-container');
    if (!container) {
        container = document.createElement('div');
        container.id = 'app-success-toast-container';
        container.className = 'app-success-toast-container';
        document.body.appendChild(container);
    }

    const toast = document.createElement('div');
    toast.className = 'app-success-toast';
    toast.textContent = text;
    container.appendChild(toast);

    setTimeout(() => {
        toast.classList.add('is-leaving');
        setTimeout(() => toast.remove(), 220);
    }, duration);
}

function roundMoneyValue(value) {
    return Number(formatMoney(value));
}

function normalizeDateOnlyValue(value) {
    const raw = String(value || '').trim();
    if (!raw) return '';
    const isoMatch = raw.match(/^(\d{4})-(\d{2})-(\d{2})/);
    if (isoMatch) return `${isoMatch[1]}-${isoMatch[2]}-${isoMatch[3]}`;
    return '';
}

function parseDateOnlyValue(value) {
    const normalized = normalizeDateOnlyValue(value);
    if (!normalized) return null;
    const [year, month, day] = normalized.split('-').map(Number);
    const date = new Date(year, month - 1, day);
    if (
        !Number.isFinite(date.getTime()) ||
        date.getFullYear() !== year ||
        date.getMonth() !== month - 1 ||
        date.getDate() !== day
    ) {
        return null;
    }
    date.setHours(0, 0, 0, 0);
    return date;
}

function getPeremptionAlertInfo(peremptionValue, monthsAhead = 4) {
    const peremptionDate = parseDateOnlyValue(peremptionValue);
    if (!peremptionDate) {
        return {
            hasDate: false,
            status: 'none',
            daysLeft: null,
            date: null
        };
    }

    const today = new Date();
    today.setHours(0, 0, 0, 0);

    const alertLimit = new Date(today);
    alertLimit.setMonth(alertLimit.getMonth() + Number(monthsAhead || 0));
    alertLimit.setHours(0, 0, 0, 0);

    const diffMs = peremptionDate.getTime() - today.getTime();
    const daysLeft = Math.ceil(diffMs / 86400000);

    if (peremptionDate < today) {
        return {
            hasDate: true,
            status: 'expired',
            daysLeft,
            date: peremptionDate
        };
    }

    if (peremptionDate <= alertLimit) {
        return {
            hasDate: true,
            status: 'soon',
            daysLeft,
            date: peremptionDate
        };
    }

    return {
        hasDate: true,
        status: 'ok',
        daysLeft,
        date: peremptionDate
    };
}

function getSupabaseErrorMessage(error) {
    const raw = String(error?.message || error || '').trim();
    if (!raw) return 'Erreur inconnue.';

    if (raw.includes('row-level security') || raw.includes('permission denied') || raw.includes('new row violates row-level security policy')) {
        return 'Acces refuse par Supabase (RLS / permissions). Verifiez les policies et les droits du role anon.';
    }

    if (raw.includes('Could not find the') || raw.includes('schema cache')) {
        return 'La structure de table n est pas encore visible dans le cache Supabase. Rechargez le schema ou relancez le SQL ALTER TABLE.';
    }

    return raw;
}

function escapeHtml(value) {
    return String(value ?? '')
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&#39;');
}

function normalizeSearchText(value) {
    return String(value || '')
        .normalize('NFD')
        .replace(/[\u0300-\u036f]/g, '')
        .toLowerCase()
        .trim();
}

function sanitizeScannerCodeValue(value) {
    return String(value || '')
        .normalize('NFKC')
        .replace(/[\u0000-\u001F\u007F]/g, '')
        .replace(/\s+/g, '')
        .trim();
}

function normalizeCodeInputText(value) {
    return normalizeSearchText(
        String(value || '')
            .normalize('NFKC')
            .replace(/[\u0000-\u001F\u007F]/g, '')
            .replace(/\s+/g, ' ')
            .trim()
    );
}

function normalizeBarcodeText(value) {
    return normalizeCodeInputText(value).replace(/[^a-z0-9]/g, '');
}

function matchesProductCodeSearch(product, searchTerm, options = {}) {
    const { allowPartial = false } = options;
    const normalized = normalizeCodeInputText(searchTerm);
    const compact = normalizeBarcodeText(searchTerm);
    if (!normalized && !compact) return false;

    const code = normalizeCodeInputText(product?.code_article);
    const barcode = normalizeCodeInputText(product?.code_barre);
    const compactCode = normalizeBarcodeText(product?.code_article);
    const compactBarcode = normalizeBarcodeText(product?.code_barre);
    const designation = normalizeSearchText(product?.designation);
    const fullLabel = `${code} - ${designation}`;

    if (!allowPartial) {
        return code === normalized
            || barcode === normalized
            || (compact && (compactCode === compact || compactBarcode === compact))
            || fullLabel === normalized
            || designation.includes(normalized);
    }

    return code.includes(normalized)
        || barcode.includes(normalized)
        || (compact && (compactCode.includes(compact) || compactBarcode.includes(compact)))
        || designation.includes(normalized);
}

function findExactProductByCodeTerm(sourceProducts, searchTerm) {
    const normalized = normalizeCodeInputText(searchTerm);
    const compact = normalizeBarcodeText(searchTerm);
    if (!normalized && !compact) return null;

    return (Array.isArray(sourceProducts) ? sourceProducts : []).find(product => {
        const code = normalizeCodeInputText(product?.code_article);
        const barcode = normalizeCodeInputText(product?.code_barre);
        const compactCode = normalizeBarcodeText(product?.code_article);
        const compactBarcode = normalizeBarcodeText(product?.code_barre);

        return code === normalized
            || barcode === normalized
            || (compact && (compactCode === compact || compactBarcode === compact));
    }) || null;
}

function numberToFrenchWords(value) {
    const units = ['zero', 'un', 'deux', 'trois', 'quatre', 'cinq', 'six', 'sept', 'huit', 'neuf'];
    const teens = ['dix', 'onze', 'douze', 'treize', 'quatorze', 'quinze', 'seize', 'dix-sept', 'dix-huit', 'dix-neuf'];
    const tens = ['', '', 'vingt', 'trente', 'quarante', 'cinquante', 'soixante'];

    const underHundred = (n) => {
        if (n < 10) return units[n];
        if (n < 20) return teens[n - 10];
        if (n < 70) {
            const ten = Math.floor(n / 10);
            const unit = n % 10;
            if (unit === 0) return tens[ten];
            if (unit === 1) return `${tens[ten]} et un`;
            return `${tens[ten]}-${units[unit]}`;
        }
        if (n < 80) {
            if (n === 71) return 'soixante et onze';
            return `soixante-${underHundred(n - 60)}`;
        }
        if (n === 80) return 'quatre-vingts';
        if (n < 100) {
            const suffix = underHundred(n - 80);
            return `quatre-vingt-${suffix}`;
        }
        return '';
    };

    const underThousand = (n) => {
        if (n < 100) return underHundred(n);
        const hundred = Math.floor(n / 100);
        const rest = n % 100;
        if (hundred === 1) {
            return rest ? `cent ${underHundred(rest)}` : 'cent';
        }
        const hundredLabel = rest ? 'cent' : 'cents';
        return `${units[hundred]} ${hundredLabel}${rest ? ` ${underHundred(rest)}` : ''}`;
    };

    const normalized = Math.floor(Math.abs(Number(value || 0)));
    if (normalized === 0) return 'zero';

    const chunks = [];
    const millions = Math.floor(normalized / 1000000);
    const thousands = Math.floor((normalized % 1000000) / 1000);
    const remainder = normalized % 1000;

    if (millions > 0) {
        chunks.push(millions === 1 ? 'un million' : `${underThousand(millions)} millions`);
    }
    if (thousands > 0) {
        chunks.push(thousands === 1 ? 'mille' : `${underThousand(thousands)} mille`);
    }
    if (remainder > 0) {
        chunks.push(underThousand(remainder));
    }

    return chunks.join(' ').replace(/\s+/g, ' ').trim();
}

function amountToFrenchCurrencyWords(amount) {
    const numeric = Number(amount || 0);
    let dinars = Math.floor(Math.abs(numeric));
    let millimes = Math.round((Math.abs(numeric) - dinars) * 1000);
    if (millimes === 1000) {
        dinars += 1;
        millimes = 0;
    }
    const dinarsWords = numberToFrenchWords(dinars);
    const millimesWords = millimes > 0 ? numberToFrenchWords(millimes) : '';

    let label = `${dinarsWords} dinar${dinars > 1 ? 's' : ''}`;
    if (millimes > 0) {
        label += ` et ${millimesWords} millime${millimes > 1 ? 's' : ''}`;
    }
    return label;
}

async function fetchEntryProductsForSaleAndPurchase() {
    egressTracker.pushFlow('load-all-products');
    try {
    const selectVariants = [
        'id,code_article,code_barre,designation,forme,stock_actuel,peremption,prix_vente_ht,tva,prix_vente_ttc,prix_vente_web_ttc,prix_vente_passager_ttc,remise_web_pct,marge,prix_achat_ht,prix_achat_ttc,code_pct,web_category_slug,is_web_hidden,date_alerte,image_url',
        'id,code_article,code_barre,designation,forme,stock_actuel,peremption,prix_vente_ht,tva,prix_vente_ttc,marge,prix_achat_ht,prix_achat_ttc,code_pct,web_category_slug,date_alerte',
        '*'
    ];
    let emptyResult = null;

    for (const selectColumns of selectVariants) {
        const rows = await fetchCollection(`products?select=${selectColumns}&order=designation`, null);
        if (!Array.isArray(rows)) continue;
        if (rows.length > 0) return rows.map(normalizeProductPricingFields);
        emptyResult = rows;
    }

    if (Array.isArray(allManagedProducts) && allManagedProducts.length > 0) {
        return allManagedProducts.map(normalizeProductPricingFields);
    }

    try {
        await ensureManagedProductsCacheLoaded();
    } catch (error) {
        console.warn('Cache articles indisponible pour vente/achat.', error);
    }

    if (Array.isArray(allManagedProducts) && allManagedProducts.length > 0) {
        return allManagedProducts.map(normalizeProductPricingFields);
    }

    return Array.isArray(emptyResult) ? emptyResult : [];
    } finally { egressTracker.popFlow(); }
}

function mergeEntryProductsCache(currentProducts, incomingProducts) {
    const merged = Array.isArray(currentProducts) ? currentProducts.slice() : [];
    const existingKeys = new Set(merged.map(product => String(product?.id || product?.code_article || '').trim()).filter(Boolean));

    (Array.isArray(incomingProducts) ? incomingProducts : []).forEach(product => {
        const normalizedProduct = normalizeProductPricingFields(product);
        const key = String(normalizedProduct?.id || normalizedProduct?.code_article || '').trim();
        if (!key || existingKeys.has(key)) return;
        existingKeys.add(key);
        merged.push(normalizedProduct);
    });

    return merged;
}

function buildEntryProductSearchEndpoint(searchTerm) {
    const rawTerm = String(searchTerm || '').trim();
    if (!rawTerm) return '';

    const safeTerm = rawTerm
        .replace(/[,*()]/g, ' ')
        .replace(/\s+/g, ' ')
        .trim();
    if (!safeTerm) return '';

    const encodedTerm = encodeURIComponent(`*${safeTerm}*`);
    return `or=(code_article.ilike.${encodedTerm},code_barre.ilike.${encodedTerm},designation.ilike.${encodedTerm})&order=designation&limit=50`;
}

async function searchEntryProductsFromDatabase(searchTerm) {
    const searchFilter = buildEntryProductSearchEndpoint(searchTerm);
    if (!searchFilter) return [];

    const selectVariants = [
        'id,code_article,code_barre,designation,forme,stock_actuel,peremption,prix_vente_ht,tva,prix_vente_ttc,prix_vente_web_ttc,prix_vente_passager_ttc,remise_web_pct,marge,prix_achat_ht,prix_achat_ttc,code_pct',
        'id,code_article,code_barre,designation,forme,stock_actuel,peremption,prix_vente_ht,tva,prix_vente_ttc,marge,prix_achat_ht,prix_achat_ttc',
        'id,code_article,code_barre,designation,forme,stock_actuel,peremption,tva,prix_vente_ttc',
        '*'
    ];

    for (const selectColumns of selectVariants) {
        const rows = await fetchCollection(`products?select=${selectColumns}&${searchFilter}`, [], 50);
        if (Array.isArray(rows) && rows.length > 0) {
            return rows.map(normalizeProductPricingFields);
        }
    }

    return [];
}

async function refreshProductsCache() {
    egressTracker.pushFlow('refresh-cache');
    try {
    saleState.products = await fetchEntryProductsForSaleAndPurchase();
    webStoreState.products = await fetchWebStoreProducts();
    const webProductMap = new Map((webStoreState.products || []).map(product => [String(product.id), product]));
    webStoreState.cart = (webStoreState.cart || []).map(line => {
        const product = webProductMap.get(String(line.product_id));
        return product
            ? { ...line, unit_price: getProductWebPriceTtc(product), product }
            : line;
    });
    if (Array.isArray(allManagedWebCategories) && allManagedWebCategories.length > 0) {
        webStoreState.categories = getWebStoreCategories(webStoreState.products);
    }

    if (activeTabId === 'vente') {
        syncSaleItemsWithCurrentProducts();
        fillSaleSelects();
        const searchValue = document.getElementById('sale-product-search')?.value || '';
        saleState.filteredProducts = getFilteredProducts(searchValue);
        saleState.highlightedSuggestionIndex = saleState.filteredProducts.length > 0 ? 0 : -1;
        renderProductSuggestions();
        renderSaleItems();
        calculateSaleTotals();
    }

    const appMode = document.body?.dataset?.app || 'admin';
    if (activeTabId === 'web_orders' || appMode === 'public-store') {
        refreshWebStoreProducts();
        renderWebStoreCategories();
        renderWebStoreCart();
    }
    } finally { egressTracker.popFlow(); }
}

function updateCachedProductsLocally(productUpdates = []) {
    if (!Array.isArray(productUpdates) || productUpdates.length === 0) return;

    const updatesMap = new Map(
        productUpdates
            .filter(item => item && item.id)
            .map(item => [String(item.id), item])
    );

    const applyUpdates = (rows = []) => rows.map(product => {
        const update = updatesMap.get(String(product?.id || ''));
        return update ? normalizeProductPricingFields({ ...product, ...update }) : product;
    });

    saleState.products = applyUpdates(saleState.products || []);
    purchaseState.products = applyUpdates(purchaseState.products || []);
    webStoreState.products = applyUpdates(webStoreState.products || []);
    allManagedProducts = applyUpdates(allManagedProducts || []);

    saleState.items = (saleState.items || []).map(item => {
        const update = updatesMap.get(String(item?.product_id || item?.id || ''));
        return update ? { ...item, ...update } : item;
    });

    purchaseState.items = (purchaseState.items || []).map(item => {
        const update = updatesMap.get(String(item?.product_id || item?.id || ''));
        return update ? { ...item, ...update } : item;
    });

    webStoreState.cart = (webStoreState.cart || []).map(line => {
        const update = updatesMap.get(String(line?.product_id || ''));
        if (!update) return line;
        const product = normalizeProductPricingFields({ ...(line.product || {}), ...update });
        return {
            ...line,
            unit_price: getProductWebPriceTtc(product),
            product
        };
    });

    webStoreState.recentOrders = (webStoreState.recentOrders || []).map(order => ({
        ...order,
        items: Array.isArray(order.items)
            ? order.items.map(item => {
                const update = updatesMap.get(String(item?.product_id || item?.product?.id || ''));
                if (!update) return item;
                return {
                    ...item,
                    product: normalizeProductPricingFields({ ...(item.product || {}), ...update })
                };
            })
            : []
    }));
}

let _productsBackgroundRefreshTimer = null;
let _lastProductsBackgroundRefreshAt = 0;
const PRODUCTS_BACKGROUND_REFRESH_COOLDOWN = 10 * 60 * 1000;
const PRODUCTS_BACKGROUND_REFRESH_DELAY = 5000;

function refreshProductsCacheInBackground(reason = '') {
    if (document.visibilityState && document.visibilityState !== 'visible') return;

    const now = Date.now();
    if (now - _lastProductsBackgroundRefreshAt < PRODUCTS_BACKGROUND_REFRESH_COOLDOWN) {
        return;
    }

    if (_productsBackgroundRefreshTimer) {
        clearTimeout(_productsBackgroundRefreshTimer);
    }

    _productsBackgroundRefreshTimer = setTimeout(() => {
        _productsBackgroundRefreshTimer = null;
        const current = Date.now();
        if (current - _lastProductsBackgroundRefreshAt < PRODUCTS_BACKGROUND_REFRESH_COOLDOWN) {
            return;
        }

        _lastProductsBackgroundRefreshAt = current;
        refreshProductsCache().catch(error => {
            console.warn(`Refresh produits differe indisponible${reason ? ` (${reason})` : ''}.`, error);
        });
    }, PRODUCTS_BACKGROUND_REFRESH_DELAY);
}

function syncWebOrderAlertsFromRecentOrders() {
    webOrderAlertState.pendingOrders = (webStoreState.recentOrders || [])
        .filter(order => getWebOrderStatusKey(order?.status) === 'nouvelle')
        .map(order => ({
            id: order.id,
            order_number: order.order_number,
            customer_name: order.customer_name,
            total_ttc: order.total_ttc,
            status: order.status,
            created_at: order.created_at
        }));

    webOrderAlertState.freshOrderIds.forEach(id => {
        if (!webOrderAlertState.pendingOrders.some(order => String(order.id) === String(id))) {
            webOrderAlertState.freshOrderIds.delete(id);
        }
    });

    renderWebOrderNotificationState();
}

const _productsCache = { data: null, ts: 0, endpoint: '' };
const PRODUCTS_CACHE_TTL = 6 * 60 * 60 * 1000;

const _referenceCache = {};
const REFERENCE_CACHE_TTL = 30 * 60 * 1000;

const egressTracker = {
    enabled: true,
    maxLog: 500,
    logs: [],
    totals: { requests: 0, rows: 0, bytesEstimate: 0, cacheHits: 0 },
    tables: {},
    flows: {},
    _callerStack: [],

    pushFlow(label) {
        this._callerStack.push(label);
    },
    popFlow() {
        this._callerStack.pop();
    },

    _detectCaller() {
        try {
            const stack = new Error().stack;
            const lines = stack.split('\n');
            let foundFetch = false;
            for (const line of lines) {
                const match = line.match(/at\s+(?:async\s+)?(\S+)\s/);
                if (!match) continue;
                const name = match[1];
                if (name === 'egressTracker.log' || name === 'log') continue;
                if (name === 'fetchCollection') { foundFetch = true; continue; }
                if (foundFetch) return name;
            }
        } catch (e) {}
        return '';
    },

    log(endpoint, rows, bytes, cached) {
        if (!this.enabled) return;
        this.totals.requests++;
        if (cached) this.totals.cacheHits++;
        if (!cached && Array.isArray(rows)) this.totals.rows += rows.length;
        if (!cached) this.totals.bytesEstimate += bytes;

        const table = (endpoint || '').split('?')[0] || endpoint;
        if (!this.tables[table]) this.tables[table] = { requests: 0, rows: 0, bytesEstimate: 0, cacheHits: 0 };
        this.tables[table].requests++;
        if (cached) this.tables[table].cacheHits++;
        if (!cached) {
            this.tables[table].rows += Array.isArray(rows) ? rows.length : 0;
            this.tables[table].bytesEstimate += bytes;
        }

        let flow = this._callerStack.length > 0 ? this._callerStack[this._callerStack.length - 1] : '';
        if (!flow) flow = this._detectCaller();
        if (!flow) flow = 'unknown';
        if (!this.flows[flow]) this.flows[flow] = { requests: 0, rows: 0, bytesEstimate: 0, cacheHits: 0 };
        this.flows[flow].requests++;
        if (cached) this.flows[flow].cacheHits++;
        if (!cached) {
            this.flows[flow].rows += Array.isArray(rows) ? rows.length : 0;
            this.flows[flow].bytesEstimate += bytes;
        }

        this.logs.push({ time: new Date().toISOString().slice(11, 23), endpoint, rows: Array.isArray(rows) ? rows.length : 0, bytes, cached, table, flow });
        if (this.logs.length > this.maxLog) this.logs.splice(0, this.logs.length - this.maxLog);
    },

    report() {
        console.log('%c=== EGRESS DETECTIVE REPORT ===', 'font-weight:bold;font-size:14px');
        console.log(`Total requests: ${this.totals.requests} (cache hits: ${this.totals.cacheHits})`);
        console.log(`Total rows fetched: ${this.totals.rows}`);
        console.log(`Estimated bytes: ${(this.totals.bytesEstimate / 1024).toFixed(1)} KB`);
        console.log('');
        console.log('%cPer table:', 'font-weight:bold');
        console.table(Object.entries(this.tables).map(([t, s]) => ({
            table: t,
            requests: s.requests,
            'rows fetched': s.rows,
            'bytes est.': `${(s.bytesEstimate / 1024).toFixed(1)} KB`,
            cacheHits: s.cacheHits
        })).sort((a, b) => b['bytes est.'] - a['bytes est.']));
        console.log('');
        console.log('%cPer flow (calling context):', 'font-weight:bold');
        console.table(Object.entries(this.flows).map(([f, s]) => ({
            flow: f,
            requests: s.requests,
            'rows fetched': s.rows,
            'bytes est.': `${(s.bytesEstimate / 1024).toFixed(1)} KB`,
            cacheHits: s.cacheHits
        })).sort((a, b) => b['bytes est.'] - a['bytes est.']));
        console.log('');
        console.log('%cLast 20 requests:', 'font-weight:bold');
        console.table(this.logs.slice(-20).map(r => ({
            time: r.time, table: r.table, flow: r.flow,
            rows: r.rows, bytes: r.bytes, cached: r.cached
        })));
    },

    reportLive() {
        console.log('%c=== EGRESS LIVE (last 50 requests) ===', 'font-weight:bold;font-size:14px');
        console.table(this.logs.slice(-50).map(r => ({
            time: r.time, table: r.table, flow: r.flow,
            rows: r.rows, bytes: r.bytes, cached: r.cached
        })));
    },

    reset() {
        this.logs = [];
        this.totals = { requests: 0, rows: 0, bytesEstimate: 0, cacheHits: 0 };
        this.tables = {};
        this.flows = {};
    }
};

window.egressReport = () => egressTracker.report();
window.egressLive = () => egressTracker.reportLive();
window.egressReset = () => egressTracker.reset();

function invalidateProductsCache() {
    _productsCache.ts = 0;
    _productsCache.endpoint = '';
}

function invalidateReferenceCache(table) {
    if (table) {
        const prefix = table + '?';
        Object.keys(_referenceCache).forEach(key => {
            if (key.startsWith(prefix)) delete _referenceCache[key];
        });
    } else {
        Object.keys(_referenceCache).forEach(key => delete _referenceCache[key]);
    }
}

async function fetchCollection(endpoint, fallback = [], maxRows = 0) {
    const pageSize = 1000;
    const urlLimitMatch = endpoint.match(/[?&]limit=(\d+)/);
    const urlLimit = urlLimitMatch ? parseInt(urlLimitMatch[1], 10) : 0;
    const effectivePageSize = Math.min(pageSize, ...(maxRows > 0 ? [maxRows] : []), ...(urlLimit > 0 ? [urlLimit] : []));
    const results = [];
    let from = 0;

    const isProductsQuery = endpoint.startsWith('products?');
    if (isProductsQuery && _productsCache.data && (Date.now() - _productsCache.ts) < PRODUCTS_CACHE_TTL && endpoint === _productsCache.endpoint) {
        const out = maxRows > 0 ? _productsCache.data.slice(0, maxRows) : _productsCache.data;
        egressTracker.log(endpoint, out, 0, true);
        return out;
    }

    const isRefQuery = ['customers?', 'mutuelles?', 'suppliers?'].some(prefix => endpoint.startsWith(prefix));
    if (isRefQuery && _referenceCache[endpoint] && (Date.now() - _referenceCache[endpoint].ts) < REFERENCE_CACHE_TTL) {
        const out = maxRows > 0 ? _referenceCache[endpoint].data.slice(0, maxRows) : _referenceCache[endpoint].data;
        egressTracker.log(endpoint, out, 0, true);
        return out;
    }

    try {
        while (true) {
            if (maxRows > 0 && results.length >= maxRows) break;

            const response = await fetch(`${supabaseUrl}${endpoint}`, {
                headers: {
                    ...supabaseHeaders,
                    Range: `${from}-${from + effectivePageSize - 1}`,
                    'Range-Unit': 'items'
                }
            });

            if (!response.ok) {
                throw new Error(`HTTP ${response.status}`);
            }

            const batch = await response.json();
            if (!Array.isArray(batch)) {
                egressTracker.log(endpoint, [], JSON.stringify(batch).length, false);
                return batch ?? fallback;
            }

            results.push(...batch);

            if (batch.length < effectivePageSize) {
                break;
            }

            from += effectivePageSize;
        }

        if (isProductsQuery) {
            _productsCache.data = results;
            _productsCache.ts = Date.now();
            _productsCache.endpoint = endpoint;
        }

        if (isRefQuery && results.length > 0) {
            _referenceCache[endpoint] = { data: results, ts: Date.now() };
        }

        const final = maxRows > 0 ? results.slice(0, maxRows) : results;
        egressTracker.log(endpoint, final, JSON.stringify(final).length, false);
        return final;
    } catch (error) {
        console.error(`Erreur chargement ${endpoint}:`, error);
        egressTracker.log(endpoint, [], 0, false);
        return fallback;
    }
}

function getDefaultDateFilter(daysBack = 30) {
    const d = new Date();
    d.setDate(d.getDate() - daysBack);
    return d.toISOString().slice(0, 10);
}

function inferSaleMode(sale) {
    const explicitType = String(sale?.type_vente || '').trim().toUpperCase();
    const explicitPaymentMode = String(sale?.payment_mode || '').trim().toUpperCase();
    if (explicitType === 'MUTUELLE' || sale.mutuelle_id) return 'MUTUELLE';
    if (explicitType === 'CREDIT' || explicitPaymentMode === 'CREDIT') return 'CREDIT';
    if (explicitType === 'COMPTANT') return 'COMPTANT';
    if (['ESPECE', 'CARTE', 'CHEQUE', 'TRAITE', 'VIREMENT'].includes(explicitPaymentMode)) return 'COMPTANT';
    if (sale.client_id) return 'CREDIT';
    return 'COMPTANT';
}

function isMutuelleClientCreditSale(sale) {
    return inferSaleMode(sale) === 'MUTUELLE'
        && String(sale?.payment_mode || '').trim().toUpperCase() === 'CREDIT';
}

function getSaleDisplayModeLabel(sale) {
    if (isMutuelleClientCreditSale(sale)) return 'MUTUELLE / CREDIT';
    return inferSaleMode(sale);
}

function getModeDisplayLabel(item) {
    if (!item) return '-';
    if (String(item.source || '').toUpperCase() === 'PAYMENT') {
        return item.mode || '-';
    }
    if (item.displayMode) {
        return item.displayMode;
    }
    if (item.originalMode === 'MUTUELLE' && item.mode === 'CREDIT') {
        return 'MUTUELLE / CREDIT';
    }
    if (item.originalMode === 'MUTUELLE' && item.mode === 'COMPTANT') {
        return 'MUTUELLE / COMPTANT';
    }
    return item.mode || getSaleDisplayModeLabel(item) || '-';
}

function formatSaleModeLabel(mode) {
    if (!mode) return '-';
    const m = String(mode).toUpperCase();
    if (m === 'COMPTANT') return 'Comptant';
    if (m === 'CREDIT') return 'Crédit';
    if (m === 'MUTUELLE') return 'Mutuelle';
    return mode;
}

function normalizeReportFilterValue(value) {
    return String(value || '').trim().toUpperCase();
}

function matchesReportCustomer(item, customerId) {
    if (!customerId) return true;
    const itemCustomerId = String(item?.client_id || item?.customer_id || '');
    return itemCustomerId === String(customerId);
}

function matchesReportMode(item, mode) {
    if (!mode) return true;
    return normalizeReportFilterValue(item?.mode || inferSaleMode(item)) === normalizeReportFilterValue(mode);
}

function matchesReportCustomerType(item, customerType) {
    if (!customerType) return true;
    return normalizeReportFilterValue(item?.customerType || getCustomerTypeKey(item)) === normalizeReportFilterValue(customerType);
}

function matchesReportDateRange(item, from, to, dateField = 'date_vente') {
    const rawDate = getLocalDateKey(item?.[dateField]);
    if (!rawDate) return !from && !to;
    if (from && rawDate < from) return false;
    if (to && rawDate > to) return false;
    return true;
}

function getLocalDateKey(value) {
    if (!value) return '';
    if (/^\d{4}-\d{2}-\d{2}$/.test(value)) return value;
    const date = new Date(value);
    if (Number.isNaN(date.getTime())) {
        return String(value || '').split('T')[0];
    }
    const year = date.getFullYear();
    const month = String(date.getMonth() + 1).padStart(2, '0');
    const day = String(date.getDate()).padStart(2, '0');
    return `${year}-${month}-${day}`;
}

function matchesReportInvoiceStatus(item, status) {
    if (!status) return true;
    const hasInvoice = String(item?.numero_vente || item?.order_number || '').trim() !== '';
    if (status === 'facturees') return hasInvoice;
    if (status === 'non_facturees') return !hasInvoice;
    return true;
}

function getNumericPrice(value, fallback = 0) {
    const numeric = Number(value);
    return Number.isFinite(numeric) ? numeric : Number(fallback || 0);
}

function normalizeProductPricingFields(product) {
    if (!product || typeof product !== 'object') return product;

    const normalizedProduct = {
        ...product,
        code_article: product.code_article ?? product.CodeArticle ?? product.product_code ?? product.code ?? '',
        code_barre: product.code_barre ?? product.CodeABarre ?? product.barcode ?? '',
        designation: product.designation ?? product.Designation ?? product.name ?? product.label ?? '',
        forme: product.forme ?? product.Forme ?? '',
        tva: product.tva ?? product.TVA ?? 0
    };

    const prixVenteTtc = getNumericPrice(normalizedProduct.prix_vente_ttc ?? normalizedProduct.PrixVenteTTC, 0);
    const remiseWebPct = getNumericPrice(normalizedProduct.remise_web_pct, 0);
    const prixVenteWebTtc = remiseWebPct > 0
        ? calculateWebPriceFromBase(prixVenteTtc, remiseWebPct)
        : getNumericPrice(normalizedProduct.prix_vente_web_ttc, prixVenteTtc);
    const prixVentePassagerTtc = getNumericPrice(normalizedProduct.prix_vente_passager_ttc, prixVenteTtc);

    return {
        ...normalizedProduct,
        prix_vente_ttc: prixVenteTtc,
        remise_web_pct: remiseWebPct,
        prix_vente_web_ttc: prixVenteWebTtc,
        prix_vente_passager_ttc: prixVentePassagerTtc,
        is_web_hidden: Boolean(normalizedProduct.is_web_hidden ?? false)
    };
}

async function fetchWebStoreProducts() {
    egressTracker.pushFlow('load-web-products');
    try {
    if (_productsCache.data && (Date.now() - _productsCache.ts) < PRODUCTS_CACHE_TTL && _productsCache.data.length > 0) {
        const mapped = _productsCache.data.map(normalizeProductPricingFields);
        if (mapped.some(p => typeof p.prix_vente_web_ttc !== 'undefined')) {
            return mapped.filter(product => !product.is_web_hidden);
        }
    }

    const queries = [
        'products?select=id,code_article,code_barre,designation,forme,web_category_slug,prix_vente_ttc,prix_vente_web_ttc,remise_web_pct,stock_actuel,peremption,image_url,tva,is_web_hidden&order=designation',
        'products?select=id,code_article,code_barre,designation,forme,web_category_slug,prix_vente_ttc,prix_vente_web_ttc,remise_web_pct,stock_actuel,peremption,image_url,tva&order=designation',
        'products?select=id,code_article,code_barre,designation,forme,prix_vente_ttc,stock_actuel,peremption,tva,is_web_hidden&order=designation',
        'products?select=id,code_article,code_barre,designation,forme,prix_vente_ttc,stock_actuel,peremption,tva&order=designation'
    ];

    for (const q of queries) {
        try {
            const rows = await fetchCollection(q, null);
            if (Array.isArray(rows) && rows.length > 0) {
                return rows.map(normalizeProductPricingFields).filter(product => !product.is_web_hidden);
            }
        } catch (e) {
            continue;
        }
    }

    console.warn('Toutes les tentatives de chargement produits ont echoue.');
    return [];
    } finally { egressTracker.popFlow(); }
}

function getProductPassagerPriceTtc(product) {
    const dedicated = getNumericPrice(product?.prix_vente_passager_ttc, NaN);
    if (Number.isFinite(dedicated) && dedicated > 0) return dedicated;
    return getNumericPrice(product?.prix_vente_ttc, 0);
}

function getProductWebPriceTtc(product) {
    const dedicated = getNumericPrice(product?.prix_vente_web_ttc, NaN);
    const remisePct = getNumericPrice(product?.remise_web_pct, NaN);
    const baseTtc = getNumericPrice(product?.prix_vente_ttc, 0);
    if (Number.isFinite(remisePct) && remisePct > 0) {
        return calculateWebPriceFromBase(baseTtc, remisePct);
    }
    if (Number.isFinite(dedicated) && dedicated > 0) return dedicated;
    return baseTtc;
}

function getSaleSpecialMarginBoostPct(context = {}) {
    const saleType = String(context.saleType || document.getElementById('sale-type')?.value || 'comptant').toLowerCase();
    if (saleType === 'mutuelle') return 0;
    const explicitFlag = typeof context.specialMarginBoost === 'boolean'
        ? context.specialMarginBoost
        : Boolean(document.getElementById('sale-special-margin-boost')?.checked);
    return explicitFlag ? 5 : 0;
}

function getProductSpecialSalePriceTtc(product, context = {}) {
    const baseTtc = getNumericPrice(product?.prix_vente_ttc, 0);
    const purchaseHt = getNumericPrice(product?.prix_achat_ht, NaN);
    const marginPct = getNumericPrice(product?.marge, NaN);
    const tvaPct = getNumericPrice(product?.tva, 0);
    const extraMarginPct = getSaleSpecialMarginBoostPct(context);

    if (extraMarginPct <= 0 || !Number.isFinite(purchaseHt) || purchaseHt <= 0 || !Number.isFinite(marginPct)) {
        return baseTtc;
    }

    const saleHt = Number(calculateSaleHtFromMargin(purchaseHt, marginPct + extraMarginPct).toFixed(3));
    const saleTtc = Number((saleHt * (1 + (tvaPct / 100))).toFixed(3));
    return saleTtc > 0 ? saleTtc : baseTtc;
}

function getProductSalePriceTtc(product, context = {}) {
    const channel = String(context.channel || 'POS').toUpperCase();
    if (channel === 'WEB') {
        return getProductWebPriceTtc(product);
    }

    if (channel === 'POS') {
        return getProductSpecialSalePriceTtc(product, context);
    }

    return getNumericPrice(product?.prix_vente_ttc, 0);
}

function syncSaleItemsWithCurrentProducts() {
    if (!Array.isArray(saleState.items) || saleState.items.length === 0) return;

    const saleType = document.getElementById('sale-type')?.value || 'comptant';
    const customerId = document.getElementById('sale-customer')?.value || '';
    const productsMap = new Map((saleState.products || []).map(product => [String(product.id || ''), product]));

    saleState.items = saleState.items.map(item => {
        const product = productsMap.get(String(item?.product_id || ''));
        if (!product) return item;

        return {
            ...item,
            designation: product.designation,
            forme: product.forme,
            peremption: product.peremption,
            stock_actuel: Number(product.stock_actuel || 0),
            tva: Number(product.tva || 0),
            prix_unitaire_ttc: getProductSalePriceTtc(product, { channel: 'POS', saleType, customerId })
        };
    });
}

function isSaleHistoryReadonlyMode() {
    return Boolean(saleState.isHistoryReadonly);
}

function ensureSelectOptionValue(selectNode, value, label = '') {
    if (!selectNode || !value) return;

    Array.from(selectNode.querySelectorAll('option[data-history-temp="1"]')).forEach(option => option.remove());

    if (!Array.from(selectNode.options).some(option => String(option.value) === String(value))) {
        const option = document.createElement('option');
        option.value = value;
        option.textContent = label || value;
        option.dataset.historyTemp = '1';
        selectNode.appendChild(option);
    }
}

function syncSaleHistoryNavigationState() {
    const prevButton = document.getElementById('sale-history-prev-button');
    const nextButton = document.getElementById('sale-history-next-button');
    const statusNode = document.getElementById('sale-history-status');
    const inHistory = isSaleHistoryReadonlyMode();
    const rows = Array.isArray(saleState.historyRows) ? saleState.historyRows : [];
    const currentRow = inHistory ? rows[saleState.historyIndex] : null;

    if (prevButton) {
        prevButton.disabled = inHistory ? saleState.historyIndex >= rows.length - 1 : false;
    }
    if (nextButton) {
        nextButton.disabled = inHistory ? saleState.historyIndex <= 0 : false;
    }
    if (statusNode) {
        statusNode.style.display = 'none';
        statusNode.textContent = '';
    }
}

function setSaleFormReadonlyMode(isReadonly) {
    const fieldIds = [
        'sale-date',
        'sale-type',
        'sale-customer',
        'sale-customer-search',
        'sale-mutuelle',
        'sale-mutuelle-matricule',
        'sale-product-code',
        'sale-product-search',
        'sale-product-select',
        'sale-qty',
        'sale-special-margin-boost'
    ];

    fieldIds.forEach(id => {
        const node = document.getElementById(id);
        if (!node) return;
        node.disabled = Boolean(isReadonly);
        if (node.tagName === 'INPUT' && node.type === 'text') {
            node.readOnly = Boolean(isReadonly);
        }
    });
    const numberInput = document.getElementById('purchase-number');
    if (numberInput) numberInput.readOnly = true;

    const frigoButton = document.getElementById('sale-frigo-button');
    const confirmButton = document.getElementById('sale-confirm-button');
    if (frigoButton) frigoButton.disabled = Boolean(isReadonly);
    if (confirmButton) confirmButton.disabled = Boolean(isReadonly);
    if (isReadonly) {
        closeSaleCustomerSuggestions();
    }

    syncSaleHistoryNavigationState();
}

async function fetchSaleHistoryRows() {
    const response = await fetch(`${supabaseUrl}sales?select=*,customers(id,nom,telephone,solde,en_cours,reste_a_payer,mutuelle_id,numero_matricule_mutuelle,nom_malade),mutuelles(id,nom,taux_remboursement)&order=numero_vente.desc`, {
        headers: {
            ...supabaseHeaders,
            Range: '0-99',
            'Range-Unit': 'items'
        }
    });

    if (!response.ok) {
        throw new Error(`HTTP ${response.status}`);
    }

    const rows = await response.json();
    return Array.isArray(rows) ? rows : [];
}

async function fetchSaleHistoryItems(saleId) {
    if (!saleId) return [];

    const rows = await fetchCollection(`sale_items?select=product_id,prix_unitaire_ttc,quantite,remise,products(code_article,designation,forme,peremption,tva,stock_actuel,code_pct)&sale_id=eq.${saleId}&order=created_at.asc`, []);
    return (Array.isArray(rows) ? rows : []).map(item => ({
        product_id: item.product_id,
        code_article: item.products?.code_article || item.code_article || '-',
        code_pct: item.products?.code_pct || item.code_pct || '',
        designation: item.products?.designation || item.designation || '-',
        forme: item.products?.forme || item.forme || '-',
        peremption: item.products?.peremption || item.peremption || null,
        stock_actuel: Number(item.products?.stock_actuel || item.stock_actuel || 0),
        prix_unitaire_ttc: Number(item.prix_unitaire_ttc || 0),
        tva: Number(item.products?.tva || item.tva || 0),
        quantite: Number(item.quantite || 0),
        remise: Number(item.remise || 0)
    }));
}

async function openSaleHistoryAtIndex(index) {
    const rows = Array.isArray(saleState.historyRows) ? saleState.historyRows : [];
    if (!rows.length || index < 0 || index >= rows.length) return;

    const saleRow = rows[index];
    const saleItems = await fetchSaleHistoryItems(saleRow.id);
    if (!saleItems.length) {
        alert('Aucune ligne trouvee pour cette vente.');
        return;
    }

    saleState.isHistoryReadonly = true;
    saleState.historyIndex = index;
    saleState.historyViewedSale = {
        sale: saleRow,
        customer: saleRow.customers || null,
        mutuelle: saleRow.mutuelles || null
    };
    saleState.items = saleItems;
    saleState.selectedLineIndex = saleItems.length > 0 ? 0 : -1;
    saleState.selectedProductId = '';
    saleState.filteredProducts = saleState.products.slice(0, 8);
    saleState.highlightedSuggestionIndex = saleState.filteredProducts.length > 0 ? 0 : -1;
    closeProductSuggestions();

    const saleDate = document.getElementById('sale-date');
    const saleType = document.getElementById('sale-type');
    const customer = document.getElementById('sale-customer');
    const customerSearch = document.getElementById('sale-customer-search');
    const mutuelle = document.getElementById('sale-mutuelle');
    const code = document.getElementById('sale-product-code');
    const productSearch = document.getElementById('sale-product-search');
    const qty = document.getElementById('sale-qty');
    const specialMarginBoost = document.getElementById('sale-special-margin-boost');

    if (saleDate) saleDate.value = String(saleRow.date_vente || '').slice(0, 16);
    if (saleType) saleType.value = String(saleRow.type_vente || 'COMPTANT').toLowerCase();
    if (customer) {
        ensureSelectOptionValue(customer, saleRow.client_id || '', saleRow.customers?.nom || 'Client');
        customer.value = saleRow.client_id || '';
    }
    if (customerSearch) {
        customerSearch.value = saleRow.customers?.nom || '';
        customerSearch.placeholder = 'Client passager';
    }
    if (mutuelle) {
        ensureSelectOptionValue(mutuelle, saleRow.mutuelle_id || '', saleRow.mutuelles?.nom || 'Mutuelle');
        mutuelle.value = saleRow.mutuelle_id || '';
    }
    const mutuelleMatricule = document.getElementById('sale-mutuelle-matricule');
    if (mutuelleMatricule) {
        mutuelleMatricule.value = saleRow.customers?.numero_matricule_mutuelle || '';
    }
    if (code) code.value = '';
    if (productSearch) productSearch.value = '';
    if (qty) qty.value = '1';
    if (specialMarginBoost) specialMarginBoost.checked = false;
    saleState.specialMarginBoost = false;

    renderSaleItems();
    calculateSaleTotals();
    refreshSaleMutuelleSummary();
    setSaleFormReadonlyMode(true);
    setSaleNumberPreview(saleRow.numero_vente || '-');
    const operatorSpan = document.getElementById('sale-operator-name');
    if (operatorSpan) {
        operatorSpan.textContent = saleRow.created_by || '\u00A0';
    }
}

function setSaleNumberPreview(value = '-') {
    const input = document.getElementById('sale-number-preview');
    if (input) input.value = value || '-';
}

async function refreshSaleNumberPreview() {
    const input = document.getElementById('sale-number-preview');
    if (!input) return;

    input.value = '...';
    const number = await peekSequentialNumber('VTE', () => generateLegacyPrefixedNumber('VTE'));
    input.value = number || '-';
}

async function openSaleHistoryPrevious() {
    try {
        if (!Array.isArray(saleState.historyRows) || saleState.historyRows.length === 0) {
            saleState.historyRows = await fetchSaleHistoryRows();
        }

        if (!saleState.historyRows.length) {
            alert('Aucune vente dans l historique.');
            return;
        }

        if (!isSaleHistoryReadonlyMode()) {
            await openSaleHistoryAtIndex(0);
            return;
        }

        const nextIndex = saleState.historyIndex + 1;
        if (nextIndex >= saleState.historyRows.length) return;
        await openSaleHistoryAtIndex(nextIndex);
    } catch (error) {
        console.error('Erreur chargement historique ventes:', error);
        alert('Impossible de charger l historique des ventes.');
    }
}

async function openSaleHistoryNext() {
    try {
        if (!isSaleHistoryReadonlyMode()) {
            if (!Array.isArray(saleState.historyRows) || saleState.historyRows.length === 0) {
                saleState.historyRows = await fetchSaleHistoryRows();
            }
            if (!saleState.historyRows.length) {
                alert('Aucune vente dans l historique.');
                return;
            }
            await openSaleHistoryAtIndex(0);
            return;
        }

        const nextIndex = saleState.historyIndex - 1;
        if (nextIndex < 0) return;
        await openSaleHistoryAtIndex(nextIndex);
    } catch (error) {
        console.error('Erreur chargement historique ventes:', error);
        alert('Impossible de charger l historique des ventes.');
    }
}

function getSaleSearchNumberValue(rawValue) {
    const value = String(rawValue || '').trim().toUpperCase();
    if (!value) return '';
    const digits = value.replace(/^VTE-/, '').replace(/\D/g, '');
    return digits ? `VTE-${digits.padStart(6, '0')}` : '';
}

function handleSaleNumberSearchKeydown(event) {
    if (event.key !== 'Enter') return;
    event.preventDefault();
    searchSaleByNumber();
}

async function searchSaleByNumber() {
    const input = document.getElementById('sale-number-search');
    const saleNumber = getSaleSearchNumberValue(input?.value || '');
    if (!saleNumber) {
        alert('Saisissez un numero de vente, exemple VTE-000016.');
        return;
    }

    if (input) input.value = saleNumber.replace(/^VTE-/, '');

    try {
        let rows = await fetchCollection(`sales?select=*,customers(id,nom,telephone,solde,en_cours,reste_a_payer,mutuelle_id,numero_matricule_mutuelle,nom_malade),mutuelles(id,nom,taux_remboursement)&numero_vente=eq.${encodeURIComponent(saleNumber)}&limit=1`, []);
        let saleRow = Array.isArray(rows) ? rows[0] : null;
        if (!saleRow) {
            const fallbackResponse = await fetch(`${supabaseUrl}sales?numero_vente=eq.${encodeURIComponent(saleNumber)}&select=id,numero_vente,date_vente,type_vente,client_id,mutuelle_id,payment_mode,total_ht,total_tva,total_ttc,statut&limit=1`, { headers: supabaseHeaders });
            if (fallbackResponse.ok) {
                const fallbackRows = await fallbackResponse.json();
                saleRow = Array.isArray(fallbackRows) ? fallbackRows[0] : null;
            }
        }
        if (!saleRow) {
            alert(`Vente ${saleNumber} introuvable.`);
            return;
        }

        if (!Array.isArray(saleState.historyRows) || saleState.historyRows.length === 0) {
            saleState.historyRows = await fetchSaleHistoryRows();
        }

        let index = saleState.historyRows.findIndex(item => String(item.id) === String(saleRow.id));
        if (index < 0) {
            saleState.historyRows.unshift(saleRow);
            index = 0;
        }

        await openSaleHistoryAtIndex(index);
        const statusNode = document.getElementById('sale-history-status');
        if (statusNode) {
            statusNode.style.display = 'none';
            statusNode.textContent = '';
        }
    } catch (error) {
        console.error('Erreur recherche vente par numero:', error);
        alert('Impossible de rechercher cette vente.');
    }
}

function getCustomerTypeKey(item) {
    const explicitType = String(item?.customerType || '').trim().toUpperCase();
    if (explicitType === 'WEB' || explicitType === 'REGISTERED' || explicitType === 'PASSAGER') {
        return explicitType;
    }
    if (String(item?.source || '').toUpperCase() === 'WEB' || String(item?.mode || '').toUpperCase() === 'E-COMMERCE') {
        return 'WEB';
    }
    if (item?.client_id) {
        return 'REGISTERED';
    }
    return 'PASSAGER';
}

function getCustomerTypeLabel(item) {
    const explicitLabel = String(item?.customerTypeLabel || '').trim();
    if (explicitLabel) return explicitLabel;
    const key = getCustomerTypeKey(item);
    if (key === 'WEB') return 'Client web';
    if (key === 'REGISTERED') return 'Client enregistre';
    return 'Client passager';
}

function renderCustomerTypeBadge(item) {
    const key = getCustomerTypeKey(item);
    const label = getCustomerTypeLabel(item);
    const cssKey = key.toLowerCase();
    return `<span class="customer-type-badge customer-type-${cssKey}">${escapeHtml(label)}</span>`;
}

