function saveSale() {
    if (isSaleHistoryReadonlyMode()) {
        alert('Historique des ventes en lecture seule.');
        return;
    }
    if (!validateCurrentUserSaleDiscountLimits(true)) return;
    const context = getSaleValidationContext();
    if (!context) return;
    openSalePaymentModal(context);
}

function openSalePaymentModal(context = getSaleValidationContext()) {
    if (!context) return;

    const modal = document.getElementById('sale-payment-modal');
    if (!modal) return;

    const paymentMode = document.getElementById('sale-payment-mode');
    const receivedInput = document.getElementById('sale-payment-received');
    const paymentName = document.getElementById('sale-payment-name');
    const paymentReference = document.getElementById('sale-payment-reference');
    const paymentEcheance = document.getElementById('sale-payment-echeance');
    const totalDisplay = document.getElementById('sale-payment-total-display');
    const breakdown = getSaleMutuelleBreakdown(context.totalTtc);
    const payableAmount = roundMoneyValue(context.saleType === 'mutuelle' ? breakdown.partClient : context.totalTtc);
    const hasRegisteredCustomer = Boolean(context.customerId);

    if (paymentMode) {
        Array.from(paymentMode.options || []).forEach(option => {
            if (String(option.value || '').toUpperCase() === 'CREDIT') {
                option.disabled = !hasRegisteredCustomer;
            }
        });
        paymentMode.value = 'ESPECE';
        paymentMode.disabled = false;
    }
    if (receivedInput) {
        receivedInput.value = '';
        receivedInput.disabled = false;
    }
    if (paymentName) paymentName.value = '';
    if (paymentReference) paymentReference.value = '';
    if (paymentEcheance) paymentEcheance.value = (context.saleDateValue || new Date().toISOString().slice(0, 10)).slice(0, 10);
    if (totalDisplay) totalDisplay.innerText = formatMoney(payableAmount);
    const passwordInput = document.getElementById('sale-payment-operator-password');
    if (passwordInput) passwordInput.value = '';

    modal.dataset.totalTtc = String(roundMoneyValue(context.totalTtc));
    modal.dataset.payableAmount = String(payableAmount);
    modal.style.display = 'block';
    handleSalePaymentModeChange();
    updateSalePaymentSummary();
    setTimeout(() => {
        const input = document.getElementById('sale-payment-received');
        if (!input || input.disabled) return;
        input.focus();
        input.select?.();
    }, 0);
}

function closeSalePaymentModal() {
    const modal = document.getElementById('sale-payment-modal');
    if (modal) modal.style.display = 'none';
}

function handleSalePaymentModeChange() {
    const mode = document.getElementById('sale-payment-mode')?.value || 'ESPECE';
    const receivedInput = document.getElementById('sale-payment-received');
    const echeanceInput = document.getElementById('sale-payment-echeance');
    const payableAmount = roundMoneyValue(document.getElementById('sale-payment-modal')?.dataset.payableAmount || 0);
    const isCash = mode === 'ESPECE';

    if (receivedInput) {
        receivedInput.disabled = !isCash;
        if (!isCash && Number(receivedInput.value || 0) !== 0) {
            receivedInput.value = formatMoney(0);
        }
    }

    if (echeanceInput) {
        echeanceInput.disabled = isCash || mode === 'CARTE';
    }

    updateSalePaymentSummary();
}

function handleSalePaymentReceivedKeydown(event) {
    if (event.key !== 'Enter') return;
    event.preventDefault();
    updateSalePaymentSummary();
    const passwordInput = document.getElementById('sale-payment-operator-password');
    if (passwordInput) {
        passwordInput.focus();
        passwordInput.select?.();
    }
}

function handleSalePaymentPasswordKeydown(event) {
    if (event.key !== 'Enter') return;
    event.preventDefault();
    confirmSalePayment();
}

function updateSalePaymentSummary() {
    const modal = document.getElementById('sale-payment-modal');
    const totalTtc = roundMoneyValue(modal?.dataset.totalTtc || 0);
    const payableAmount = roundMoneyValue(modal?.dataset.payableAmount || totalTtc);
    const mode = document.getElementById('sale-payment-mode')?.value || 'ESPECE';
    const received = roundMoneyValue(document.getElementById('sale-payment-received')?.value || 0);
    const isCash = mode === 'ESPECE';
    const change = isCash ? roundMoneyValue(Math.max(received - payableAmount, 0)) : 0;

    const changeDisplay = document.getElementById('sale-payment-change-display');
    const totalDisplay = document.getElementById('sale-payment-total-display');
    const paymentRateDisplay = document.getElementById('sale-payment-rate-display');
    const paymentMutuelleDisplay = document.getElementById('sale-payment-mutuelle-display');
    const paymentClientDisplay = document.getElementById('sale-payment-client-display');
    const breakdown = getSaleMutuelleBreakdown(totalTtc);
    if (totalDisplay) totalDisplay.innerText = formatMoney(payableAmount);
    if (changeDisplay) changeDisplay.innerText = formatMoney(change);
    if (paymentRateDisplay) paymentRateDisplay.innerText = `${formatMoney(breakdown.rate)} %`;
    if (paymentMutuelleDisplay) paymentMutuelleDisplay.innerText = formatMoney(breakdown.partMutuelle);
    if (paymentClientDisplay) paymentClientDisplay.innerText = formatMoney(breakdown.partClient);
}

function applySaleReceivedPreset(amount) {
    const input = document.getElementById('sale-payment-received');
    if (!input || input.disabled) return;
    input.value = formatMoney(amount || 0);
    updateSalePaymentSummary();
}

function setSaleSavingState(isSaving) {
    saleState.isSaving = Boolean(isSaving);
    const confirmButton = document.getElementById('sale-confirm-button');
    const paymentValidateButton = document.querySelector('#sale-payment-modal .pos-action-btn.green');
    if (confirmButton) {
        confirmButton.disabled = saleState.isSaving;
        confirmButton.style.opacity = saleState.isSaving ? '0.7' : '1';
        confirmButton.style.pointerEvents = saleState.isSaving ? 'none' : 'auto';
    }
    if (paymentValidateButton) {
        paymentValidateButton.disabled = saleState.isSaving;
        paymentValidateButton.innerText = saleState.isSaving ? 'Enregistrement...' : 'Valider F3';
        paymentValidateButton.style.opacity = saleState.isSaving ? '0.7' : '1';
        paymentValidateButton.style.pointerEvents = saleState.isSaving ? 'none' : 'auto';
    }
}

function getDuplicateGuardAmount(value) {
    return Number(Number(value || 0).toFixed(3));
}

function getDuplicateGuardLineSignature(items = [], kind = 'sale') {
    return (Array.isArray(items) ? items : [])
        .map(item => {
            const productId = String(item.product_id || '').trim();
            const qty = getDuplicateGuardAmount(item.quantite || 0);
            const freeQty = kind === 'purchase' ? getDuplicateGuardAmount(item.quantite_gratuite || 0) : 0;
            const price = getDuplicateGuardAmount(kind === 'purchase' ? item.prix_achat_ht : item.prix_unitaire_ttc);
            const remise = getDuplicateGuardAmount(item.remise || 0);
            const fodec = kind === 'purchase' ? getDuplicateGuardAmount(item.fodec_pct || 0) : 0;
            const peremption = kind === 'purchase' ? String(item.peremption || '') : '';
            return [productId, qty, freeQty, price, remise, fodec, peremption].join('|');
        })
        .sort()
        .join('||');
}

function areDuplicateGuardLinesEqual(leftItems = [], rightItems = [], kind = 'sale') {
    return getDuplicateGuardLineSignature(leftItems, kind) === getDuplicateGuardLineSignature(rightItems, kind);
}

function getDuplicateGuardWindowIso(minutes = 10) {
    return new Date(Date.now() - (minutes * 60 * 1000)).toISOString();
}

async function findRecentDuplicateSale(context, paymentMode, saleItemsSnapshot = []) {
    const typeVente = String(context.saleType || '').toUpperCase();
    const totalTtc = getDuplicateGuardAmount(context.totalTtc);
    const since = encodeURIComponent(getDuplicateGuardWindowIso(10));
    const clientFilter = context.customerId ? `client_id=eq.${context.customerId}` : 'client_id=is.null';
    const endpoint = [
        'sales?select=id,numero_vente,created_at,date_vente,total_ttc,client_id,type_vente,payment_mode',
        `created_at=gte.${since}`,
        `total_ttc=eq.${totalTtc}`,
        `type_vente=eq.${encodeURIComponent(typeVente)}`,
        `payment_mode=eq.${encodeURIComponent(paymentMode)}`,
        clientFilter,
        'order=created_at.desc'
    ].join('&');

    const candidates = await fetchCollection(endpoint, []);
    if (!Array.isArray(candidates) || candidates.length === 0) return null;

    const ids = candidates.map(item => item.id).filter(Boolean);
    if (ids.length === 0) return null;

    const itemRows = await fetchCollection(`sale_items?select=sale_id,product_id,quantite,prix_unitaire_ttc,remise&sale_id=in.(${ids.join(',')})`, []);
    const rowsBySaleId = (Array.isArray(itemRows) ? itemRows : []).reduce((acc, item) => {
        const key = String(item.sale_id || '');
        if (!acc[key]) acc[key] = [];
        acc[key].push(item);
        return acc;
    }, {});

    return candidates.find(candidate => areDuplicateGuardLinesEqual(saleItemsSnapshot, rowsBySaleId[String(candidate.id || '')] || [], 'sale')) || null;
}

async function confirmSalePayment() {
    if (saleState.isSaving) return;
    if (!validateCurrentUserSaleDiscountLimits(true)) return;
    const context = getSaleValidationContext();
    if (!context) return;

    const paymentModeInput = document.getElementById('sale-payment-mode');
    let mode = paymentModeInput?.value || 'ESPECE';
    if (String(mode).toUpperCase() === 'CREDIT' && !context.customerId) {
        alert('Le mode CREDIT est interdit pour Client passager.');
        return;
    }
    const receivedRaw = String(document.getElementById('sale-payment-received')?.value || '').trim();
    if (context.customerId && !receivedRaw) {
        mode = 'CREDIT';
        if (paymentModeInput) paymentModeInput.value = 'CREDIT';
    }
    if (!context.customerId && !['ESPECE', 'CARTE', 'CHEQUE', 'TRAITE', 'VIREMENT'].includes(String(mode).toUpperCase())) {
        mode = 'ESPECE';
        if (paymentModeInput) paymentModeInput.value = 'ESPECE';
    }
    const received = roundMoneyValue(receivedRaw || 0);
    const breakdown = getSaleMutuelleBreakdown(context.totalTtc);
    const payableAmount = roundMoneyValue(context.saleType === 'mutuelle' ? breakdown.partClient : context.totalTtc);
    if (mode === 'ESPECE' && received < payableAmount) {
        alert('Le montant recu doit etre superieur ou egal au net a payer.');
        return;
    }

    const passwordInput = document.getElementById('sale-payment-operator-password');
    const password = passwordInput ? passwordInput.value : '';
    if (!password) {
        alert("Veuillez entrer le mot de passe de l'opérateur.");
        passwordInput?.focus();
        return;
    }
    const operator = authorizationState.users.find(u => u.isActive !== false && String(u.password || '') === password);
    if (!operator) {
        alert('Mot de passe opérateur incorrect.');
        passwordInput?.focus();
        passwordInput?.select?.();
        return;
    }

    setSaleSavingState(true);
    try {
        await finalizeSale(context, operator.fullName || operator.username);
    } finally {
        setSaleSavingState(false);
    }
}

async function finalizeSale(context, operatorName = '') {
    const {
        saleType,
        customerId,
        mutuelleId,
        saleDateValue,
        totalHt,
        totalTva,
        totalTtc
    } = context;
    const paymentMode = document.getElementById('sale-payment-mode')?.value || 'ESPECE';
    const saleItemsSnapshot = saleState.items.map(item => ({ ...item }));
    const duplicateSale = await findRecentDuplicateSale(context, paymentMode, saleItemsSnapshot);
    if (duplicateSale) {
        alert(`Doublon vente detecte.\n\nLa vente ${duplicateSale.numero_vente || ''} a deja ete enregistree avec le meme client, le meme total et les memes articles.`);
        return;
    }

    const numeroVente = await requestSequentialNumber('VTE', () => generateLegacyPrefixedNumber('VTE'));

    const salePayload = {
        numero_vente: numeroVente,
        type_vente: saleType.toUpperCase(),
        client_id: customerId,
        mutuelle_id: saleType === 'mutuelle' ? mutuelleId : null,
        payment_mode: paymentMode,
        total_ht: totalHt,
        total_tva: totalTva,
        total_ttc: totalTtc,
        statut: 'Valide',
        date_vente: saleDateValue ? new Date(saleDateValue).toISOString() : new Date().toISOString(),
        created_by: operatorName || null
    };

    try {
        const resumedFridgeSale = pendingFridgeSaleResumeSnapshot;
        const saleResponse = await fetch(`${supabaseUrl}sales`, {
            method: 'POST',
            headers: { ...supabaseHeaders, Prefer: 'return=representation' },
            body: JSON.stringify(salePayload)
        });

        if (!saleResponse.ok) {
            const errorText = await saleResponse.text();
            if (saleResponse.status === 400 && /type_vente|payment_mode|schema cache/i.test(errorText)) {
                throw new Error(
                    `Colonne manquante dans la table sales.\n\n` +
                    `Execute d'abord ce SQL dans Supabase:\n${getSalesMigrationSql()}`
                );
            }
            throw new Error(`HTTP ${saleResponse.status} - ${errorText}`);
        }

        const [savedSale] = await saleResponse.json();
        const saleItemsPayload = saleItemsSnapshot.map(item => ({
            sale_id: savedSale.id,
            product_id: item.product_id,
            quantite: item.quantite,
            prix_unitaire_ttc: item.prix_unitaire_ttc,
            remise: item.remise || 0
        }));

        const itemResponse = await fetch(`${supabaseUrl}sale_items`, {
            method: 'POST',
            headers: supabaseHeaders,
            body: JSON.stringify(saleItemsPayload)
        });

        if (!itemResponse.ok) {
            throw new Error(`HTTP ${itemResponse.status}`);
        }

        const hasRegisteredCustomer = Boolean(customerId);
        const isPassagerSale = saleType === 'comptant' && !hasRegisteredCustomer;
        if (isPassagerSale) {
            const remiseAlerts = saleItemsSnapshot
                .map(item => {
                    const grossLineTotal = Number(item.quantite || 0) * Number(item.prix_unitaire_ttc || 0);
                    const remiseValue = Number(item.remise || 0);
                    const remisePct = grossLineTotal > 0 ? (remiseValue / grossLineTotal) * 100 : 0;
                    if (remisePct <= 10) return null;
                    return {
                        field: item.code_article || item.designation || 'Article',
                        label: item.designation || item.code_article || 'Article',
                        before: `${formatMoney(remisePct)} %`,
                        after: `${formatMoney(remiseValue)} DT`
                    };
                })
                .filter(Boolean);

            if (remiseAlerts.length) {
                await recordActionHistory({
                    category: 'REMISE_PASSAGER_10',
                    action: 'CREATE',
                    entityType: 'SALE',
                    entityId: savedSale.id || '',
                    entityLabel: savedSale.numero_vente || 'Vente passager',
                    details: remiseAlerts
                });
            }
        }

        const stockUpdatesByProduct = new Map();
        saleItemsSnapshot.forEach(item => {
            const productId = String(item.product_id || '');
            if (!productId || stockUpdatesByProduct.has(productId)) return;
            const totalQuantity = saleItemsSnapshot
                .filter(line => String(line.product_id || '') === productId)
                .reduce((sum, line) => sum + Number(line.quantite || 0), 0);
            stockUpdatesByProduct.set(productId, {
                id: item.product_id,
                stock_actuel: Number(item.stock_actuel || 0) - totalQuantity
            });
        });

        await Promise.all(Array.from(stockUpdatesByProduct.values()).map(item => {
            return fetch(`${supabaseUrl}products?id=eq.${item.id}`, {
                method: 'PATCH',
                headers: supabaseHeaders,
                body: JSON.stringify({ stock_actuel: item.stock_actuel })
            });
        }));

        updateCachedProductsLocally(Array.from(stockUpdatesByProduct.values()).map(item => ({
            id: item.id,
            stock_actuel: item.stock_actuel
        })));
        invalidateProductsCache();

        const inferredMode = inferSaleMode({
            ...savedSale,
            type_vente: salePayload.type_vente,
            payment_mode: salePayload.payment_mode,
            client_id: salePayload.client_id,
            mutuelle_id: salePayload.mutuelle_id
        });
        const mutuelleClientCredit = saleType === 'mutuelle' && String(paymentMode || '').toUpperCase() === 'CREDIT';
        if (customerId && (inferredMode === 'CREDIT' || mutuelleClientCredit)) {
            const customer = getSaleCustomerById(customerId);
            const currentSolde = Number(customer?.solde || 0);
            const currentEncours = Number(customer?.en_cours || 0);
            const currentReste = Number(customer?.reste_a_payer || 0);
            const breakdown = getSaleMutuelleBreakdown(totalTtc);
            const clientDebit = roundMoneyValue(mutuelleClientCredit ? breakdown.partClient : totalTtc);
            const customerUpdatePayload = {
                solde: currentSolde + clientDebit,
                en_cours: currentEncours + clientDebit,
                reste_a_payer: currentReste + clientDebit
            };
            const customerResponse = await fetch(`${supabaseUrl}customers?id=eq.${customerId}`, {
                method: 'PATCH',
                headers: { ...supabaseHeaders, Prefer: 'return=representation' },
                body: JSON.stringify(customerUpdatePayload)
            });
            if (!customerResponse.ok) {
                const customerError = await customerResponse.text();
                throw new Error(customerError || `HTTP ${customerResponse.status}`);
            }
            const updatedCustomers = await customerResponse.json();
            const updatedCustomer = Array.isArray(updatedCustomers) ? updatedCustomers[0] : null;
            updateCachedCustomersLocally([{
                id: customerId,
                ...customerUpdatePayload,
                ...(updatedCustomer || {})
            }]);
        }

        closeSalePaymentModal();
        if (resumedFridgeSale?.id) {
            await updateFridgeSaleRecord(resumedFridgeSale.id, {
                statut: 'LIVREE',
                resumed_at: new Date().toISOString()
            }, 'Vente frigo reprise et confirmee.');
            pendingFridgeSaleResumeSnapshot = null;
        }
        showSuccessToast(`Vente enregistree avec succes. Ticket N ${savedSale.numero_vente || '-'}.`);
        resetSaleForm();
        refreshProductsCacheInBackground('vente');
    } catch (error) {
        console.error('Erreur enregistrement vente:', error);
        alert("Erreur lors de l'enregistrement de la vente.");
    }
}

