const supplierReturnState = {
    products: [],
    suppliers: [],
    items: [],
    selectedProductId: '',
    filteredProducts: [],
    highlightedSuggestionIndex: -1,
    productSearchRequestId: 0,
    selectedSupplierId: '',
    filteredSuppliers: [],
    highlightedSupplierIndex: -1,
    supplierSearchRequestId: 0,
    isSaving: false
};

