async function initSupplierReturnModule() {
    const supplierSelect = document.getElementById('supplier-return-supplier');
    if (supplierSelect) {
        supplierSelect.innerHTML = '<option value="">Chargement des fournisseurs...</option>';
    }
    const [products, suppliers] = await Promise.all([
        fetchEntryProductsForSaleAndPurchase(),
        loadSupplierReturnSuppliers({ force: true })
    ]);
    supplierReturnState.products = Array.isArray(products) ? products : [];
    supplierReturnState.suppliers = Array.isArray(suppliers) ? suppliers : [];
    supplierReturnState.filteredProducts = supplierReturnState.products.slice(0, 8);
    supplierReturnState.highlightedSuggestionIndex = supplierReturnState.filteredProducts.length ? 0 : -1;
    supplierReturnState.filteredSuppliers = supplierReturnState.suppliers.slice(0, 8);
    supplierReturnState.highlightedSupplierIndex = supplierReturnState.filteredSuppliers.length ? 0 : -1;
    fillSupplierReturnSuppliers();
    resetSupplierReturnForm({ keepLoadedData: true });
    if (!supplierReturnState.suppliers.length) {
        setTimeout(() => reloadSupplierReturnSuppliers({ silent: true }), 500);
    }
    renderSupplierReturnHistory();
    setTimeout(() => document.getElementById('supplier-return-date')?.focus(), 0);
}

function handleSupplierReturnFocusNext(event, nextId) {
    if (event.key !== 'Enter') return;
    event.preventDefault();
    const next = document.getElementById(nextId);
    next?.focus();
    next?.select?.();
}

function fillSupplierReturnSuppliers() {
    const select = document.getElementById('supplier-return-supplier');
    if (!select) return;
    const suppliers = getSupplierReturnSupplierSource();
    if (!suppliers.length) {
        select.innerHTML = '<option value="">Aucun fournisseur charge - cliquez Actualiser</option>';
        const input = document.getElementById('supplier-return-supplier-search');
        if (input && !input.value) input.placeholder = 'Aucun fournisseur charge';
        return;
    }
    select.innerHTML = suppliers.map(supplier => `<option value="${supplier.id}">${escapeHtml(supplier.nom || supplier.name || '-')}</option>`).join('');
    if (!select.value) {
        select.value = suppliers[0]?.id || '';
    }
    selectSupplierReturnSupplierById(select.value);
}

function getSupplierReturnSupplierSource() {
    const merged = [];
    const seen = new Set();
    [
        supplierReturnState.suppliers,
        purchaseState.suppliers,
        allSuppliers
    ].forEach(list => {
        (Array.isArray(list) ? list : []).forEach(supplier => {
            const key = String(supplier?.id || supplier?.nom || supplier?.name || '').trim();
            if (!key || seen.has(key)) return;
            seen.add(key);
            merged.push(supplier);
        });
    });
    if (merged.length) {
        supplierReturnState.suppliers = merged;
    }
    return merged;
}

function getFilteredSupplierReturnSuppliers(searchTerm) {
    const normalized = normalizeSearchText(searchTerm);
    const suppliers = getSupplierReturnSupplierSource();
    if (!normalized) return suppliers.slice(0, 8);
    return suppliers
        .filter(supplier => {
            const name = normalizeSearchText(supplier.nom || supplier.name);
            const phone = normalizeSearchText(supplier.telephone || supplier.phone);
            const taxId = normalizeSearchText(supplier.matricule_fiscale || supplier.tax_id);
            return name.includes(normalized) || phone.includes(normalized) || taxId.includes(normalized);
        })
        .slice(0, 12);
}

function renderSupplierReturnSupplierSuggestions() {
    const container = document.getElementById('supplier-return-supplier-suggestions');
    if (!container) return;
    const rows = supplierReturnState.filteredSuppliers || [];
    if (!rows.length) {
        container.innerHTML = '<div class="sale-autocomplete-item empty">Aucun fournisseur trouve</div>';
        container.style.display = 'block';
        return;
    }
    container.innerHTML = rows.map((supplier, index) => `
        <button
            type="button"
            class="sale-autocomplete-item ${index === supplierReturnState.highlightedSupplierIndex ? 'active' : ''}"
            onmousedown="chooseSupplierReturnSupplierSuggestion(${index})"
        >
            <span class="code">${escapeHtml(supplier.telephone || supplier.matricule_fiscale || '')}</span>
            <span class="label">${escapeHtml(supplier.nom || supplier.name || '')}</span>
        </button>
    `).join('');
    container.style.display = 'block';
}

function closeSupplierReturnSupplierSuggestions() {
    const container = document.getElementById('supplier-return-supplier-suggestions');
    if (container) container.style.display = 'none';
}

function findSupplierReturnSupplier(searchTerm) {
    const normalized = normalizeSearchText(searchTerm);
    if (!normalized) return null;
    return getSupplierReturnSupplierSource().find(supplier => {
        const name = normalizeSearchText(supplier.nom || supplier.name);
        const phone = normalizeSearchText(supplier.telephone || supplier.phone);
        const taxId = normalizeSearchText(supplier.matricule_fiscale || supplier.tax_id);
        return name === normalized || phone === normalized || taxId === normalized || name.includes(normalized);
    }) || null;
}

function selectSupplierReturnSupplierById(supplierId) {
    const supplier = getSupplierReturnSupplierSource().find(item => String(item.id) === String(supplierId));
    if (!supplier) return;
    supplierReturnState.selectedSupplierId = supplier.id;
    const input = document.getElementById('supplier-return-supplier-search');
    const select = document.getElementById('supplier-return-supplier');
    if (input) input.value = supplier.nom || supplier.name || '';
    if (select) select.value = supplier.id;
    closeSupplierReturnSupplierSuggestions();
}

function chooseSupplierReturnSupplierSuggestion(index) {
    const supplier = supplierReturnState.filteredSuppliers[index];
    if (!supplier) return;
    selectSupplierReturnSupplierById(supplier.id);
    document.getElementById('supplier-return-code')?.focus();
}

async function handleSupplierReturnSupplierInput(event) {
    const rawValue = String(event.target.value || '');
    const requestId = ++supplierReturnState.supplierSearchRequestId;
    if (!rawValue.trim()) {
        supplierReturnState.filteredSuppliers = getSupplierReturnSupplierSource().slice(0, 8);
        supplierReturnState.highlightedSupplierIndex = supplierReturnState.filteredSuppliers.length ? 0 : -1;
        supplierReturnState.selectedSupplierId = '';
        const select = document.getElementById('supplier-return-supplier');
        if (select) select.value = '';
        renderSupplierReturnSupplierSuggestions();
        return;
    }

    const supplier = findSupplierReturnSupplier(rawValue);
    supplierReturnState.filteredSuppliers = getFilteredSupplierReturnSuppliers(rawValue);
    if (!supplierReturnState.filteredSuppliers.length && rawValue.trim().length >= 2) {
        await reloadSupplierReturnSuppliers({ silent: true });
        if (requestId !== supplierReturnState.supplierSearchRequestId) return;
        supplierReturnState.filteredSuppliers = getFilteredSupplierReturnSuppliers(rawValue);
    }
    supplierReturnState.highlightedSupplierIndex = supplierReturnState.filteredSuppliers.length ? 0 : -1;
    renderSupplierReturnSupplierSuggestions();

    const select = document.getElementById('supplier-return-supplier');
    if (supplier) {
        supplierReturnState.selectedSupplierId = supplier.id;
        if (select) select.value = supplier.id;
    } else {
        supplierReturnState.selectedSupplierId = '';
        if (select) select.value = '';
    }
}

function handleSupplierReturnSupplierKeydown(event) {
    if (event.key === 'ArrowDown') {
        event.preventDefault();
        if (!supplierReturnState.filteredSuppliers.length) return;
        supplierReturnState.highlightedSupplierIndex = Math.min(
            supplierReturnState.highlightedSupplierIndex + 1,
            supplierReturnState.filteredSuppliers.length - 1
        );
        renderSupplierReturnSupplierSuggestions();
        return;
    }
    if (event.key === 'ArrowUp') {
        event.preventDefault();
        if (!supplierReturnState.filteredSuppliers.length) return;
        supplierReturnState.highlightedSupplierIndex = Math.max(supplierReturnState.highlightedSupplierIndex - 1, 0);
        renderSupplierReturnSupplierSuggestions();
        return;
    }
    if (event.key === 'Escape') {
        closeSupplierReturnSupplierSuggestions();
        return;
    }
    if (event.key !== 'Enter') return;
    event.preventDefault();
    if (supplierReturnState.highlightedSupplierIndex >= 0 && supplierReturnState.filteredSuppliers[supplierReturnState.highlightedSupplierIndex]) {
        selectSupplierReturnSupplierById(supplierReturnState.filteredSuppliers[supplierReturnState.highlightedSupplierIndex].id);
        document.getElementById('supplier-return-code')?.focus();
        return;
    }
    const supplier = findSupplierReturnSupplier(event.target.value);
    if (!supplier) {
        alert('Fournisseur introuvable.');
        return;
    }
    selectSupplierReturnSupplierById(supplier.id);
    document.getElementById('supplier-return-code')?.focus();
}

async function loadSupplierReturnSuppliers(options = {}) {
    const cached = Array.isArray(allSuppliers) && allSuppliers.length
        ? allSuppliers
        : Array.isArray(purchaseState.suppliers) && purchaseState.suppliers.length
            ? purchaseState.suppliers
            : [];
    if (!options.force && cached.length) return cached;
    try {
        const suppliers = await refreshSuppliersCache();
        if (Array.isArray(suppliers) && suppliers.length) return suppliers;
        return cached;
    } catch (error) {
        console.warn('Chargement fournisseurs retour impossible.', error);
        return cached;
    }
}

async function reloadSupplierReturnSuppliers(options = {}) {
    const select = document.getElementById('supplier-return-supplier');
    if (select && !options.silent) {
        select.innerHTML = '<option value="">Chargement des fournisseurs...</option>';
    }
    try {
        supplierReturnState.suppliers = await refreshSuppliersCache();
    } catch (error) {
        console.warn('Actualisation fournisseurs retour impossible.', error);
        supplierReturnState.suppliers = await loadSupplierReturnSuppliers();
    }
    fillSupplierReturnSuppliers();
}

function resetSupplierReturnForm(options = {}) {
    supplierReturnState.items = [];
    supplierReturnState.selectedProductId = '';
    supplierReturnState.selectedSupplierId = options.keepSupplier ? supplierReturnState.selectedSupplierId : '';
    supplierReturnState.isSaving = false;
    const number = document.getElementById('supplier-return-number');
    const date = document.getElementById('supplier-return-date');
    const supplierBlNumber = document.getElementById('supplier-return-bl-number');
    const supplier = document.getElementById('supplier-return-supplier');
    const supplierSearch = document.getElementById('supplier-return-supplier-search');
    const code = document.getElementById('supplier-return-code');
    const search = document.getElementById('supplier-return-search');
    const qty = document.getElementById('supplier-return-qty');
    const motif = document.getElementById('supplier-return-motif');
    if (number) number.value = generateLegacyPrefixedNumber('RTF');
    if (date) date.value = new Date().toISOString().split('T')[0];
    if (supplierBlNumber) supplierBlNumber.value = '';
    if (supplier && !options.keepSupplier && !options.keepLoadedData) {
        supplier.value = '';
    }
    if (supplier && !supplier.value && supplier.options.length > 0) {
        supplier.selectedIndex = 0;
        supplierReturnState.selectedSupplierId = supplier.value || '';
    }
    if (supplierSearch && !options.keepSupplier && !options.keepLoadedData) {
        const selectedSupplier = (supplierReturnState.suppliers || []).find(item => String(item.id) === String(supplier?.value || ''));
        supplierSearch.value = selectedSupplier?.nom || selectedSupplier?.name || '';
    }
    if (supplierSearch && options.keepSupplier) {
        const selectedSupplier = (supplierReturnState.suppliers || []).find(item => String(item.id) === String(supplier?.value || supplierReturnState.selectedSupplierId || ''));
        supplierSearch.value = selectedSupplier?.nom || selectedSupplier?.name || supplierSearch.value || '';
    }
    if (code) code.value = '';
    if (search) search.value = '';
    if (qty) qty.value = '1';
    if (motif && !options.keepMotif) motif.value = '';
    closeSupplierReturnSuggestions();
    closeSupplierReturnSupplierSuggestions();
    renderSupplierReturnItems();
    updateSupplierReturnSaveState(false);
    if (!options.keepLoadedData) {
        setTimeout(() => supplierBlNumber?.focus(), 0);
    }
}

function findSupplierReturnProductByCode(value) {
    const query = normalizeSearchText(value);
    if (!query) return null;
    return supplierReturnState.products.find(product =>
        normalizeSearchText(product.code_barre) === query
        || normalizeSearchText(product.code_article) === query
    ) || null;
}

function findSupplierReturnProductFromSearch(value) {
    const selectedId = supplierReturnState.selectedProductId;
    if (selectedId) {
        return supplierReturnState.products.find(product => String(product.id) === String(selectedId)) || null;
    }
    const query = normalizeSearchText(value);
    if (!query) return null;
    return supplierReturnState.products.find(product =>
        normalizeSearchText(product.designation) === query
        || normalizeSearchText(product.code_article) === query
        || normalizeSearchText(product.code_barre) === query
    ) || null;
}

function renderSupplierReturnSuggestions() {
    const container = document.getElementById('supplier-return-suggestions');
    if (!container) return;
    const rows = supplierReturnState.filteredProducts || [];
    if (!rows.length) {
        container.innerHTML = '<div class="sale-autocomplete-item empty">Aucun article trouve</div>';
        container.style.display = 'block';
        return;
    }
    container.innerHTML = rows.map((product, index) => `
        <div class="sale-autocomplete-item ${index === supplierReturnState.highlightedSuggestionIndex ? 'active' : ''}" onmousedown="chooseSupplierReturnSuggestion(${index})">
            <strong>${escapeHtml(product.code_article || '')}</strong>
            <span>${escapeHtml(product.designation || '')}</span>
            <small>Stock ${formatMoney(product.stock_actuel || 0)}</small>
        </div>
    `).join('');
    container.style.display = 'block';
}

function closeSupplierReturnSuggestions() {
    const container = document.getElementById('supplier-return-suggestions');
    if (container) container.style.display = 'none';
}

async function handleSupplierReturnSearchInput(event) {
    const query = normalizeSearchText(event.target?.value || '');
    const rawValue = String(event.target?.value || '').trim();
    const requestId = ++supplierReturnState.productSearchRequestId;
    supplierReturnState.selectedProductId = '';
    supplierReturnState.filteredProducts = supplierReturnState.products
        .filter(product => {
            if (!query) return true;
            return [
                product.code_article,
                product.code_barre,
                product.designation,
                product.forme
            ].some(value => normalizeSearchText(value).includes(query));
        })
        .slice(0, 8);
    supplierReturnState.highlightedSuggestionIndex = supplierReturnState.filteredProducts.length ? 0 : -1;
    renderSupplierReturnSuggestions();

    if (supplierReturnState.filteredProducts.length > 0 || rawValue.length < 2) return;

    const remoteRows = await searchEntryProductsFromDatabase(rawValue);
    if (requestId !== supplierReturnState.productSearchRequestId) return;
    supplierReturnState.products = mergeEntryProductsCache(supplierReturnState.products, remoteRows);
    supplierReturnState.filteredProducts = remoteRows.slice(0, 8);
    supplierReturnState.highlightedSuggestionIndex = supplierReturnState.filteredProducts.length ? 0 : -1;
    renderSupplierReturnSuggestions();
}

function handleSupplierReturnSearchKeydown(event) {
    if (event.key === 'ArrowDown') {
        event.preventDefault();
        supplierReturnState.highlightedSuggestionIndex = Math.min(
            supplierReturnState.highlightedSuggestionIndex + 1,
            Math.max((supplierReturnState.filteredProducts || []).length - 1, 0)
        );
        renderSupplierReturnSuggestions();
        return;
    }
    if (event.key === 'ArrowUp') {
        event.preventDefault();
        supplierReturnState.highlightedSuggestionIndex = Math.max(supplierReturnState.highlightedSuggestionIndex - 1, 0);
        renderSupplierReturnSuggestions();
        return;
    }
    if (event.key === 'Enter') {
        event.preventDefault();
        if (supplierReturnState.highlightedSuggestionIndex >= 0) {
            chooseSupplierReturnSuggestion(supplierReturnState.highlightedSuggestionIndex);
        } else {
            addSelectedSupplierReturnItem();
        }
    }
    if (event.key === 'Escape') {
        closeSupplierReturnSuggestions();
    }
}

function chooseSupplierReturnSuggestion(index) {
    const product = supplierReturnState.filteredProducts[index];
    if (!product) return;
    supplierReturnState.selectedProductId = product.id;
    const search = document.getElementById('supplier-return-search');
    if (search) search.value = `${product.code_article || ''} - ${product.designation || ''}`.trim();
    closeSupplierReturnSuggestions();
    const qty = document.getElementById('supplier-return-qty');
    qty?.focus();
    qty?.select?.();
}

async function handleSupplierReturnCodeKeydown(event) {
    if (event.key !== 'Enter') return;
    event.preventDefault();
    const rawValue = String(event.target?.value || '').trim();
    let product = findSupplierReturnProductByCode(rawValue);
    if (!product && rawValue) {
        const remoteRows = await searchEntryProductsFromDatabase(rawValue);
        supplierReturnState.products = mergeEntryProductsCache(supplierReturnState.products, remoteRows);
        product = findSupplierReturnProductByCode(rawValue);
    }
    if (!product) {
        document.getElementById('supplier-return-search')?.focus();
        return;
    }
    supplierReturnState.selectedProductId = product.id;
    const search = document.getElementById('supplier-return-search');
    if (search) search.value = `${product.code_article || ''} - ${product.designation || ''}`.trim();
    document.getElementById('supplier-return-qty')?.focus();
}

function handleSupplierReturnQtyKeydown(event) {
    if (event.key !== 'Enter') return;
    event.preventDefault();
    addSelectedSupplierReturnItem();
}

function addSelectedSupplierReturnItem() {
    const product = findSupplierReturnProductFromSearch(document.getElementById('supplier-return-search')?.value || '')
        || findSupplierReturnProductByCode(document.getElementById('supplier-return-code')?.value || '');
    const qty = Number(document.getElementById('supplier-return-qty')?.value || 0);
    if (!product) {
        alert('Selectionnez un article.');
        return;
    }
    if (!Number.isFinite(qty) || qty <= 0) {
        alert('La quantite retour doit etre superieure a zero.');
        return;
    }
    if (qty > Number(product.stock_actuel || 0)) {
        alert(`Stock insuffisant. Disponible: ${formatMoney(product.stock_actuel || 0)}.`);
        return;
    }
    const existingIndex = supplierReturnState.items.findIndex(item => String(item.product_id) === String(product.id));
    if (existingIndex >= 0) {
        const nextQty = Number(supplierReturnState.items[existingIndex].quantite || 0) + qty;
        if (nextQty > Number(product.stock_actuel || 0)) {
            alert(`Stock insuffisant. Disponible: ${formatMoney(product.stock_actuel || 0)}.`);
            return;
        }
        supplierReturnState.items[existingIndex].quantite = nextQty;
    } else {
        supplierReturnState.items.push({
            product_id: product.id,
            code_article: product.code_article || '',
            designation: product.designation || '',
            stock_actuel: Number(product.stock_actuel || 0),
            prix_achat_ht: Number(product.prix_achat_ht || 0),
            quantite: qty
        });
    }
    supplierReturnState.selectedProductId = '';
    const code = document.getElementById('supplier-return-code');
    const search = document.getElementById('supplier-return-search');
    const qtyInput = document.getElementById('supplier-return-qty');
    if (code) code.value = '';
    if (search) search.value = '';
    if (qtyInput) qtyInput.value = '1';
    closeSupplierReturnSuggestions();
    renderSupplierReturnItems();
    code?.focus();
}

function updateSupplierReturnItemQty(index, value) {
    const item = supplierReturnState.items[index];
    if (!item) return;
    const qty = Number(value || 0);
    if (!Number.isFinite(qty) || qty <= 0) {
        alert('La quantite retour doit etre superieure a zero.');
        renderSupplierReturnItems();
        return;
    }
    if (qty > Number(item.stock_actuel || 0)) {
        alert(`Stock insuffisant. Disponible: ${formatMoney(item.stock_actuel || 0)}.`);
        renderSupplierReturnItems();
        return;
    }
    item.quantite = qty;
    renderSupplierReturnItems();
}

function removeSupplierReturnItem(index) {
    supplierReturnState.items.splice(index, 1);
    renderSupplierReturnItems();
}

function renderSupplierReturnItems() {
    const tbody = document.getElementById('supplier-return-items-body');
    if (!tbody) return;
    if (!supplierReturnState.items.length) {
        tbody.innerHTML = '<tr><td colspan="7" style="text-align:center; padding:28px;">Aucun article ajoute au retour.</td></tr>';
    } else {
        tbody.innerHTML = supplierReturnState.items.map((item, index) => {
            const totalHt = Number(item.quantite || 0) * Number(item.prix_achat_ht || 0);
            return `
                <tr>
                    <td>${escapeHtml(item.code_article || '-')}</td>
                    <td>${escapeHtml(item.designation || '-')}</td>
                    <td style="text-align:right; font-weight:800;">${formatMoney(item.stock_actuel || 0)}</td>
                    <td style="text-align:right;"><input type="number" min="1" step="0.001" value="${item.quantite}" class="field-input small" style="text-align:right;" onchange="updateSupplierReturnItemQty(${index}, this.value)"></td>
                    <td style="text-align:right;">${formatMoney(item.prix_achat_ht || 0)}</td>
                    <td style="text-align:right; font-weight:800;">${formatMoney(totalHt)}</td>
                    <td><button class="small-action-btn" type="button" onclick="removeSupplierReturnItem(${index})">Suppr.</button></td>
                </tr>
            `;
        }).join('');
    }
    const totals = supplierReturnState.items.reduce((acc, item) => {
        acc.qty += Number(item.quantite || 0);
        acc.ht += Number(item.quantite || 0) * Number(item.prix_achat_ht || 0);
        return acc;
    }, { qty: 0, ht: 0 });
    const count = document.getElementById('supplier-return-count');
    const totalQty = document.getElementById('supplier-return-total-qty');
    const totalHt = document.getElementById('supplier-return-total-ht');
    if (count) count.innerText = String(supplierReturnState.items.length);
    if (totalQty) totalQty.innerText = formatMoney(totals.qty);
    if (totalHt) totalHt.innerText = `${formatMoney(totals.ht)} DT`;
}

function getStoredSupplierReturns() {
    try {
        const raw = localStorage.getItem(SUPPLIER_RETURN_STORAGE_KEY);
        const parsed = raw ? JSON.parse(raw) : [];
        return Array.isArray(parsed) ? parsed : [];
    } catch {
        return [];
    }
}

function saveStoredSupplierReturns(rows) {
    localStorage.setItem(SUPPLIER_RETURN_STORAGE_KEY, JSON.stringify(Array.isArray(rows) ? rows : []));
}

function rememberSupplierReturnRecord(record) {
    if (!record) return;
    const rows = getStoredSupplierReturns();
    const key = String(record.numero || record.id || '').trim();
    const filtered = key
        ? rows.filter(item => String(item.numero || item.id || '').trim() !== key)
        : rows;
    saveStoredSupplierReturns([{ ...record }, ...filtered].slice(0, 200));
    renderSupplierReturnHistory();
}

function getSupplierReturnHistoryRows() {
    return getStoredSupplierReturns()
        .filter(item => item && (item.numero || item.id))
        .sort((a, b) => new Date(b.created_at || b.date || 0) - new Date(a.created_at || a.date || 0));
}

function initSupplierReturnHistoryModule() {
    const supplierSelect = document.getElementById('supplier-return-history-supplier');
    if (supplierSelect) {
        supplierSelect.innerHTML = '<option value="">Tous les fournisseurs</option>' + purchaseState.suppliers.map(s => `<option value="${s.id}">${escapeHtml(s.nom)}</option>`).join('');
    }
    renderSupplierReturnHistory();
}

