function printSupplierReturnHistoryList() {
    printElementContent(document.querySelector('.purchase-history-view .pos-table-container'), 'Historique des retours fournisseurs');
}

function renderSupplierReturnHistory() {
    const tbody = document.getElementById('supplier-return-history-body');
    if (!tbody) return;
    
    let rows = getSupplierReturnHistoryRows();
    
    // Apply filters if we are in the independent history module
    const supplierId = document.getElementById('supplier-return-history-supplier')?.value;
    const dateFrom = document.getElementById('supplier-return-history-from')?.value;
    const dateTo = document.getElementById('supplier-return-history-to')?.value;
    
    if (supplierId || dateFrom || dateTo) {
        rows = rows.filter(r => {
            if (supplierId && String(r.supplier_id) !== String(supplierId)) return false;
            const rDate = (r.date || '').split('T')[0];
            if (dateFrom && rDate < dateFrom) return false;
            if (dateTo && rDate > dateTo) return false;
            return true;
        });
    }

    if (!rows.length) {
        tbody.innerHTML = '<tr><td colspan="7" style="text-align:center; padding:18px;">Aucun bon de retour fournisseur.</td></tr>';
        return;
    }
    tbody.innerHTML = rows.map((record, index) => {
        // Find actual index in full rows array to keep openSupplierReturnDetail working
        const fullRows = getSupplierReturnHistoryRows();
        const actualIndex = fullRows.findIndex(r => r.id === record.id || r.numero === record.numero);
        
        const lineCount = Array.isArray(record.items) ? record.items.length : 0;
        const dateValue = record.date ? new Date(record.date).toLocaleDateString('fr-FR') : '-';
        return `
            <tr>
                <td style="font-weight:800;">${escapeHtml(record.numero || '-')}</td>
                <td>${escapeHtml(dateValue)}</td>
                <td>${escapeHtml(record.supplier_bl_number || '-')}</td>
                <td>${escapeHtml(record.supplier_name || '-')}</td>
                <td style="text-align:right;">${lineCount}</td>
                <td style="text-align:right; font-weight:800;">${formatMoney(record.total_ht || 0)}</td>
                <td style="white-space:nowrap;">
                    <div style="display:flex; gap:8px; flex-wrap:nowrap; align-items:center;">
                        <button class="small-action-btn" type="button" onclick="openSupplierReturnDetail(${actualIndex})">Details</button>
                        <button class="small-action-btn" type="button" onclick="printSupplierReturnHistory(${actualIndex})">Imprimer</button>
                    </div>
                </td>
            </tr>
        `;
    }).join('');
}

function openSupplierReturnDetail(index) {
    const record = getSupplierReturnHistoryRows()[index];
    const modal = document.getElementById('supplier-return-detail-modal');
    const title = document.getElementById('supplier-return-detail-title');
    const content = document.getElementById('supplier-return-detail-content');
    const printButton = document.getElementById('supplier-return-detail-print-btn');
    if (!record || !modal || !title || !content) return;
    const items = Array.isArray(record.items) ? record.items : [];
    const totalQty = items.reduce((sum, item) => sum + Number(item.quantite || 0), 0);
    const totalHt = Number(record.total_ht || items.reduce((sum, item) => sum + (Number(item.quantite || 0) * Number(item.prix_achat_ht || 0)), 0));
    title.innerText = `${record.numero || '-'} - ${record.supplier_name || '-'}`;
    content.innerHTML = `
        <div style="display:grid; grid-template-columns:repeat(4, minmax(0, 1fr)); gap:12px; margin-bottom:14px;">
            <div><strong>Numero</strong><div>${escapeHtml(record.numero || '-')}</div></div>
            <div><strong>Date</strong><div>${record.date ? new Date(record.date).toLocaleDateString('fr-FR') : '-'}</div></div>
            <div><strong>Numero BL Fournisseur</strong><div>${escapeHtml(record.supplier_bl_number || '-')}</div></div>
            <div><strong>Fournisseur</strong><div>${escapeHtml(record.supplier_name || '-')}</div></div>
        </div>
        ${record.note ? `<div style="margin-bottom:14px;"><strong>Motif</strong><div>${escapeHtml(record.note)}</div></div>` : ''}
        <table class="pos-table achat-table">
            <thead>
                <tr>
                    <th style="width:130px;">Code</th>
                    <th>Designation</th>
                    <th style="width:120px; text-align:right;">Qte retour</th>
                    <th style="width:140px; text-align:right;">Prix achat HT</th>
                    <th style="width:130px; text-align:right;">Total HT</th>
                </tr>
            </thead>
            <tbody>
                ${items.length ? items.map(item => {
        const lineTotal = Number(item.quantite || 0) * Number(item.prix_achat_ht || 0);
        return `
                        <tr>
                            <td>${escapeHtml(item.code_article || '-')}</td>
                            <td>${escapeHtml(item.designation || '-')}</td>
                            <td style="text-align:right;">${formatMoney(item.quantite || 0)}</td>
                            <td style="text-align:right;">${formatMoney(item.prix_achat_ht || 0)}</td>
                            <td style="text-align:right; font-weight:800;">${formatMoney(lineTotal)}</td>
                        </tr>
                    `;
    }).join('') : '<tr><td colspan="5" style="text-align:center; padding:18px;">Aucun article.</td></tr>'}
            </tbody>
        </table>
        <div style="display:flex; justify-content:flex-end; gap:24px; margin-top:14px; font-weight:900;">
            <span>Total quantite: ${formatMoney(totalQty)}</span>
            <span>Total HT: ${formatMoney(totalHt)} DT</span>
        </div>
    `;
    if (printButton) printButton.onclick = () => printSupplierReturnRecord(record);
    modal.style.display = 'flex';
}

function closeSupplierReturnDetail() {
    const modal = document.getElementById('supplier-return-detail-modal');
    if (modal) modal.style.display = 'none';
}

function getCurrentSupplierReturnDraftRecord() {
    const supplierId = document.getElementById('supplier-return-supplier')?.value || supplierReturnState.selectedSupplierId || '';
    const supplier = supplierReturnState.suppliers.find(item => String(item.id) === String(supplierId));
    const items = supplierReturnState.items.map(item => ({ ...item }));
    const totalHt = items.reduce((sum, item) => sum + (Number(item.quantite || 0) * Number(item.prix_achat_ht || 0)), 0);
    return {
        id: 'supplier-return-draft',
        numero: document.getElementById('supplier-return-number')?.value || generateLegacyPrefixedNumber('RTF'),
        supplier_id: supplierId,
        supplier_name: supplier?.nom || supplier?.name || document.getElementById('supplier-return-supplier-search')?.value || '',
        date: document.getElementById('supplier-return-date')?.value || new Date().toISOString().split('T')[0],
        supplier_bl_number: (document.getElementById('supplier-return-bl-number')?.value || '').trim(),
        note: (document.getElementById('supplier-return-motif')?.value || '').trim(),
        total_ht: roundMoneyValue(totalHt),
        items,
        created_at: new Date().toISOString()
    };
}

