async function persistSupplierReturnRecord(record) {
    try {
        const response = await fetch(`${supabaseUrl}supplier_returns`, {
            method: 'POST',
            headers: { ...supabaseHeaders, Prefer: 'return=representation' },
            body: JSON.stringify({
                return_number: record.numero,
                supplier_id: record.supplier_id || null,
                return_date: record.date,
                note: record.note || null,
                total_ht: record.total_ht
            })
        });
        if (!response.ok) {
            const errorText = await response.text();
            throw new Error(errorText || `HTTP ${response.status}`);
        }
        const savedRows = await response.json();
        const saved = Array.isArray(savedRows) ? savedRows[0] : savedRows;
        const returnId = saved?.id;
        if (returnId && record.items.length) {
            const itemResponse = await fetch(`${supabaseUrl}supplier_return_items`, {
                method: 'POST',
                headers: supabaseHeaders,
                body: JSON.stringify(record.items.map(item => ({
                    supplier_return_id: returnId,
                    product_id: item.product_id,
                    quantite: item.quantite,
                    prix_achat_ht: item.prix_achat_ht
                })))
            });
            if (!itemResponse.ok) {
                const errorText = await itemResponse.text();
                throw new Error(errorText || `HTTP ${itemResponse.status}`);
            }
        }
        return { ...record, id: returnId || record.id };
    } catch (error) {
        console.warn('Ecriture Supabase retour fournisseur indisponible, repli local.', error);
        const rows = getStoredSupplierReturns();
        saveStoredSupplierReturns([{ ...record, localOnly: true }, ...rows]);
        return { ...record, localOnly: true };
    }
}

async function persistSupplierReturnStockMovements(record) {
    const currentUser = getCurrentBackofficeUser();
    const localRecords = getStockOperationRecords();
    const nextLocalRecords = [];
    for (const [index, item] of record.items.entries()) {
        const movement = normalizeStockOperationRecord({
            id: buildStockOperationId('RF'),
            numero: `${record.numero}-${index + 1}`,
            moduleId: 'retour_fournisseur',
            type: 'RETOUR_FOURNISSEUR',
            product_id: item.product_id,
            code_article: item.code_article,
            designation: item.designation,
            partner: record.supplier_name || '',
            note: record.note || '',
            quantity: item.quantite,
            stock_effect: -Number(item.quantite || 0),
            date: `${record.date}T00:00:00`
        });
        try {
            const response = await fetch(`${supabaseUrl}stock_operations`, {
                method: 'POST',
                headers: { ...supabaseHeaders, Prefer: 'return=representation' },
                body: JSON.stringify({
                    operation_number: movement.numero,
                    module_id: movement.moduleId,
                    movement_type: movement.type,
                    product_id: movement.product_id,
                    product_code: movement.code_article || '',
                    product_designation: movement.designation || '',
                    partner_name: movement.partner || null,
                    note: movement.note || null,
                    quantity: movement.quantity,
                    stock_effect: movement.stock_effect,
                    operation_date: record.date,
                    created_by: currentUser ? (currentUser.fullName || currentUser.username || '') : null
                })
            });
            if (!response.ok) throw new Error(await response.text() || `HTTP ${response.status}`);
            const savedRows = await response.json();
            nextLocalRecords.push(normalizeStockOperationRecord(Array.isArray(savedRows) ? savedRows[0] : savedRows) || movement);
        } catch (error) {
            console.warn('Ecriture mouvement retour fournisseur indisponible, repli local.', error);
            nextLocalRecords.push(movement);
        }
    }
    saveStockOperationRecords([...nextLocalRecords, ...localRecords]);
}

function updateSupplierReturnSaveState(isSaving) {
    supplierReturnState.isSaving = Boolean(isSaving);
    const button = document.getElementById('supplier-return-save-btn');
    if (!button) return;
    button.disabled = supplierReturnState.isSaving;
    button.innerText = supplierReturnState.isSaving ? 'Validation...' : 'Valider retour';
}

async function saveSupplierReturn() {
    if (supplierReturnState.isSaving) return;
    let supplierId = document.getElementById('supplier-return-supplier')?.value || supplierReturnState.selectedSupplierId || '';
    if (!supplierId) {
        const supplierSearch = document.getElementById('supplier-return-supplier-search')?.value || '';
        const supplier = findSupplierReturnSupplier(supplierSearch);
        if (supplier) {
            selectSupplierReturnSupplierById(supplier.id);
            supplierId = supplier.id;
        }
    }
    const supplier = supplierReturnState.suppliers.find(item => String(item.id) === String(supplierId));
    const date = document.getElementById('supplier-return-date')?.value || new Date().toISOString().split('T')[0];
    const supplierBlNumber = (document.getElementById('supplier-return-bl-number')?.value || '').trim();
    const motif = (document.getElementById('supplier-return-motif')?.value || '').trim();
    if (!supplierId) {
        alert('Selectionnez un fournisseur.');
        return;
    }
    if (!supplierReturnState.items.length) {
        alert('Ajoutez au moins un article au retour fournisseur.');
        return;
    }
    const invalidLine = supplierReturnState.items.find(item => Number(item.quantite || 0) <= 0 || Number(item.quantite || 0) > Number(item.stock_actuel || 0));
    if (invalidLine) {
        alert(`Quantite retour invalide pour ${invalidLine.designation || invalidLine.code_article || 'article'}.`);
        return;
    }
    if (!confirm('Valider le retour fournisseur et deduire le stock des articles ?')) return;

    updateSupplierReturnSaveState(true);
    try {
        const productIds = supplierReturnState.items.map(item => item.product_id).filter(Boolean);
        const liveProducts = await fetchCollection(`products?select=id,stock_actuel&id=in.(${productIds.join(',')})`, []);
        const liveById = new Map((Array.isArray(liveProducts) ? liveProducts : []).map(item => [String(item.id), item]));
        const stockUpdates = supplierReturnState.items.map(item => {
            const liveProduct = liveById.get(String(item.product_id));
            const currentStock = Number(liveProduct?.stock_actuel ?? item.stock_actuel ?? 0);
            const nextStock = currentStock - Number(item.quantite || 0);
            if (nextStock < 0) {
                throw new Error(`Stock insuffisant pour ${item.designation || item.code_article}. Disponible: ${formatMoney(currentStock)}.`);
            }
            return { id: item.product_id, stock_actuel: nextStock };
        });

        await Promise.all(stockUpdates.map(item => fetch(`${supabaseUrl}products?id=eq.${encodeURIComponent(item.id)}`, {
            method: 'PATCH',
            headers: supabaseHeaders,
            body: JSON.stringify({ stock_actuel: item.stock_actuel })
        }).then(async response => {
            if (!response.ok) throw new Error(await response.text() || `HTTP ${response.status}`);
        })));

        updateCachedProductsLocally(stockUpdates);
        supplierReturnState.products = supplierReturnState.products.map(product => {
            const update = stockUpdates.find(item => String(item.id) === String(product.id));
            return update ? { ...product, stock_actuel: update.stock_actuel } : product;
        });

        const itemsSnapshot = supplierReturnState.items.map(item => ({ ...item }));
        const totalHt = itemsSnapshot.reduce((sum, item) => sum + (Number(item.quantite || 0) * Number(item.prix_achat_ht || 0)), 0);
        const record = {
            id: generateLegacyPrefixedNumber('RTFLOCAL'),
            numero: await requestSequentialNumber('RTF', () => generateLegacyPrefixedNumber('RTF')),
            supplier_id: supplierId,
            supplier_name: supplier?.nom || '',
            date,
            supplier_bl_number: supplierBlNumber,
            note: motif,
            total_ht: roundMoneyValue(totalHt),
            items: itemsSnapshot,
            created_at: new Date().toISOString()
        };

        const savedRecord = await persistSupplierReturnRecord(record);
        rememberSupplierReturnRecord(savedRecord || record);
        await persistSupplierReturnStockMovements(record);
        showSuccessToast(`Retour fournisseur enregistre. Numero ${record.numero}.`);
        resetSupplierReturnForm({ keepSupplier: true });
        refreshProductsCacheInBackground('retour-fournisseur');
    } catch (error) {
        console.error('Erreur retour fournisseur:', error);
        alert(`Impossible de valider le retour fournisseur.\n\nDetail: ${getSupabaseErrorMessage(error)}`);
    } finally {
        updateSupplierReturnSaveState(false);
    }
}

async function refreshSuppliersCache() {
    const suppliers = await fetchCollection('suppliers?select=id,nom,telephone,matricule_fiscale&order=nom');
    purchaseState.suppliers = suppliers;
    allSuppliers = suppliers;
    return suppliers;
}

