async function getPurchasesReportsBundle(startDate = null, endDate = null, purchaseId = null) {
    startDate = startDate ? String(startDate).slice(0, 10) : null;
    endDate = endDate ? String(endDate).slice(0, 10) : null;
    const rpcPayload = {};
    if (startDate) rpcPayload.p_start_date = startDate;
    if (endDate) rpcPayload.p_end_date = endDate;
    if (purchaseId) rpcPayload.p_purchase_id = purchaseId;
    let rpcBundle = null;
    try {
        const controller = new AbortController();
        const rpcTimeout = setTimeout(() => controller.abort(), 30000);
        const rpcResponse = await fetch(`${supabaseUrl}rpc/get_purchases_reports_bundle`, {
            method: 'POST',
            headers: supabaseHeaders,
            body: JSON.stringify(rpcPayload || {}),
            signal: controller.signal
        });
        clearTimeout(rpcTimeout);
        if (rpcResponse.ok) {
            rpcBundle = await rpcResponse.json();
        }
    } catch (rpcError) {
        console.warn('RPC get_purchases_reports_bundle indisponible, fallback REST.', rpcError);
    }

    if (rpcBundle && Array.isArray(rpcBundle.purchases)) {
        return rpcBundle;
    }

    let purchases = [];
    let purchaseItems = [];
    let products = [];
    let suppliers = [];
    try {
        const purchaseRes = await fetch(`${supabaseUrl}purchases?select=*,suppliers(id,nom,telephone)&order=date_achat.desc&limit=500`, { headers: supabaseHeaders });
        if (purchaseRes.ok) {
            purchases = await purchaseRes.json();
            if (!Array.isArray(purchases)) purchases = [];
        }
    } catch (fetchErr) {
        console.warn('Erreur chargement achats:', fetchErr);
    }
    if (startDate) purchases = purchases.filter(p => String(p.date_achat || '').slice(0, 10) >= startDate);
    if (endDate) purchases = purchases.filter(p => String(p.date_achat || '').slice(0, 10) <= endDate);
    if (purchaseId) purchases = purchases.filter(p => String(p.id) === String(purchaseId));

    const purchaseIds = purchases.map(p => p.id).filter(Boolean);
    if (purchaseIds.length > 0) {
        try {
            const itemsRes = await fetch(`${supabaseUrl}purchase_items?select=*,products(id,code_article,designation,forme,tva,stock_actuel,prix_vente_ttc,prix_vente_web_ttc,prix_vente_passager_ttc,marge,remise_web_pct,code_pct)&purchase_id=in.(${purchaseIds.map(id => encodeURIComponent(id)).join(',')})&order=created_at.asc`, { headers: supabaseHeaders });
            if (itemsRes.ok) {
                purchaseItems = await itemsRes.json();
                if (!Array.isArray(purchaseItems)) purchaseItems = [];
            }
        } catch (itemsErr) {
            console.warn('Erreur chargement lignes achats:', itemsErr);
        }
    }
    const productIds = [...new Set(purchaseItems.map(i => i.product_id).filter(Boolean))];
    if (productIds.length > 0) {
        try {
            const prodRes = await fetch(`${supabaseUrl}products?select=id,code_article,designation,forme,tva,stock_actuel,prix_vente_ttc,prix_vente_web_ttc,prix_vente_passager_ttc,marge,remise_web_pct,code_pct&id=in.(${productIds.map(id => encodeURIComponent(id)).join(',')})`, { headers: supabaseHeaders });
            if (prodRes.ok) {
                products = await prodRes.json();
                if (!Array.isArray(products)) products = [];
            }
        } catch (prodErr) {
            console.warn('Erreur chargement produits:', prodErr);
        }
    }
    const supplierIds = [...new Set(purchases.map(p => p.supplier_id).filter(Boolean))];
    if (supplierIds.length > 0) {
        try {
            const suppRes = await fetch(`${supabaseUrl}suppliers?select=id,nom,telephone&id=in.(${supplierIds.map(id => encodeURIComponent(id)).join(',')})`, { headers: supabaseHeaders });
            if (suppRes.ok) {
                suppliers = await suppRes.json();
                if (!Array.isArray(suppliers)) suppliers = [];
            }
        } catch (suppErr) {
            console.warn('Erreur chargement fournisseurs:', suppErr);
        }
    }

    return { purchases, purchaseItems, products, suppliers };
}

async function getPurchasesDetailed(startDate = null, endDate = null, purchaseId = null) {
    const { purchases, purchaseItems, products } = await getPurchasesReportsBundle(startDate, endDate, purchaseId);

    const productsById = new Map(products.map(product => [String(product.id || ''), product]));
    const itemsByPurchaseId = purchaseItems.reduce((acc, item) => {
        const enrichedItem = {
            ...item,
            products: item.products || productsById.get(String(item.product_id || '')) || null
        };
        if (!acc[item.purchase_id]) acc[item.purchase_id] = [];
        acc[item.purchase_id].push(enrichedItem);
        return acc;
    }, {});

    return purchases.map(purchase => {
        const items = itemsByPurchaseId[purchase.id] || [];
        return items.reduce((acc, item) => {
            const qty = Number(item.quantite || 0);
            const freeQty = Number(item.quantite_gratuite || 0);
            const amounts = computePurchaseLineAmounts({
                quantite: qty,
                prix_achat_ht: Number(item.prix_achat_ht || 0),
                remise: Number(item.remise || 0),
                tva: Number(item.products?.tva || 0),
                fodec_pct: Number(item.fodec_pct || 0)
            });
            const tvaPct = Number(item.products?.tva || 0);
            const salePrice = Number(item.products?.prix_vente_ttc || 0);

            acc.totalHt += amounts.grossHt;
            acc.totalRemise += amounts.remiseAmount;
            acc.totalFodec += amounts.fodecAmount;
            acc.totalTva += amounts.tvaAmount;
            acc.totalTtc += amounts.totalTtc;
            acc.saleValue += (qty + freeQty) * salePrice;
            acc.saleTva += (qty + freeQty) * salePrice * tvaPct / (100 + tvaPct || 1);
            return acc;
        }, {
            ...purchase,
            totalHt: 0,
            totalRemise: 0,
            totalFodec: 0,
            totalTva: 0,
            totalTtc: 0,
            saleValue: 0,
            saleTva: 0,
            detailItems: items
        });
    }).map(item => ({
        ...item,
        totalTtc: item.totalTtc || Number(item.total_ttc || 0)
    }));
}

async function initPurchaseHistoryModule() {
    const suppliers = purchaseState.suppliers.length > 0 ? purchaseState.suppliers : await fetchCollection('suppliers?select=id,nom&order=nom');
    purchaseState.suppliers = suppliers;
    const select = document.getElementById('purchase-history-supplier');
    if (select) {
        select.innerHTML = [
            '<option value="">Tous les fournisseurs</option>',
            ...suppliers.map(supplier => `<option value="${supplier.id}">${escapeHtml(supplier.nom)}</option>`)
        ].join('');
    }
    await loadPurchaseHistory();
}

async function loadPurchaseHistory() {
    const tbody = document.getElementById('purchase-history-body');
    if (!tbody) return;

    const filtered = await getFilteredPurchaseHistoryRows();
    const grouping = document.getElementById('purchase-history-grouping')?.value || 'none';

    if (filtered.length === 0) {
        tbody.innerHTML = '<tr><td colspan="12" style="text-align:center; padding:24px;">Aucun achat trouve.</td></tr>';
    } else {
        tbody.innerHTML = renderPurchaseHistoryRows(filtered, grouping);
    }

    const summary = filtered.reduce((acc, item) => {
        acc.count += 1;
        acc.totalHt += item.totalHt;
        acc.totalRemise += item.totalRemise;
        acc.totalFodec += Number(item.totalFodec || item.total_fodec || 0);
        acc.totalTva += item.totalTva;
        acc.totalTtc += item.totalTtc;
        acc.saleValue += item.saleValue;
        acc.saleTva += item.saleTva;
        return acc;
    }, { count: 0, totalHt: 0, totalRemise: 0, totalFodec: 0, totalTva: 0, totalTtc: 0, saleValue: 0, saleTva: 0 });

    const summaryMapping = {
        'purchase-history-count': summary.count,
        'purchase-history-total-ht': formatMoney(summary.totalHt),
        'purchase-history-total-remise': formatMoney(summary.totalRemise),
        'purchase-history-total-tva': formatMoney(summary.totalTva),
        'purchase-history-total-ttc': formatMoney(summary.totalTtc),
        'purchase-history-sale-value': formatMoney(summary.saleValue),
        'purchase-history-sale-tva': formatMoney(summary.saleTva)
    };

    Object.entries(summaryMapping).forEach(([id, value]) => {
        const element = document.getElementById(id);
        if (element) element.value = String(value);
    });
}

async function getFilteredPurchaseHistoryRows() {
    const supplierId = document.getElementById('purchase-history-supplier')?.value || '';
    const from = document.getElementById('purchase-history-from')?.value || '';
    const to = document.getElementById('purchase-history-to')?.value || '';
    const filterType = document.querySelector('input[name="purchase_history_filter_type"]:checked')?.value || 'date_achat';
    const allPurchases = await getPurchasesDetailed(from || null, to || null);

    return allPurchases
        .filter(item => {
            if (supplierId && item.supplier_id !== supplierId) return false;
            const referenceDate = String(filterType === 'created_at' ? item.created_at : item.date_achat || '').split('T')[0];
            if (from && referenceDate && referenceDate < from) return false;
            if (to && referenceDate && referenceDate > to) return false;
            return true;
        })
        .sort((a, b) => {
            const dateGap = new Date(b.date_achat || b.created_at || 0) - new Date(a.date_achat || a.created_at || 0);
            if (dateGap !== 0) return dateGap;
            const createdGap = new Date(b.created_at || 0) - new Date(a.created_at || 0);
            if (createdGap !== 0) return createdGap;
            return parsePrefixedSequentialNumber(b.numero_achat, 'ACH') - parsePrefixedSequentialNumber(a.numero_achat, 'ACH');
        });
}

function renderPurchaseHistoryDataRow(item) {
    return `
        <tr onclick="showPurchaseHistoryDetail('${item.id}')" style="cursor:pointer;">
            <td>${escapeHtml(item.numero_achat || '-')}</td>
            <td>${item.created_at ? new Date(item.created_at).toLocaleDateString('fr-FR') : '-'}</td>
            <td>${item.date_achat ? new Date(item.date_achat).toLocaleDateString('fr-FR') : '-'}</td>
            <td>${escapeHtml(item.suppliers?.nom || '-')}</td>
            <td>${escapeHtml(item.num_bl_fact || '-')}</td>
            <td>${escapeHtml(item.created_by || '-')}</td>
            <td style="text-align:right;">${formatMoney(item.totalHt)}</td>
            <td style="text-align:right;">${formatMoney(item.totalRemise)}</td>
            <td style="text-align:right;">${formatMoney(item.totalTva)}</td>
            <td style="text-align:right; font-weight:600;">${formatMoney(item.totalTtc)}</td>
            <td style="text-align:right;">${formatMoney(item.saleValue)}</td>
            <td style="text-align:right;">${formatMoney(item.saleTva)}</td>
        </tr>
    `;
}

function renderPurchaseHistoryRows(rows, grouping = 'none') {
    if (grouping === 'none') {
        return rows.map(renderPurchaseHistoryDataRow).join('');
    }

    const groupedMap = new Map();
    rows.forEach(item => {
        const key = item.suppliers?.nom || 'Sans fournisseur';
        if (!groupedMap.has(key)) {
            groupedMap.set(key, []);
        }
        groupedMap.get(key).push(item);
    });

    return Array.from(groupedMap.entries()).map(([groupLabel, groupRows]) => {
        const subtotal = groupRows.reduce((acc, item) => {
            acc.ht += Number(item.totalHt || 0);
            acc.remise += Number(item.totalRemise || 0);
            acc.tva += Number(item.totalTva || 0);
            acc.ttc += Number(item.totalTtc || 0);
            acc.saleValue += Number(item.saleValue || 0);
            acc.saleTva += Number(item.saleTva || 0);
            return acc;
        }, { ht: 0, remise: 0, tva: 0, ttc: 0, saleValue: 0, saleTva: 0 });

        return `
            <tr class="statement-group-row">
                <td colspan="12" style="background:#dbeafe; color:#1e3a8a; font-weight:800;">${escapeHtml(groupLabel)} (${groupRows.length})</td>
            </tr>
            ${groupRows.map(renderPurchaseHistoryDataRow).join('')}
            <tr class="statement-subtotal-row">
                <td colspan="6" style="text-align:right; font-weight:800; background:#eff6ff;">Sous-total</td>
                <td style="text-align:right; font-weight:800; background:#eff6ff;">${formatMoney(subtotal.ht)}</td>
                <td style="text-align:right; font-weight:800; background:#eff6ff;">${formatMoney(subtotal.remise)}</td>
                <td style="text-align:right; font-weight:800; background:#eff6ff;">${formatMoney(subtotal.tva)}</td>
                <td style="text-align:right; font-weight:800; background:#eff6ff;">${formatMoney(subtotal.ttc)}</td>
                <td style="text-align:right; font-weight:800; background:#eff6ff;">${formatMoney(subtotal.saleValue)}</td>
                <td style="text-align:right; font-weight:800; background:#eff6ff;">${formatMoney(subtotal.saleTva)}</td>
            </tr>
        `;
    }).join('');
}

async function initPurchaseMovementModule() {
    const suppliers = purchaseState.suppliers.length > 0 ? purchaseState.suppliers : await fetchCollection('suppliers?select=id,nom&order=nom');
    purchaseState.suppliers = suppliers;
    const select = document.getElementById('supplier-movement-filter');
    if (select) {
        select.innerHTML = [
            '<option value="">Tous les fournisseurs</option>',
            ...suppliers.map(supplier => `<option value="${supplier.id}">${escapeHtml(supplier.nom)}</option>`)
        ].join('');
    }
    await loadSupplierMovements();
}

async function initPurchaseFreeHistoryModule() {
    const suppliers = purchaseState.suppliers.length > 0 ? purchaseState.suppliers : await fetchCollection('suppliers?select=id,nom&order=nom');
    purchaseState.suppliers = suppliers;

    const select = document.getElementById('purchase-free-history-supplier');
    if (select) {
        select.innerHTML = [
            '<option value="">Tous les fournisseurs</option>',
            ...suppliers.map(supplier => `<option value="${supplier.id}">${escapeHtml(supplier.nom)}</option>`)
        ].join('');
    }

    await loadPurchaseFreeHistory();
}

async function getFilteredPurchaseFreeHistoryRows() {
    const from = document.getElementById('purchase-free-history-from')?.value || '';
    const to = document.getElementById('purchase-free-history-to')?.value || '';
    const supplierId = document.getElementById('purchase-free-history-supplier')?.value || '';
    const purchases = await getPurchasesDetailed(from || null, to || null);

    return purchases
        .map(item => {
            const freeItems = (item.detailItems || []).filter(line => Number(line.quantite_gratuite || 0) > 0);
            const freeLinesCount = freeItems.length;
            const totalFreeQty = freeItems.reduce((sum, line) => sum + Number(line.quantite_gratuite || 0), 0);
            const totalReceivedQty = freeItems.reduce((sum, line) => sum + Number(line.quantite || 0) + Number(line.quantite_gratuite || 0), 0);

            return {
                ...item,
                freeItems,
                freeLinesCount,
                totalFreeQty,
                totalReceivedQty
            };
        })
        .filter(item => item.freeLinesCount > 0)
        .filter(item => !supplierId || String(item.supplier_id || '') === String(supplierId))
        .filter(item => {
            const purchaseDate = String(item.date_achat || item.created_at || '').split('T')[0];
            if (from && purchaseDate && purchaseDate < from) return false;
            if (to && purchaseDate && purchaseDate > to) return false;
            return true;
        })
        .sort((a, b) => new Date(b.date_achat || b.created_at || 0) - new Date(a.date_achat || a.created_at || 0));
}

function renderPurchaseFreeHistoryRows(rows = []) {
    return rows.map(item => `
        <tr onclick="showPurchaseFreeHistoryDetail('${item.id}')" style="cursor:pointer;">
            <td>${item.date_achat ? new Date(item.date_achat).toLocaleDateString('fr-FR') : '-'}</td>
            <td>${escapeHtml(item.numero_achat || '-')}</td>
            <td>${escapeHtml(item.suppliers?.nom || '-')}</td>
            <td style="text-align:right;">${Number(item.freeLinesCount || 0)}</td>
            <td style="text-align:right; font-weight:700; color:#0f766e;">${formatMoney(item.totalFreeQty || 0)}</td>
            <td style="text-align:right;">${formatMoney(item.totalReceivedQty || 0)}</td>
        </tr>
    `).join('');
}

async function loadPurchaseFreeHistory() {
    const tbody = document.getElementById('purchase-free-history-body');
    if (!tbody) return;

    const rows = await getFilteredPurchaseFreeHistoryRows();
    if (rows.length === 0) {
        tbody.innerHTML = '<tr><td colspan="6" style="text-align:center; padding:24px;">Aucune gratuite trouvee.</td></tr>';
    } else {
        tbody.innerHTML = renderPurchaseFreeHistoryRows(rows);
    }

    const summary = rows.reduce((acc, item) => {
        acc.count += 1;
        acc.lines += Number(item.freeLinesCount || 0);
        acc.totalFree += Number(item.totalFreeQty || 0);
        acc.totalReceived += Number(item.totalReceivedQty || 0);
        return acc;
    }, { count: 0, lines: 0, totalFree: 0, totalReceived: 0 });

    const summaryMap = {
        'purchase-free-history-count': summary.count,
        'purchase-free-history-lines': summary.lines,
        'purchase-free-history-total-free': formatMoney(summary.totalFree),
        'purchase-free-history-total-received': formatMoney(summary.totalReceived)
    };

    Object.entries(summaryMap).forEach(([id, value]) => {
        const element = document.getElementById(id);
        if (element) element.innerText = String(value);
    });
}

