function closePurchaseFreeHistoryDetail() {
    const modal = document.getElementById('purchase-free-history-detail-modal');
    if (modal) modal.style.display = 'none';
}

async function loadSupplierMovements() {
    const tbody = document.getElementById('supplier-movement-body');
    if (!tbody) return;

    const filtered = await getFilteredSupplierMovementsRows();
    const grouping = document.getElementById('supplier-movement-grouping')?.value || 'none';
    let totalDebit = 0;
    const totalCredit = 0;

    if (filtered.length === 0) {
        tbody.innerHTML = '<tr><td colspan="7" style="text-align:center; padding:24px;">Aucun mouvement trouve.</td></tr>';
    } else {
        tbody.innerHTML = renderSupplierMovementRows(filtered, grouping);
        totalDebit = filtered.reduce((acc, item) => acc + Number(item.totalTtc || 0), 0);
    }

    const runningBalance = totalDebit - totalCredit;
    document.getElementById('supplier-total-debit').innerText = `${formatMoney(totalDebit)} DT`;
    document.getElementById('supplier-total-credit').innerText = `${formatMoney(totalCredit)} DT`;
    document.getElementById('supplier-balance').innerText = `${formatMoney(runningBalance)} DT`;
}

async function getFilteredSupplierMovementsRows() {
    const from = document.getElementById('supplier-movement-from')?.value || '';
    const to = document.getElementById('supplier-movement-to')?.value || '';
    const supplierId = document.getElementById('supplier-movement-filter')?.value || '';
    const purchases = await getPurchasesDetailed(from || null, to || null);

    return purchases
        .filter(item => !supplierId || item.supplier_id === supplierId)
        .filter(item => {
            const purchaseDate = String(item.date_achat || '').split('T')[0];
            if (from && purchaseDate && purchaseDate < from) return false;
            if (to && purchaseDate && purchaseDate > to) return false;
            return true;
        })
        .sort((a, b) => new Date(a.date_achat || a.created_at || 0) - new Date(b.date_achat || b.created_at || 0));
}

function renderSupplierMovementDataRow(item, runningBalance) {
    const debit = Number(item.totalTtc || 0);
    return `
        <tr onclick="showSupplierMovementDetail('${item.id}')" style="cursor:pointer;">
            <td>${item.date_achat ? new Date(item.date_achat).toLocaleDateString('fr-FR') : '-'}</td>
            <td>${escapeHtml(item.numero_achat || '-')}</td>
            <td>${escapeHtml(item.suppliers?.nom || '-')}</td>
            <td>${escapeHtml(item.num_bl_fact || '-')}</td>
            <td style="text-align:right;">${formatMoney(debit)}</td>
            <td style="text-align:right;">${formatMoney(0)}</td>
            <td style="text-align:right; font-weight:600;">${formatMoney(runningBalance)}</td>
        </tr>
    `;
}

function renderSupplierMovementRows(rows, grouping = 'none') {
    if (grouping === 'none') {
        let runningBalance = 0;
        return rows.map(item => {
            runningBalance += Number(item.totalTtc || 0);
            return renderSupplierMovementDataRow(item, runningBalance);
        }).join('');
    }

    const groupedMap = new Map();
    rows.forEach(item => {
        const key = item.suppliers?.nom || 'Sans fournisseur';
        if (!groupedMap.has(key)) {
            groupedMap.set(key, []);
        }
        groupedMap.get(key).push(item);
    });

    return Array.from(groupedMap.entries()).map(([groupLabel, groupRows]) => {
        let runningBalance = 0;
        const subtotalDebit = groupRows.reduce((acc, item) => acc + Number(item.totalTtc || 0), 0);

        return `
            <tr class="statement-group-row">
                <td colspan="7" style="background:#dbeafe; color:#1e3a8a; font-weight:800;">${escapeHtml(groupLabel)} (${groupRows.length})</td>
            </tr>
            ${groupRows.map(item => {
            runningBalance += Number(item.totalTtc || 0);
            return renderSupplierMovementDataRow(item, runningBalance);
        }).join('')}
            <tr class="statement-subtotal-row">
                <td colspan="4" style="text-align:right; font-weight:800; background:#eff6ff;">Sous-total</td>
                <td style="text-align:right; font-weight:800; background:#eff6ff;">${formatMoney(subtotalDebit)}</td>
                <td style="text-align:right; font-weight:800; background:#eff6ff;">0.000</td>
                <td style="text-align:right; font-weight:800; background:#eff6ff;">${formatMoney(subtotalDebit)}</td>
            </tr>
        `;
    }).join('');
}

async function exportPurchaseHistoryToExcel() {
    try {
        if (typeof XLSX === 'undefined') throw new Error('La librairie XLSX n est pas chargee.');
        const rows = await getFilteredPurchaseHistoryRows();
        if (rows.length === 0) {
            alert('Aucune donnee a exporter.');
            return;
        }

        const exportRows = rows.map(item => ({
            Numero: item.numero_achat || '',
            DateSaisie: item.created_at ? new Date(item.created_at).toLocaleDateString('fr-FR') : '',
            DateFacture: item.date_achat ? new Date(item.date_achat).toLocaleDateString('fr-FR') : '',
            Fournisseur: item.suppliers?.nom || '',
            NFacture: item.num_bl_fact || '',
            TotalHT: Number(formatMoney(item.totalHt)),
            Remise: Number(formatMoney(item.totalRemise)),
            TVA: Number(formatMoney(item.totalTva)),
            TotalTTC: Number(formatMoney(item.totalTtc)),
            ValeurVenteTTC: Number(formatMoney(item.saleValue)),
            TotalTVAVente: Number(formatMoney(item.saleTva))
        }));

        const workbook = XLSX.utils.book_new();
        const worksheet = XLSX.utils.json_to_sheet(exportRows);
        XLSX.utils.book_append_sheet(workbook, worksheet, 'Historique Achats');
        XLSX.writeFile(workbook, `historique-achats-${new Date().toISOString().split('T')[0]}.xlsx`);
    } catch (error) {
        console.error('Erreur export historique achats:', error);
        alert(`Export impossible: ${error.message}`);
    }
}

async function exportPurchaseHistoryToPdf() {
    const rows = await getFilteredPurchaseHistoryRows();
    if (rows.length === 0) {
        alert('Aucune donnee a exporter en PDF.');
        return;
    }
    const grouping = document.getElementById('purchase-history-grouping')?.value || 'none';
    const body = buildPurchaseHistoryPrintDocument(rows, grouping);
    const printWindow = openReportPrintWindow('Historique achats PDF', body);
    if (!printWindow) return;
    printWindow.print();
}

async function printPurchaseHistory() {
    const rows = await getFilteredPurchaseHistoryRows();
    if (rows.length === 0) {
        alert('Aucune donnee a imprimer.');
        return;
    }
    const grouping = document.getElementById('purchase-history-grouping')?.value || 'none';
    const printWindow = openReportPrintWindow('Historique achats', buildPurchaseHistoryPrintDocument(rows, grouping));
    if (!printWindow) return;
    printWindow.print();
}

function buildPurchaseHistoryPrintDocument(rows, grouping = 'none') {
    const summary = rows.reduce((acc, item) => {
        acc.count += 1;
        acc.totalHt += item.totalHt;
        acc.totalRemise += item.totalRemise;
        acc.totalTva += item.totalTva;
        acc.totalTtc += item.totalTtc;
        return acc;
    }, { count: 0, totalHt: 0, totalRemise: 0, totalTva: 0, totalTtc: 0 });

    return `
        <h1>Historique achats</h1>
        <p>Achats: ${summary.count} | Total HT: ${formatMoney(summary.totalHt)} | TVA: ${formatMoney(summary.totalTva)} | Total TTC: ${formatMoney(summary.totalTtc)}</p>
        <table>
            <thead>
                <tr>
                    <th>Numero</th>
                    <th>Date Saisie</th>
                    <th>Date Facture</th>
                    <th>Fournisseur</th>
                    <th>N Facture</th>
                    <th>Total HT</th>
                    <th>Remise</th>
                    <th>TVA</th>
                    <th>Total TTC</th>
                    <th>Valeur Vente TTC</th>
                    <th>Total TVA Vente</th>
                </tr>
            </thead>
            <tbody>
                ${renderPurchaseHistoryRows(rows, grouping)}
            </tbody>
        </table>
    `;
}

