async function initSalesJournalModule() {
    if (!Array.isArray(saleState.customers) || saleState.customers.length === 0) {
        saleState.customers = await fetchCollection('customers?select=id,nom,telephone,solde,en_cours,reste_a_payer&order=nom');
    }

    const customerSelect = document.getElementById('sales-journal-customer');
    if (customerSelect) {
        customerSelect.innerHTML = [
            '<option value="">Tous les clients</option>',
            ...saleState.customers.map(customer => `<option value="${customer.id}">${escapeHtml(customer.nom)}</option>`)
        ].join('');
    }

    await loadSalesJournal();
}

async function getSalesJournalRows(startDate = null, endDate = null, saleId = null) {
    return (await getSalesTaxReportRows(startDate, endDate, saleId)).map(item => ({
        ...item,
        totalHt: Number(item.totalHt || item.total_ht || 0),
        totalTva: Number(item.totalTva || item.total_tva || 0),
        totalTtc: Number(item.totalTtc || item.total_ttc || 0),
        mode: item.mode || inferSaleMode(item),
        customerType: getCustomerTypeKey(item),
        customerTypeLabel: getCustomerTypeLabel(item)
    }));
}

async function getSalesJournalFilteredRows() {
    const customerId = document.getElementById('sales-journal-customer')?.value || '';
    const mode = document.getElementById('sales-journal-mode')?.value || '';
    const customerType = document.getElementById('sales-journal-customer-type')?.value || '';
    const from = document.getElementById('sales-journal-from')?.value || '';
    const to = document.getElementById('sales-journal-to')?.value || '';

    return (await getSalesJournalRows(from || null, to || null))
        .filter(item => matchesReportCustomer(item, customerId))
        .filter(item => matchesReportMode(item, mode))
        .filter(item => matchesReportCustomerType(item, customerType))
        .filter(item => matchesReportDateRange(item, from, to));
}

async function getVisibleSalesJournalFilteredRows() {
    return (await getSalesJournalFilteredRows()).filter(item => !isSalesJournalRowHidden(item));
}

async function getHiddenSalesJournalFilteredRows() {
    return (await getSalesJournalFilteredRows()).filter(item => isSalesJournalRowHidden(item));
}

async function loadSalesJournal() {
    const tbody = document.getElementById('sales-journal-body');
    if (!tbody) return;

    const rows = await getVisibleSalesJournalFilteredRows();
    const grouping = document.getElementById('sales-journal-grouping')?.value || 'none';

    if (rows.length === 0) {
        tbody.innerHTML = '<tr><td colspan="11" style="text-align:center; padding:40px;">Aucune vente pour ces criteres.</td></tr>';
    } else {
        tbody.innerHTML = renderSalesJournalRows(rows, grouping);
    }

    const totals = rows.reduce((acc, item) => {
        acc.count += 1;
        acc.ht += item.totalHt;
        acc.tva += item.totalTva;
        acc.ttc += item.totalTtc;
        return acc;
    }, { count: 0, ht: 0, tva: 0, ttc: 0 });

    document.getElementById('sales-journal-count').innerText = String(totals.count);
    document.getElementById('sales-journal-total-ht').innerText = `${formatMoney(totals.ht)} DT`;
    document.getElementById('sales-journal-total-tva').innerText = `${formatMoney(totals.tva)} DT`;
    document.getElementById('sales-journal-total-ttc').innerText = `${formatMoney(totals.ttc)} DT`;
}

function renderSalesJournalRows(rows, grouping = 'none') {
    return getSalesJournalDailyRows(rows).map(renderSalesJournalDataRow).join('');
}

function getSalesJournalDailyRows(rows) {
    const groupedMap = new Map();

    rows.forEach(item => {
        const dayKey = getLocalDateKey(item.date_vente);
        if (!dayKey) return;

        if (!groupedMap.has(dayKey)) {
            groupedMap.set(dayKey, {
                dayKey,
                dayNumber: Number(String(dayKey).split('-')[2] || 0),
                tax: {
                    exonore: 0,
                    base7: 0,
                    tva7: 0,
                    base13: 0,
                    tva13: 0,
                    base19: 0,
                    tva19: 0
                },
                totalHt: 0,
                totalTva: 0,
                totalTtc: 0,
                salesCount: 0,
                customerNames: new Set(),
                customerTypes: new Set(),
                mutuelleNames: new Set(),
                modeLabels: new Set()
            });
        }

        const bucket = groupedMap.get(dayKey);
        bucket.tax.exonore += Number(item.tax?.exonore || 0);
        bucket.tax.base7 += Number(item.tax?.base7 || 0);
        bucket.tax.tva7 += Number(item.tax?.tva7 || 0);
        bucket.tax.base13 += Number(item.tax?.base13 || 0);
        bucket.tax.tva13 += Number(item.tax?.tva13 || 0);
        bucket.tax.base19 += Number(item.tax?.base19 || 0);
        bucket.tax.tva19 += Number(item.tax?.tva19 || 0);
        bucket.totalHt += Number(item.totalHt || 0);
        bucket.totalTva += Number(item.totalTva || 0);
        bucket.totalTtc += Number(item.totalTtc || 0);
        bucket.salesCount += 1;
        bucket.customerNames.add(item.customerName || item.customers?.nom || 'Client passager');
        bucket.customerTypes.add(item.customerTypeLabel || getCustomerTypeLabel(item));
        bucket.modeLabels.add(getModeDisplayLabel(item));
        if (item.mutuelles?.nom) {
            bucket.mutuelleNames.add(item.mutuelles.nom);
        }
    });

    return Array.from(groupedMap.values())
        .sort((a, b) => a.dayKey.localeCompare(b.dayKey))
        .map(item => ({
            ...item,
            dateLabel: new Date(`${item.dayKey}T00:00:00`).toLocaleDateString('fr-FR'),
            customerLabel: formatSalesJournalSummaryLabel(item.customerNames, 'client'),
            customerTypeLabel: formatSalesJournalSummaryLabel(item.customerTypes, 'type'),
            mutuelleLabel: item.mutuelleNames.size ? formatSalesJournalSummaryLabel(item.mutuelleNames, 'mutuelle') : '-',
            modeLabel: formatSalesJournalSummaryLabel(item.modeLabels, 'mode')
        }));
}

function formatSalesJournalSummaryLabel(values, unitLabel) {
    const list = Array.from(values || []).filter(Boolean);
    if (list.length === 0) return '-';
    if (list.length === 1) return list[0];
    if (list.length === 2) return `${list[0]} / ${list[1]}`;
    return `${list[0]} / ${list[1]} +${list.length - 2} ${unitLabel}${list.length - 2 > 1 ? 's' : ''}`;
}

function renderSalesJournalDataRow(item) {
    return `
        <tr onclick="openSalesJournalDayModal('${item.dayKey || ''}')" style="cursor:pointer;">
            <td style="text-align:center; font-weight:800;">${item.dayNumber || '-'}</td>
            <td>${escapeHtml(item.dateLabel || '-')}</td>
            <td style="text-align:center; font-weight:700;">${item.salesCount || 0}</td>
            <td>${escapeHtml(item.customerLabel || '-')}</td>
            <td>${escapeHtml(item.customerTypeLabel || '-')}</td>
            <td>${escapeHtml(item.mutuelleLabel || '-')}</td>
            <td>${escapeHtml(item.modeLabel || '-')}</td>
            <td style="text-align:right;">${formatMoney(item.totalHt)}</td>
            <td style="text-align:right;">${formatMoney(item.totalTva)}</td>
            <td style="text-align:right; font-weight:700;">${formatMoney(item.totalTtc)}</td>
            <td class="sales-journal-actions-cell" onclick="event.stopPropagation();" style="white-space:nowrap;">
                <button class="small-action-btn" type="button" onclick="openSalesJournalDayModal('${item.dayKey || ''}')">Voir ventes</button>
            </td>
        </tr>
    `;
}

function getSalesJournalPeriodLabel() {
    const from = document.getElementById('sales-journal-from')?.value || '';
    const to = document.getElementById('sales-journal-to')?.value || '';
    if (from && to) return `Periode du ${from} au ${to}`;
    if (from) return `Periode a partir du ${from}`;
    if (to) return `Periode jusqu'au ${to}`;
    return 'Toutes les periodes';
}

async function getSalesJournalDayRows(dateValue) {
    const dayKey = getLocalDateKey(dateValue);
    if (!dayKey) {
        return { dayKey: '', rows: [] };
    }

    const allVisibleRows = await getVisibleSalesJournalFilteredRows();
    const rows = allVisibleRows
        .filter(item => getLocalDateKey(item.date_vente) === dayKey)
        .map(item => ({
            ...item,
            sequenceNumber: allVisibleRows.findIndex(row => String(row.id) === String(item.id)) + 1
        }));

    return { dayKey, rows };
}

async function openSalesJournalDayModal(dateValue) {
    const modal = document.getElementById('sales-journal-day-modal');
    const titleNode = document.getElementById('sales-journal-day-modal-title');
    const subtitleNode = document.getElementById('sales-journal-day-modal-subtitle');
    const bodyNode = document.getElementById('sales-journal-day-modal-body');
    if (!modal || !titleNode || !subtitleNode || !bodyNode) return;

    const { dayKey, rows } = await getSalesJournalDayRows(dateValue);
    salesJournalDayCurrentDateKey = dayKey;
    salesJournalDaySelectionCache = new Set();

    titleNode.innerText = dayKey
        ? `Ventes du ${new Date(`${dayKey}T00:00:00`).toLocaleDateString('fr-FR')}`
        : 'Ventes du jour';
    subtitleNode.innerText = rows.length
        ? `${rows.length} vente(s) visible(s). Les ventes cochees seront masquees et exclues des exports.`
        : 'Aucune vente visible pour cette date.';

    if (!rows.length) {
        bodyNode.innerHTML = '<tr><td colspan="9" style="text-align:center; padding:24px;">Aucune vente visible pour cette date.</td></tr>';
        modal.style.display = 'block';
        return;
    }

    bodyNode.innerHTML = rows.map(item => `
        <tr>
            <td style="text-align:center;">
                <input type="checkbox" class="pos-checkbox-styled" data-sales-journal-hide-id="${escapeHtml(String(item.id || ''))}" onchange="toggleSalesJournalDaySelection('${escapeHtml(String(item.id || ''))}', this.checked)">
            </td>
            <td style="text-align:right; font-weight:700;">${item.sequenceNumber}</td>
            <td>${item.date_vente ? new Date(item.date_vente).toLocaleString('fr-FR') : '-'}</td>
            <td>${escapeHtml(item.numero_vente || item.invoiceNumber || '-')}</td>
            <td>${escapeHtml(item.customerName || item.customers?.nom || 'Client passager')}</td>
            <td>${escapeHtml(item.mutuelles?.nom || '-')}</td>
            <td>${escapeHtml(getModeDisplayLabel(item))}</td>
            <td style="text-align:right; font-weight:700;">${formatMoney(item.totalTtc)}</td>
            <td>
                <button class="small-action-btn" type="button" onclick="showSalesJournalDetail('${escapeHtml(String(item.id || ''))}'); event.stopPropagation();">Detail</button>
            </td>
        </tr>
    `).join('');

    modal.style.display = 'block';
}

function toggleSalesJournalDaySelection(saleId, checked) {
    const normalizedId = String(saleId || '').trim();
    if (!normalizedId) return;
    if (checked) {
        salesJournalDaySelectionCache.add(normalizedId);
    } else {
        salesJournalDaySelectionCache.delete(normalizedId);
    }
}

async function maskSelectedSalesJournalRows() {
    const selectedIds = Array.from(salesJournalDaySelectionCache || []).filter(Boolean);
    if (selectedIds.length === 0) {
        alert('Selectionnez au moins une vente a masquer.');
        return;
    }

    const hiddenIds = getSalesJournalHiddenIds();
    selectedIds.forEach(id => hiddenIds.add(String(id)));
    saveSalesJournalHiddenIds(hiddenIds);

    await loadSalesJournal();

    if (salesJournalDayCurrentDateKey) {
        await openSalesJournalDayModal(salesJournalDayCurrentDateKey);
    }

    alert(`${selectedIds.length} vente(s) masquee(s). Elles sont maintenant exclues du journal visible et de l export Excel.`);
}

function closeSalesJournalDayModal() {
    salesJournalDayCurrentDateKey = '';
    salesJournalDaySelectionCache = new Set();
    const modal = document.getElementById('sales-journal-day-modal');
    if (modal) modal.style.display = 'none';
}

function toggleHiddenSalesJournalSelection(saleId, checked) {
    const normalizedId = String(saleId || '').trim();
    if (!normalizedId) return;
    if (checked) {
        salesJournalHiddenSelectionCache.add(normalizedId);
    } else {
        salesJournalHiddenSelectionCache.delete(normalizedId);
    }
}

async function openHiddenSalesJournalModal() {
    const modal = document.getElementById('sales-journal-hidden-modal');
    const titleNode = document.getElementById('sales-journal-hidden-modal-title');
    const subtitleNode = document.getElementById('sales-journal-hidden-modal-subtitle');
    const bodyNode = document.getElementById('sales-journal-hidden-modal-body');
    if (!modal || !titleNode || !subtitleNode || !bodyNode) return;

    const rows = await getHiddenSalesJournalFilteredRows();
    salesJournalHiddenSelectionCache = new Set();

    titleNode.innerText = 'Ventes masquees';
    subtitleNode.innerText = rows.length
        ? `${rows.length} vente(s) masquee(s) sur les filtres courants. La reaffichage les reintegre dans le journal et les totaux.`
        : 'Aucune vente masquee pour les filtres courants.';

    if (!rows.length) {
        bodyNode.innerHTML = '<tr><td colspan="8" style="text-align:center; padding:24px;">Aucune vente masquee.</td></tr>';
        modal.style.display = 'block';
        return;
    }

    bodyNode.innerHTML = rows.map(item => `
        <tr>
            <td style="text-align:center;">
                <input type="checkbox" class="pos-checkbox-styled" onchange="toggleHiddenSalesJournalSelection('${escapeHtml(String(item.id || ''))}', this.checked)">
            </td>
            <td>${item.date_vente ? new Date(item.date_vente).toLocaleString('fr-FR') : '-'}</td>
            <td>${escapeHtml(item.numero_vente || item.invoiceNumber || '-')}</td>
            <td>${escapeHtml(item.customerName || item.customers?.nom || 'Client passager')}</td>
            <td>${escapeHtml(item.mutuelles?.nom || '-')}</td>
            <td>${escapeHtml(getModeDisplayLabel(item))}</td>
            <td style="text-align:right; font-weight:700;">${formatMoney(item.totalTtc)}</td>
            <td>
                <button class="small-action-btn" type="button" onclick="showSalesJournalDetail('${escapeHtml(String(item.id || ''))}'); event.stopPropagation();">Detail</button>
            </td>
        </tr>
    `).join('');

    modal.style.display = 'block';
}

async function restoreSelectedSalesJournalRows() {
    const selectedIds = Array.from(salesJournalHiddenSelectionCache || []).filter(Boolean);
    if (selectedIds.length === 0) {
        alert('Selectionnez au moins une vente a reafficher.');
        return;
    }

    const hiddenIds = getSalesJournalHiddenIds();
    selectedIds.forEach(id => hiddenIds.delete(String(id)));
    saveSalesJournalHiddenIds(hiddenIds);

    await loadSalesJournal();
    await openHiddenSalesJournalModal();

    alert(`${selectedIds.length} vente(s) reaffichee(s). Les totaux du journal ont ete recalcules automatiquement.`);
}

function closeHiddenSalesJournalModal() {
    salesJournalHiddenSelectionCache = new Set();
    const modal = document.getElementById('sales-journal-hidden-modal');
    if (modal) modal.style.display = 'none';
}

function buildSalesJournalPrintDocument(rows, grouping = 'none') {
    const totals = rows.reduce((acc, item) => {
        acc.count += 1;
        acc.exonore += Number(item.tax?.exonore || 0);
        acc.base7 += Number(item.tax?.base7 || 0);
        acc.tva7 += Number(item.tax?.tva7 || 0);
        acc.base13 += Number(item.tax?.base13 || 0);
        acc.tva13 += Number(item.tax?.tva13 || 0);
        acc.base19 += Number(item.tax?.base19 || 0);
        acc.tva19 += Number(item.tax?.tva19 || 0);
        acc.ht += item.totalHt;
        acc.tva += item.totalTva;
        acc.ttc += item.totalTtc;
        return acc;
    }, { count: 0, exonore: 0, base7: 0, tva7: 0, base13: 0, tva13: 0, base19: 0, tva19: 0, ht: 0, tva: 0, ttc: 0 });
    const dailyRows = getSalesJournalDailyRows(rows);

    return `
        <h1>Journal des ventes</h1>
        <p>${escapeHtml(getSalesJournalPeriodLabel())}</p>
        <p>Total periode: ${formatMoney(totals.ttc)} DT | HT: ${formatMoney(totals.ht)} DT | TVA: ${formatMoney(totals.tva)} DT | Nb ventes: ${totals.count}</p>
        <table>
            <thead>
                <tr>
                    <th>Date</th>
                    <th>Nombre ventes</th>
                    <th>Exonore</th>
                    <th>Base TVA 7</th>
                    <th>TVA 7</th>
                    <th>Base TVA 13</th>
                    <th>TVA 13</th>
                    <th>Base TVA 19</th>
                    <th>TVA 19</th>
                    <th>Total HT</th>
                    <th>TVA</th>
                    <th>Total TTC</th>
                </tr>
            </thead>
            <tbody>
                ${dailyRows.map(item => `
                    <tr>
                        <td>${escapeHtml(item.dateLabel || '-')}</td>
                        <td style="text-align:right;">${item.salesCount || 0}</td>
                        <td style="text-align:right;">${formatMoney(item.tax.exonore)}</td>
                        <td style="text-align:right;">${formatMoney(item.tax.base7)}</td>
                        <td style="text-align:right;">${formatMoney(item.tax.tva7)}</td>
                        <td style="text-align:right;">${formatMoney(item.tax.base13)}</td>
                        <td style="text-align:right;">${formatMoney(item.tax.tva13)}</td>
                        <td style="text-align:right;">${formatMoney(item.tax.base19)}</td>
                        <td style="text-align:right;">${formatMoney(item.tax.tva19)}</td>
                        <td style="text-align:right;">${formatMoney(item.totalHt)}</td>
                        <td style="text-align:right;">${formatMoney(item.totalTva)}</td>
                        <td style="text-align:right;">${formatMoney(item.totalTtc)}</td>
                    </tr>
                `).join('')}
                <tr>
                    <td style="font-weight:800;">Total periode</td>
                    <td style="text-align:right; font-weight:800;">${totals.count}</td>
                    <td style="text-align:right; font-weight:800;">${formatMoney(totals.exonore)}</td>
                    <td style="text-align:right; font-weight:800;">${formatMoney(totals.base7)}</td>
                    <td style="text-align:right; font-weight:800;">${formatMoney(totals.tva7)}</td>
                    <td style="text-align:right; font-weight:800;">${formatMoney(totals.base13)}</td>
                    <td style="text-align:right; font-weight:800;">${formatMoney(totals.tva13)}</td>
                    <td style="text-align:right; font-weight:800;">${formatMoney(totals.base19)}</td>
                    <td style="text-align:right; font-weight:800;">${formatMoney(totals.tva19)}</td>
                    <td style="text-align:right; font-weight:800;">${formatMoney(totals.ht)}</td>
                    <td style="text-align:right; font-weight:800;">${formatMoney(totals.tva)}</td>
                    <td style="text-align:right; font-weight:800;">${formatMoney(totals.ttc)}</td>
                </tr>
            </tbody>
        </table>
    `;
}

async function printSalesJournalSale(saleId, event) {
    if (event) {
        event.stopPropagation();
    }

    if (String(saleId || '').startsWith('web-')) {
        const orderId = String(saleId).replace(/^web-/, '');
        return printWebStoreOrder(orderId, false);
    }

    const rows = await getSalesJournalRows(null, null, saleId);
    const sale = rows.find(item => item.id === saleId);
    if (!sale) {
        alert('Vente introuvable.');
        return;
    }

    const { saleItems, products } = await getSalesReportsBundle(null, null, saleId);
    const productsById = new Map(products.map(product => [String(product.id || ''), product]));
    const linkedSaleItems = saleItems
        .filter(line => String(line.sale_id) === String(saleId))
        .map(line => ({
            ...line,
            products: productsById.get(String(line.product_id || '')) || null
        }));

    if (!Array.isArray(linkedSaleItems) || linkedSaleItems.length === 0) {
        alert('Aucune ligne article trouvee pour cette vente.');
        return;
    }

    const paymentMode = sale.mode || inferSaleMode(sale);
    const saleType = paymentMode === 'MUTUELLE' ? 'mutuelle' : paymentMode === 'CREDIT' ? 'credit' : 'comptant';
    const totalTtc = Number(sale.total_ttc || sale.totalTtc || 0);
    const breakdown = getSaleMutuelleBreakdown(totalTtc, sale.mutuelles?.taux_remboursement);
    const items = linkedSaleItems.map(line => ({
        product_id: line.product_id,
        code_article: line.products?.code_article || '-',
        code_pct: line.products?.code_pct || line.code_pct || '',
        designation: line.products?.designation || '-',
        forme: line.products?.forme || '',
        quantite: Number(line.quantite || 0),
        prix_unitaire_ttc: Number(line.prix_unitaire_ttc || 0),
        tva: Number(line.products?.tva || 0),
        remise: Number(line.remise || 0),
        peremption: line.products?.peremption || null
    }));

    const payload = {
        sale,
        context: {
            saleType,
            totalHt: Number(sale.total_ht || sale.totalHt || 0),
            totalTva: Number(sale.total_tva || sale.totalTva || 0),
            totalTtc
        },
        customer: sale.customers || null,
        mutuelle: sale.mutuelles || null,
        breakdown,
        items,
        paymentMode,
        paymentReference: '',
        paymentName: '',
        paymentEcheance: '',
        received: saleType === 'comptant' ? totalTtc : 0,
        printDate: sale.date_vente || new Date().toISOString()
    };

    const printWindow = openReportPrintWindow(`Facture ${sale.numero_vente || 'vente'}`, buildSaleInvoicePrintDocument(payload));
    if (!printWindow) return;
    printWindow.print();
}

async function exportSalesJournalToExcel() {
    try {
        if (typeof XLSX === 'undefined') {
            throw new Error('La librairie XLSX n est pas chargee.');
        }

        const rows = await getVisibleSalesJournalFilteredRows();
        if (rows.length === 0) {
            alert('Aucune donnee a exporter.');
            return;
        }

        const dailyRows = getSalesJournalDailyRows(rows);
        const totals = dailyRows.reduce((acc, item) => {
            acc.salesCount += Number(item.salesCount || 0);
            acc.exonore += Number(item.tax?.exonore || 0);
            acc.base7 += Number(item.tax?.base7 || 0);
            acc.tva7 += Number(item.tax?.tva7 || 0);
            acc.base13 += Number(item.tax?.base13 || 0);
            acc.tva13 += Number(item.tax?.tva13 || 0);
            acc.base19 += Number(item.tax?.base19 || 0);
            acc.tva19 += Number(item.tax?.tva19 || 0);
            acc.totalHt += Number(item.totalHt || 0);
            acc.totalTva += Number(item.totalTva || 0);
            acc.totalTtc += Number(item.totalTtc || 0);
            return acc;
        }, { salesCount: 0, exonore: 0, base7: 0, tva7: 0, base13: 0, tva13: 0, base19: 0, tva19: 0, totalHt: 0, totalTva: 0, totalTtc: 0 });

        const exportRows = dailyRows.map((item, index) => ({
            Sequence: index + 1,
            Date: item.dateLabel || '',
            Exonore: Number(formatMoney(item.tax?.exonore || 0)),
            BaseTVA7: Number(formatMoney(item.tax?.base7 || 0)),
            TVA7: Number(formatMoney(item.tax?.tva7 || 0)),
            BaseTVA13: Number(formatMoney(item.tax?.base13 || 0)),
            TVA13: Number(formatMoney(item.tax?.tva13 || 0)),
            BaseTVA19: Number(formatMoney(item.tax?.base19 || 0)),
            TVA19: Number(formatMoney(item.tax?.tva19 || 0)),
            TotalHT: Number(formatMoney(item.totalHt)),
            TotalTVA: Number(formatMoney(item.totalTva)),
            TotalTTC: Number(formatMoney(item.totalTtc))
        }));

        exportRows.push({
            Sequence: '',
            Date: 'Total periode',
            Exonore: Number(formatMoney(totals.exonore)),
            BaseTVA7: Number(formatMoney(totals.base7)),
            TVA7: Number(formatMoney(totals.tva7)),
            BaseTVA13: Number(formatMoney(totals.base13)),
            TVA13: Number(formatMoney(totals.tva13)),
            BaseTVA19: Number(formatMoney(totals.base19)),
            TVA19: Number(formatMoney(totals.tva19)),
            TotalHT: Number(formatMoney(totals.totalHt)),
            TotalTVA: Number(formatMoney(totals.totalTva)),
            TotalTTC: Number(formatMoney(totals.totalTtc))
        });

        const worksheet = XLSX.utils.json_to_sheet(exportRows);
        const workbook = XLSX.utils.book_new();
        XLSX.utils.book_append_sheet(workbook, worksheet, 'Journal Ventes');
        XLSX.writeFile(workbook, `journal-ventes-${new Date().toISOString().split('T')[0]}.xlsx`);
    } catch (error) {
        console.error('Erreur export journal ventes:', error);
        alert(`Export impossible: ${error.message}`);
    }
}

