async function showSalesJournalDetail(saleId) {
    const rows = await getSalesJournalRows(null, null, saleId);
    const item = rows.find(row => row.id === saleId);
    if (!item) return;

    const modal = document.getElementById('sales-journal-detail-modal');
    const content = document.getElementById('sales-journal-detail-content');
    if (!modal || !content) return;

    const saleItems = String(saleId).startsWith('web-')
        ? await fetchCollection(`web_order_items?select=order_id,product_id,designation,code_article,quantite,prix_unitaire,products(code_article,designation)&order_id=eq.${String(saleId).replace(/^web-/, '')}`)
        : await fetchCollection(`sale_items?select=prix_unitaire_ttc,quantite,remise,products(code_article,designation)&sale_id=eq.${saleId}`);

    const linesHtml = saleItems.length === 0
        ? '<tr><td colspan="5" style="text-align:center; padding:16px;">Aucune ligne trouvee.</td></tr>'
        : saleItems.map(line => {
            const unitPrice = Number(line.prix_unitaire_ttc || line.unit_price || 0);
            const qty = Number(line.quantite || line.quantity || 0);
            const remise = Number(line.remise || 0);
            return `
                <tr>
                    <td>${escapeHtml(line.products?.code_article || '-')}</td>
                    <td>${escapeHtml(line.products?.designation || '-')}</td>
                    <td style="text-align:right;">${formatMoney(qty)}</td>
                    <td style="text-align:right;">${formatMoney(unitPrice)}</td>
                    <td style="text-align:right;">${formatMoney((qty * unitPrice) - remise)}</td>
                </tr>
            `;
        }).join('');

    content.innerHTML = `
        <div class="state-detail-grid state-detail-grid-compact-3 sales-journal-detail-grid">
            <div><strong>Date</strong><div>${item.date_vente ? new Date(item.date_vente).toLocaleString('fr-FR') : '-'}</div></div>
            <div><strong>Numero vente</strong><div>${escapeHtml(item.numero_vente || item.invoiceNumber || '-')}</div></div>
            <div><strong>Client</strong><div>${escapeHtml(item.customerName || item.customers?.nom || 'Client passager')}</div></div>
            <div><strong>Type client</strong><div>${escapeHtml(item.customerTypeLabel || getCustomerTypeLabel(item))}</div></div>
            <div><strong>Mutuelle</strong><div>${escapeHtml(item.mutuelles?.nom || '-')}</div></div>
            <div><strong>Mode</strong><div>${escapeHtml(getModeDisplayLabel(item))}</div></div>
            <div><strong>Statut</strong><div>${escapeHtml(item.statut || 'Valide')}</div></div>
            <div><strong>Total HT</strong><div>${formatMoney(item.totalHt)} DT</div></div>
            <div><strong>Total TVA</strong><div>${formatMoney(item.totalTva)} DT</div></div>
            <div><strong>Total TTC</strong><div>${formatMoney(item.totalTtc)} DT</div></div>
            <div><strong>Opérateur</strong><div>${escapeHtml(item.created_by || '-')}</div></div>
        </div>
        <div class="state-detail-lines">
            <table class="pos-table">
                <thead>
                    <tr>
                        <th>Code</th>
                        <th>Designation</th>
                        <th style="text-align:right;">Qté</th>
                        <th style="text-align:right;">PU TTC</th>
                        <th style="text-align:right;">Total</th>
                    </tr>
                </thead>
                <tbody>${linesHtml}</tbody>
            </table>
        </div>
    `;

    modal.style.display = 'block';
}

