async function initSalesTaxReportModule(kind) {
    if (!Array.isArray(saleState.customers) || saleState.customers.length === 0) {
        saleState.customers = await fetchCollection('customers?select=id,nom,telephone,solde,en_cours,reste_a_payer&order=nom');
    }

    const prefix = getSalesTaxReportPrefix(kind);
    const customerSelect = document.getElementById(`${prefix}-customer`);
    if (customerSelect) {
        customerSelect.innerHTML = [
            '<option value="">TOUS</option>',
            ...saleState.customers.map(customer => `<option value="${customer.id}">${escapeHtml(customer.nom)}</option>`)
        ].join('');
    }

    await loadSalesTaxReport(kind);
}

async function fetchItemsByParentIds(table, parentField, parentIds, batchSize = 100) {
    const allIds = Array.from(parentIds);
    if (allIds.length === 0) return [];

    const results = [];
    for (let i = 0; i < allIds.length; i += batchSize) {
        const batch = allIds.slice(i, i + batchSize);
        const idList = batch.map(id => `${parentField}.eq.${id}`).join(',');
        const items = await fetchCollection(`${table}&or=(${idList})`, []);
        results.push(...(Array.isArray(items) ? items : []));
    }
    return results;
}

async function getSalesReportsBundle(startDate = null, endDate = null, saleId = null) {
    // Normaliser les dates pour maximiser les hits de cache
    const normStart = startDate ? String(startDate).slice(0, 10) : null;
    const normEnd = endDate ? String(endDate).slice(0, 10) : null;
    startDate = normStart;
    endDate = normEnd;
    const rpcPayload = {};
    if (startDate) rpcPayload.p_start_date = startDate;
    if (endDate) rpcPayload.p_end_date = endDate;
    if (saleId) rpcPayload.p_sale_id = saleId;
    try {
        const controller = new AbortController();
        const rpcTimeout = setTimeout(() => controller.abort(), 30000);
        const rpcResponse = await fetch(`${supabaseUrl}rpc/get_sales_reports_bundle`, {
            method: 'POST',
            headers: supabaseHeaders,
            body: JSON.stringify(rpcPayload || {}),
            signal: controller.signal
        });
        clearTimeout(rpcTimeout);
        if (rpcResponse.ok) {
            const rpcBundle = await rpcResponse.json();
            if (rpcBundle && typeof rpcBundle === 'object') {
                const rpcSales = Array.isArray(rpcBundle.sales) ? rpcBundle.sales : [];
                if (rpcSales.length > 0 || !startDate) {
                    return {
                        sales: rpcSales,
                        saleItems: Array.isArray(rpcBundle.sale_items) ? rpcBundle.sale_items : [],
                        products: Array.isArray(rpcBundle.products) ? rpcBundle.products : [],
                        webOrders: Array.isArray(rpcBundle.web_orders) ? rpcBundle.web_orders : [],
                        webOrderItems: Array.isArray(rpcBundle.web_order_items) ? rpcBundle.web_order_items : []
                    };
                }
            }
        }
    } catch (rpcError) {
        console.warn('RPC get_sales_reports_bundle indisponible, fallback REST.', rpcError);
    }

    const since = startDate || getDefaultDateFilter(1);
    const endBase = endDate || new Date().toISOString().slice(0, 10);
    const until = `${endBase}T23:59:59.999Z`;
    const salesUrl = saleId ? `sales?select=id,numero_vente,date_vente,type_vente,payment_mode,total_ttc,total_ht,client_id,mutuelle_id,statut,created_at,created_by,customers(nom,numero_matricule_mutuelle,nom_malade),mutuelles(nom,taux_remboursement)&id=eq.${saleId}` : `sales?select=id,numero_vente,date_vente,type_vente,payment_mode,total_ttc,total_ht,client_id,mutuelle_id,statut,created_at,created_by,customers(nom,numero_matricule_mutuelle,nom_malade),mutuelles(nom,taux_remboursement)&date_vente=gte.${since}&date_vente=lte.${until}&order=date_vente.desc`;
    const webOrdersUrl = saleId ? `web_orders?select=id&id=eq.00000000-0000-0000-0000-000000000000` : `web_orders?select=id,order_number,customer_name,customer_phone,customer_email,customer_address,notes,delivery_mode,payment_mode,delivery_fee_ttc,total_ttc,status,stock_decremented,created_at&created_at=gte.${since}&created_at=lte.${until}&order=created_at.desc`;

    const [sales, webOrders] = await Promise.all([
        fetchCollection(salesUrl),
        fetchCollection(webOrdersUrl)
    ]);

    let products = Array.isArray(allManagedProducts) && allManagedProducts.length > 0
        ? allManagedProducts
        : (_productsCache.data && _productsCache.data.length > 0)
            ? _productsCache.data
            : await fetchCollection('products?select=id,code_article,designation,tva,forme,prix_vente_ttc,code_pct');

    const saleIds = new Set(sales.map(s => s.id));
    const webOrderIds = new Set(webOrders.map(o => o.id));

    const [saleItems, webOrderItems] = await Promise.all([
        saleIds.size > 0
            ? fetchItemsByParentIds('sale_items?select=id,sale_id,product_id,quantite,prix_unitaire_ttc,remise,products(id,code_article,designation,tva,forme,prix_vente_ttc,code_pct)', 'sale_id', saleIds)
            : Promise.resolve([]),
        webOrderIds.size > 0
            ? fetchItemsByParentIds('web_order_items?select=order_id,product_id,quantity,unit_price,products(id,code_article,designation,tva,forme,prix_vente_ttc,code_pct)', 'order_id', webOrderIds)
            : Promise.resolve([])
    ]);

    return { sales, saleItems, products, webOrders, webOrderItems };
}

async function getSalesTaxReportRows(startDate = null, endDate = null, saleId = null) {
    const { sales, saleItems, products, webOrders, webOrderItems } = await getSalesReportsBundle(startDate, endDate, saleId);

    const productsById = new Map(products.map(product => [String(product.id || ''), product]));
    const itemsBySaleId = saleItems.reduce((acc, item) => {
        const enrichedItem = {
            ...item,
            products: item.products || productsById.get(String(item.product_id || '')) || null
        };
        if (!acc[item.sale_id]) acc[item.sale_id] = [];
        acc[item.sale_id].push(enrichedItem);
        return acc;
    }, {});

    const saleRows = sales.map(sale => {
        const items = itemsBySaleId[sale.id] || [];
        const tax = {
            exonore: 0,
            base7: 0,
            tva7: 0,
            base13: 0,
            tva13: 0,
            base19: 0,
            tva19: 0
        };

        items.forEach(line => {
            const qty = Number(line.quantite || 0);
            const remise = Number(line.remise || 0);
            const lineTtc = (qty * Number(line.prix_unitaire_ttc || 0)) - remise;
            const rate = Number(line.products?.tva || 0);
            if (rate <= 0) {
                tax.exonore += lineTtc;
                return;
            }

            const base = lineTtc / (1 + (rate / 100));
            const tvaAmount = lineTtc - base;
            if (rate === 7) {
                tax.base7 += base;
                tax.tva7 += tvaAmount;
            } else if (rate === 13) {
                tax.base13 += base;
                tax.tva13 += tvaAmount;
            } else {
                tax.base19 += base;
                tax.tva19 += tvaAmount;
            }
        });

        return {
            ...sale,
            mode: inferSaleMode(sale),
            customerType: getCustomerTypeKey(sale),
            customerTypeLabel: getCustomerTypeLabel(sale),
            customerName: sale.customers?.nom || 'Client passager',
            totalHt: Number(sale.total_ht || 0),
            totalTva: Number(sale.total_tva || 0),
            totalTtc: Number(sale.total_ttc || 0),
            invoiceNumber: sale.numero_vente || '-',
            tax,
            detailItems: items
        };
    });

    const itemsByWebOrderId = webOrderItems.reduce((acc, item) => {
        const enrichedItem = {
            ...item,
            quantite: Number(item.quantity || 0),
            prix_unitaire_ttc: Number(item.unit_price || 0),
            remise: 0,
            products: item.products || productsById.get(String(item.product_id || '')) || null
        };
        if (!acc[item.order_id]) acc[item.order_id] = [];
        acc[item.order_id].push(enrichedItem);
        return acc;
    }, {});

    const webRows = webOrders
        .filter(isWebOrderValidated)
        .map(order => {
            const items = itemsByWebOrderId[order.id] || [];
            const tax = {
                exonore: 0,
                base7: 0,
                tva7: 0,
                base13: 0,
                tva13: 0,
                base19: 0,
                tva19: 0
            };

            items.forEach(line => {
                const qty = Number(line.quantite || 0);
                const lineTtc = qty * Number(line.prix_unitaire_ttc || 0);
                const rate = Number(line.products?.tva || 0);
                if (rate <= 0) {
                    tax.exonore += lineTtc;
                    return;
                }

                const base = lineTtc / (1 + (rate / 100));
                const tvaAmount = lineTtc - base;
                if (rate === 7) {
                    tax.base7 += base;
                    tax.tva7 += tvaAmount;
                } else if (rate === 13) {
                    tax.base13 += base;
                    tax.tva13 += tvaAmount;
                } else {
                    tax.base19 += base;
                    tax.tva19 += tvaAmount;
                }
            });

            const totalHt = tax.exonore + tax.base7 + tax.base13 + tax.base19;
            const totalTva = tax.tva7 + tax.tva13 + tax.tva19;

            return {
                ...order,
                id: `web-${order.id}`,
                source: 'WEB',
                mode: 'E-COMMERCE',
                customerType: 'WEB',
                customerTypeLabel: 'Client web',
                customerName: order.customer_name || 'Client web',
                date_vente: order.created_at,
                totalHt,
                totalTva,
                totalTtc: Number(order.total_ttc || 0),
                invoiceNumber: order.order_number || '-',
                tax,
                detailItems: items,
                customers: { nom: order.customer_name || 'Client web' },
                mutuelles: null
            };
        });

    return [...saleRows, ...webRows].sort((a, b) => {
        const dateA = new Date(a.date_vente || 0).getTime();
        const dateB = new Date(b.date_vente || 0).getTime();
        return dateB - dateA;
    });
}

async function getSalesTaxReportFilteredRows(kind) {
    const prefix = getSalesTaxReportPrefix(kind);
    const customerId = document.getElementById(`${prefix}-customer`)?.value || '';
    const mode = document.getElementById(`${prefix}-mode`)?.value || '';
    const customerType = document.getElementById(`${prefix}-customer-type`)?.value || '';
    const status = document.getElementById(`${prefix}-status`)?.value || '';
    const from = document.getElementById(`${prefix}-from`)?.value || '';
    const to = document.getElementById(`${prefix}-to`)?.value || '';

    return (await getSalesTaxReportRows(from || null, to || null))
        .filter(item => matchesReportCustomer(item, customerId))
        .filter(item => matchesReportMode(item, mode))
        .filter(item => matchesReportCustomerType(item, customerType))
        .filter(item => matchesReportDateRange(item, from, to))
        .filter(item => matchesReportInvoiceStatus(item, status));
}

async function loadSalesTaxReport(kind) {
    const prefix = getSalesTaxReportPrefix(kind);
    const tbody = document.getElementById(`${prefix}-body`);
    if (!tbody) return;

    const rows = await getSalesTaxReportFilteredRows(kind);
    const detailed = document.getElementById(`${prefix}-detail`)?.checked !== false;
    const detailRows = kind === 'etat' ? getEtatSalesDetailRows(rows) : [];
    const hasDetailRows = detailRows.length > 0;

    if (kind === 'etat') {
        if (detailed && hasDetailRows) {
            tbody.innerHTML = renderEtatSalesDetailRows(detailRows);
        } else if (detailed && !hasDetailRows && rows.length > 0) {
            tbody.innerHTML = renderEtatFallbackRows(rows);
        } else if (!detailed && rows.length > 0) {
            tbody.innerHTML = renderSalesTaxReportRows(rows, kind, false);
        } else {
            tbody.innerHTML = `<tr><td colspan="17" style="text-align:center; padding:40px;">Aucune vente pour ces criteres.</td></tr>`;
        }
    } else {
        tbody.innerHTML = rows.length > 0
            ? renderSalesTaxReportRows(rows, kind, detailed)
            : `<tr><td colspan="15" style="text-align:center; padding:40px;">Aucune vente pour ces criteres.</td></tr>`;
    }

    if (kind === 'etat') {
        const totals = (detailed && hasDetailRows)
            ? detailRows.reduce((acc, item) => {
                acc.ttc += item.totalTtc;
                acc.tva += item.totalTva;
                acc.ht += item.totalHt;
                acc.qty += item.qty;
                acc.mutuelle += item.totalMutuelle;
                acc.sales.add(item.saleId);
                return acc;
            }, { ttc: 0, tva: 0, ht: 0, qty: 0, mutuelle: 0, sales: new Set() })
            : rows.reduce((acc, item) => {
                acc.ttc += item.totalTtc;
                acc.tva += item.totalTva;
                acc.ht += item.totalHt;
                acc.mutuelle += Number(item.mutuelles?.taux_remboursement || 0) > 0 && item.mode === 'MUTUELLE'
                    ? (item.totalTtc * Number(item.mutuelles?.taux_remboursement || 0) / 100)
                    : 0;
                acc.sales.add(item.id);
                return acc;
            }, { ttc: 0, tva: 0, ht: 0, qty: 0, mutuelle: 0, sales: new Set() });

        const sumTtc = document.getElementById(`${prefix}-sum-ttc`);
        const sumCount = document.getElementById(`${prefix}-sum-count`);
        const sumQty = document.getElementById(`${prefix}-sum-qty`);
        const sumTva = document.getElementById(`${prefix}-sum-tva`);
        const sumHt = document.getElementById(`${prefix}-sum-ht`);
        const sumMutuelle = document.getElementById(`${prefix}-sum-mutuelle`);

        if (sumTtc) sumTtc.innerText = formatMoney(totals.ttc);
        if (sumCount) sumCount.innerText = String(totals.sales.size);
        if (sumQty) sumQty.innerText = formatMoney(totals.qty);
        if (sumTva) sumTva.innerText = formatMoney(totals.tva);
        if (sumHt) sumHt.innerText = formatMoney(totals.ht);
        if (sumMutuelle) sumMutuelle.innerText = formatMoney(totals.mutuelle);
        return;
    }

    const totals = rows.reduce((acc, item) => {
        acc.exonore += item.tax.exonore;
        acc.base7 += item.tax.base7;
        acc.base13 += item.tax.base13;
        acc.base19 += item.tax.base19;
        acc.tva7 += item.tax.tva7;
        acc.tva13 += item.tax.tva13;
        acc.tva19 += item.tax.tva19;
        acc.ht += item.totalHt;
        acc.tva += item.totalTva;
        acc.ttc += item.totalTtc;
        acc.count += 1;
        return acc;
    }, { exonore: 0, base7: 0, base13: 0, base19: 0, tva7: 0, tva13: 0, tva19: 0, ht: 0, tva: 0, ttc: 0, count: 0 });

    const sumExonore = document.getElementById(`${prefix}-sum-exonore`);
    const sumBase7 = document.getElementById(`${prefix}-sum-base7`);
    const sumBase13 = document.getElementById(`${prefix}-sum-base13`);
    const sumBase19 = document.getElementById(`${prefix}-sum-base19`);
    const sumHt = document.getElementById(`${prefix}-sum-ht`);
    const sumHr = document.getElementById(`${prefix}-sum-hr`);
    const sumTva7 = document.getElementById(`${prefix}-sum-tva7`);
    const sumTva13 = document.getElementById(`${prefix}-sum-tva13`);
    const sumTva19 = document.getElementById(`${prefix}-sum-tva19`);
    const sumTva = document.getElementById(`${prefix}-sum-tva`);
    const sumTtc = document.getElementById(`${prefix}-sum-ttc`);
    const sumCount = document.getElementById(`${prefix}-sum-count`);

    if (sumExonore) sumExonore.innerText = formatMoney(totals.exonore);
    if (sumBase7) sumBase7.innerText = formatMoney(totals.base7);
    if (sumBase13) sumBase13.innerText = formatMoney(totals.base13);
    if (sumBase19) sumBase19.innerText = formatMoney(totals.base19);
    if (sumHt) sumHt.innerText = formatMoney(totals.ht);
    if (sumHr) sumHr.innerText = '0.000';
    if (sumTva7) sumTva7.innerText = formatMoney(totals.tva7);
    if (sumTva13) sumTva13.innerText = formatMoney(totals.tva13);
    if (sumTva19) sumTva19.innerText = formatMoney(totals.tva19);
    if (sumTva) sumTva.innerText = formatMoney(totals.tva);
    if (sumTtc) sumTtc.innerText = formatMoney(totals.ttc);
    if (sumCount) sumCount.innerText = String(totals.count);
}

function getEtatSalesDetailRows(rows) {
    return rows.flatMap(item => {
        const rateMutuelle = Number(item.mutuelles?.taux_remboursement || 0);
        const isMutuelle = item.mode === 'MUTUELLE';
        return (item.detailItems || []).map(line => {
            const qty = Number(line.quantite || 0);
            const remise = Number(line.remise || 0);
            const totalTtc = (qty * Number(line.prix_unitaire_ttc || 0)) - remise;
            const tvaRate = Number(line.products?.tva || 0);
            const totalHt = tvaRate > 0 ? totalTtc / (1 + (tvaRate / 100)) : totalTtc;
            const totalTva = totalTtc - totalHt;
            const totalMutuelle = isMutuelle ? (totalTtc * rateMutuelle / 100) : 0;
            return {
                saleId: item.id,
                numero: item.invoiceNumber || '-',
                date: item.date_vente,
                designation: line.products?.designation || '-',
                forme: line.products?.forme || item.forme || '-',
                customerName: item.customerName,
                customerType: item.customerType,
                customerTypeLabel: item.customerTypeLabel,
                mode: item.mode || '',
                created_by: item.created_by || '',
                qty,
                tvaRate,
                totalTva,
                remise,
                totalTtc,
                totalMutuelle,
                totalCnam: 0,
                totalHt
            };
        });
    });
}

function renderEtatFallbackRows(rows) {
    return rows.map(item => {
        const rateMutuelle = Number(item.mutuelles?.taux_remboursement || 0);
        const isMutuelle = item.mode === 'MUTUELLE';
        const totalMutuelle = isMutuelle ? (item.totalTtc * rateMutuelle / 100) : 0;
        return `
        <tr onclick="showSalesTaxReportDetail('etat', '${item.id}')" style="cursor:pointer;">
            <td>${escapeHtml(item.invoiceNumber || '-')}</td>
            <td>${item.date_vente ? new Date(item.date_vente).toLocaleDateString('fr-FR') : '-'}</td>
            <td>-</td>
            <td>-</td>
            <td>${escapeHtml(item.customerName || 'Client')}</td>
            <td style="text-align:center; white-space:nowrap;">${renderCustomerTypeBadge(item)}</td>
            <td style="text-align:center; white-space:nowrap;">${formatSaleModeLabel(item.mode)}</td>
            <td style="text-align:right;">-</td>
            <td style="text-align:right;">-</td>
            <td style="text-align:right;">${formatMoney(item.totalTva)}</td>
            <td style="text-align:right;">0.000</td>
            <td style="text-align:right; font-weight:700;">${formatMoney(item.totalTtc)}</td>
            <td style="text-align:right;">${formatMoney(totalMutuelle)}</td>
            <td style="text-align:right;">0.000</td>
            <td style="text-align:right;">${formatMoney(item.totalHt)}</td>
            <td style="white-space:nowrap; font-size:12px;">${escapeHtml(item.created_by || '-')}</td>
            <td class="sales-tax-actions-cell" onclick="event.stopPropagation();">${renderSalesTaxReportActionButton(item, 'etat')}</td>
        </tr>`;
    }).join('');
}

function renderEtatSalesDetailRows(rows) {
    return rows.map(item => `
        <tr>
            <td>${escapeHtml(item.numero)}</td>
            <td>${item.date ? new Date(item.date).toLocaleDateString('fr-FR') : '-'}</td>
            <td>${escapeHtml(item.designation)}</td>
            <td>${escapeHtml(item.forme || '-')}</td>
            <td>${escapeHtml(item.customerName || 'Client')}</td>
            <td style="text-align:center; white-space:nowrap;">${renderCustomerTypeBadge(item)}</td>
            <td style="text-align:center; white-space:nowrap;">${formatSaleModeLabel(item.mode)}</td>
            <td style="text-align:right;">${formatMoney(item.qty)}</td>
            <td style="text-align:right;">${formatMoney(item.tvaRate)}</td>
            <td style="text-align:right;">${formatMoney(item.totalTva)}</td>
            <td style="text-align:right;">${formatMoney(item.remise)}</td>
            <td style="text-align:right; font-weight:700;">${formatMoney(item.totalTtc)}</td>
            <td style="text-align:right;">${formatMoney(item.totalMutuelle)}</td>
            <td style="text-align:right;">${formatMoney(item.totalCnam)}</td>
            <td style="text-align:right;">${formatMoney(item.totalHt)}</td>
            <td style="white-space:nowrap; font-size:12px;">${escapeHtml(item.created_by || '-')}</td>
            <td class="sales-tax-actions-cell" onclick="event.stopPropagation();">${renderSalesTaxReportActionButton({ id: item.saleId }, 'etat')}</td>
        </tr>
    `).join('');
}

function renderSalesTaxReportRows(rows, kind, detailed = true) {
    if (detailed) {
        return rows.map(item => {
            const masterRow = `
                <tr onclick="showSalesTaxReportDetail('${kind}', '${item.id}')" style="cursor:pointer;">
                    <td>${item.date_vente ? new Date(item.date_vente).toLocaleDateString('fr-FR') : '-'}</td>
                    <td style="text-align:right;">${formatMoney(item.tax.exonore)}</td>
                    <td style="text-align:right;">${formatMoney(item.tax.base7)}</td>
                    <td style="text-align:right;">${formatMoney(item.tax.tva7)}</td>
                    <td style="text-align:right;">${formatMoney(item.tax.base13)}</td>
                    <td style="text-align:right;">${formatMoney(item.tax.tva13)}</td>
                    <td style="text-align:right;">${formatMoney(item.tax.base19)}</td>
                    <td style="text-align:right;">${formatMoney(item.tax.tva19)}</td>
                    <td style="text-align:right;">${formatMoney(item.totalHt)}</td>
            <td style="text-align:right;">${formatMoney(item.totalTva)}</td>
            <td style="text-align:right; font-weight:700;">${formatMoney(item.totalTtc)}</td>
            <td>${escapeHtml(item.customerName)}</td>
            <td style="text-align:center; white-space:nowrap;">${renderCustomerTypeBadge(item)}</td>
            <td>${escapeHtml(item.invoiceNumber)}</td>
            <td class="sales-tax-actions-cell" onclick="event.stopPropagation();">${renderSalesTaxReportActionButton(item, kind)}</td>
        </tr>
            `;

            if (kind !== 'etat') {
                return masterRow;
            }

            const detailRows = (item.detailItems || []).map(line => {
                const qty = Number(line.quantite || 0);
                const unitPrice = Number(line.prix_unitaire_ttc || 0);
                const total = (qty * unitPrice) - Number(line.remise || 0);
                const rate = Number(line.products?.tva || 0);
                const baseHt = rate > 0 ? total / (1 + (rate / 100)) : total;
                return `
                    <tr class="tax-report-detail-row">
                        <td colspan="2" style="padding-left:28px; color:#1d4ed8; font-weight:700;">${escapeHtml(line.products?.code_article || '-')}</td>
                        <td colspan="4">${escapeHtml(line.products?.designation || '-')}</td>
                        <td style="text-align:right;">Qté ${formatMoney(qty)}</td>
                        <td style="text-align:right;">TVA ${formatMoney(rate)}%</td>
                        <td style="text-align:right;">${formatMoney(baseHt)}</td>
                        <td></td>
                        <td style="text-align:right; font-weight:700;">${formatMoney(total)}</td>
                        <td>${escapeHtml(item.customerName)}</td>
                        <td style="text-align:center; white-space:nowrap;">${renderCustomerTypeBadge(item)}</td>
                        <td></td>
                        <td class="sales-tax-actions-cell" onclick="event.stopPropagation();">${renderSalesTaxReportActionButton(item, kind)}</td>
                    </tr>
                `;
            }).join('');

            return `${masterRow}${detailRows}`;
        }).join('');
    }

    const totals = rows.reduce((acc, item) => {
        acc.tax.exonore += item.tax.exonore;
        acc.tax.base7 += item.tax.base7;
        acc.tax.tva7 += item.tax.tva7;
        acc.tax.base13 += item.tax.base13;
        acc.tax.tva13 += item.tax.tva13;
        acc.tax.base19 += item.tax.base19;
        acc.tax.tva19 += item.tax.tva19;
        acc.totalHt += item.totalHt;
        acc.totalTva += item.totalTva;
        acc.totalTtc += item.totalTtc;
        return acc;
    }, { tax: { exonore: 0, base7: 0, tva7: 0, base13: 0, tva13: 0, base19: 0, tva19: 0 }, totalHt: 0, totalTva: 0, totalTtc: 0 });

    return `
        <tr>
            <td>Periode</td>
            <td style="text-align:right;">${formatMoney(totals.tax.exonore)}</td>
            <td style="text-align:right;">${formatMoney(totals.tax.base7)}</td>
            <td style="text-align:right;">${formatMoney(totals.tax.tva7)}</td>
            <td style="text-align:right;">${formatMoney(totals.tax.base13)}</td>
            <td style="text-align:right;">${formatMoney(totals.tax.tva13)}</td>
            <td style="text-align:right;">${formatMoney(totals.tax.base19)}</td>
            <td style="text-align:right;">${formatMoney(totals.tax.tva19)}</td>
            <td style="text-align:right;">${formatMoney(totals.totalHt)}</td>
            <td style="text-align:right;">${formatMoney(totals.totalTva)}</td>
            <td style="text-align:right; font-weight:700;">${formatMoney(totals.totalTtc)}</td>
            <td>Tous</td>
            <td>-</td>
            <td>-</td>
            <td class="sales-tax-actions-cell"></td>
        </tr>
    `;
}

