async function initPretEmpruntHistoryModule() {
    await loadPretEmpruntHistory();
    await loadPretEmpruntPartners();
}

async function loadPretEmpruntPartners() {
    const partnerSelect = document.getElementById('pe-hist-partner');
    if (!partnerSelect) return;
    
    partnerSelect.innerHTML = '<option value="">-- Tous les partenaires --</option>';
    
    try {
        const url = `${supabaseUrl}stock_operations?select=partner_name&movement_type=in.(PRET,EMPRUNT)&partner_name=not.is.null&order=partner_name`;
        const response = await fetch(url, { headers: supabaseHeaders });
        if (!response.ok) throw new Error(`HTTP ${response.status}`);
        const movements = await response.json();
        
        const uniquePartners = [...new Set(movements.map(m => m.partner_name).filter(p => p))];
        uniquePartners.forEach(partner => {
            const option = document.createElement('option');
            option.value = partner;
            option.textContent = partner;
            partnerSelect.appendChild(option);
        });
    } catch (err) {
        console.error('Erreur chargement partenaires:', err);
    }
}

async function loadPretEmpruntHistory() {
    const tbody = document.getElementById('pe-hist-body');
    if (!tbody) return;
    
    tbody.innerHTML = '<tr><td colspan="9" style="text-align:center;padding:40px;">Chargement...</td></tr>';
    
    const fromDate = document.getElementById('pe-hist-from')?.value;
    const toDate = document.getElementById('pe-hist-to')?.value;
    const partner = document.getElementById('pe-hist-partner')?.value;
    const typeOp = document.getElementById('pe-hist-type')?.value;
    
    try {
        const params = new URLSearchParams();
        params.set('select', '*,products(prix_vente_ttc)');
        params.set('movement_type', 'in.(PRET,EMPRUNT)');
        params.set('order', 'operation_date.desc');
        
        if (fromDate) params.append('operation_date', `gte.${fromDate}`);
        if (toDate) params.append('operation_date', `lte.${toDate}`);
        if (partner) params.append('partner_name', `eq.${partner}`);
        if (typeOp) params.append('movement_type', `eq.${typeOp}`);
        
        const url = `${supabaseUrl}stock_operations?${params.toString()}`;
        const response = await fetch(url, { headers: supabaseHeaders });
        if (!response.ok) throw new Error(`HTTP ${response.status}`);
        const movements = await response.json();
        
        let pretTotal = 0;
        let empruntTotal = 0;
        
        if (!movements || movements.length === 0) {
            tbody.innerHTML = '<tr><td colspan="9" style="text-align:center;padding:40px;color:#64748b;">Aucun mouvement trouvé</td></tr>';
        } else {
            let valPretTotal = 0;
            let valEmpruntTotal = 0;

            tbody.innerHTML = movements.map((m, idx) => {
                const qty = Math.abs(m.quantity);
                if (m.movement_type === 'PRET') pretTotal += qty;
                else empruntTotal += qty;

                const pu = Number(m.products?.prix_vente_ttc || 0);
                const valeur = qty * pu;
                if (m.movement_type === 'PRET') valPretTotal += valeur;
                else valEmpruntTotal += valeur;

                const date = new Date(m.operation_date).toLocaleDateString('fr-FR');
                const typeLabel = m.movement_type === 'PRET' ? 'Prêt' : 'Emprunt';
                const designation = m.product_designation || '-';
                const code = m.product_code || '-';
                const isPret = m.movement_type === 'PRET';
                const rowBg = idx % 2 === 0 ? '#f8fafc' : '#ffffff';
                const typeBg = isPret ? '#fef2f2' : '#f0fdf4';
                const typeColor = isPret ? '#dc2626' : '#16a34a';
                const qtyColor = isPret ? '#dc2626' : '#16a34a';

                return `
                    <tr style="border-bottom:1px solid #e2e8f0;background:${rowBg};">
                        <td style="padding:8px;color:#334155;font-weight:500;">${date}</td>
                        <td style="padding:8px;background:${typeBg};"><span style="padding:3px 10px;border-radius:4px;font-size:11px;font-weight:700;background:${typeBg};color:${typeColor};border:1px solid ${typeColor}20;">${typeLabel}</span></td>
                        <td style="padding:8px;color:#1e293b;">${designation}</td>
                        <td style="padding:8px;color:#475569;font-family:monospace;font-size:12px;">${code}</td>
                        <td style="padding:8px;text-align:right;font-weight:700;color:${qtyColor};">${qty.toFixed(3)}</td>
                        <td style="padding:8px;text-align:right;font-weight:700;color:#0f172a;">${formatMoney(valeur)}</td>
                        <td style="padding:8px;color:#0f172a;font-weight:500;">${m.partner_name || '-'}</td>
                        <td style="padding:8px;font-size:12px;color:#64748b;font-style:italic;">${m.note || '-'}</td>
                        <td style="padding:8px;color:#475569;font-size:12px;">${m.created_by || '-'}</td>
                    </tr>
                `;
            }).join('');

            const solde = valEmpruntTotal - valPretTotal;
            const soldeColor = solde > 0 ? '#16a34a' : solde < 0 ? '#dc2626' : '#64748b';
            tbody.innerHTML += `
                <tr style="background:#1e293b;color:white;font-weight:700;">
                    <td colspan="4" style="padding:10px;text-align:right;font-size:13px;color:white;">TOTAUX</td>
                    <td style="padding:10px;text-align:right;font-size:13px;color:white;">P: ${pretTotal.toFixed(3)} / E: ${empruntTotal.toFixed(3)}</td>
                    <td style="padding:10px;text-align:right;font-size:13px;color:white;">P: ${formatMoney(valPretTotal)} / E: ${formatMoney(valEmpruntTotal)}</td>
                    <td colspan="3" style="padding:10px;text-align:right;font-size:13px;color:white;">Solde: ${formatMoney(solde)}</td>
                </tr>
            `;

            document.getElementById('pe-hist-sum-val-pret').textContent = formatMoney(valPretTotal);
            document.getElementById('pe-hist-sum-val-emprunt').textContent = formatMoney(valEmpruntTotal);
            const soldeEl = document.getElementById('pe-hist-sum-solde');
            soldeEl.textContent = formatMoney(solde);
            soldeEl.style.color = soldeColor;
        }
        
        document.getElementById('pe-hist-sum-count').textContent = movements?.length || 0;
        document.getElementById('pe-hist-sum-pret').textContent = pretTotal.toFixed(3);
        document.getElementById('pe-hist-sum-emprunt').textContent = empruntTotal.toFixed(3);
        
    } catch (err) {
        console.error('Erreur chargement historique:', err);
        tbody.innerHTML = '<tr><td colspan="9" style="text-align:center;padding:40px;color:#ef4444;">Erreur de chargement</td></tr>';
    }
}

