function closeHitParadeView() {
    openTab('dashboard');
}

function getHitParadeFilters() {
    return {
        from: document.getElementById('hit-parade-from')?.value || '',
        to: document.getElementById('hit-parade-to')?.value || '',
        mode: document.getElementById('hit-parade-mode')?.value || '',
        sortBy: document.getElementById('hit-parade-sort')?.value || 'qty',
        top: Math.max(1, Number(document.getElementById('hit-parade-top')?.value || 20))
    };
}

async function initHitParadeModule() {
    await loadHitParadeReport();
}

async function getHitParadeRows() {
    const filters = getHitParadeFilters();
    const { sales, saleItems, products, webOrders, webOrderItems } = await getSalesReportsBundle(filters.from || null, filters.to || null);
    const productsById = new Map(products.map(product => [String(product.id || ''), product]));
    const aggregates = new Map();

    const ensureBucket = (productId, product, sourceMode = '') => {
        const key = productId || `virtual-${product?.code_article || product?.designation || sourceMode}`;
        if (!aggregates.has(key)) {
            aggregates.set(key, {
                productId: productId || '',
                codeArticle: product?.code_article || '-',
                designation: product?.designation || 'Article inconnu',
                forme: product?.forme || '-',
                saleCount: 0,
                quantity: 0,
                totalHt: 0,
                totalTtc: 0
            });
        }
        return aggregates.get(key);
    };

    const salesById = new Map(sales.map(sale => [sale.id, sale]));

    saleItems.forEach(line => {
        const sale = salesById.get(line.sale_id);
        if (!sale) return;
        const mode = inferSaleMode(sale);
        const saleDate = String(sale.date_vente || '').split('T')[0];
        if (filters.mode && mode !== filters.mode) return;
        if (filters.from && saleDate < filters.from) return;
        if (filters.to && saleDate > filters.to) return;

        const product = line.products || productsById.get(String(line.product_id || '')) || null;
        const qty = Number(line.quantite || 0);
        if (qty <= 0) return;
        const remise = Number(line.remise || 0);
        const totalTtc = (qty * Number(line.prix_unitaire_ttc || 0)) - remise;
        const tvaRate = Number(product?.tva || 0);
        const totalHt = tvaRate > 0 ? totalTtc / (1 + (tvaRate / 100)) : totalTtc;
        const bucket = ensureBucket(line.product_id, product, mode);

        bucket.quantity += qty;
        bucket.totalHt += totalHt;
        bucket.totalTtc += totalTtc;
        bucket.saleCount += 1;
    });

    webOrderItems.forEach(line => {
        const order = webOrders.find(item => item.id === line.order_id);
        if (!order || !isWebOrderValidated(order)) return;
        const saleDate = String(order.created_at || '').split('T')[0];
        if (filters.mode && filters.mode !== 'E-COMMERCE') return;
        if (filters.from && saleDate < filters.from) return;
        if (filters.to && saleDate > filters.to) return;

        const product = line.products || productsById.get(String(line.product_id || '')) || null;
        const qty = Number(line.quantity || 0);
        if (qty <= 0) return;
        const totalTtc = qty * Number(line.unit_price || 0);
        const tvaRate = Number(product?.tva || 0);
        const totalHt = tvaRate > 0 ? totalTtc / (1 + (tvaRate / 100)) : totalTtc;
        const bucket = ensureBucket(line.product_id, product, 'E-COMMERCE');

        bucket.quantity += qty;
        bucket.totalHt += totalHt;
        bucket.totalTtc += totalTtc;
        bucket.saleCount += 1;
    });

    const rows = Array.from(aggregates.values()).map(item => ({
        ...item,
        averagePriceTtc: item.quantity > 0 ? item.totalTtc / item.quantity : 0
    }));

    const sorters = {
        qty: (a, b) => b.quantity - a.quantity || b.totalTtc - a.totalTtc,
        ttc: (a, b) => b.totalTtc - a.totalTtc || b.quantity - a.quantity,
        count: (a, b) => b.saleCount - a.saleCount || b.totalTtc - a.totalTtc
    };

    return rows
        .sort(sorters[filters.sortBy] || sorters.qty)
        .slice(0, filters.top)
        .map((item, index) => ({
            ...item,
            rank: index + 1
        }));
}

async function loadHitParadeReport() {
    const tbody = document.getElementById('hit-parade-body');
    if (!tbody) return;

    const rows = await getHitParadeRows();
    if (rows.length === 0) {
        tbody.innerHTML = '<tr><td colspan="9" style="text-align:center; padding:40px;">Aucune vente article pour ces criteres.</td></tr>';
    } else {
        tbody.innerHTML = rows.map(item => `
            <tr>
                <td style="text-align:center; font-weight:700;">${item.rank}</td>
                <td>${escapeHtml(item.codeArticle)}</td>
                <td>${escapeHtml(item.designation)}</td>
                <td>${escapeHtml(item.forme)}</td>
                <td style="text-align:right;">${formatMoney(item.averagePriceTtc)}</td>
                <td style="text-align:right;">${item.saleCount}</td>
                <td style="text-align:right; font-weight:700;">${formatMoney(item.quantity)}</td>
                <td style="text-align:right;">${formatMoney(item.totalHt)}</td>
                <td style="text-align:right; font-weight:700;">${formatMoney(item.totalTtc)}</td>
            </tr>
        `).join('');
    }

    const totals = rows.reduce((acc, item) => {
        acc.count += 1;
        acc.quantity += item.quantity;
        acc.totalHt += item.totalHt;
        acc.totalTtc += item.totalTtc;
        return acc;
    }, { count: 0, quantity: 0, totalHt: 0, totalTtc: 0 });

    const currentUser = getCurrentBackofficeUser();
    const isAdmin = Boolean(currentUser?.isAdmin);
    const sumCount = document.getElementById('hit-parade-sum-count');
    const sumQty = document.getElementById('hit-parade-sum-qty');
    const sumHt = document.getElementById('hit-parade-sum-ht');
    const sumTtc = document.getElementById('hit-parade-sum-ttc');
    if (sumCount) sumCount.innerText = String(totals.count);
    if (sumQty) sumQty.innerText = formatMoney(totals.quantity);
    if (sumHt) sumHt.innerText = isAdmin ? formatMoney(totals.totalHt) : '---';
    if (sumTtc) sumTtc.innerText = isAdmin ? formatMoney(totals.totalTtc) : '---';
}

async function exportHitParadeToExcel() {
    try {
        if (typeof XLSX === 'undefined') {
            throw new Error('La librairie XLSX n est pas chargee.');
        }
        const rows = await getHitParadeRows();
        if (rows.length === 0) {
            alert('Aucune donnee a exporter.');
            return;
        }

        const exportRows = rows.map(item => ({
            Rang: item.rank,
            CodeArticle: item.codeArticle,
            Designation: item.designation,
            Forme: item.forme,
            PrixMoyenTTC: Number(formatMoney(item.averagePriceTtc)),
            NombreVentes: item.saleCount,
            QuantiteVendue: Number(formatMoney(item.quantity)),
            TotalHT: Number(formatMoney(item.totalHt)),
            TotalTTC: Number(formatMoney(item.totalTtc))
        }));

        const worksheet = XLSX.utils.json_to_sheet(exportRows);
        const workbook = XLSX.utils.book_new();
        XLSX.utils.book_append_sheet(workbook, worksheet, 'Hit Parade');
        XLSX.writeFile(workbook, `hit-parade-${new Date().toISOString().split('T')[0]}.xlsx`);
    } catch (error) {
        console.error('Erreur export hit parade:', error);
        alert(`Export impossible: ${error.message}`);
    }
}

function buildHitParadePrintDocument(rows) {
    const totals = rows.reduce((acc, item) => {
        acc.quantity += item.quantity;
        acc.totalHt += item.totalHt;
        acc.totalTtc += item.totalTtc;
        return acc;
    }, { quantity: 0, totalHt: 0, totalTtc: 0 });
    const filters = getHitParadeFilters();

    return `
        <h1>Hit parade des articles</h1>
        <p>Periode du ${escapeHtml(filters.from || '-')} au ${escapeHtml(filters.to || '-')} | Articles: ${rows.length}</p>
        <table>
            <thead>
                <tr>
                    <th>Rang</th>
                    <th>Code article</th>
                    <th>Designation</th>
                    <th>Forme</th>
                    <th>Prix moyen TTC</th>
                    <th>Nb ventes</th>
                    <th>Quantite vendue</th>
                    <th>CA HT</th>
                    <th>CA TTC</th>
                </tr>
            </thead>
            <tbody>
                ${rows.map(item => `
                    <tr>
                        <td>${item.rank}</td>
                        <td>${escapeHtml(item.codeArticle)}</td>
                        <td>${escapeHtml(item.designation)}</td>
                        <td>${escapeHtml(item.forme)}</td>
                        <td style="text-align:right;">${formatMoney(item.averagePriceTtc)}</td>
                        <td style="text-align:right;">${item.saleCount}</td>
                        <td style="text-align:right;">${formatMoney(item.quantity)}</td>
                        <td style="text-align:right;">${formatMoney(item.totalHt)}</td>
                        <td style="text-align:right;">${formatMoney(item.totalTtc)}</td>
                    </tr>
                `).join('')}
            </tbody>
        </table>
        <p>Total quantite: ${formatMoney(totals.quantity)} | Total HT: ${formatMoney(totals.totalHt)} | Total TTC: ${formatMoney(totals.totalTtc)}</p>
    `;
}

async function printHitParade() {
    const rows = await getHitParadeRows();
    if (rows.length === 0) {
        alert('Aucune donnee a imprimer.');
        return;
    }
    const printWindow = openReportPrintWindow('Hit parade des articles', buildHitParadePrintDocument(rows));
    if (!printWindow) return;
    printWindow.print();
}

function renderSalesTaxReportActionButton(item, kind = 'journal') {
    return `<button class="small-action-btn" type="button" onclick="openSalesTaxReportPrintChoiceModal('${item.id}', '${kind}', event)">Imprimer</button>`;
}

function openSalesTaxReportPrintChoiceModal(itemId, reportKind = 'etat', event) {
    if (event) {
        event.stopPropagation();
    }
    salesTaxReportPrintChoiceState.itemId = String(itemId || '');
    salesTaxReportPrintChoiceState.reportKind = reportKind || 'etat';
    const prefix = getSalesTaxReportPrefix(reportKind || 'etat');
    const modal = document.getElementById(`${prefix}-print-choice-modal`);
    if (!modal) return;
    modal.style.display = 'block';
}

function closeSalesTaxReportPrintChoiceModal(reportKind = 'etat') {
    const prefix = getSalesTaxReportPrefix(reportKind || salesTaxReportPrintChoiceState.reportKind || 'etat');
    const modal = document.getElementById(`${prefix}-print-choice-modal`);
    if (!modal) return;
    modal.style.display = 'none';
}

function confirmSalesTaxReportPrintChoice(documentKind) {
    const reportKind = salesTaxReportPrintChoiceState.reportKind || 'etat';
    closeSalesTaxReportPrintChoiceModal(reportKind);
    executeSalesTaxReportPrintChoice(documentKind);
}

async function buildSalesTaxReportSalePrintPayload(itemId) {
    const rows = await getSalesTaxReportRows(null, null, itemId);
    const sale = rows.find(item => String(item.id) === String(itemId));
    if (!sale) {
        alert('Vente introuvable.');
        return null;
    }

    const totalTtc = Number(sale.total_ttc || sale.totalTtc || 0);
    const paymentMode = sale.mode || inferSaleMode(sale) || (sale.source === 'WEB' ? 'E-COMMERCE' : 'ESPECE');
    const saleType = paymentMode === 'MUTUELLE' ? 'mutuelle' : paymentMode === 'CREDIT' ? 'credit' : 'comptant';
    const breakdown = getSaleMutuelleBreakdown(totalTtc, sale.mutuelles?.taux_remboursement);
    const items = (sale.detailItems || []).map(line => ({
        product_id: line.product_id,
        code_article: line.products?.code_article || '-',
        code_pct: line.products?.code_pct || line.code_pct || '',
        designation: line.products?.designation || '-',
        forme: line.products?.forme || '',
        quantite: Number(line.quantite || 0),
        prix_unitaire_ttc: Number(line.prix_unitaire_ttc || 0),
        tva: Number(line.products?.tva || 0),
        remise: Number(line.remise || 0),
        peremption: line.products?.peremption || null
    }));

    if (!items.length) {
        alert('Aucune ligne article trouvee pour cette vente.');
        return null;
    }

    return {
        sale,
        context: {
            saleType,
            totalHt: Number(sale.total_ht || sale.totalHt || 0),
            totalTva: Number(sale.total_tva || sale.totalTva || 0),
            totalTtc
        },
        customer: sale.customers || { nom: sale.customerName || 'Client passager' },
        mutuelle: sale.mutuelles || null,
        breakdown,
        items,
        paymentMode,
        paymentReference: '',
        paymentName: '',
        paymentEcheance: '',
        received: saleType === 'comptant' ? totalTtc : 0,
        printDate: sale.date_vente || sale.created_at || new Date().toISOString()
    };
}

async function executeSalesTaxReportPrintChoice(documentKind) {
    const itemId = salesTaxReportPrintChoiceState.itemId;
    if (!itemId) return;

    const payload = await buildSalesTaxReportSalePrintPayload(itemId);
    if (!payload) return;

    let printWindow = null;
    if (documentKind === 'invoice') {
        const number = await assignSequentialNumberToSalePrintPayload(payload, 'invoice');
        printWindow = openReportPrintWindow(`Facture ${number || payload.sale.numero_vente || payload.sale.invoiceNumber || 'vente'}`, buildSaleInvoicePrintDocument(payload));
    } else if (documentKind === 'ordonnance') {
        printWindow = openReportPrintWindow(`Ordonnance ${payload.sale.numero_vente || payload.sale.invoiceNumber || 'vente'}`, buildSaleOrdonnancePrintDocument(payload));
    } else if (documentKind === 'delivery_note') {
        const number = await assignSequentialNumberToSalePrintPayload(payload, 'delivery_note');
        printWindow = openReportPrintWindow(`Bon de livraison ${number || payload.sale.numero_vente || payload.sale.invoiceNumber || 'vente'}`, buildSaleDeliveryNotePrintDocument(payload));
    } else if (documentKind === 'quote') {
        const number = await assignSequentialNumberToSalePrintPayload(payload, 'quote');
        printWindow = openReportPrintWindow(`Devis ${number || payload.sale.numero_vente || payload.sale.invoiceNumber || 'vente'}`, buildSaleQuotePrintDocument(payload));
    }

    if (!printWindow) return;
    printWindow.print();
}

function buildSalesTaxReportPrintDocument(kind, rows) {
    const title = kind === 'journal' ? 'Journal des ventes' : 'Etat des ventes';
    const prefix = getSalesTaxReportPrefix(kind);
    const detailed = document.getElementById(`${prefix}-detail`)?.checked !== false;
    return `
        <h1>${title}</h1>
        <p>Periode du ${document.getElementById(`${prefix}-from`)?.value || '-'} au ${document.getElementById(`${prefix}-to`)?.value || '-'}</p>
        <table>
            <thead>
                <tr>
                    <th>Date</th>
                    <th>Exonore</th>
                    <th>Base TVA 7</th>
                    <th>TVA 7</th>
                    <th>Base TVA 13</th>
                    <th>TVA 13</th>
                    <th>Base TVA 19</th>
                    <th>TVA 19</th>
                    <th>Total HT</th>
                    <th>Total TVA</th>
                    <th>Total TTC</th>
                    <th>Nom</th>
                    <th>Type client</th>
                    <th>Numero Facture</th>
                </tr>
            </thead>
            <tbody>${renderSalesTaxReportRows(rows, kind, detailed)}</tbody>
        </table>
    `;
}

async function exportSalesTaxReportToExcel(kind) {
    try {
        if (typeof XLSX === 'undefined') {
            throw new Error('La librairie XLSX n est pas chargee.');
        }

        const rows = await getSalesTaxReportFilteredRows(kind);
        if (rows.length === 0) {
            alert('Aucune donnee a exporter.');
            return;
        }

        const exportRows = rows.map(item => ({
            Date: item.date_vente ? new Date(item.date_vente).toLocaleDateString('fr-FR') : '',
            Exonore: Number(formatMoney(item.tax.exonore)),
            BaseTVA7: Number(formatMoney(item.tax.base7)),
            TVA7: Number(formatMoney(item.tax.tva7)),
            BaseTVA13: Number(formatMoney(item.tax.base13)),
            TVA13: Number(formatMoney(item.tax.tva13)),
            BaseTVA19: Number(formatMoney(item.tax.base19)),
            TVA19: Number(formatMoney(item.tax.tva19)),
            TotalHT: Number(formatMoney(item.totalHt)),
            TotalTVA: Number(formatMoney(item.totalTva)),
            TotalTTC: Number(formatMoney(item.totalTtc)),
            Nom: item.customerName,
            NumeroFacture: item.invoiceNumber
        }));

        const workbook = XLSX.utils.book_new();
        const worksheet = XLSX.utils.json_to_sheet(exportRows);
        XLSX.utils.book_append_sheet(workbook, worksheet, kind === 'journal' ? 'Journal Ventes' : 'Etat Ventes');
        XLSX.writeFile(workbook, `${kind === 'journal' ? 'journal' : 'etat'}-ventes-${new Date().toISOString().split('T')[0]}.xlsx`);
    } catch (error) {
        console.error('Erreur export etat ventes:', error);
        alert(`Export impossible: ${error.message}`);
    }
}

async function printSalesTaxReport(kind) {
    const rows = await getSalesTaxReportFilteredRows(kind);
    if (rows.length === 0) {
        alert('Aucune donnee a imprimer.');
        return;
    }

    const title = kind === 'journal' ? 'Journal des ventes' : 'Etat des ventes';
    const printWindow = openReportPrintWindow(title, buildSalesTaxReportPrintDocument(kind, rows));
    if (!printWindow) return;
    printWindow.print();
}

async function exportSalesTaxReportToPdf(kind) {
    const rows = await getSalesTaxReportFilteredRows(kind);
    if (rows.length === 0) {
        alert('Aucune donnee a exporter en PDF.');
        return;
    }

    const title = kind === 'journal' ? 'Journal des ventes PDF' : 'Etat des ventes PDF';
    const pdfWindow = openReportPrintWindow(title, buildSalesTaxReportPrintDocument(kind, rows));
    if (!pdfWindow) return;
    pdfWindow.print();
}

async function showSalesTaxReportDetail(kind, saleId) {
    const rows = await getSalesTaxReportRows(null, null, saleId);
    const item = rows.find(row => row.id === saleId);
    if (!item) return;

    const prefix = getSalesTaxReportPrefix(kind);
    const modal = document.getElementById(`${prefix}-detail-modal`);
    const content = document.getElementById(`${prefix}-detail-content`);
    if (!modal || !content) return;

    const linesHtml = (item.detailItems || []).length === 0
        ? '<tr><td colspan="6" style="text-align:center; padding:16px;">Aucune ligne trouvee.</td></tr>'
        : item.detailItems.map(line => {
            const qty = Number(line.quantite || 0);
            const unitPrice = Number(line.prix_unitaire_ttc || 0);
            const total = (qty * unitPrice) - Number(line.remise || 0);
            return `
                <tr>
                    <td>${escapeHtml(line.products?.code_article || '-')}</td>
                    <td>${escapeHtml(line.products?.designation || '-')}</td>
                    <td style="text-align:right;">${formatMoney(line.products?.tva || 0)}</td>
                    <td style="text-align:right;">${formatMoney(qty)}</td>
                    <td style="text-align:right;">${formatMoney(unitPrice)}</td>
                    <td style="text-align:right;">${formatMoney(total)}</td>
                </tr>
            `;
        }).join('');

    content.innerHTML = `
        <div class="state-detail-grid state-detail-grid-compact-3">
            <div><strong>Date</strong><div>${item.date_vente ? new Date(item.date_vente).toLocaleString('fr-FR') : '-'}</div></div>
            <div><strong>Numero facture</strong><div>${escapeHtml(item.invoiceNumber)}</div></div>
            <div><strong>Client</strong><div>${escapeHtml(item.customerName)}</div></div>
            <div><strong>Mode</strong><div>${escapeHtml(getModeDisplayLabel(item))}</div></div>
            <div><strong>Total HT</strong><div>${formatMoney(item.totalHt)} DT</div></div>
            <div><strong>Total TVA</strong><div>${formatMoney(item.totalTva)} DT</div></div>
            <div><strong>Total TTC</strong><div>${formatMoney(item.totalTtc)} DT</div></div>
            <div><strong>Mutuelle</strong><div>${escapeHtml(item.mutuelles?.nom || '-')}</div></div>
            <div><strong>Opérateur</strong><div>${escapeHtml(item.created_by || '-')}</div></div>
        </div>
        <div class="state-detail-lines">
            <table class="pos-table">
                <thead>
                    <tr>
                        <th>Code</th>
                        <th>Designation</th>
                        <th style="text-align:right;">TVA %</th>
                        <th style="text-align:right;">Qte</th>
                        <th style="text-align:right;">PU TTC</th>
                        <th style="text-align:right;">Total</th>
                    </tr>
                </thead>
                <tbody>${linesHtml}</tbody>
            </table>
        </div>
    `;

    modal.style.display = 'block';
}

function closeSalesTaxReportDetail(kind) {
    const prefix = getSalesTaxReportPrefix(kind);
    const modal = document.getElementById(`${prefix}-detail-modal`);
    if (modal) modal.style.display = 'none';
}

function renderReportTable(data, type) {
    const tbody = document.getElementById('report-table-body');
    if (!tbody) return;

    if (!Array.isArray(data) || data.length === 0) {
        tbody.innerHTML = '<tr><td colspan="6" style="text-align:center; padding:40px;">Aucune donnee trouvee.</td></tr>';
        const totalEl = document.getElementById('report-total-ttc');
        const countEl = document.getElementById('report-total-count');
        if (totalEl) totalEl.innerText = '0.000 DT';
        if (countEl) countEl.innerText = '0';
        return;
    }

    let totalGeneral = 0;
    const isWeb = type === 'Commandes Web' || type === 'Commandes E-commerce';

    tbody.innerHTML = data.map(item => {
        if (isWeb) {
            const total = Number(item.total_ttc || 0);
            totalGeneral += total;
            return `
                <tr>
                    <td>${escapeHtml(item.order_number)}</td>
                    <td>${item.created_at ? new Date(item.created_at).toLocaleString('fr-FR') : '-'}</td>
                    <td>${escapeHtml(item.customer_name)}</td>
                    <td style="text-align:right; font-weight:600;">${formatMoney(total)}</td>
                    <td>${escapeHtml(item.status || 'Nouvelle')}</td>
                    <td><button class="small-action-btn">Details</button></td>
                </tr>
            `;
        }

        const total = Number(item.total_ttc || item.prix_vente_ttc || 0);
        totalGeneral += total;
        const customerName = item.customers?.nom || item.designation || item.nom || 'Client passager';
        const mode = item.designation ? 'STOCK' : inferSaleMode(item);
        const ref = item.numero_vente || item.code_article || item.numero_achat || '-';
        const dateValue = item.date_vente || item.created_at || item.date_achat;
        const status = item.statut || (item.stock_actuel !== undefined ? `${item.stock_actuel} en stock` : 'Actif');

        return `
            <tr>
                <td>${dateValue ? new Date(dateValue).toLocaleString('fr-FR') : '-'}</td>
                <td>${escapeHtml(ref)}</td>
                <td>${escapeHtml(customerName)}</td>
                <td>${escapeHtml(mode)}</td>
                <td style="text-align:right; font-weight:600;">${formatMoney(total)}</td>
                <td>${escapeHtml(status)}</td>
            </tr>
        `;
    }).join('');

    const totalEl = document.getElementById('report-total-ttc');
    const countEl = document.getElementById('report-total-count');
    if (totalEl) totalEl.innerText = `${formatMoney(totalGeneral)} DT`;
    if (countEl) countEl.innerText = String(data.length);
}

