async function initClientMovementModule() {
    const customerSelect = document.getElementById('client-movement-customer');
    if (customerSelect) {
        const customers = saleState.customers.length > 0 ? saleState.customers : await fetchCollection('customers?select=id,nom,telephone,solde,en_cours,reste_a_payer&order=nom');
        saleState.customers = customers;
        customerSelect.innerHTML = [
            '<option value="">Tous les clients</option>',
            ...customers.map(customer => `<option value="${customer.id}">${escapeHtml(customer.nom)}</option>`)
        ].join('');
    }

    await loadClientMovements();
}

async function loadClientMovements() {
    const tbody = document.getElementById('client-movement-body');
    if (!tbody) return;

    const rows = await getClientMovementFilteredRows();
    const grouping = document.getElementById('client-movement-grouping')?.value || 'none';
    const openingBalance = Number(rows.openingBalance || 0);
    const selectedCustomerId = document.getElementById('client-movement-customer')?.value || '';

    if (rows.length === 0) {
        tbody.innerHTML = '<tr><td colspan="12" style="text-align:center; padding:40px;">Aucun mouvement client.</td></tr>';
        document.getElementById('client-total-count').innerText = '0';
        document.getElementById('client-opening-balance').innerText = `${formatMoney(openingBalance)} DT`;
        document.getElementById('client-total-debit').innerText = '0.000 DT';
        document.getElementById('client-total-credit').innerText = '0.000 DT';
        document.getElementById('client-balance').innerText = `${formatMoney(openingBalance)} DT`;
        await updateClientMovementBalanceHighlight(selectedCustomerId, openingBalance);
        return;
    }

    tbody.innerHTML = renderClientMovementRows(rows, grouping);

    const totals = rows.reduce((acc, item) => {
        acc.count += 1;
        acc.debit += Number(item.debit || 0);
        acc.credit += Number(item.credit || 0);
        acc.balance = item.runningBalance;
        return acc;
    }, { count: 0, debit: 0, credit: 0, balance: 0 });

    document.getElementById('client-total-count').innerText = String(totals.count);
    document.getElementById('client-opening-balance').innerText = `${formatMoney(openingBalance)} DT`;
    document.getElementById('client-total-debit').innerText = `${formatMoney(totals.debit)} DT`;
    document.getElementById('client-total-credit').innerText = `${formatMoney(totals.credit)} DT`;
    
    const balanceEl = document.getElementById('client-balance');
    balanceEl.innerText = `${formatMoney(totals.balance)} DT`;
    if (totals.balance > 400) {
        balanceEl.style.color = '#ef4444';
        balanceEl.style.fontWeight = '900';
    } else {
        balanceEl.style.color = '';
        balanceEl.style.fontWeight = '';
    }

    await updateClientMovementBalanceHighlight(selectedCustomerId, totals.balance);
}

async function updateClientMovementBalanceHighlight(customerId = '', fallbackBalance = 0) {
    const highlightEl = document.getElementById('client-balance-highlight');
    if (!highlightEl) return;

    const balance = customerId
        ? await getClientOutstandingBalance(customerId)
        : Number(fallbackBalance || 0);

    highlightEl.innerText = `${formatMoney(balance)} DT`;
}

async function getClientMovementRows() {
    const cmFrom = document.getElementById('client-movement-from')?.value || null;
    const cmTo = document.getElementById('client-movement-to')?.value || null;
    const { sales: salesData, saleItems, products, webOrders, webOrderItems } = await getSalesReportsBundle(cmFrom, cmTo);
    const productsById = new Map((products || []).map(product => [String(product.id || ''), product]));
    const saleItemsBySaleId = (saleItems || []).reduce((acc, item) => {
        const key = String(item.sale_id || '');
        if (!key) return acc;
        if (!acc[key]) acc[key] = [];
        acc[key].push({
            ...item,
            products: item.products || productsById.get(String(item.product_id || '')) || null
        });
        return acc;
    }, {});
    const webItemsByOrderId = (webOrderItems || []).reduce((acc, item) => {
        const key = String(item.order_id || '');
        if (!key) return acc;
        if (!acc[key]) acc[key] = [];
        acc[key].push({
            ...item,
            products: item.products || productsById.get(String(item.product_id || '')) || null
        });
        return acc;
    }, {});

    const saleRows = salesData
        .filter(item => getCustomerTypeKey(item) !== 'PASSAGER')
        .map(item => {
            const mode = inferSaleMode(item);
            const isMutuelleCredit = isMutuelleClientCreditSale(item);
            const totalTtc = Number(item.total_ttc || 0);
            const rate = Number(item.mutuelles?.taux_remboursement || 0);
            const partMutuelle = mode === 'MUTUELLE' ? (totalTtc * rate / 100) : 0;
            const clientAmount = totalTtc - partMutuelle;
            const isPassager = getCustomerTypeKey(item) === 'PASSAGER';
            const credit = (mode === 'CREDIT' || isMutuelleCredit) ? 0 : clientAmount;
            return {
                ...item,
                client_id: item.client_id || item.customer_id,
                mode: isMutuelleCredit ? 'CREDIT' : mode,
                originalMode: mode,
                customerType: getCustomerTypeKey(item),
                customerTypeLabel: getCustomerTypeLabel(item),
                customerName: item.customers?.nom || (isPassager ? 'Client passager' : 'Client'),
                totalTtc,
                partMutuelle,
                clientAmount,
                debit: clientAmount,
                credit,
                detailItems: saleItemsBySaleId[String(item.id || '')] || []
            };
        });

    const webRows = (webOrders || [])
        .filter(isWebOrderValidated)
        .map(item => {
            const totalTtc = Number(item.total_ttc || 0);
            return {
                ...item,
                id: `web-${item.id}`,
                numero_vente: item.order_number || '-',
                date_vente: item.created_at,
                mode: 'E-COMMERCE',
                customerType: 'WEB',
                customerTypeLabel: 'Client web',
                customerName: item.customer_name || 'Client web',
                customers: { nom: item.customer_name || 'Client web' },
                mutuelles: null,
                totalTtc,
                partMutuelle: 0,
                clientAmount: totalTtc,
                debit: totalTtc,
                credit: totalTtc,
                detailItems: webItemsByOrderId[String(item.id || '')] || []
            };
        });

    const paymentRows = await getCustomerPaymentsRows();

    return enrichClientMovementRowsWithLastDates([...saleRows, ...webRows, ...paymentRows]).sort(compareClientMovementRows);
}

function getClientMovementCustomerKey(item) {
    const id = item?.client_id || item?.customer_id || item?.customerId || '';
    if (id) return `id:${String(id)}`;
    const name = item?.customerName || item?.customers?.nom || '';
    const type = item?.customerType || getCustomerTypeKey(item) || '';
    return name ? `name:${String(type).toUpperCase()}:${normalizeSearchText(name)}` : '';
}

function getClientMovementDateTime(value) {
    if (!value) return 0;
    const time = new Date(value).getTime();
    return Number.isNaN(time) ? 0 : time;
}

function enrichClientMovementRowsWithLastDates(rows = []) {
    const datesByCustomer = new Map();

    rows.forEach(item => {
        const key = getClientMovementCustomerKey(item);
        if (!key) return;
        const time = getClientMovementDateTime(item.date_vente || item.created_at);
        if (!time) return;

        if (!datesByCustomer.has(key)) {
            datesByCustomer.set(key, { lastPurchaseTime: 0, lastPaymentTime: 0 });
        }

        const dates = datesByCustomer.get(key);
        if (String(item.source || '').toUpperCase() === 'PAYMENT' || item.mode === 'REGLEMENT') {
            dates.lastPaymentTime = Math.max(dates.lastPaymentTime, time);
        } else {
            dates.lastPurchaseTime = Math.max(dates.lastPurchaseTime, time);
        }
    });

    return rows.map(item => {
        const dates = datesByCustomer.get(getClientMovementCustomerKey(item)) || {};
        return {
            ...item,
            lastPurchaseDate: dates.lastPurchaseTime ? new Date(dates.lastPurchaseTime).toISOString() : '',
            lastPaymentDate: dates.lastPaymentTime ? new Date(dates.lastPaymentTime).toISOString() : ''
        };
    });
}

function formatClientMovementLastDate(value) {
    if (!value) return '-';
    const date = new Date(value);
    return Number.isNaN(date.getTime()) ? '-' : date.toLocaleDateString('fr-FR');
}

function compareClientMovementRows(a, b) {
    const dateA = new Date(a.date_vente || 0).getTime();
    const dateB = new Date(b.date_vente || 0).getTime();
    if (dateA !== dateB) return dateA - dateB;

    const createdA = new Date(a.created_at || a.date_vente || 0).getTime();
    const createdB = new Date(b.created_at || b.date_vente || 0).getTime();
    if (createdA !== createdB) return createdA - createdB;

    return String(a.numero_vente || a.id || '').localeCompare(String(b.numero_vente || b.id || ''), undefined, { numeric: true });
}

async function getClientMovementFilteredRows() {
    const customerId = document.getElementById('client-movement-customer')?.value || '';
    const mode = document.getElementById('client-movement-mode')?.value || '';
    const customerType = document.getElementById('client-movement-customer-type')?.value || '';
    const from = document.getElementById('client-movement-from')?.value || '';
    const to = document.getElementById('client-movement-to')?.value || '';

    const baseRows = (await getClientMovementRows())
        .filter(item => matchesReportCustomer(item, customerId))
        .filter(item => matchesReportMode(item, mode))
        .filter(item => matchesReportCustomerType(item, customerType));

    const openingBalance = from
        ? baseRows
            .filter(item => {
                const rawDate = getLocalDateKey(item.date_vente);
                return rawDate && rawDate < from;
            })
            .reduce((sum, item) => sum + Number(item.debit || 0) - Number(item.credit || 0), 0)
        : 0;

    let runningBalance = openingBalance;
    const periodRows = baseRows
        .filter(item => matchesReportDateRange(item, from, to))
        .map(item => {
            runningBalance += Number(item.debit || 0) - Number(item.credit || 0);
            return { ...item, runningBalance };
        });

    periodRows.openingBalance = openingBalance;
    return periodRows;
}

function renderClientMovementRows(rows, grouping = 'none', options = {}) {
    const includeCustomerAction = options.includeCustomerAction !== false;
    if (grouping === 'none') {
        return rows.map(item => renderClientMovementDataRow(item, includeCustomerAction)).join('');
    }

    const groupedMap = new Map();
    rows.forEach(item => {
        const key = grouping === 'client'
            ? (item.customerName || item.customers?.nom || 'Client')
            : getModeDisplayLabel(item);
        if (!groupedMap.has(key)) {
            groupedMap.set(key, []);
        }
        groupedMap.get(key).push(item);
    });

    return Array.from(groupedMap.entries()).map(([groupLabel, groupRows]) => {
        const totalColumns = includeCustomerAction ? 12 : 11;
        const subtotalLabelColumns = includeCustomerAction ? 9 : 8;
        const subtotal = groupRows.reduce((acc, item) => {
            acc.debit += item.debit;
            acc.credit += item.credit;
            return acc;
        }, { debit: 0, credit: 0 });
        const balance = subtotal.debit - subtotal.credit;

        return `
            <tr class="statement-group-row">
                <td colspan="${totalColumns}" style="background:#dbeafe; color:#1e3a8a; font-weight:800;">${escapeHtml(groupLabel)} (${groupRows.length})</td>
            </tr>
            ${groupRows.map(item => renderClientMovementDataRow(item, includeCustomerAction)).join('')}
            <tr class="statement-subtotal-row">
                <td colspan="${subtotalLabelColumns}" style="text-align:right; font-weight:800; background:#eff6ff;">Sous-total</td>
                <td style="text-align:right; font-weight:800; background:#eff6ff;">${formatMoney(subtotal.debit)}</td>
                <td style="text-align:right; font-weight:800; background:#eff6ff;">${formatMoney(subtotal.credit)}</td>
                <td style="text-align:right; font-weight:800; background:#eff6ff;">${formatMoney(balance)}</td>
            </tr>
        `;
    }).join('');
}

function renderClientMovementCustomerFicheButton(item) {
    const customerId = item?.client_id || item?.customer_id || '';
    if (!customerId) return '-';
    return `<button class="small-action-btn" type="button" onclick="event.stopPropagation(); showClientMovementCustomerFiche('${escapeHtml(String(customerId))}')">Fiche</button>`;
}

function renderClientMovementDataRow(item, includeCustomerAction = true) {
    const mode = String(item.mode || item.saleType || '').toUpperCase();
    const isPayment = item.source === 'PAYMENT' || mode === 'REGLEMENT';
    const isCredit = mode === 'CREDIT';
    const isMutuelle = mode === 'MUTUELLE';
    const isComptant = mode === 'COMPTANT';
    const rowBg = isPayment ? '#dcfce7' : isCredit ? '#fee2e2' : isMutuelle ? '#ede9fe' : isComptant ? '#dbeafe' : '#f3f4f6';
    return `
        <tr onclick="showClientMovementDetail('${item.id}')" style="cursor:pointer; background:${rowBg};">
            <td style="border:none; padding:7px 10px;">${item.date_vente ? new Date(item.date_vente).toLocaleString('fr-FR') : '-'}</td>
            <td style="border:none; padding:7px 10px;">${escapeHtml(item.numero_vente || '-')}</td>
            <td style="border:none; padding:7px 10px;">${escapeHtml(item.customerName || item.customers?.nom || 'Client')}</td>
            ${includeCustomerAction ? `<td style="border:none; padding:7px 10px; text-align:center;" onclick="event.stopPropagation();">${renderClientMovementCustomerFicheButton(item)}</td>` : ''}
            <td style="border:none; padding:7px 10px;">${formatClientMovementLastDate(item.lastPurchaseDate)}</td>
            <td style="border:none; padding:7px 10px;">${formatClientMovementLastDate(item.lastPaymentDate)}</td>
            <td style="border:none; padding:7px 10px; text-align:center; white-space:nowrap;">${renderCustomerTypeBadge(item)}</td>
            <td style="border:none; padding:7px 10px; font-weight:700; color:${isPayment ? '#16a34a' : isCredit ? '#dc2626' : isMutuelle ? '#7c3aed' : isComptant ? '#1d4ed8' : '#374151'};">${escapeHtml(getModeDisplayLabel(item))}</td>
            <td style="border:none; padding:7px 10px;">${escapeHtml(item.mutuelles?.nom || '-')}</td>
            <td style="border:none; padding:7px 10px; text-align:right; color:#dc2626; font-weight:700;">${formatMoney(item.debit)}</td>
            <td style="border:none; padding:7px 10px; text-align:right; color:#16a34a; font-weight:700;">${formatMoney(item.credit)}</td>
            <td style="border:none; padding:7px 10px; text-align:right; font-weight:800; background-color:#e0f2fe; color:#0369a1;">${formatMoney(item.runningBalance)}</td>
        </tr>
    `;
}

function renderClientMovementDetailItemsTable(items = []) {
    if (!Array.isArray(items) || items.length === 0) {
        return '<div style="margin-top:16px; padding:14px; border:1px dashed #cbd5e1; border-radius:12px; text-align:center; color:#64748b;">Aucune ligne detaillee pour cette vente.</div>';
    }

    const rowsHtml = items.map(line => {
        const qty = Number(line.quantite || line.quantity || 0);
        const unitPrice = Number(line.prix_unitaire_ttc || line.unit_price || 0);
        const remise = Number(line.remise || 0);
        const totalLine = Math.max(0, (qty * unitPrice) - remise);

        return `
            <tr>
                <td>${escapeHtml(line.products?.code_article || '-')}</td>
                <td>${escapeHtml(line.products?.designation || '-')}</td>
                <td style="text-align:right;">${formatMoney(qty)}</td>
                <td style="text-align:right;">${formatMoney(unitPrice)}</td>
                <td style="text-align:right;">${formatMoney(remise)}</td>
                <td style="text-align:right; font-weight:700;">${formatMoney(totalLine)}</td>
            </tr>
        `;
    }).join('');

    return `
        <div style="margin-top:18px;">
            <div style="font-size:13px; font-weight:800; color:#0f172a; margin-bottom:10px;">Detail de la vente</div>
            <div style="border:1px solid #e2e8f0; border-radius:12px; overflow:hidden;">
                <table class="pos-table" style="margin:0;">
                    <thead>
                        <tr>
                            <th>Code</th>
                            <th>Designation</th>
                            <th style="text-align:right;">Qte</th>
                            <th style="text-align:right;">PU TTC</th>
                            <th style="text-align:right;">Remise</th>
                            <th style="text-align:right;">Total</th>
                        </tr>
                    </thead>
                    <tbody>${rowsHtml}</tbody>
                </table>
            </div>
        </div>
    `;
}

function getClientMovementPeriodLabel() {
    const from = document.getElementById('client-movement-from')?.value || '';
    const to = document.getElementById('client-movement-to')?.value || '';
    if (from && to) return `Periode du ${from} au ${to}`;
    if (from) return `Periode a partir du ${from}`;
    if (to) return `Periode jusqu'au ${to}`;
    return 'Toutes les periodes';
}

function buildClientMovementPrintDocument(rows, grouping = 'none') {
    const openingBalance = Number(rows.openingBalance || 0);
    const totals = rows.reduce((acc, item) => {
        acc.count += 1;
        acc.debit += Number(item.debit || 0);
        acc.credit += Number(item.credit || 0);
        acc.balance = item.runningBalance;
        return acc;
    }, { count: 0, debit: 0, credit: 0, balance: openingBalance });

    return `
        <h1>Mouvement clients</h1>
        <p>${escapeHtml(getClientMovementPeriodLabel())}</p>
        <p>Solde initial: ${formatMoney(openingBalance)} DT | Total periode: ${formatMoney(totals.debit)} DT | Regle: ${formatMoney(totals.credit)} DT | Solde: ${formatMoney(totals.balance)} DT | Nb mouvements: ${totals.count}</p>
        <table>
            <thead>
                <tr>
                    <th>Date</th>
                    <th>Numero</th>
                    <th>Client</th>
                    <th>Dernier achat</th>
                    <th>Dernier reglement</th>
                    <th>Type client</th>
                    <th>Type</th>
                    <th>Mutuelle</th>
                    <th>Debit</th>
                    <th>Credit</th>
                    <th>Solde</th>
                </tr>
            </thead>
            <tbody>
                ${renderClientMovementRows(rows, grouping, { includeCustomerAction: false })}
            </tbody>
        </table>
    `;
}

async function exportClientMovementsToExcel() {
    try {
        if (typeof XLSX === 'undefined') {
            throw new Error('La librairie XLSX n est pas chargee.');
        }

        const rows = await getClientMovementFilteredRows();
        if (rows.length === 0) {
            alert('Aucune donnee a exporter.');
            return;
        }

        const exportRows = rows.map(item => ({
            Date: item.date_vente ? new Date(item.date_vente).toLocaleString('fr-FR') : '',
            Numero: item.numero_vente || '',
            Client: item.customerName || item.customers?.nom || 'Client',
            DernierAchat: formatClientMovementLastDate(item.lastPurchaseDate),
            DernierReglement: formatClientMovementLastDate(item.lastPaymentDate),
            TypeClient: item.customerTypeLabel || getCustomerTypeLabel(item),
            Type: getModeDisplayLabel(item),
            Mutuelle: item.mutuelles?.nom || '',
            Debit: Number(formatMoney(item.debit)),
            Credit: Number(formatMoney(item.credit)),
            Solde: Number(formatMoney(item.runningBalance))
        }));

        const worksheet = XLSX.utils.json_to_sheet(exportRows);
        const workbook = XLSX.utils.book_new();
        XLSX.utils.book_append_sheet(workbook, worksheet, 'Mouvement Clients');
        XLSX.writeFile(workbook, `mouvement-clients-${new Date().toISOString().split('T')[0]}.xlsx`);
    } catch (error) {
        console.error('Erreur export mouvement clients:', error);
        alert(`Export impossible: ${error.message}`);
    }
}

async function printClientMovements() {
    const rows = await getClientMovementFilteredRows();
    if (rows.length === 0 && Math.abs(Number(rows.openingBalance || 0)) < 0.0009) {
        alert('Aucune donnee a imprimer.');
        return;
    }

    const grouping = document.getElementById('client-movement-grouping')?.value || 'none';
    const printWindow = openReportPrintWindow('Mouvement clients', buildClientMovementPrintDocument(rows, grouping));
    if (!printWindow) return;
    printWindow.print();
}

async function exportClientMovementsToPdf() {
    const rows = await getClientMovementFilteredRows();
    if (rows.length === 0 && Math.abs(Number(rows.openingBalance || 0)) < 0.0009) {
        alert('Aucune donnee a exporter en PDF.');
        return;
    }

    const grouping = document.getElementById('client-movement-grouping')?.value || 'none';
    const pdfWindow = openReportPrintWindow('Mouvement clients PDF', buildClientMovementPrintDocument(rows, grouping));
    if (!pdfWindow) return;
    pdfWindow.print();
}

