async function loadCaisseRecap() {
    window.SUPABASE_CACHE?.invalidate?.('sales');
    window.SUPABASE_CACHE?.invalidate?.('rpc:get_sales_reports_bundle');
    let recap;
    try { recap = await getCaisseRecapData(); } catch (e) { console.warn('loadCaisseRecap error:', e); return; }
    const tbody = document.getElementById('caisse-recap-body');
    const detailBody = document.getElementById('caisse-recap-detail-body');
    if (tbody) {
        tbody.innerHTML = recap.paymentRows.map((row, index) => {
            const rowBackground = row.isTotal
                ? 'linear-gradient(180deg,#eff6ff 0%,#f8fbff 100%)'
                : index % 2 === 0
                    ? '#f8fbff'
                    : '#ffffff';
            const cellColor = row.isTotal ? '#1d4ed8' : '#2563eb';
            return `
                <tr class="${row.isTotal ? 'is-total' : ''}" style="background:${rowBackground};">
                    <td style="padding:14px 16px; border-bottom:1px solid #edf2f7; color:${cellColor}; font-weight:800; font-size:15px;">${escapeHtml(row.label)}</td>
                    <td style="padding:14px 16px; border-bottom:1px solid #edf2f7; text-align:right; color:${cellColor}; font-weight:800; font-size:15px;">${formatMoney(row.cash)}</td>
                    <td style="padding:14px 16px; border-bottom:1px solid #edf2f7; text-align:right; color:${cellColor}; font-weight:800; font-size:15px;">${formatMoney(row.creditMutuelle)}</td>
                    <td style="padding:14px 16px; border-bottom:1px solid #edf2f7; text-align:right; color:${cellColor}; font-weight:800; font-size:15px; background:${row.isTotal ? '#dbeafe' : 'transparent'};">${formatMoney(row.total)}</td>
                </tr>
            `;
        }).join('');
    }
    if (detailBody) {
        const detailRows = getCaisseRecapRowsForMode(recap, caisseRecapModeFilter);
        detailBody.innerHTML = detailRows.length > 0
            ? detailRows.map(item => `
                <tr onclick="showCaisseRecapSaleDetail('${escapeHtml(String(item.id || ''))}')" style="cursor:pointer;">
                    <td style="padding:10px 12px; border-bottom:1px solid #edf2f7;">${escapeHtml(item.numero)}</td>
                    <td style="padding:10px 12px; border-bottom:1px solid #edf2f7;">${escapeHtml(item.date)}</td>
                    <td style="padding:10px 12px; border-bottom:1px solid #edf2f7;">${escapeHtml(item.client)}</td>
                    <td style="padding:10px 12px; border-bottom:1px solid #edf2f7; color:#2563eb; font-weight:700;">${escapeHtml(getModeDisplayLabel(item))}</td>
                    <td style="padding:10px 12px; border-bottom:1px solid #edf2f7; text-align:right; font-weight:700;">${formatMoney(item.total)}</td>
                </tr>
            `).join('')
            : `<tr><td colspan="5" style="text-align:center; padding:18px; color:#64748b;">Aucune vente pour ce filtre.</td></tr>`;
    }

    const salesCountNode = document.getElementById('caisse-total-sales');
    const fondNode = document.getElementById('caisse-fond-caisse');
    const theoriqueNode = document.getElementById('caisse-total-theorique');
    const comptantNode = document.getElementById('caisse-total-comptant');
    const mutuelleNode = document.getElementById('caisse-total-mutuelle');
    const creditNode = document.getElementById('caisse-total-credit');
    const webNode = document.getElementById('caisse-total-web');
    const cnamNode = document.getElementById('caisse-total-cnam');
    const retourNode = document.getElementById('caisse-retour-ventes');
    const remiseReglementsNode = document.getElementById('caisse-remise-reglements');
    const remiseVentesNode = document.getElementById('caisse-remise-ventes');

    if (salesCountNode) salesCountNode.innerText = String(recap.totalCount);
    if (fondNode) fondNode.innerText = formatMoney(recap.fondCaisse);
    if (theoriqueNode) theoriqueNode.innerText = formatMoney(recap.totalTheorique);
    if (comptantNode) comptantNode.innerText = formatMoney(recap.groups.COMPTANT.amount + recap.groups['E-COMMERCE'].amount);
    if (mutuelleNode) mutuelleNode.innerText = formatMoney(recap.groups.MUTUELLE.amount);
    if (creditNode) creditNode.innerText = formatMoney(recap.groups.CREDIT.amount);
    if (webNode) webNode.innerText = formatMoney(recap.groups['E-COMMERCE'].amount);
    if (cnamNode) cnamNode.innerText = formatMoney(recap.cnamAmount);
    if (retourNode) retourNode.innerText = formatMoney(recap.returnAmount);
    if (remiseReglementsNode) remiseReglementsNode.innerText = formatMoney(recap.reglementClientAmount);
    if (remiseVentesNode) remiseVentesNode.innerText = formatMoney(recap.remiseVentes);

    updateCaissePhysicalDifference();
    updateCaisseRecapFilterButtons();

    const sideButtons = document.querySelectorAll('.recap-caisse-right .recap-caisse-side-row span');
    sideButtons.forEach(button => {
        const label = normalizeSearchText(button.textContent || '');
        let mode = '';
        if (label.includes('comptant')) mode = 'COMPTANT';
        if (label.includes('vente web')) mode = 'E-COMMERCE';
        if (label.includes('retour')) mode = 'RETURN_SALES';
        if (label.includes('reglement') && label.includes('client')) mode = 'CUSTOMER_SETTLEMENTS';
        if (label.includes('remise') && label.includes('vente')) mode = 'DISCOUNT_SALES';
        if (label.includes('mutuelle')) mode = 'MUTUELLE';
        if (label.includes('credit')) mode = 'CREDIT';
        if (!mode) return;
        button.onclick = () => openCaisseSalesModal(mode);
        button.style.cursor = 'pointer';
        button.onmouseenter = () => {
            button.style.filter = 'brightness(1.08)';
        };
        button.onmouseleave = () => {
            button.style.filter = '';
        };
    });
}

function getCaisseSaleFilterValue() {
    return document.querySelector('input[name="caisse-sale-filter"]:checked')?.value || 'filled';
}

function getCaisseVidageRecords() {
    try {
        const raw = localStorage.getItem(CAISSE_VIDAGE_STORAGE_KEY);
        const rows = raw ? JSON.parse(raw) : [];
        return Array.isArray(rows) ? rows : [];
    } catch (error) {
        console.warn('Lecture vidage caisse impossible.', error);
        return [];
    }
}

function saveCaisseVidageRecords(records) {
    try {
        localStorage.setItem(CAISSE_VIDAGE_STORAGE_KEY, JSON.stringify(Array.isArray(records) ? records : []));
    } catch (error) {
        console.warn('Enregistrement vidage caisse impossible.', error);
    }
}

function getCaisseEmptiedSaleIds() {
    const ids = new Set();
    getCaisseVidageRecords().forEach(record => {
        (record.saleIds || []).forEach(id => ids.add(String(id)));
    });
    return ids;
}

async function requestCaisseVidage() {
    const recap = await getCaisseRecapData({ includeEmptied: false });
    const rows = getCaisseRecapRowsForMode(recap, 'ALL');
    const saleIds = Array.from(new Set(rows.map(item => String(item.id || '')).filter(Boolean)));

    if (!saleIds.length) {
        alert('Aucune vente non videe a vider sur cette periode.');
        return;
    }

    const confirmed = confirm(`Confirmer le vidage de caisse pour ${saleIds.length} vente(s) ?\n\nLes ventes seront masquees du filtre "Non videes".`);
    if (!confirmed) return;

    const records = getCaisseVidageRecords();
    records.unshift({
        id: `VID-${new Date().toISOString()}`,
        from: recap.from || '',
        to: recap.to || '',
        created_at: new Date().toISOString(),
        total: recap.totalAmount || 0,
        saleIds
    });
    saveCaisseVidageRecords(records);

    const filledRadio = document.querySelector('input[name="caisse-sale-filter"][value="filled"]');
    if (filledRadio) filledRadio.checked = true;
    clearCaissePhysicalInput();
    await loadCaisseRecap();
    alert('Vidage caisse enregistre.');
}

async function getCaisseRecapData(options = {}) {
    const from = document.getElementById('caisse-from')?.value || '';
    const to = document.getElementById('caisse-to')?.value || '';
    const { sales, saleItems, products, webOrders, webOrderItems } = await getSalesReportsBundle(from || null, to || null);
    let customerPayments = [];
    try { customerPayments = await getCustomerPaymentsRows(); } catch (e) { console.warn('customer_payments fallback:', e); }
    const productsById = new Map((products || []).map(product => [String(product.id || ''), product]));
    const saleItemsBySaleId = (saleItems || []).reduce((acc, item) => {
        const key = String(item.sale_id || '');
        if (!key) return acc;
        if (!acc[key]) acc[key] = [];
        acc[key].push({
            ...item,
            products: item.products || productsById.get(String(item.product_id || '')) || null
        });
        return acc;
    }, {});
    const webItemsByOrderId = (webOrderItems || []).reduce((acc, item) => {
        const key = String(item.order_id || '');
        if (!key) return acc;
        if (!acc[key]) acc[key] = [];
        acc[key].push({
            ...item,
            quantite: Number(item.quantity || 0),
            prix_unitaire_ttc: Number(item.unit_price || 0),
            remise: 0,
            products: item.products || productsById.get(String(item.product_id || '')) || null
        });
        return acc;
    }, {});

    const emptiedSaleIds = getCaisseEmptiedSaleIds();
    const showEmptied = options.includeEmptied === true || getCaisseSaleFilterValue() === 'all';

    const filteredSales = sales.filter(item => {
        if (!showEmptied && emptiedSaleIds.has(String(item.id || ''))) return false;
        const saleDate = getLocalDateKey(item.date_vente);
        if (from && saleDate < from) return false;
        if (to && saleDate > to) return false;
        return true;
    });

    const filteredWebOrders = webOrders
        .filter(isWebOrderValidated)
        .filter(item => {
            if (!showEmptied && emptiedSaleIds.has(`web-${String(item.id || '')}`)) return false;
            const orderDate = getLocalDateKey(item.created_at);
            if (from && orderDate < from) return false;
            if (to && orderDate > to) return false;
            return true;
        });
    const filteredCustomerPayments = customerPayments.filter(item => {
        const paymentDate = getLocalDateKey(item.date_vente || item.payment_date || item.created_at);
        if (from && paymentDate < from) return false;
        if (to && paymentDate > to) return false;
        return true;
    });

    const groups = {
        COMPTANT: { count: 0, amount: 0 },
        CREDIT: { count: 0, amount: 0 },
        MUTUELLE: { count: 0, amount: 0 },
        'E-COMMERCE': { count: 0, amount: 0 }
    };

    const salesComptantByMode = {
        ESPECE: 0,
        CHEQUE: 0,
        CARTE: 0,
        TRAITE: 0,
        VIREMENT: 0
    };

    filteredSales.forEach(item => {
        const mode = inferSaleMode(item);
        const totalTtc = Number(item.total_ttc || 0);
        const rate = Number(item.mutuelles?.taux_remboursement || 0);
        const partMutuelle = mode === 'MUTUELLE' ? (totalTtc * rate / 100) : 0;
        const clientAmount = totalTtc - partMutuelle;
        const isMutuelleCredit = isMutuelleClientCreditSale(item);

        if (mode === 'MUTUELLE') {
            groups.MUTUELLE.count += 1;
            groups.MUTUELLE.amount += partMutuelle;
            if (isMutuelleCredit) {
                groups.CREDIT.count += 1;
                groups.CREDIT.amount += clientAmount;
            } else {
                groups.COMPTANT.count += 1;
                groups.COMPTANT.amount += clientAmount;
                const pMode = String(item.payment_mode || 'ESPECE').toUpperCase();
                const key = pMode === 'ESPECES' ? 'ESPECE' : pMode;
                if (salesComptantByMode[key] !== undefined) {
                    salesComptantByMode[key] += clientAmount;
                } else {
                    salesComptantByMode.ESPECE += clientAmount;
                }
            }
            return;
        }

        groups[mode].count += 1;
        groups[mode].amount += totalTtc;

        if (mode === 'COMPTANT') {
            const pMode = String(item.payment_mode || 'ESPECE').toUpperCase();
            const key = pMode === 'ESPECES' ? 'ESPECE' : pMode;
            if (salesComptantByMode[key] !== undefined) {
                salesComptantByMode[key] += totalTtc;
            } else {
                salesComptantByMode.ESPECE += totalTtc;
            }
        }
    });

    filteredWebOrders.forEach(item => {
        groups['E-COMMERCE'].count += 1;
        groups['E-COMMERCE'].amount += Number(item.total_ttc || 0);

        const pMode = String(item.payment_mode || 'ESPECE').toUpperCase();
        let key = 'ESPECE';
        if (pMode.includes('CARTE') || pMode.includes('STRIPE') || pMode.includes('EN LIGNE')) {
            key = 'CARTE';
        } else if (pMode.includes('CHEQUE')) {
            key = 'CHEQUE';
        } else if (pMode.includes('VIREMENT')) {
            key = 'VIREMENT';
        } else if (pMode.includes('TRAITE')) {
            key = 'TRAITE';
        }
        if (salesComptantByMode[key] !== undefined) {
            salesComptantByMode[key] += Number(item.total_ttc || 0);
        } else {
            salesComptantByMode.ESPECE += Number(item.total_ttc || 0);
        }
    });

    const totalCount = filteredSales.length + filteredWebOrders.length;
    const totalAmount = filteredSales.reduce((sum, item) => sum + Number(item.total_ttc || 0), 0)
        + filteredWebOrders.reduce((sum, item) => sum + Number(item.total_ttc || 0), 0);
    const saleLineAdjustments = filteredSales.reduce((acc, sale) => {
        const lines = saleItemsBySaleId[String(sale.id || '')] || [];
        if (!lines.length && Number(sale.total_ttc || 0) < 0) {
            acc.returns += Math.abs(Number(sale.total_ttc || 0));
            return acc;
        }

        lines.forEach(line => {
            const qty = Number(line.quantite || 0);
            const unitPrice = Number(line.prix_unitaire_ttc || 0);
            const remise = Math.max(0, Number(line.remise || 0));
            if (qty < 0) {
                acc.returns += Math.abs(qty * unitPrice);
            } else {
                acc.remises += remise;
            }
        });
        return acc;
    }, { returns: 0, remises: 0 });

    const cashAmount = groups.COMPTANT.amount + groups['E-COMMERCE'].amount;
    const clientSettlementByMode = filteredCustomerPayments.reduce((acc, item) => {
        const mode = String(item.payment_mode || item.paymentMode || 'ESPECE').toUpperCase();
        const key = mode === 'ESPECES' ? 'ESPECE' : mode;
        acc[key] = (acc[key] || 0) + Number(item.credit || item.amount || 0);
        return acc;
    }, {});
    const clientSettlementAmount = Object.values(clientSettlementByMode).reduce((sum, amount) => sum + Number(amount || 0), 0);
    const creditMutuelleAmount = groups.CREDIT.amount + groups.MUTUELLE.amount;
    const customerSettlementRows = filteredCustomerPayments.map(item => ({
        id: String(item.id || ''),
        source: 'PAYMENT',
        numero: item.numero_vente || item.payment_number || item.id || '-',
        date: item.date_vente ? new Date(item.date_vente).toLocaleDateString('fr-FR') : '-',
        client: item.customerName || item.customers?.nom || 'Client',
        mode: 'CUSTOMER_SETTLEMENTS',
        displayMode: item.payment_mode || 'REGLEMENT',
        total: Number(item.credit || item.amount || 0),
        paymentReference: item.paymentReference || item.reference || '',
        paymentNote: item.paymentNote || item.note || ''
    }));
    const detailRows = [
        ...filteredSales.flatMap(item => {
            const mode = inferSaleMode(item);
            const totalTtc = Number(item.total_ttc || 0);
            const rate = Number(item.mutuelles?.taux_remboursement || 0);
            const partMutuelle = mode === 'MUTUELLE' ? (totalTtc * rate / 100) : 0;
            const clientAmount = totalTtc - partMutuelle;
            const detailItems = saleItemsBySaleId[String(item.id || '')] || [];
            const returnAmount = detailItems.length
                ? detailItems.reduce((sum, line) => {
                    const qty = Number(line.quantite || 0);
                    return qty < 0 ? sum + Math.abs(qty * Number(line.prix_unitaire_ttc || 0)) : sum;
                }, 0)
                : Math.max(0, -totalTtc);
            const discountAmount = detailItems.reduce((sum, line) => {
                const qty = Number(line.quantite || 0);
                return qty < 0 ? sum : sum + Math.max(0, Number(line.remise || 0));
            }, 0);
            const baseRow = {
                id: String(item.id || ''),
                numero: item.numero_vente || item.id || '-',
                date: item.date_vente ? new Date(item.date_vente).toLocaleDateString('fr-FR') : '-',
                client: item.customers?.nom || 'Client',
                customerTypeLabel: getCustomerTypeLabel(item),
                mutuelle: item.mutuelles?.nom || '-',
                detailItems,
                totalHt: Number(item.total_ht || 0),
                totalTva: Number(item.total_tva || 0),
                totalTtc,
                hasReturn: returnAmount > 0,
                returnAmount,
                hasDiscount: discountAmount > 0,
                discountAmount
            };

            if (mode !== 'MUTUELLE') {
                const pMode = String(item.payment_mode || 'ESPECE').toUpperCase();
                const displaySuffix = pMode === 'ESPECES' ? 'ESPECE' : pMode;
                return [{
                    ...baseRow,
                    mode,
                    displayMode: mode === 'COMPTANT' ? `COMPTANT / ${displaySuffix}` : getSaleDisplayModeLabel(item),
                    total: totalTtc
                }];
            }

            const rows = [{
                ...baseRow,
                mode: 'MUTUELLE',
                displayMode: 'MUTUELLE',
                total: partMutuelle
            }];

            const pMode = String(item.payment_mode || 'ESPECE').toUpperCase();
            const displaySuffix = pMode === 'ESPECES' ? 'ESPECE' : pMode;
            rows.push({
                ...baseRow,
                mode: isMutuelleClientCreditSale(item) ? 'CREDIT' : 'COMPTANT',
                displayMode: isMutuelleClientCreditSale(item) ? 'MUTUELLE / CREDIT' : `MUTUELLE / COMPTANT / ${displaySuffix}`,
                total: clientAmount
            });

            return rows;
        }),
        ...filteredWebOrders.map(item => ({
            id: `web-${item.id}`,
            numero: item.order_number || item.id || '-',
            date: item.created_at ? new Date(item.created_at).toLocaleDateString('fr-FR') : '-',
            client: item.customer_name || 'Client web',
            mode: 'E-COMMERCE',
            displayMode: 'VENTE WEB',
            customerTypeLabel: 'Client web',
            mutuelle: '-',
            detailItems: webItemsByOrderId[String(item.id || '')] || [],
            totalHt: (webItemsByOrderId[String(item.id || '')] || []).reduce((sum, line) => {
                const qty = Number(line.quantite || 0);
                const lineTtc = qty * Number(line.prix_unitaire_ttc || 0);
                const rate = Number(line.products?.tva || 0);
                return sum + (rate > 0 ? (lineTtc / (1 + (rate / 100))) : lineTtc);
            }, 0),
            totalTva: (webItemsByOrderId[String(item.id || '')] || []).reduce((sum, line) => {
                const qty = Number(line.quantite || 0);
                const lineTtc = qty * Number(line.prix_unitaire_ttc || 0);
                const rate = Number(line.products?.tva || 0);
                if (!(rate > 0)) return sum;
                const base = lineTtc / (1 + (rate / 100));
                return sum + (lineTtc - base);
            }, 0),
            totalTtc: Number(item.total_ttc || 0),
            total: Number(item.total_ttc || 0)
        }))
    ];
    const remiseReglementRows = [
        ...detailRows
            .filter(item => item.hasDiscount)
            .map(item => ({
                ...item,
                mode: 'CUSTOMER_SETTLEMENTS',
                displayMode: 'REMISE VENTE',
                total: item.discountAmount || 0
            })),
        ...customerSettlementRows
    ];
    const paymentRows = [
        { label: 'Espece', cash: salesComptantByMode.ESPECE, creditMutuelle: clientSettlementByMode.ESPECE || 0, total: salesComptantByMode.ESPECE + (clientSettlementByMode.ESPECE || 0) },
        { label: 'Cheque', cash: salesComptantByMode.CHEQUE, creditMutuelle: clientSettlementByMode.CHEQUE || 0, total: salesComptantByMode.CHEQUE + (clientSettlementByMode.CHEQUE || 0) },
        { label: 'Carte', cash: salesComptantByMode.CARTE, creditMutuelle: clientSettlementByMode.CARTE || 0, total: salesComptantByMode.CARTE + (clientSettlementByMode.CARTE || 0) },
        { label: 'Traite', cash: salesComptantByMode.TRAITE, creditMutuelle: clientSettlementByMode.TRAITE || 0, total: salesComptantByMode.TRAITE + (clientSettlementByMode.TRAITE || 0) },
        { label: 'Virement', cash: salesComptantByMode.VIREMENT, creditMutuelle: clientSettlementByMode.VIREMENT || 0, total: salesComptantByMode.VIREMENT + (clientSettlementByMode.VIREMENT || 0) },
        { label: 'Totaux', cash: cashAmount, creditMutuelle: clientSettlementAmount, total: cashAmount + clientSettlementAmount, isTotal: true }
    ];

    return {
        from,
        to,
        groups,
        detailRows,
        customerSettlementRows,
        remiseReglementRows,
        paymentRows,
        totalCount,
        totalAmount,
        totalTheorique: cashAmount + clientSettlementAmount,
        fondCaisse: 0,
        cnamAmount: 0,
        returnAmount: saleLineAdjustments.returns,
        remiseReglements: clientSettlementAmount + saleLineAdjustments.remises,
        reglementClientAmount: clientSettlementAmount,
        reglementClientRows: customerSettlementRows,
        remiseVentes: saleLineAdjustments.remises
    };
}

function setCaisseRecapModeFilter(mode = 'ALL') {
    caisseRecapModeFilter = mode || 'ALL';
    loadCaisseRecap();
}

function getCaisseRecapModeLabel(mode = 'ALL') {
    if (mode === 'COMPTANT') return 'Ventes au comptant';
    if (mode === 'E-COMMERCE') return 'Ventes WEB';
    if (mode === 'MUTUELLE') return 'Ventes mutuelle';
    if (mode === 'CREDIT') return 'Ventes crédit';
    return 'Toutes les ventes';
}

function getCaisseRecapRowsForMode(recap, mode = 'ALL') {
    const rows = Array.isArray(recap?.detailRows) ? recap.detailRows : [];
    if (mode === 'CUSTOMER_SETTLEMENTS') {
        return Array.isArray(recap?.reglementClientRows) ? recap.reglementClientRows : [];
    }
    if (mode === 'RETURN_SALES' || mode === 'DISCOUNT_SALES') {
        const seen = new Set();
        return rows
            .filter(item => mode === 'RETURN_SALES' ? item.hasReturn : item.hasDiscount)
            .filter(item => {
                const key = String(item.id || '');
                if (!key || seen.has(key)) return false;
                seen.add(key);
                return true;
            })
            .map(item => ({
                ...item,
                total: mode === 'RETURN_SALES' ? item.returnAmount : item.discountAmount
            }));
    }
    return rows.filter(item => mode === 'ALL' || item.mode === mode);
}

async function openCaisseSalesModal(mode = 'ALL') {
    const modal = document.getElementById('caisse-sales-modal');
    const titleNode = document.getElementById('caisse-sales-modal-title');
    const subtitleNode = document.getElementById('caisse-sales-modal-subtitle');
    const bodyNode = document.getElementById('caisse-sales-modal-body');
    const totalNode = document.getElementById('caisse-sales-modal-total');
    if (!modal || !titleNode || !subtitleNode || !bodyNode || !totalNode) return;

    caisseRecapModeFilter = mode || 'ALL';
    updateCaisseRecapFilterButtons();

    const recap = await getCaisseRecapData();
    const filteredRows = getCaisseRecapRowsForMode(recap, caisseRecapModeFilter);
    const total = filteredRows.reduce((sum, item) => sum + Number(item.total || 0), 0);

    titleNode.innerText = caisseRecapModeFilter === 'RETURN_SALES'
        ? 'Retour/Ventes'
        : caisseRecapModeFilter === 'DISCOUNT_SALES'
            ? 'Remise/Ventes'
            : caisseRecapModeFilter === 'CUSTOMER_SETTLEMENTS'
                ? 'REGLEMENT CLIENT'
                : getCaisseRecapModeLabel(caisseRecapModeFilter);
    subtitleNode.innerText = `${filteredRows.length} opération(s) trouvée(s) sur la période sélectionnée.`;
    totalNode.innerText = `Total : ${formatMoney(total)}`;
    bodyNode.innerHTML = filteredRows.length > 0
        ? filteredRows.map(item => `
            <tr class="caisse-modal-row" ${item.source === 'PAYMENT' ? '' : `onclick="showCaisseRecapSaleDetail('${escapeHtml(String(item.id || ''))}')"`} style="${item.source === 'PAYMENT' ? '' : 'cursor:pointer;'}">
                <td class="caisse-modal-cell caisse-modal-cell-number">${escapeHtml(item.numero)}</td>
                <td class="caisse-modal-cell caisse-modal-cell-date">${escapeHtml(item.date)}</td>
                <td class="caisse-modal-cell caisse-modal-cell-client">${escapeHtml(item.client)}</td>
                <td class="caisse-modal-cell"><span class="caisse-mode-chip">${escapeHtml(item.displayMode || getModeDisplayLabel(item))}</span></td>
                <td class="caisse-modal-cell caisse-modal-cell-amount">${formatMoney(item.total)} DT</td>
            </tr>
        `).join('')
        : `<tr><td colspan="5" style="text-align:center; padding:18px; color:#64748b;">Aucune opération trouvée pour ce type.</td></tr>`;

    modal.style.display = 'flex';
}

function closeCaisseSalesModal() {
    const modal = document.getElementById('caisse-sales-modal');
    if (!modal) return;
    modal.style.display = 'none';
}

async function showCaisseRecapSaleDetail(saleId) {
    const recap = await getCaisseRecapData();
    const item = (recap.detailRows || []).find(row => String(row.id || '') === String(saleId || ''));
    if (!item) return;

    const modal = document.getElementById('caisse-sale-detail-modal');
    const titleNode = document.getElementById('caisse-sale-detail-title');
    const subtitleNode = document.getElementById('caisse-sale-detail-subtitle');
    const contentNode = document.getElementById('caisse-sale-detail-content');
    if (!modal || !titleNode || !subtitleNode || !contentNode) return;

    const linesHtml = Array.isArray(item.detailItems) && item.detailItems.length > 0
        ? item.detailItems.map(line => {
            const qty = Number(line.quantite || line.quantity || 0);
            const unitPrice = Number(line.prix_unitaire_ttc || line.unit_price || 0);
            const remise = Number(line.remise || 0);
            const total = (qty * unitPrice) - remise;
            return `
                <tr class="caisse-detail-line-row">
                    <td>${escapeHtml(line.products?.code_article || '-')}</td>
                    <td>${escapeHtml(line.products?.designation || '-')}</td>
                    <td class="amount">${formatMoney(line.products?.tva || 0)}%</td>
                    <td class="amount">${formatMoney(qty)}</td>
                    <td class="amount">${formatMoney(unitPrice)} DT</td>
                    <td class="amount strong">${formatMoney(total)} DT</td>
                </tr>
            `;
        }).join('')
        : '<tr><td colspan="6" style="text-align:center; padding:16px;">Aucune ligne trouvee.</td></tr>';

    titleNode.innerText = `${item.numero || 'Vente'} - ${getModeDisplayLabel(item)}`;
    subtitleNode.innerText = `${item.client || 'Client'} | ${item.date || '-'}`;
    contentNode.innerHTML = `
        <div class="caisse-detail-shell">
            <div class="caisse-detail-summary-grid">
                <div class="caisse-detail-summary-card">
                    <span class="label">Numero</span>
                    <strong>${escapeHtml(item.numero || '-')}</strong>
                </div>
                <div class="caisse-detail-summary-card">
                    <span class="label">Date</span>
                    <strong>${escapeHtml(item.date || '-')}</strong>
                </div>
                <div class="caisse-detail-summary-card caisse-detail-summary-card-wide">
                    <span class="label">Client</span>
                    <strong>${escapeHtml(item.client || '-')}</strong>
                    <small>${escapeHtml(item.customerTypeLabel || '-')}</small>
                </div>
                <div class="caisse-detail-summary-card">
                    <span class="label">Mode</span>
                    <strong>${escapeHtml(getModeDisplayLabel(item))}</strong>
                </div>
                <div class="caisse-detail-summary-card">
                    <span class="label">Mutuelle</span>
                    <strong>${escapeHtml(item.mutuelle || '-')}</strong>
                </div>
                <div class="caisse-detail-summary-card caisse-detail-summary-card-accent">
                    <span class="label">Total TTC</span>
                    <strong>${formatMoney(item.totalTtc || item.total || 0)} DT</strong>
                    <small>HT ${formatMoney(item.totalHt || 0)} | TVA ${formatMoney(item.totalTva || 0)}</small>
                </div>
            </div>
            <div class="caisse-detail-lines-shell">
                <div class="caisse-detail-lines-head">
                    <div class="caisse-detail-lines-title">Articles de la vente</div>
                    <div class="caisse-detail-lines-count">${Array.isArray(item.detailItems) ? item.detailItems.length : 0} ligne(s)</div>
                </div>
                <div class="state-detail-lines caisse-detail-lines-table-wrap">
                    <table class="pos-table caisse-detail-lines-table">
                        <thead>
                            <tr>
                                <th>Code</th>
                                <th>Designation</th>
                                <th class="amount">TVA %</th>
                                <th class="amount">Qte</th>
                                <th class="amount">PU TTC</th>
                                <th class="amount">Total</th>
                            </tr>
                        </thead>
                        <tbody>${linesHtml}</tbody>
                    </table>
                </div>
            </div>
            <div class="caisse-detail-total-bar">
                <div class="caisse-detail-total-meta">
                    <span class="label">Total final</span>
                    <small>HT ${formatMoney(item.totalHt || 0)} | TVA ${formatMoney(item.totalTva || 0)}</small>
                </div>
                <div class="caisse-detail-total-value">${formatMoney(item.totalTtc || item.total || 0)} DT</div>
            </div>
        </div>
    `;

    modal.style.display = 'flex';
}

function closeCaisseSaleDetailModal() {
    const modal = document.getElementById('caisse-sale-detail-modal');
    if (!modal) return;
    modal.style.display = 'none';
}

function updateCaisseRecapFilterButtons() {
    const config = [
        ['caisse-filter-all', 'ALL'],
        ['caisse-filter-comptant', 'COMPTANT'],
        ['caisse-filter-web', 'E-COMMERCE'],
        ['caisse-filter-credit', 'CREDIT'],
        ['caisse-filter-mutuelle', 'MUTUELLE']
    ];
    config.forEach(([id, mode]) => {
        const button = document.getElementById(id);
        if (!button) return;
        button.style.background = caisseRecapModeFilter === mode ? '#2563eb' : '#ffffff';
        button.style.color = caisseRecapModeFilter === mode ? '#ffffff' : '#1e293b';
        button.style.borderColor = caisseRecapModeFilter === mode ? '#2563eb' : '';
    });
}

function updateCaissePhysicalDifference() {
    const theorique = Number(document.getElementById('caisse-total-theorique')?.innerText || 0);
    const physique = Number(document.getElementById('caisse-total-physique')?.value || 0);
    const difference = physique - theorique;
    const differenceNode = document.getElementById('caisse-difference');
    if (differenceNode) {
        differenceNode.innerText = formatMoney(difference);
        differenceNode.style.color = Math.abs(difference) < 0.0005 ? '#2563eb' : difference > 0 ? '#15803d' : '#dc2626';
    }
}

function clearCaissePhysicalInput() {
    const input = document.getElementById('caisse-total-physique');
    if (!input) return;
    input.value = '0.000';
    updateCaissePhysicalDifference();
}

async function exportCaisseRecapToExcel() {
    const recap = await getCaisseRecapData();
    if (typeof XLSX === 'undefined') {
        alert('Bibliotheque Excel indisponible.');
        return;
    }

    const rows = [
        ['RECAPITULATIF DE CAISSE'],
        ['Periode', recap.from || '-', recap.to || '-'],
        [],
        ['Libelle', 'Ventes Au Comptant', 'Reglements Credit+Mutuelles', 'Totaux'],
        ...recap.paymentRows.map(row => [row.label, Number(formatMoney(row.cash)), Number(formatMoney(row.creditMutuelle)), Number(formatMoney(row.total))]),
        [],
        ['Fond de Caisse', Number(formatMoney(recap.fondCaisse))],
        ['Total Theorique', Number(formatMoney(recap.totalTheorique))],
        ['Total Physique', Number(document.getElementById('caisse-total-physique')?.value || 0)],
        ['Difference', Number(formatMoney((Number(document.getElementById('caisse-total-physique')?.value || 0)) - recap.totalTheorique))],
        [],
        ['Mutuelle', Number(formatMoney(recap.groups.MUTUELLE.amount))],
        ['Credit', Number(formatMoney(recap.groups.CREDIT.amount))],
        ['Nombre de ventes', recap.totalCount]
    ];

    const workbook = XLSX.utils.book_new();
    const worksheet = XLSX.utils.aoa_to_sheet(rows);
    XLSX.utils.book_append_sheet(workbook, worksheet, 'Recap caisse');
    XLSX.writeFile(workbook, `recap_caisse_${recap.from || 'periode'}_${recap.to || 'periode'}.xlsx`);
}

function buildCaisseRecapPrintDocument(recap) {
    const periodLabel = recap.from && recap.to
        ? `Periode du ${recap.from} au ${recap.to}`
        : recap.from
            ? `Periode a partir du ${recap.from}`
            : recap.to
                ? `Periode jusqu'au ${recap.to}`
                : 'Toutes les periodes';

    return `
        <div class="print-doc">
            <div class="print-head">
                <div>
                    <div class="print-brand">RECAP CAISSE</div>
                    <div class="print-kicker">${escapeHtml(periodLabel)}</div>
                </div>
                <div class="print-doc-chip">${recap.totalCount} mouvement(s)</div>
            </div>

            <div class="print-meta-grid">
                <div class="print-card">
                    <div class="print-card-title">Synthese</div>
                    <div>Total ventes : <strong>${recap.totalCount}</strong></div>
                    <div>Total TTC : <strong>${formatMoney(recap.totalAmount)} DT</strong></div>
                    <div>Total comptant : <strong>${formatMoney(recap.groups.COMPTANT.amount)} DT</strong></div>
                    <div>Total e-commerce : <strong>${formatMoney(recap.groups['E-COMMERCE'].amount)} DT</strong></div>
                </div>
            </div>

            <table>
                <thead>
                    <tr>
                        <th>Type</th>
                        <th style="text-align:right;">Nombre</th>
                        <th style="text-align:right;">Montant</th>
                    </tr>
                </thead>
                <tbody>
                    ${Object.entries(recap.groups).map(([mode, stats]) => `
                        <tr>
                            <td>${escapeHtml(mode)}</td>
                            <td style="text-align:right;">${stats.count}</td>
                            <td style="text-align:right; font-weight:700;">${formatMoney(stats.amount)} DT</td>
                        </tr>
                    `).join('')}
                </tbody>
            </table>
        </div>
    `;
}

async function printCaisseRecap() {
    const recap = await getCaisseRecapData();
    if (!recap.totalCount) {
        alert('Aucune donnee a imprimer.');
        return;
    }

    const printWindow = openReportPrintWindow('Recap caisse', buildCaisseRecapPrintDocument(recap));
    if (!printWindow) return;
    printWindow.print();
}

