async function loadStockDiscountManager() {
    const tbody = document.getElementById('stock-discount-table-body');
    const summary = document.getElementById('stock-discount-summary');
    if (tbody) {
        tbody.innerHTML = '<tr><td colspan="7" style="text-align:center; padding:32px;">Chargement...</td></tr>';
    }
    if (summary) {
        summary.innerText = 'Chargement des articles...';
    }

    try {
        stockDiscountState.products = (await fetchCollection('products?select=id,code_article,designation,forme,code_pct,product_brand,web_category_slug,prix_vente_ttc,prix_vente_web_ttc,remise_web_pct&order=designation', []))
            .map(normalizeProductPricingFields);
        renderStockDiscountPreview();
    } catch (error) {
        console.error('Erreur chargement gestion remise article:', error);
        if (tbody) {
            tbody.innerHTML = `<tr><td colspan="7" style="text-align:center; padding:32px; color:#b91c1c;">${escapeHtml(error.message || 'Erreur de chargement')}</td></tr>`;
        }
        if (summary) {
            summary.innerText = 'Chargement impossible.';
        }
    }
}

function getFilteredStockDiscountProducts() {
    return stockDiscountState.products || [];
}

function renderStockDiscountPreview() {
    const rows = getFilteredStockDiscountProducts();
    const tbody = document.getElementById('stock-discount-table-body');
    const summary = document.getElementById('stock-discount-summary');
    const countNode = document.getElementById('stock-discount-match-count');
    const remisePct = Math.max(0, Number(document.getElementById('stock-discount-pct')?.value || 0));

    if (countNode) {
        countNode.innerText = String(rows.length);
    }

    const avgCurrent = rows.length
        ? rows.reduce((sum, product) => sum + Number(product.remise_web_pct || 0), 0) / rows.length
        : 0;

    if (summary) {
        summary.innerText = `${rows.length} article(s) | Base de calcul: Prix Vente TTC original | Nouvelle remise web: ${formatMoney(remisePct)} % | Prix TTC client passager intact.`;
    }

    if (!tbody) return;
    if (!rows.length) {
        tbody.innerHTML = '<tr><td colspan="7" style="text-align:center; padding:32px;">Aucun article disponible.</td></tr>';
        return;
    }

    tbody.innerHTML = rows.slice(0, 200).map(product => {
        const originalPrixVenteTtc = Number(product.prix_vente_ttc || 0);
        const nextWebPrice = calculateWebPriceFromBase(originalPrixVenteTtc, remisePct);
        return `
            <tr>
                <td>${escapeHtml(product.code_article || '-')}</td>
                <td>${escapeHtml(product.designation || '-')}</td>
                <td>${escapeHtml(product.forme || '-')}</td>
                <td style="text-align:right;">${formatMoney(originalPrixVenteTtc)}</td>
                <td style="text-align:right;">${formatMoney(product.remise_web_pct || 0)}%</td>
                <td style="text-align:right;">${formatMoney(product.prix_vente_web_ttc || 0)}</td>
                <td style="text-align:right; font-weight:800; color:#166534;">${formatMoney(nextWebPrice)}</td>
            </tr>
        `;
    }).join('');
}

async function applyStockDiscountBatch() {
    const rows = getFilteredStockDiscountProducts();
    const remisePct = Math.max(0, Number(document.getElementById('stock-discount-pct')?.value || 0));

    if (!rows.length) {
        alert('Aucun article a mettre a jour.');
        return;
    }

    if (stockDiscountState.applying) return;
    stockDiscountState.applying = true;

    try {
        const productUpdates = rows.map(product => {
            const originalPrixVenteTtc = Number(product.prix_vente_ttc || 0);
            return {
                id: product.id,
                remise_web_pct: remisePct,
                prix_vente_web_ttc: calculateWebPriceFromBase(originalPrixVenteTtc, remisePct)
            };
        });
        const batchSize = 20;

        for (let index = 0; index < productUpdates.length; index += batchSize) {
            const batch = productUpdates.slice(index, index + batchSize);
            await Promise.all(batch.map(async product => {
                const response = await fetch(`${supabaseUrl}products?id=eq.${product.id}`, {
                    method: 'PATCH',
                    headers: supabaseHeaders,
                    body: JSON.stringify({
                        remise_web_pct: product.remise_web_pct,
                        prix_vente_web_ttc: product.prix_vente_web_ttc
                    })
                });

                if (!response.ok) {
                    throw new Error(`HTTP ${response.status} - ${await response.text()}`);
                }
            }));
        }

        updateCachedProductsLocally(productUpdates);
        refreshProductsCacheInBackground('stock remise article');
        await loadStockDiscountManager();
        alert(`Remise de ${formatMoney(remisePct)} % appliquee sur ${rows.length} article(s).`);
    } catch (error) {
        console.error('Erreur application remise en masse:', error);
        alert(`Impossible d'appliquer la remise.\n\nDetail: ${error.message || error}`);
    } finally {
        stockDiscountState.applying = false;
    }
}

// Activity & Visibility Polling Manager
let appLastActivityTime = Date.now();
const APP_INACTIVITY_LIMIT = 5 * 60 * 1000; // 5 minutes

function resetAppActivity() {
    const wasInactive = Date.now() - appLastActivityTime >= APP_INACTIVITY_LIMIT;
    appLastActivityTime = Date.now();
    if (wasInactive && document.visibilityState === 'visible') {
        resumeAppBackgroundPolling();
    }
}

function suspendAppBackgroundPolling() {
    if (window.fridgeSaleAlertPoller) {
        clearInterval(window.fridgeSaleAlertPoller);
        window.fridgeSaleAlertPoller = null;
    }
    if (typeof webOrderAlertState !== 'undefined' && webOrderAlertState && webOrderAlertState.pollHandle) {
        clearInterval(webOrderAlertState.pollHandle);
        webOrderAlertState.pollHandle = null;
    }
}

function resumeAppBackgroundPolling() {
    if (document.visibilityState === 'visible' && (Date.now() - appLastActivityTime < APP_INACTIVITY_LIMIT)) {
        if (!window.fridgeSaleAlertPoller) {
            startFridgeSaleAlertPolling();
        }
        if (typeof webOrderAlertState !== 'undefined' && webOrderAlertState && !webOrderAlertState.pollHandle) {
            startWebOrderAlertPolling();
        }
    }
}

function initActivityAndVisibilityMonitor() {
    ['mousemove', 'keydown', 'mousedown', 'touchstart', 'scroll'].forEach(evt => {
        window.addEventListener(evt, resetAppActivity, { passive: true });
    });

    document.addEventListener('visibilitychange', () => {
        if (document.visibilityState === 'visible') {
            resumeAppBackgroundPolling();
        } else {
            suspendAppBackgroundPolling();
        }
    });

    if (document.visibilityState !== 'visible') {
        suspendAppBackgroundPolling();
    }

    setInterval(() => {
        if (Date.now() - appLastActivityTime >= APP_INACTIVITY_LIMIT) {
            suspendAppBackgroundPolling();
        }
    }, 30000);
}

