function removeConfigSettingsButton() {
    const buttonsContainer = document.querySelector('#panel-config .ribbon-buttons');
    if (!buttonsContainer) return;

    Array.from(buttonsContainer.children).forEach((button) => {
        const label = String(button.textContent || '').trim().toLowerCase();
        const moduleId = String(button.getAttribute?.('data-module-button') || '').trim().toLowerCase();
        const onclickText = String(button.getAttribute?.('onclick') || '').toLowerCase();
        if (
            moduleId === 'settings' ||
            label.includes('parametres') ||
            label.includes('paramètres') ||
            onclickText.includes("openTab('settings')") ||
            onclickText.includes('opentab("settings")')
        ) {
            button.remove();
        }
    });
}

