function downloadImportTemplate() {
    const line = importArticleColumns.join(';');
    navigator.clipboard?.writeText(`${line}\n`);
    alert('Les colonnes du modele ont ete copiees dans le presse-papiers.');
}

function clearImportArticles() {
    importArticlesPreview = [];
    importArticlesSkippedRows = [];
    importArticlesDuplicateRows = [];
    importArticlesUpdateStats = {
        matched: 0,
        missing: 0,
        invalid: 0,
        loading: false
    };
    const fileInput = document.getElementById('articles-import-file');
    const pasteInput = document.getElementById('articles-import-paste');
    if (fileInput) fileInput.value = '';
    if (pasteInput) pasteInput.value = '';
    renderImportArticlesPreview();
    renderImportUpdateStats();
    renderImportDuplicateRows();
    renderImportSkippedRows();
    updateImportArticlesStatus('Aucune donnee chargee.');
}

