function normalizeImportHeader(value) {
    return String(value || '')
        .normalize('NFD')
        .replace(/[\u0300-\u036f]/g, '')
        .replace(/[^a-zA-Z0-9]/g, '')
        .toLowerCase();
}

function parseNumberValue(value) {
    if (value === undefined || value === null || value === '') return 0;
    return Number(String(value).replace(/\s/g, '').replace(',', '.')) || 0;
}

function isImportPercentOverflowCandidate(value) {
    const numeric = Number(value);
    return Number.isFinite(numeric) && Math.abs(numeric) >= 1000;
}

function getImportRowValidationIssues(row) {
    const issues = [];
    const tvaNumeric = Number(row.TVA);

    if (!Number.isFinite(Number(row.PrixAchatHT))) issues.push('PrixAchatHT invalide');
    if (!Number.isFinite(Number(row.PrixAchatTTC))) issues.push('PrixAchatTTC invalide');
    if (!Number.isFinite(Number(row.PrixVenteHT))) issues.push('PrixVenteHT invalide');
    if (!Number.isFinite(Number(row.PrixVenteTTC))) issues.push('PrixVenteTTC invalide');
    if (!Number.isFinite(Number(row.TVA))) issues.push('TVA invalide');
    if (!Number.isFinite(Number(row.Marge))) issues.push('Marge invalide');
    if (!Number.isFinite(Number(row.StockArticle))) issues.push('StockArticle invalide');

    if (isImportPercentOverflowCandidate(row.TVA)) {
        issues.push(`TVA trop grande (${row.TVA})`);
    }

    if (Number.isFinite(tvaNumeric) && (tvaNumeric < 0 || tvaNumeric > 100)) {
        issues.push(`TVA hors plage (${row.TVA})`);
    }

    if (isImportPercentOverflowCandidate(row.Marge)) {
        issues.push(`Marge trop grande (${row.Marge})`);
    }

    return issues;
}

function buildImportRowLabel(row, fallbackIndex) {
    const lineNumber = row.SourceRowNumber || fallbackIndex;
    const codeArticle = row.CodeArticle || '-';
    return `ligne ${lineNumber} (CodeArticle: ${codeArticle})`;
}

function validateImportedRowsBeforeUpload(rows) {
    const invalidRows = rows
        .map((row, index) => ({
            row,
            issues: getImportRowValidationIssues(row),
            fallbackIndex: index + 2
        }))
        .filter(item => item.issues.length > 0);

    if (invalidRows.length === 0) return;

    const details = invalidRows
        .slice(0, 8)
        .map(item => `${buildImportRowLabel(item.row, item.fallbackIndex)} -> ${item.issues.join(', ')}`)
        .join('\n');

    const suffix = invalidRows.length > 8
        ? `\n... ${invalidRows.length - 8} autre(s) ligne(s) invalide(s).`
        : '';

    throw new Error(
        `Certaines lignes Excel sont invalides avant import.\n\n${details}${suffix}\n\n` +
        `Astuce: la base accepte probablement TVA/Marge en pourcentage. Verifiez surtout ces colonnes si vous avez des valeurs >= 1000.`
    );
}

function splitImportedRowsByValidity(rows) {
    const validRows = [];
    const invalidRows = [];

    rows.forEach((row, index) => {
        const issues = getImportRowValidationIssues(row);
        const fallbackIndex = index + 2;

        if (issues.length > 0) {
            invalidRows.push({ row, issues, fallbackIndex });
            return;
        }

        validRows.push(row);
    });

    return { validRows, invalidRows };
}

function parseDateValue(value) {
    if (value === undefined || value === null || value === '') return null;

    const numericValue = Number(value);
    if (!Number.isNaN(numericValue) && Number.isFinite(numericValue)) {
        if (numericValue > 0 && numericValue < 100000) {
            const excelEpoch = new Date(Date.UTC(1899, 11, 30));
            const utcMillis = excelEpoch.getTime() + Math.round(numericValue) * 86400000;
            const excelDate = new Date(utcMillis);
            return excelDate.toISOString().split('T')[0];
        }
        return null;
    }

    const raw = String(value || '').trim();
    if (!raw) return null;

    if (/^\d{4}-\d{2}-\d{2}$/.test(raw)) {
        return raw;
    }

    const frMatch = raw.match(/^(\d{1,2})[\/\-](\d{1,2})[\/\-](\d{4})$/);
    if (frMatch) {
        const [, day, month, year] = frMatch;
        return `${year}-${month.padStart(2, '0')}-${day.padStart(2, '0')}`;
    }

    const isoMatch = raw.match(/^(\d{4})[\/\-](\d{1,2})[\/\-](\d{1,2})$/);
    if (isoMatch) {
        const [, year, month, day] = isoMatch;
        return `${year}-${month.padStart(2, '0')}-${day.padStart(2, '0')}`;
    }

    return null;
}

function splitImportLine(line, delimiter) {
    return line.split(delimiter).map(cell => cell.trim());
}

function detectDelimiter(firstLine) {
    if (firstLine.includes('\t')) return '\t';
    if (firstLine.includes(';')) return ';';
    return ',';
}

function buildImportHeaderMap(headers) {
    return headers.reduce((acc, header, index) => {
        acc[normalizeImportHeader(header)] = index;
        return acc;
    }, {});
}

function parseImportedArticleRow(cells, rowIndex, headerMap) {
    const getValue = (column) => cells[headerMap[normalizeImportHeader(column)]] || '';

    const codeArticle = String(getValue('CodeArticle') || '').trim();
    const designation = String(getValue('Designation') || '').trim();

    if (!codeArticle || !designation) {
        throw new Error(`Ligne ${rowIndex}: CodeArticle et Designation sont obligatoires.`);
    }

    return {
        SourceRowNumber: rowIndex,
        CodeArticle: codeArticle,
        CodeABarre: getValue('CodeABarre'),
        Designation: designation,
        PrixAchatHT: parseNumberValue(getValue('PrixAchatHT')),
        PrixAchatTTC: parseNumberValue(getValue('PrixAchatTTC')),
        PrixVenteHT: parseNumberValue(getValue('PrixVenteHT')),
        PrixVenteTTC: parseNumberValue(getValue('PrixVenteTTC')),
        TVA: parseNumberValue(getValue('TVA')),
        Marge: parseNumberValue(getValue('Marge')),
        DateAlerte: parseDateValue(getValue('DateAlerte')),
        StockArticle: Math.trunc(parseNumberValue(getValue('StockArticle'))),
        ImageURL: getValue('ImageURL'),
        DescriptionWeb: getValue('DescriptionWeb'),
        ProductBrand: getValue('ProductBrand'),
        WebCategorySlug: getValue('WebCategorySlug'),
        OldPriceTTC: parseNumberValue(getValue('OldPriceTTC')),
        PromoBadge: getValue('PromoBadge'),
        ProductGalleryURLs: getValue('ProductGalleryURLs'),
        ProductSpecs: getValue('ProductSpecs'),
        Forme: getValue('Forme'),
        ProductUrl: getValue('ProductUrl')
    };
}

function ensureRequiredImportColumns(headerMap) {
    const missingColumns = importArticleColumns.filter(column => !(normalizeImportHeader(column) in headerMap));
    if (missingColumns.length > 0) {
        throw new Error(`Colonnes manquantes: ${missingColumns.join(', ')}`);
    }
}

function finalizeImportedArticleParsing(rawRows, rowMapper) {
    const parsedRows = [];
    const skippedRows = [];

    rawRows.forEach((row, index) => {
        try {
            const parsed = rowMapper(row, index);
            if (parsed) {
                parsedRows.push(parsed);
            }
        } catch (error) {
            skippedRows.push({
                rowNumber: index + 2,
                message: String(error?.message || error)
            });
        }
    });

    if (parsedRows.length === 0) {
        if (skippedRows.length > 0) {
            throw new Error(skippedRows[0].message);
        }
        throw new Error('Aucune ligne exploitable trouvee dans le fichier.');
    }

    return { parsedRows, skippedRows };
}

function detectImportDuplicateRows(rows) {
    const buckets = new Map();

    rows.forEach(row => {
        const key = String(row?.CodeArticle || '').trim();
        if (!key) return;
        if (!buckets.has(key)) buckets.set(key, []);
        buckets.get(key).push(row);
    });

    return Array.from(buckets.entries())
        .filter(([, items]) => items.length > 1)
        .map(([codeArticle, items]) => ({
            codeArticle,
            lines: items.map(item => item.SourceRowNumber).filter(Boolean)
        }))
        .sort((a, b) => a.codeArticle.localeCompare(b.codeArticle, 'fr', { sensitivity: 'base' }));
}

function parseImportedArticlesText(text) {
    const cleanedLines = String(text || '')
        .split(/\r?\n/)
        .map(line => line.trim())
        .filter(Boolean);

    if (cleanedLines.length < 2) {
        throw new Error('Le fichier doit contenir un en-tete et au moins une ligne.');
    }

    const delimiter = detectDelimiter(cleanedLines[0]);
    const headers = splitImportLine(cleanedLines[0], delimiter);
    const headerMap = buildImportHeaderMap(headers);
    ensureRequiredImportColumns(headerMap);

    const { parsedRows, skippedRows } = finalizeImportedArticleParsing(cleanedLines.slice(1), (line, rowIndex) => {
        const cells = splitImportLine(line, delimiter);
        return parseImportedArticleRow(cells, rowIndex + 2, headerMap);
    });

    importArticlesSkippedRows = skippedRows;
    importArticlesDuplicateRows = detectImportDuplicateRows(parsedRows);
    return parsedRows;
}

function parseImportedArticlesSheetRows(rows) {
    const normalizedRows = Array.isArray(rows) ? rows : [];
    const nonEmptyRows = normalizedRows.filter(row => Array.isArray(row) && row.some(cell => String(cell ?? '').trim() !== ''));

    if (nonEmptyRows.length < 2) {
        throw new Error('Le fichier Excel doit contenir un en-tete et au moins une ligne.');
    }

    const headers = nonEmptyRows[0].map(cell => String(cell ?? '').trim());
    const headerMap = buildImportHeaderMap(headers);
    ensureRequiredImportColumns(headerMap);

    const { parsedRows, skippedRows } = finalizeImportedArticleParsing(nonEmptyRows.slice(1), (row, index) => {
        const cells = row.map(cell => String(cell ?? '').trim());
        return parseImportedArticleRow(cells, index + 2, headerMap);
    });

    importArticlesSkippedRows = skippedRows;
    importArticlesDuplicateRows = detectImportDuplicateRows(parsedRows);
    return parsedRows;
}

function buildImportSkippedRowsMessage(prefix) {
    const skippedCount = Array.isArray(importArticlesSkippedRows) ? importArticlesSkippedRows.length : 0;
    const duplicateCount = Array.isArray(importArticlesDuplicateRows) ? importArticlesDuplicateRows.length : 0;

    let message = `${prefix}${importArticlesPreview.length} lignes pretes pour import.`;
    if (skippedCount > 0) {
        message += ` ${skippedCount} ligne(s) incomplete(s) ignoree(s).`;
    }
    if (duplicateCount > 0) {
        message += ` ${duplicateCount} code(s) article en double detecte(s).`;
    }
    return message;
}

function renderImportUpdateStats() {
    const matchedEl = document.getElementById('import-articles-update-matched');
    const missingEl = document.getElementById('import-articles-update-missing');
    const invalidEl = document.getElementById('import-articles-update-invalid');

    if (matchedEl) matchedEl.innerText = importArticlesUpdateStats.loading ? '...' : String(importArticlesUpdateStats.matched || 0);
    if (missingEl) missingEl.innerText = importArticlesUpdateStats.loading ? '...' : String(importArticlesUpdateStats.missing || 0);
    if (invalidEl) invalidEl.innerText = importArticlesUpdateStats.loading ? '...' : String(importArticlesUpdateStats.invalid || 0);
}

async function evaluateImportArticlesUpdateStats() {
    importArticlesUpdateStats = {
        matched: 0,
        missing: 0,
        invalid: Array.isArray(importArticlesSkippedRows) ? importArticlesSkippedRows.length : 0,
        loading: false
    };

    if (!Array.isArray(importArticlesPreview) || importArticlesPreview.length === 0) {
        renderImportUpdateStats();
        return;
    }

    importArticlesUpdateStats.loading = true;
    renderImportUpdateStats();

    try {
        const existingProducts = await fetchCollection('products?select=code_article');
        const existingCodes = new Set(
            (Array.isArray(existingProducts) ? existingProducts : [])
                .map(item => String(item.code_article || '').trim())
                .filter(Boolean)
        );

        const { validRows } = splitImportedRowsByValidity(importArticlesPreview);
        let matched = 0;
        let missing = 0;

        validRows.forEach(row => {
            if (existingCodes.has(String(row.CodeArticle || '').trim())) matched += 1;
            else missing += 1;
        });

        importArticlesUpdateStats = {
            matched,
            missing,
            invalid: Array.isArray(importArticlesSkippedRows) ? importArticlesSkippedRows.length : 0,
            loading: false
        };
    } catch (error) {
        console.warn('Analyse mise a jour articles indisponible.', error);
        importArticlesUpdateStats.loading = false;
    }

    renderImportUpdateStats();
}

function renderImportDuplicateRows() {
    const box = document.getElementById('import-articles-duplicates-box');
    const body = document.getElementById('import-articles-duplicates-body');
    if (!box || !body) return;

    if (!Array.isArray(importArticlesDuplicateRows) || importArticlesDuplicateRows.length === 0) {
        box.style.display = 'none';
        body.innerHTML = '';
        return;
    }

    box.style.display = 'block';
    body.innerHTML = importArticlesDuplicateRows
        .slice(0, 20)
        .map(item => `<div><strong>${escapeHtml(item.codeArticle)}</strong> - lignes ${escapeHtml(item.lines.join(', '))}</div>`)
        .join('');

    if (importArticlesDuplicateRows.length > 20) {
        body.innerHTML += `<div><strong>...</strong> ${importArticlesDuplicateRows.length - 20} autre(s) doublon(s).</div>`;
    }
}

function renderImportSkippedRows() {
    const box = document.getElementById('import-articles-skipped-box');
    const body = document.getElementById('import-articles-skipped-body');
    if (!box || !body) return;

    if (!Array.isArray(importArticlesSkippedRows) || importArticlesSkippedRows.length === 0) {
        box.style.display = 'none';
        body.innerHTML = '';
        return;
    }

    box.style.display = 'block';
    body.innerHTML = importArticlesSkippedRows
        .slice(0, 20)
        .map(item => `<div><strong>Ligne ${item.rowNumber}</strong> - ${escapeHtml(item.message)}</div>`)
        .join('');

    if (importArticlesSkippedRows.length > 20) {
        body.innerHTML += `<div><strong>...</strong> ${importArticlesSkippedRows.length - 20} autre(s) ligne(s) ignoree(s).</div>`;
    }
}

function previewImportedArticles() {
    const pastedText = document.getElementById('articles-import-paste')?.value || '';
    if (!pastedText.trim()) {
        alert('Collez les donnees Excel ou chargez un fichier.');
        return;
    }

    try {
        importArticlesPreview = parseImportedArticlesText(pastedText);
        renderImportArticlesPreview();
        renderImportUpdateStats();
        renderImportDuplicateRows();
        renderImportSkippedRows();
        updateImportArticlesStatus(buildImportSkippedRowsMessage(''));
        evaluateImportArticlesUpdateStats();
    } catch (error) {
        console.error(error);
        alert(error.message);
    }
}

function previewPublicCatalogImport() {
    const fileInput = document.getElementById('public-catalog-import-file');
    const file = fileInput?.files?.[0];

    if (!file) {
        alert('Chargez le fichier CSV du catalogue public.');
        return;
    }

    updatePublicCatalogStatus('Fichier deja charge. Apercu disponible.');
    renderPublicCatalogPreview();
}

function handleArticlesImportFile(event) {
    const file = event.target.files?.[0];
    if (!file) return;

    const fileName = file.name.toLowerCase();
    const reader = new FileReader();

    if (fileName.endsWith('.xls') || fileName.endsWith('.xlsx')) {
        reader.onload = () => {
            try {
                if (typeof XLSX === 'undefined') {
                    throw new Error('La librairie XLSX n’est pas chargee.');
                }

                const workbook = XLSX.read(reader.result, { type: 'array' });
                const firstSheetName = workbook.SheetNames[0];
                const firstSheet = workbook.Sheets[firstSheetName];
                const rows = XLSX.utils.sheet_to_json(firstSheet, { header: 1, defval: '' });
                const text = rows.map(row => row.join('\t')).join('\n');

                const pasteInput = document.getElementById('articles-import-paste');
                if (pasteInput) pasteInput.value = text;

                importArticlesPreview = parseImportedArticlesSheetRows(rows);
                renderImportArticlesPreview();
                renderImportUpdateStats();
                renderImportDuplicateRows();
                renderImportSkippedRows();
                updateImportArticlesStatus(buildImportSkippedRowsMessage(''));
                evaluateImportArticlesUpdateStats();
            } catch (error) {
                console.error('Erreur lecture Excel:', error);
                alert(`Erreur lecture Excel: ${error.message}`);
            }
        };
        reader.readAsArrayBuffer(file);
        return;
    }

    reader.onload = () => {
        const text = String(reader.result || '');
        const pasteInput = document.getElementById('articles-import-paste');
        if (pasteInput) pasteInput.value = text;
        previewImportedArticles();
    };
    reader.readAsText(file);
}

function handlePublicCatalogImportFile(event) {
    const file = event.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = () => {
        try {
            const text = String(reader.result || '');
            publicCatalogImportPreview = parseImportedArticlesText(text);
            renderPublicCatalogPreview();
            updatePublicCatalogStatus(`${publicCatalogImportPreview.length} produits publics prets pour import.`);
        } catch (error) {
            console.error('Erreur lecture catalogue public:', error);
            alert(`Erreur lecture catalogue public: ${error.message}`);
        }
    };
    reader.readAsText(file);
}

function renderImportArticlesPreview() {
    const tbody = document.getElementById('import-articles-preview-body');
    const countEl = document.getElementById('import-articles-count');
    if (!tbody) return;

    if (countEl) countEl.innerText = String(importArticlesPreview.length);

    if (importArticlesPreview.length === 0) {
        tbody.innerHTML = '<tr><td colspan="11" style="text-align:center; padding:40px;">Aucune ligne a importer.</td></tr>';
        return;
    }

    tbody.innerHTML = importArticlesPreview.slice(0, 100).map(row => `
        <tr>
            <td>${escapeHtml(row.CodeArticle)}</td>
            <td>${escapeHtml(row.CodeABarre)}</td>
            <td>${escapeHtml(row.Designation)}</td>
            <td>${formatMoney(row.PrixAchatHT)}</td>
            <td>${formatMoney(row.PrixAchatTTC)}</td>
            <td>${formatMoney(row.PrixVenteHT)}</td>
            <td>${formatMoney(row.PrixVenteTTC)}</td>
            <td>${formatMoney(row.TVA)}</td>
            <td>${formatMoney(row.Marge)}</td>
            <td>${escapeHtml(row.DateAlerte || '-')}</td>
            <td>${row.StockArticle}</td>
        </tr>
    `).join('');
}

function renderPublicCatalogPreview() {
    const tbody = document.getElementById('public-catalog-preview-body');
    const countEl = document.getElementById('public-catalog-count');
    if (!tbody) return;

    if (countEl) countEl.innerText = String(publicCatalogImportPreview.length);

    if (publicCatalogImportPreview.length === 0) {
        tbody.innerHTML = '<tr><td colspan="7" style="text-align:center; padding:40px;">Aucun produit public charge.</td></tr>';
        return;
    }

    tbody.innerHTML = publicCatalogImportPreview.slice(0, 100).map(row => `
        <tr>
            <td>${escapeHtml(row.CodeArticle)}</td>
            <td>${escapeHtml(row.Designation)}</td>
            <td>${escapeHtml(row.ProductBrand || '-')}</td>
            <td>${escapeHtml(row.WebCategorySlug || '-')}</td>
            <td>${formatMoney(row.PrixVenteTTC)}</td>
            <td>${row.OldPriceTTC ? formatMoney(row.OldPriceTTC) : '-'}</td>
            <td>${row.ImageURL ? '<span style="color:#16a34a; font-weight:600;">Oui</span>' : '-'}</td>
        </tr>
    `).join('');
}

function updateImportArticlesStatus(message) {
    const statusEl = document.getElementById('import-articles-status');
    if (statusEl) statusEl.innerText = message;
}

function updatePublicCatalogStatus(message) {
    const statusEl = document.getElementById('public-catalog-status');
    if (statusEl) statusEl.innerText = message;
}

