function buildImportedProductPayload(row) {
    const payload = {
        code_article: row.CodeArticle,
        code_barre: row.CodeABarre || null,
        designation: row.Designation,
        prix_achat_ht: row.PrixAchatHT,
        prix_achat_ttc: row.PrixAchatTTC,
        prix_vente_ht: row.PrixVenteHT,
        prix_vente_ttc: row.PrixVenteTTC,
        tva: row.TVA,
        marge: row.Marge,
        date_alerte: row.DateAlerte,
        stock_actuel: row.StockArticle,
        forme: row.Forme || null
    };
    if (row.ImageURL !== undefined && row.ImageURL !== null && String(row.ImageURL).trim() !== '') payload.image_url = String(row.ImageURL).trim();
    if (row.DescriptionWeb !== undefined && row.DescriptionWeb !== null && String(row.DescriptionWeb).trim() !== '') payload.description_web = String(row.DescriptionWeb).trim();
    if (row.ProductBrand !== undefined && row.ProductBrand !== null && String(row.ProductBrand).trim() !== '') payload.product_brand = String(row.ProductBrand).trim();
    if (row.WebCategorySlug !== undefined && row.WebCategorySlug !== null && String(row.WebCategorySlug).trim() !== '') payload.web_category_slug = String(row.WebCategorySlug).trim();
    if (row.OldPriceTTC !== undefined && row.OldPriceTTC !== null && Number(row.OldPriceTTC) > 0) payload.old_price_ttc = Number(row.OldPriceTTC);
    if (row.PromoBadge !== undefined && row.PromoBadge !== null && String(row.PromoBadge).trim() !== '') payload.promo_badge = String(row.PromoBadge).trim();
    if (row.ProductGalleryURLs !== undefined && row.ProductGalleryURLs !== null && String(row.ProductGalleryURLs).trim() !== '') payload.product_gallery_urls = String(row.ProductGalleryURLs).trim();
    if (row.ProductSpecs !== undefined && row.ProductSpecs !== null && String(row.ProductSpecs).trim() !== '') payload.product_specs = String(row.ProductSpecs).trim();
    if (row.ProductUrl !== undefined && row.ProductUrl !== null && String(row.ProductUrl).trim() !== '') payload.product_url = String(row.ProductUrl).trim();
    return payload;
}

async function updateImportedArticlesOnly() {
    if (importArticlesPreview.length === 0) {
        alert('Aucune ligne a mettre a jour.');
        return;
    }

    const { validRows, invalidRows } = splitImportedRowsByValidity(importArticlesPreview);
    if (validRows.length === 0) {
        validateImportedRowsBeforeUpload(importArticlesPreview);
        return;
    }

    try {
        updateImportArticlesStatus(
            invalidRows.length > 0
                ? `Preparation mise a jour... ${validRows.length} ligne(s) valide(s), ${invalidRows.length} ligne(s) ignoree(s).`
                : 'Preparation mise a jour...'
        );

        const existingProducts = await fetchCollection('products?select=id,code_article');
        const existingMap = new Map(
            (Array.isArray(existingProducts) ? existingProducts : [])
                .map(item => [String(item.code_article || '').trim(), item])
                .filter(([code]) => code)
        );

        const matchedRows = [];
        const missingRows = [];

        validRows.forEach((row, index) => {
            const existing = existingMap.get(String(row.CodeArticle || '').trim());
            if (!existing?.id) {
                missingRows.push({
                    row,
                    fallbackIndex: row.SourceRowNumber || index + 2
                });
                return;
            }

            matchedRows.push({
                id: existing.id,
                row
            });
        });

        if (matchedRows.length === 0) {
            const details = missingRows
                .slice(0, 8)
                .map(item => `${buildImportRowLabel(item.row, item.fallbackIndex)} -> CodeArticle introuvable en base`)
                .join('\n');
            const suffix = missingRows.length > 8
                ? `\n... ${missingRows.length - 8} autre(s) ligne(s) non trouvee(s).`
                : '';
            throw new Error(
                `Aucun article existant correspondant a mettre a jour.\n\n${details}${suffix}`
            );
        }

        updateImportArticlesStatus(
            missingRows.length > 0 || invalidRows.length > 0
                ? `Mise a jour en cours... ${matchedRows.length} article(s) cible(s), ${missingRows.length + invalidRows.length} ligne(s) ignoree(s).`
                : `Mise a jour en cours... ${matchedRows.length} article(s) cible(s).`
        );

        for (let i = 0; i < matchedRows.length; i += 50) {
            const chunk = matchedRows.slice(i, i + 50);
            await Promise.all(chunk.map(async item => {
                const response = await fetch(`${supabaseUrl}products?id=eq.${item.id}`, {
                    method: 'PATCH',
                    headers: supabaseHeaders,
                    body: JSON.stringify(buildImportedProductPayload(item.row))
                });

                if (!response.ok) {
                    const errorText = await response.text();
                    if (response.status === 400 && errorText.includes('schema cache')) {
                        throw new Error(
                            `Colonnes manquantes dans la table products.\n\n` +
                            `Execute d'abord ce SQL dans Supabase:\n${getProductsMigrationSql()}`
                        );
                    }
                    throw new Error(`Erreur mise a jour article ${item.row.CodeArticle}: ${errorText || `HTTP ${response.status}`}`);
                }
            }));
        }

        await refreshProductsCache();

        const ignoredRows = [
            ...invalidRows.map(item => ({
                message: `${buildImportRowLabel(item.row, item.fallbackIndex)} -> ${item.issues.join(', ')}`
            })),
            ...missingRows.map(item => ({
                message: `${buildImportRowLabel(item.row, item.fallbackIndex)} -> CodeArticle introuvable en base`
            }))
        ];

        if (ignoredRows.length > 0) {
            const details = ignoredRows
                .slice(0, 8)
                .map(item => item.message)
                .join('\n');
            const suffix = ignoredRows.length > 8
                ? `\n... ${ignoredRows.length - 8} autre(s) ligne(s) ignoree(s).`
                : '';

            updateImportArticlesStatus(
                `Mise a jour terminee: ${matchedRows.length} article(s) mis a jour, ${ignoredRows.length} ligne(s) ignoree(s).`
            );
            alert(
                `Mise a jour terminee avec succes: ${matchedRows.length} article(s) mis a jour.\n\n` +
                `${ignoredRows.length} ligne(s) ont ete ignoree(s):\n${details}${suffix}`
            );
        } else {
            updateImportArticlesStatus(`Mise a jour terminee: ${matchedRows.length} article(s) mis a jour.`);
            alert(`Mise a jour terminee avec succes: ${matchedRows.length} article(s) mis a jour.`);
        }
    } catch (error) {
        console.error('Erreur mise a jour articles existants:', error);
        updateImportArticlesStatus(`Echec mise a jour: ${error.message}`);
        alert(`Echec mise a jour: ${error.message}`);
    }
}

async function importRowsToSupabase(rows, updateStatus, label) {
    const { validRows, invalidRows } = splitImportedRowsByValidity(rows);

    if (validRows.length === 0) {
        validateImportedRowsBeforeUpload(rows);
        return;
    }

    const payload = validRows.map(buildImportedProductPayload);

    try {
        updateStatus(
            invalidRows.length > 0
                ? `Import en cours... ${validRows.length} ligne(s) valide(s), ${invalidRows.length} ligne(s) ignoree(s).`
                : 'Import en cours...'
        );

        for (let i = 0; i < payload.length; i += 100) {
            const chunk = payload.slice(i, i + 100);
            const response = await fetch(`${supabaseUrl}products?on_conflict=code_article`, {
                method: 'POST',
                headers: {
                    ...supabaseHeaders,
                    Prefer: 'resolution=merge-duplicates,return=representation'
                },
                body: JSON.stringify(chunk)
            });

            if (!response.ok) {
                const errorText = await response.text();
                const sourceChunk = validRows.slice(i, i + 100);
                const suspiciousRows = sourceChunk
                    .map((row, index) => ({
                        row,
                        issues: getImportRowValidationIssues(row),
                        fallbackIndex: i + index + 2
                    }))
                    .filter(item => item.issues.length > 0);

                if (response.status === 400 && errorText.includes('schema cache')) {
                    throw new Error(
                        `Colonnes manquantes dans la table products.\n\n` +
                        `Execute d'abord ce SQL dans Supabase:\n${getProductsMigrationSql()}`
                    );
                }

                if (errorText.includes('numeric field overflow') && suspiciousRows.length > 0) {
                    const details = suspiciousRows
                        .slice(0, 5)
                        .map(item => `${buildImportRowLabel(item.row, item.fallbackIndex)} -> ${item.issues.join(', ')}`)
                        .join('\n');

                    throw new Error(
                        `Erreur import lot ${i + 1}: ${errorText}\n\n` +
                        `Lignes suspectes dans ce lot:\n${details}`
                    );
                }

                throw new Error(`Erreur import lot ${i + 1}: ${errorText}`);
            }
        }

        await refreshProductsCache();
        if (invalidRows.length > 0) {
            const details = invalidRows
                .slice(0, 8)
                .map(item => `${buildImportRowLabel(item.row, item.fallbackIndex)} -> ${item.issues.join(', ')}`)
                .join('\n');
            const suffix = invalidRows.length > 8
                ? `\n... ${invalidRows.length - 8} autre(s) ligne(s) ignoree(s).`
                : '';

            updateStatus(
                `Import termine: ${payload.length} ${label} insere(s) ou mis a jour, ${invalidRows.length} ligne(s) ignoree(s).`
            );
            alert(
                `Import termine avec succes: ${payload.length} ${label}.\n\n` +
                `${invalidRows.length} ligne(s) ont ete ignoree(s):\n${details}${suffix}`
            );
        } else {
            updateStatus(`Import termine: ${payload.length} ${label} insere(s) ou mis a jour.`);
            alert(`Import termine avec succes: ${payload.length} ${label}.`);
        }
    } catch (error) {
        console.error('Erreur import articles:', error);
        updateStatus(`Echec import: ${error.message}`);
        alert(`Echec import: ${error.message}`);
    }
}

