async function getSuppliersManagementRows() {
    const [suppliers, purchases] = await Promise.all([
        refreshSuppliersCache(),
        getPurchasesDetailed(`${new Date().getFullYear()}-01-01`, new Date().toISOString().split('T')[0])
    ]);

    const summaryBySupplier = purchases.reduce((acc, item) => {
        const supplierId = item.supplier_id || '';
        if (!supplierId) return acc;
        if (!acc[supplierId]) {
            acc[supplierId] = {
                count: 0,
                totalTtc: 0,
                lastDate: ''
            };
        }
        acc[supplierId].count += 1;
        acc[supplierId].totalTtc += Number(item.totalTtc || 0);
        const purchaseDate = String(item.date_achat || item.created_at || '').split('T')[0];
        if (purchaseDate && (!acc[supplierId].lastDate || purchaseDate > acc[supplierId].lastDate)) {
            acc[supplierId].lastDate = purchaseDate;
        }
        return acc;
    }, {});

    return suppliers.map(supplier => {
        const summary = summaryBySupplier[supplier.id] || { count: 0, totalTtc: 0, lastDate: '' };
        return {
            ...supplier,
            purchaseCount: summary.count,
            totalPurchasesTtc: summary.totalTtc,
            lastPurchaseDate: summary.lastDate
        };
    });
}

async function loadSuppliersManagement() {
    try {
        allSuppliers = await getSuppliersManagementRows();
        renderSuppliersManagementTable(allSuppliers);
    } catch (error) {
        console.error('Erreur fournisseurs:', error);
    }
}

function renderSuppliersManagementTable(data) {
    const tbody = document.getElementById('suppliers-management-body');
    if (!tbody) return;

    if (!data.length) {
        tbody.innerHTML = '<tr><td colspan="7" style="text-align:center; padding:40px;">Aucun fournisseur.</td></tr>';
    } else {
        tbody.innerHTML = data.map(item => `
            <tr>
                <td style="font-weight:600;">${escapeHtml(item.nom || '-')}</td>
                <td>${escapeHtml(item.telephone || '-')}</td>
                <td>${escapeHtml(item.matricule_fiscale || '-')}</td>
                <td style="text-align:right;">${item.purchaseCount || 0}</td>
                <td style="text-align:right;">${formatMoney(item.totalPurchasesTtc || 0)}</td>
                <td>${item.lastPurchaseDate ? new Date(item.lastPurchaseDate).toLocaleDateString('fr-FR') : '-'}</td>
                <td style="text-align:center;">
                    <button class="small-action-btn" type="button" onclick="editSupplierManagement('${item.id}')">Edit</button>
                    <button class="small-action-btn" type="button" onclick="deleteSupplierManagement('${item.id}')" style="color:red;">Suppr.</button>
                </td>
            </tr>
        `).join('');
    }

    const totals = data.reduce((acc, item) => {
        acc.suppliers += 1;
        acc.purchases += Number(item.purchaseCount || 0);
        acc.total += Number(item.totalPurchasesTtc || 0);
        return acc;
    }, { suppliers: 0, purchases: 0, total: 0 });

    const countEl = document.getElementById('suppliers-management-count');
    const purchasesEl = document.getElementById('suppliers-management-purchases');
    const totalEl = document.getElementById('suppliers-management-total');
    if (countEl) countEl.innerText = String(totals.suppliers);
    if (purchasesEl) purchasesEl.innerText = String(totals.purchases);
    if (totalEl) totalEl.innerText = `${formatMoney(totals.total)} DT`;
}

function filterSuppliersManagement() {
    const query = normalizeSearchText(document.getElementById('supplier-management-search')?.value || '');
    const filtered = allSuppliers.filter(item => {
        return normalizeSearchText(item.nom).includes(query)
            || normalizeSearchText(item.telephone).includes(query)
            || normalizeSearchText(item.matricule_fiscale).includes(query);
    });
    renderSuppliersManagementTable(filtered);
}

function showSupplierManagementModal() {
    document.getElementById('supplier-management-modal-title').innerText = 'Ajouter un Fournisseur';
    document.getElementById('supplier-management-id').value = '';
    document.getElementById('supplier-management-name').value = '';
    document.getElementById('supplier-management-phone').value = '';
    document.getElementById('supplier-management-tax-id').value = '';
    document.getElementById('supplier-management-modal').style.display = 'block';
}

function hideSupplierManagementModal() {
    const modal = document.getElementById('supplier-management-modal');
    if (modal) modal.style.display = 'none';
}

function editSupplierManagement(id) {
    const item = allSuppliers.find(supplier => supplier.id === id);
    if (!item) return;

    document.getElementById('supplier-management-modal-title').innerText = 'Modifier le Fournisseur';
    document.getElementById('supplier-management-id').value = item.id;
    document.getElementById('supplier-management-name').value = item.nom || '';
    document.getElementById('supplier-management-phone').value = item.telephone || '';
    document.getElementById('supplier-management-tax-id').value = item.matricule_fiscale || '';
    document.getElementById('supplier-management-modal').style.display = 'block';
}

async function saveSupplierManagement() {
    const id = document.getElementById('supplier-management-id')?.value || '';
    const payload = {
        nom: document.getElementById('supplier-management-name')?.value.trim() || '',
        telephone: document.getElementById('supplier-management-phone')?.value.trim() || '',
        matricule_fiscale: document.getElementById('supplier-management-tax-id')?.value.trim() || ''
    };

    if (!payload.nom) {
        alert('Le nom du fournisseur est obligatoire.');
        return;
    }

    if (!id) {
        const dupCheck = await findDuplicateByName('suppliers', payload.nom);
        if (dupCheck) {
            if (!confirm(`Un fournisseur "${dupCheck.nom}" existe deja. Creer quand meme ?`)) return;
        }
    }

    try {
        let url = `${supabaseUrl}suppliers`;
        let method = 'POST';

        if (id) {
            url += `?id=eq.${id}`;
            method = 'PATCH';
        }

        const response = await fetch(url, {
            method,
            headers: supabaseHeaders,
            body: JSON.stringify(payload)
        });

        if (!response.ok) {
            const errorText = await response.text();
            throw new Error(errorText || `HTTP ${response.status}`);
        }

        await refreshSuppliersCache();
        fillPurchaseSupplierSelect(document.getElementById('purchase-supplier')?.value || '');
        hideSupplierManagementModal();
        await loadSuppliersManagement();
    } catch (error) {
        console.error('Erreur sauvegarde fournisseur:', error);
        alert(`Impossible d'enregistrer le fournisseur.\n\nDetail: ${getSupabaseErrorMessage(error)}`);
    }
}

async function deleteSupplierManagement(id) {
    if (!confirm('Voulez-vous vraiment supprimer ce fournisseur ?')) return;

    try {
        const response = await fetch(`${supabaseUrl}suppliers?id=eq.${id}`, {
            method: 'DELETE',
            headers: supabaseHeaders
        });

        if (!response.ok) {
            const errorText = await response.text();
            throw new Error(errorText || `HTTP ${response.status}`);
        }

        await refreshSuppliersCache();
        fillPurchaseSupplierSelect();
        await loadSuppliersManagement();
    } catch (error) {
        console.error('Erreur suppression fournisseur:', error);
        alert(`Impossible de supprimer le fournisseur.\n\nDetail: ${getSupabaseErrorMessage(error)}`);
    }
}

