async function initMutuelleStatementModule() {
    if (!Array.isArray(saleState.mutuelles) || saleState.mutuelles.length === 0) {
        saleState.mutuelles = await fetchCollection('mutuelles?select=id,nom,taux_remboursement,created_at&order=nom');
    }
    if (!Array.isArray(saleState.customers) || saleState.customers.length === 0) {
        saleState.customers = await fetchCollection('customers?select=id,nom,telephone,solde,en_cours,reste_a_payer,mutuelles(nom)&order=nom');
    }

    const select = document.getElementById('mutuelle-list-filter-mutuelle');
    if (select) {
        select.innerHTML = [
            '<option value="">Toutes les mutuelles</option>',
            ...saleState.mutuelles.map(mutuelle => `<option value="${mutuelle.id}">${escapeHtml(mutuelle.nom)}</option>`)
        ].join('');
    }

    try {
        mutuelleStatementState.bordereaux = await fetchMutuelleBordereauxFromSupabase();
        await loadMutuelleStatement();
    } catch (error) {
        const tbody = document.getElementById('mutuelle-board-list-body');
        if (tbody) {
            tbody.innerHTML = `<tr><td colspan="11" style="text-align:center; padding:40px;">${escapeHtml(String(error.message || error))}</td></tr>`;
        }
    }
}

async function loadMutuelleStatement() {
    const tbody = document.getElementById('mutuelle-board-list-body');
    if (!tbody) return;

    const filters = getMutuelleStatementListingFilters();
    mutuelleStatementState.bordereaux = (await fetchMutuelleBordereauxFromSupabase())
        .sort((a, b) => new Date(b.dateCreation || 0).getTime() - new Date(a.dateCreation || 0).getTime());
    const rows = mutuelleStatementState.bordereaux.filter(item => matchesMutuelleBordereauFilters(item, filters));

    if (rows.length === 0) {
        mutuelleStatementState.selectedId = '';
        tbody.innerHTML = '<tr><td colspan="11" style="text-align:center; padding:40px;">Aucun bordereau pour ces criteres.</td></tr>';
        return;
    }

    if (!mutuelleStatementState.selectedId || !rows.some(item => item.id === mutuelleStatementState.selectedId)) {
        mutuelleStatementState.selectedId = rows[0].id;
    }
    tbody.innerHTML = renderMutuelleBordereauxRows(rows);
}

function selectMutuelleBordereau(id) {
    mutuelleStatementState.selectedId = id;
    loadMutuelleStatement();
}

function getSelectedMutuelleBordereau() {
    return mutuelleStatementState.bordereaux.find(item => item.id === mutuelleStatementState.selectedId) || null;
}

function closeMutuelleStatementModule() {
    closeTab('releve_mutuelle');
}

function setMutuelleStatementEditorMutuelles(selectedId = '') {
    const select = document.getElementById('mutuelle-editor-mutuelle');
    if (!select) return;
    select.innerHTML = [
        '<option value="">Choisir une mutuelle</option>',
        ...saleState.mutuelles.map(mutuelle => `<option value="${mutuelle.id}">${escapeHtml(mutuelle.nom)}</option>`)
    ].join('');
    select.value = selectedId || '';
}

async function showMutuelleStatementEditor(id = '') {
    const modal = document.getElementById('mutuelle-statement-editor-modal');
    if (!modal) return;

    const bordereau = id ? mutuelleStatementState.bordereaux.find(item => item.id === id) : null;
    const today = new Date().toISOString().split('T')[0];

    mutuelleStatementState.editorMode = bordereau ? 'edit' : 'create';
    mutuelleStatementState.editingId = bordereau?.id || null;

    setMutuelleStatementEditorMutuelles(bordereau?.mutuelleId || '');
    document.getElementById('mutuelle-editor-from').value = bordereau?.dateDebut || today;
    document.getElementById('mutuelle-editor-to').value = bordereau?.dateFin || today;
    document.getElementById('mutuelle-editor-number').value = bordereau?.numero || getNextMutuelleStatementNumber();
    document.getElementById('mutuelle-editor-status').value = bordereau?.statut || 'BROUILLON';
    document.getElementById('mutuelle-editor-paid').value = String(Number(bordereau?.dejaRegle || 0));
    document.getElementById('mutuelle-editor-retention').value = String(Number(bordereau?.retenueSource || 0));

    document.querySelectorAll('input[name="mutuelle-editor-sort"]').forEach(radio => {
        radio.checked = radio.value === (bordereau?.sortBy || 'date');
    });

    modal.style.display = 'block';
    await refreshMutuelleStatementEditorRows(bordereau?.rows || null);
}

function hideMutuelleStatementEditor() {
    const modal = document.getElementById('mutuelle-statement-editor-modal');
    if (modal) modal.style.display = 'none';
    mutuelleStatementState.editorRows = [];
    mutuelleStatementState.editingId = null;
    mutuelleStatementState.editorMode = 'create';
}

function updateMutuelleStatementEditorField(index, field, value) {
    const row = mutuelleStatementState.editorRows[index];
    if (!row) return;
    row[field] = value;
}

async function refreshMutuelleStatementEditorRows(preloadedRows = null) {
    const tbody = document.getElementById('mutuelle-editor-body');
    if (!tbody) return;

    let rows = [];
    if (Array.isArray(preloadedRows)) {
        rows = preloadedRows.map(item => ({
            ...item,
            customerPatientName: item.customerPatientName || item.customerName || '-'
        }));
    } else {
        const filters = getMutuelleStatementEditorFilters();
        rows = (await getMutuelleStatementRows())
            .filter(item => matchesMutuelleSaleFilters(item, filters))
            .sort((a, b) => {
                if (filters.sortBy === 'matricule') {
                    return String(a.customerMatricule || '').localeCompare(String(b.customerMatricule || ''), 'fr', { sensitivity: 'base' });
                }
                return new Date(a.saleDate || 0).getTime() - new Date(b.saleDate || 0).getTime();
            });
    }

    mutuelleStatementState.editorRows = rows;
    if (rows.length === 0) {
        tbody.innerHTML = '<tr><td colspan="11" style="text-align:center; padding:40px;">Aucune vente mutuelle pour cette selection.</td></tr>';
    } else {
        tbody.innerHTML = rows.map(item => `
            <tr>
                <td>${escapeHtml(item.numeroDisplay || '-')}</td>
                <td>${item.saleDateOnly ? new Date(item.saleDateOnly).toLocaleDateString('fr-FR') : '-'}</td>
                <td>${escapeHtml(item.customerName || '-')}</td>
                <td>${escapeHtml(item.customerMatricule || '-')}</td>
                <td style="text-align:right;">${formatMoney(item.totalTtc || 0)}</td>
                <td style="text-align:right;">${formatMoney(item.partMutuelle || 0)}</td>
                <td><input type="text" class="field-input" value="${escapeHtml(item.libelle1 || item.customerPatientName || item.customerName || '')}" oninput="updateMutuelleStatementEditorField(${rows.indexOf(item)}, 'libelle1', this.value)"></td>
                <td><input type="text" class="field-input" value="${escapeHtml(item.libelle2 || item.mutuelleName || '')}" oninput="updateMutuelleStatementEditorField(${rows.indexOf(item)}, 'libelle2', this.value)"></td>
                <td><input type="text" class="field-input" value="${escapeHtml(item.libelle3 || item.statusLabel || '')}" oninput="updateMutuelleStatementEditorField(${rows.indexOf(item)}, 'libelle3', this.value)"></td>
                <td><input type="text" class="field-input" value="${escapeHtml(item.libelle4 || `${formatMoney(item.rate || 0)} %`)}" oninput="updateMutuelleStatementEditorField(${rows.indexOf(item)}, 'libelle4', this.value)"></td>
                <td><input type="text" class="field-input" value="${escapeHtml(item.libelle5 || item.saleDateOnly || '')}" oninput="updateMutuelleStatementEditorField(${rows.indexOf(item)}, 'libelle5', this.value)"></td>
            </tr>
        `).join('');
    }
    updateMutuelleStatementEditorFooter();
}

function updateMutuelleStatementEditorFooter() {
    const totals = computeMutuelleBordereauTotals(
        mutuelleStatementState.editorRows,
        Number(document.getElementById('mutuelle-editor-paid')?.value || 0),
        Number(document.getElementById('mutuelle-editor-retention')?.value || 0)
    );
    const total = document.getElementById('mutuelle-editor-total');
    const reimb = document.getElementById('mutuelle-editor-reimb');
    const count = document.getElementById('mutuelle-editor-count');
    const rest = document.getElementById('mutuelle-editor-rest');
    const status = document.getElementById('mutuelle-editor-status');
    if (status) {
        status.value = resolveMutuelleBordereauStatus(status.value, totals.reimb, totals.paid, totals.retention);
    }
    if (total) total.innerText = formatMoney(totals.total);
    if (reimb) reimb.innerText = formatMoney(totals.reimb);
    if (count) count.innerText = String(mutuelleStatementState.editorRows.length);
    if (rest) rest.innerText = formatMoney(totals.rest);
}

function openSelectedMutuelleStatement() {
    const bordereau = getSelectedMutuelleBordereau();
    if (!bordereau) {
        alert('Selectionnez un bordereau.');
        return;
    }
    showMutuelleStatementEditor(bordereau.id);
}

function settleSelectedMutuelleStatement() {
    const bordereau = getSelectedMutuelleBordereau();
    if (!bordereau) {
        alert('Selectionnez un bordereau.');
        return;
    }
    if (bordereau.statut === 'SOLDE') {
        alert('Ce bordereau est deja solde.');
        return;
    }
    showMutuelleStatementEditor(bordereau.id).then(() => {
        applyMutuelleStatementSettlement(false);
    });
}

function applyMutuelleStatementSettlement(autoSave = true) {
    const reimbValue = Number(document.getElementById('mutuelle-editor-reimb')?.innerText || 0);
    const retentionInput = document.getElementById('mutuelle-editor-retention');
    const paidInput = document.getElementById('mutuelle-editor-paid');
    const statusInput = document.getElementById('mutuelle-editor-status');
    if (!retentionInput || !paidInput || !statusInput) return;

    const retention = Number(retentionInput.value || 0);
    paidInput.value = String(Math.max(reimbValue - retention, 0));
    statusInput.value = 'SOLDE';
    updateMutuelleStatementEditorFooter();

    if (autoSave) {
        saveMutuelleStatementBordereau();
    }
}

function deleteSelectedMutuelleStatement() {
    const bordereau = getSelectedMutuelleBordereau();
    if (!bordereau) {
        alert('Selectionnez un bordereau a supprimer.');
        return;
    }
    if (bordereau.statut === 'SOLDE') {
        alert('Suppression interdite : un bordereau solde ne peut pas etre supprime.');
        return;
    }
    if (!confirm(`Supprimer le releve ${bordereau.numero} ?`)) return;
    deleteMutuelleBordereauFromSupabase(bordereau.id)
        .then(() => {
            mutuelleStatementState.selectedId = '';
            return loadMutuelleStatement();
        })
        .catch(error => {
            alert(`Suppression impossible.\n\n${getSupabaseErrorMessage(error)}\n\n${getMutuelleBordereauxMigrationSql()}`);
        });
}

function deleteEditingMutuelleStatement() {
    if (!mutuelleStatementState.editingId) {
        hideMutuelleStatementEditor();
        return;
    }
    const current = mutuelleStatementState.bordereaux.find(item => item.id === mutuelleStatementState.editingId);
    if (current?.statut === 'SOLDE') {
        alert('Suppression interdite : un bordereau solde ne peut pas etre supprime.');
        return;
    }
    if (!confirm('Supprimer ce bordereau ?')) return;
    deleteMutuelleBordereauFromSupabase(mutuelleStatementState.editingId)
        .then(() => {
            hideMutuelleStatementEditor();
            mutuelleStatementState.selectedId = '';
            return loadMutuelleStatement();
        })
        .catch(error => {
            alert(`Suppression impossible.\n\n${getSupabaseErrorMessage(error)}\n\n${getMutuelleBordereauxMigrationSql()}`);
        });
}

async function saveMutuelleStatementBordereau() {
    const filters = getMutuelleStatementEditorFilters();
    const mutuelle = saleState.mutuelles.find(item => item.id === filters.mutuelleId);
    const number = document.getElementById('mutuelle-editor-number')?.value.trim() || '';
    const paidAmount = Number(document.getElementById('mutuelle-editor-paid')?.value || 0);
    const retentionAmount = Number(document.getElementById('mutuelle-editor-retention')?.value || 0);
    const manualStatus = document.getElementById('mutuelle-editor-status')?.value || 'BROUILLON';

    if (!mutuelle) {
        alert('Choisissez une mutuelle.');
        return;
    }
    if (!filters.from || !filters.to) {
        alert('Renseignez la periode du bordereau.');
        return;
    }
    if (!number) {
        alert('Le numero du releve est obligatoire.');
        return;
    }
    if (!Array.isArray(mutuelleStatementState.editorRows) || mutuelleStatementState.editorRows.length === 0) {
        alert('Aucune vente a enregistrer dans ce bordereau.');
        return;
    }

    const previous = mutuelleStatementState.bordereaux.find(item => item.id === mutuelleStatementState.editingId);
    const bordereau = buildMutuelleBordereauObject({
        existingId: mutuelleStatementState.editingId || '',
        number,
        mutuelleId: mutuelle.id,
        mutuelleName: mutuelle.nom,
        from: filters.from,
        to: filters.to,
        sortBy: filters.sortBy,
        rows: mutuelleStatementState.editorRows,
        paidAmount,
        retentionAmount,
        createdAt: previous?.dateCreation || '',
        manualStatus
    });

    try {
        const savedId = await saveMutuelleBordereauToSupabase(bordereau);
        mutuelleStatementState.selectedId = savedId;
        hideMutuelleStatementEditor();
        await loadMutuelleStatement();
    } catch (error) {
        alert(`Enregistrement impossible.\n\n${getSupabaseErrorMessage(error)}\n\n${getMutuelleBordereauxMigrationSql()}`);
    }
}

function getMutuelleStatementFilterSummary(bordereau = null) {
    if (!bordereau) {
        return {
            mutuelleLabel: 'MUTUELLES',
            generatedAtLabel: new Date().toLocaleString('fr-FR'),
            statementNumber: ''
        };
    }
    return {
        mutuelleLabel: bordereau.mutuelleName || 'MUTUELLES',
        generatedAtLabel: bordereau.dateCreation ? new Date(bordereau.dateCreation).toLocaleString('fr-FR') : new Date().toLocaleString('fr-FR'),
        statementNumber: bordereau.numero || '-',
        statusLabel: getMutuelleBordereauStatusLabel(bordereau.statut)
    };
}

function buildMutuelleStatementPrintDocument(rows, bordereau = null) {
    const totals = rows.reduce((acc, item) => {
        acc.count += 1;
        acc.ht += Number(item.total_ht || 0);
        acc.sale += Number(item.totalTtc || 0);
        acc.mutuelle += Number(item.partMutuelle || 0);
        return acc;
    }, { count: 0, ht: 0, sale: 0, mutuelle: 0 });
    const summary = getMutuelleStatementFilterSummary(bordereau);
    const companySettings = getCompanySettings();
    const amountInWords = amountToFrenchCurrencyWords(totals.mutuelle);
    const selectedMutuelleTitle = summary.mutuelleLabel === 'Toutes les mutuelles' ? 'MUTUELLES' : summary.mutuelleLabel.toUpperCase();
    const fromDate = bordereau?.dateDebut || '-';
    const toDate = bordereau?.dateFin || '-';

    return `
        <div class="mutuelle-print-sheet">
            <div class="mutuelle-print-top">
                <div class="mutuelle-print-pharmacy-box">
                    <div class="mutuelle-print-pharmacy-kicker">PARAPHARMACIE</div>
                    ${getAdminLogoPrintUrl() ? `<div class="mutuelle-print-pharmacy-logo-wrap"><img src="${escapeHtml(getAdminLogoPrintUrl())}" alt="Logo ${escapeHtml(companySettings.companyName || 'PARA MV')}" class="mutuelle-print-pharmacy-logo" onerror="this.style.display='none'"></div>` : ''}
                    <div class="mutuelle-print-pharmacy-address">${escapeHtml([companySettings.address, companySettings.city].filter(Boolean).join(' '))}</div>
                    <div class="mutuelle-print-pharmacy-line"><span>Telephone :</span><strong>${escapeHtml(companySettings.phone || companySettings.mobile || '-')}</strong></div>
                    <div class="mutuelle-print-pharmacy-line"><span>Matricule fiscale :</span><strong>${escapeHtml(companySettings.fiscalId || '-')}</strong></div>
                    <div class="mutuelle-print-pharmacy-line"><span>RIB :</span><strong>${escapeHtml(companySettings.rib || '-')}</strong></div>
                    <div class="mutuelle-print-pharmacy-line"><span>Code parapharmacie</span><strong>${escapeHtml(companySettings.pharmacistCode || '-')}</strong></div>
                </div>
                <div class="mutuelle-print-title-box">
                    <div class="mutuelle-print-title-row">
                        <span>RELEVE N&deg;</span>
                        <strong>${escapeHtml(summary.statementNumber)}</strong>
                    </div>
                    <div class="mutuelle-print-mutuelle-name">${escapeHtml(selectedMutuelleTitle)}</div>
                    <div class="mutuelle-print-period-box">
                        <span>Periode:</span>
                        <span>Du</span>
                        <strong>${escapeHtml(fromDate)}</strong>
                        <span>Au</span>
                        <strong>${escapeHtml(toDate)}</strong>
                    </div>
                </div>
            </div>

            <table class="mutuelle-print-table">
                <thead>
                    <tr>
                        <th style="width:40px;">#</th>
                        <th>Client</th>
                        <th>Matricule</th>
                        <th>Nom malade</th>
                        <th style="width:80px;"></th>
                        <th style="width:80px;"></th>
                        <th style="text-align:right; width:95px;">M.Total</th>
                        <th style="text-align:right; width:95px;">M.A.Rem</th>
                    </tr>
                </thead>
                <tbody>
                    ${rows.map((item, index) => `
                        <tr>
                            <td style="text-align:right;">${index + 1}</td>
                            <td>${escapeHtml(item.customerName || '-')}</td>
                            <td>${escapeHtml(item.customerMatricule || '-')}</td>
                            <td>${escapeHtml(item.customerPatientName || item.customerName || '-')}</td>
                            <td></td>
                            <td></td>
                            <td style="text-align:right;">${formatMoney(item.totalTtc || 0)}</td>
                            <td style="text-align:right;">${formatMoney(item.partMutuelle || 0)}</td>
                        </tr>
                    `).join('')}
                </tbody>
            </table>

            <div class="mutuelle-print-bottom">
                <div class="mutuelle-print-bottom-left">
                    <div class="mutuelle-print-amount-title">Arretee le present decompte a la somme de</div>
                    <div class="mutuelle-print-amount-words">${escapeHtml(amountInWords)}</div>
                    <div class="mutuelle-print-count-line">Nombre des ordonnances <strong>${totals.count}</strong></div>
                </div>
                <div class="mutuelle-print-bottom-right">
                    <div class="mutuelle-print-total-line"><span>T.H.T :</span><strong>${formatMoney(totals.ht)}</strong></div>
                    <div class="mutuelle-print-total-line"><span>T.T.C :</span><strong>${formatMoney(totals.sale)}</strong></div>
                </div>
            </div>
        </div>
    `;
}

function getCurrentMutuelleStatementDraft() {
    const filters = getMutuelleStatementEditorFilters();
    const mutuelle = saleState.mutuelles.find(item => item.id === filters.mutuelleId);
    const paidAmount = Number(document.getElementById('mutuelle-editor-paid')?.value || 0);
    const retentionAmount = Number(document.getElementById('mutuelle-editor-retention')?.value || 0);
    const previous = mutuelleStatementState.bordereaux.find(item => item.id === mutuelleStatementState.editingId);
    return buildMutuelleBordereauObject({
        existingId: mutuelleStatementState.editingId || '',
        number: document.getElementById('mutuelle-editor-number')?.value.trim() || getNextMutuelleStatementNumber(),
        mutuelleId: mutuelle?.id || '',
        mutuelleName: mutuelle?.nom || '',
        from: filters.from,
        to: filters.to,
        sortBy: filters.sortBy,
        rows: mutuelleStatementState.editorRows,
        paidAmount,
        retentionAmount,
        createdAt: previous?.dateCreation || '',
        manualStatus: document.getElementById('mutuelle-editor-status')?.value || previous?.statut || 'BROUILLON'
    });
}

async function exportMutuelleBordereauToExcel(id = '') {
    try {
        if (typeof XLSX === 'undefined') {
            throw new Error('La librairie XLSX n est pas chargee.');
        }

        const bordereau = id
            ? mutuelleStatementState.bordereaux.find(item => item.id === id)
            : getSelectedMutuelleBordereau();
        if (!bordereau) {
            alert('Selectionnez un bordereau.');
            return;
        }

        const rows = Array.isArray(bordereau.rows) ? bordereau.rows : [];
        if (rows.length === 0) {
            alert('Aucune ligne a exporter pour ce bordereau.');
            return;
        }

        const worksheetData = [
            ['Releve N°', bordereau.numero || ''],
            ['Mutuelle', bordereau.mutuelleName || ''],
            ['Date creation', bordereau.dateCreation ? new Date(bordereau.dateCreation).toLocaleDateString('fr-FR') : ''],
            ['Date debut', bordereau.dateDebut || ''],
            ['Date fin', bordereau.dateFin || ''],
            ['Etat', getMutuelleBordereauStatusLabel(bordereau.statut)],
            [],
            ['Num vente', 'Date', 'Nom client', 'Nom malade', 'Matricule', 'Mutuelle', 'Total TTC', 'Montant a rembourser', 'Libelle1', 'Libelle2', 'Libelle3', 'Libelle4', 'Libelle5']
        ];

        rows.forEach(item => {
            worksheetData.push([
                item.numeroDisplay || '',
                item.saleDateOnly || '',
                item.customerName || '',
                item.customerPatientName || item.customerName || '',
                item.customerMatricule || '',
                bordereau.mutuelleName || item.mutuelleName || '',
                Number(formatMoney(item.totalTtc || 0)),
                Number(formatMoney(item.partMutuelle || 0)),
                item.libelle1 || '',
                item.libelle2 || '',
                item.libelle3 || '',
                item.libelle4 || '',
                item.libelle5 || ''
            ]);
        });

        worksheetData.push([]);
        worksheetData.push(['Total ventes', Number(formatMoney(bordereau.total || 0))]);
        worksheetData.push(['Montant a rembourser', Number(formatMoney(bordereau.montantRembourser || 0))]);
        worksheetData.push(['Deja regle', Number(formatMoney(bordereau.dejaRegle || 0))]);
        worksheetData.push(['Retenue a la source', Number(formatMoney(bordereau.retenueSource || 0))]);
        worksheetData.push(['Reste', Number(formatMoney(bordereau.reste || 0))]);
        worksheetData.push(['Nombre de ventes', rows.length]);

        const worksheet = XLSX.utils.aoa_to_sheet(worksheetData);
        const workbook = XLSX.utils.book_new();
        XLSX.utils.book_append_sheet(workbook, worksheet, 'Releve Mutuelle');
        XLSX.writeFile(workbook, `releve-mutuelle-${String(bordereau.numero || 'bordereau').replace(/[^\w-]/g, '_')}.xlsx`);
    } catch (error) {
        console.error('Erreur export bordereau mutuelle:', error);
        alert(`Export impossible: ${error.message}`);
    }
}

function printMutuelleStatement() {
    const bordereau = document.getElementById('mutuelle-statement-editor-modal')?.style.display === 'block'
        ? getCurrentMutuelleStatementDraft()
        : getSelectedMutuelleBordereau();
    const rows = bordereau?.rows || [];
    if (rows.length === 0) {
        alert('Aucune donnee a imprimer.');
        return;
    }

    const printWindow = openReportPrintWindow('Releve des mutuelles', buildMutuelleStatementPrintDocument(rows, bordereau));
    if (!printWindow) return;
    printWindow.print();
}

