function editCustomer(id) {
    const currentUser = getCurrentBackofficeUser();
    const c = allCustomers.find(item => item.id === id);
    if (!c) return;

    const isAdmin = Boolean(currentUser?.isAdmin);
    document.getElementById('modal-title').innerText = isAdmin ? 'Modifier le Client' : 'Fiche Client (lecture seule)';
    document.getElementById('cust-id').value = c.id;
    document.getElementById('cust-name').value = c.nom || '';
    document.getElementById('cust-phone').value = c.telephone || '';
    document.getElementById('cust-address').value = c.adresse || '';
    document.getElementById('cust-mutuelle-matricule').value = c.numero_matricule_mutuelle || '';
    document.getElementById('cust-patient-name').value = c.nom_malade || '';
    document.getElementById('cust-solde').value = c.solde ?? 0;
    document.getElementById('cust-encours').value = c.en_cours ?? 0;
    document.getElementById('cust-reste').value = c.reste_a_payer ?? 0;
    document.getElementById('cust-solde-initial').value = c.solde_initial ?? 0;
    document.getElementById('cust-date-initial').value = c.date_initial || '2012-06-18';
    
    const readOnly = !isAdmin;
    ['cust-name','cust-phone','cust-address','cust-mutuelle-matricule','cust-patient-name',
     'cust-solde','cust-encours','cust-reste','cust-solde-initial','cust-date-initial','cust-mutuelle'
    ].forEach(fieldId => {
        const el = document.getElementById(fieldId);
        if (el) el.disabled = readOnly;
    });
    const saveBtn = document.querySelector('#customer-modal .achat-btn.blue-dark');
    if (saveBtn) saveBtn.style.display = isAdmin ? '' : 'none';

    document.getElementById('customer-modal').style.display = 'block';
    ensureCustomerMutuelleOptions(c.mutuelle_id || '');
}

async function saveCustomer() {
    const id = document.getElementById('cust-id').value;
    const previousCustomer = id
        ? (allCustomers.find(item => String(item.id) === String(id)) || saleState.customers.find(item => String(item.id) === String(id)) || null)
        : null;
    const customer = {
        nom: document.getElementById('cust-name').value.trim(),
        telephone: document.getElementById('cust-phone').value.trim(),
        adresse: document.getElementById('cust-address').value.trim(),
        mutuelle_id: document.getElementById('cust-mutuelle').value || null,
        numero_matricule_mutuelle: document.getElementById('cust-mutuelle-matricule').value.trim(),
        nom_malade: document.getElementById('cust-patient-name').value.trim(),
        solde: Number(document.getElementById('cust-solde').value || 0),
        en_cours: Number(document.getElementById('cust-encours').value || 0),
        reste_a_payer: Number(document.getElementById('cust-reste').value || 0),
        solde_initial: Number(document.getElementById('cust-solde-initial').value || 0),
        date_initial: document.getElementById('cust-date-initial').value || null
    };

    if (!customer.nom) {
        alert('Le nom est obligatoire');
        return;
    }

    if (!id) {
        const dupCheck = await findDuplicateByName('customers', customer.nom);
        if (dupCheck) {
            if (!confirm(`Un client "${dupCheck.nom}" existe deja. Creer quand meme ?`)) return;
        }
    }

    try {
        let url = `${supabaseUrl}customers`;
        let method = 'POST';

        if (id) {
            url += `?id=eq.${id}`;
            method = 'PATCH';
        }

        const response = await fetch(url, {
            method,
            headers: supabaseHeaders,
            body: JSON.stringify(customer)
        });

        if (!response.ok) {
            const errorText = await response.text();
            throw new Error(errorText || `HTTP ${response.status}`);
        }
        const savedRows = await response.json();
        const savedCustomer = Array.isArray(savedRows) ? savedRows[0] : savedRows;

        if (id && previousCustomer) {
            const customerChanges = buildActionHistoryDiffEntries(previousCustomer, customer, {
                nom: 'Nom',
                telephone: 'Telephone',
                adresse: 'Adresse',
                mutuelle_id: 'Mutuelle',
                numero_matricule_mutuelle: 'Numero matricule mutuelle',
                nom_malade: 'Nom malade',
                solde: 'Solde',
                en_cours: 'En cours',
                reste_a_payer: 'Reste a payer',
                solde_initial: 'Solde initial',
                date_initial: 'Date initiale'
            });
            if (customerChanges.length) {
                await recordActionHistory({
                    category: 'FICHE_CLIENT',
                    action: 'UPDATE',
                    entityType: 'CUSTOMER',
                    entityId: id,
                    entityLabel: customer.nom || previousCustomer.nom || 'Client',
                    details: customerChanges
                });
            }
        }
        if (!id) {
            await recordActionHistory({
                category: 'CREATION_CLIENT',
                action: 'CREATE',
                entityType: 'CUSTOMER',
                entityId: savedCustomer?.id || '',
                entityLabel: customer.nom || 'Client',
                details: [
                    { field: 'nom', label: 'Nom', before: '', after: customer.nom || '' },
                    { field: 'telephone', label: 'Telephone', before: '', after: customer.telephone || '' },
                    { field: 'mutuelle_id', label: 'Mutuelle', before: '', after: customer.mutuelle_id || '' }
                ]
            });
        }

        const shouldReturnToSale = pendingReturnToSaleAfterCustomerSave;
        pendingReturnToSaleAfterCustomerSave = false;

        const freshCustomers = await fetchCollection('customers?select=id,nom,telephone,solde,en_cours,reste_a_payer,mutuelles(nom)&order=nom');
        saleState.customers = freshCustomers;
        await loadCustomers();
        hideCustomerModal();

        if (shouldReturnToSale) {
            pendingSaleCustomerSelection = {
                id: savedCustomer?.id || freshCustomers.find(item => normalizeSearchText(item.nom) === normalizeSearchText(customer.nom || ''))?.id || '',
                name: customer.nom || savedCustomer?.nom || ''
            };
            openTab('vente');
        }
    } catch (error) {
        console.error('Erreur sauvegarde client:', error);
        alert(
            "Impossible d'enregistrer le client.\n\n" +
            `Detail: ${getSupabaseErrorMessage(error)}\n\n` +
            "Si les nouveaux champs n'existent pas encore dans Supabase, execute ce SQL:\n" +
            getCustomersMigrationSql()
        );
    }
}

