document.addEventListener('click', (event) => {
    const webStoreSearch = document.getElementById('web-store-search');
    const webStoreSuggestions = document.getElementById('web-store-search-suggestions');
    if (webStoreSearch && webStoreSuggestions && !webStoreSearch.contains(event.target) && !webStoreSuggestions.contains(event.target)) {
        closeWebStoreSearchSuggestions();
    }

    const saleSearch = document.getElementById('sale-product-search');
    const saleSuggestions = document.getElementById('sale-product-suggestions');
    if (saleSearch && saleSuggestions && !saleSearch.contains(event.target) && !saleSuggestions.contains(event.target)) {
        closeProductSuggestions();
    }

    const saleCustomerSearch = document.getElementById('sale-customer-search');
    const saleCustomerSuggestions = document.getElementById('sale-customer-suggestions');
    if (saleCustomerSearch && saleCustomerSuggestions && !saleCustomerSearch.contains(event.target) && !saleCustomerSuggestions.contains(event.target)) {
        closeSaleCustomerSuggestions();
    }

    const purchaseSearch = document.getElementById('purchase-product-search');
    const purchaseSuggestions = document.getElementById('purchase-product-suggestions');
    if (purchaseSearch && purchaseSuggestions && !purchaseSearch.contains(event.target) && !purchaseSuggestions.contains(event.target)) {
        closePurchaseSuggestions();
    }

    const supplierReturnSearch = document.getElementById('supplier-return-search');
    const supplierReturnSuggestions = document.getElementById('supplier-return-suggestions');
    if (supplierReturnSearch && supplierReturnSuggestions && !supplierReturnSearch.contains(event.target) && !supplierReturnSuggestions.contains(event.target)) {
        closeSupplierReturnSuggestions();
    }

    const supplierReturnSupplierSearch = document.getElementById('supplier-return-supplier-search');
    const supplierReturnSupplierSuggestions = document.getElementById('supplier-return-supplier-suggestions');
    if (supplierReturnSupplierSearch && supplierReturnSupplierSuggestions && !supplierReturnSupplierSearch.contains(event.target) && !supplierReturnSupplierSuggestions.contains(event.target)) {
        closeSupplierReturnSupplierSuggestions();
    }

    const articleMovementSearch = document.getElementById('article-movement-designation');
    const articleMovementSuggestionsBox = document.getElementById('article-movement-suggestions');
    if (articleMovementSearch && articleMovementSuggestionsBox && !articleMovementSearch.contains(event.target) && !articleMovementSuggestionsBox.contains(event.target)) {
        closeArticleMovementSuggestions();
    }

    ['stock_pret', 'stock_emprunt', 'stock_entree', 'stock_sortie'].forEach(moduleId => {
        const searchInput = document.getElementById(`${moduleId}-product-search`);
        const suggestionsBox = document.getElementById(`${moduleId}-product-suggestions`);
        if (searchInput && suggestionsBox && !searchInput.contains(event.target) && !suggestionsBox.contains(event.target)) {
            closeStockOperationSuggestions(moduleId);
        }
    });
});
